var fabOpen = false;
function toggleDarkMode(on) {
  document.body.classList.toggle('dark-mode', on);
  document.documentElement.classList.toggle('dark-mode', on);
  try { localStorage.setItem('nixa_dark', on ? '1' : '0'); } catch(e){}
  var ico = document.querySelector('#dark-mode-toggle');
  if (ico) ico.checked = on;
  var tonicono = document.getElementById('dark-mode-icon');
  if (tonicono) tonicono.className = on ? 'ti ti-sun' : 'ti ti-moon';
}

(function() {
  try {
    var saved = localStorage.getItem('nixa_dark');
    if (saved === '1') {
      document.body.classList.add('dark-mode');
      document.documentElement.classList.add('dark-mode');
    }
  } catch(e) {}
})();

// Dialogos propios del sistema. Reemplazan alert/confirm/prompt del navegador
// para mantener el flujo dentro de SisVentas y permitir modales apilados.
var _svDialogoCola = Promise.resolve();
var _svModalSyncPendiente = false;

function _svModalEsVisible(el) {
  if (!el || !el.isConnected) return false;
  // Un proceso minimizado conserva su nodo para seguir trabajando y mostrar
  // la barra flotante, pero ya no debe bloquear el contenido de la aplicación.
  if (el.dataset && (el.dataset.minimizado === '1' || el.dataset.noBloqueante === '1')) return false;
  var estilo = getComputedStyle(el);
  return estilo.display !== 'none' && estilo.visibility !== 'hidden' && estilo.position === 'fixed' && el.getClientRects().length > 0;
}

function svSincronizarPilaModales() {
  if (_svModalSyncPendiente) return;
  _svModalSyncPendiente = true;
  requestAnimationFrame(function() {
    _svModalSyncPendiente = false;
    var candidatos = Array.from(document.querySelectorAll('.modal-overlay, [id^="modal-"], [id$="-modal"], [role="dialog"], [role="alertdialog"]'));
    var visibles = candidatos.filter(_svModalEsVisible).filter(function(el) {
      return !candidatos.some(function(otro) { return otro !== el && otro.contains(el) && _svModalEsVisible(otro); });
    }).sort(function(a, b) {
      var za = parseInt(getComputedStyle(a).zIndex, 10) || 0;
      var zb = parseInt(getComputedStyle(b).zIndex, 10) || 0;
      return za === zb ? candidatos.indexOf(a) - candidatos.indexOf(b) : za - zb;
    });
    candidatos.forEach(function(el) { el.classList.remove('sv-modal-underlay'); });
    visibles.slice(0, -1).forEach(function(el) { el.classList.add('sv-modal-underlay'); });
    document.body.classList.toggle('sv-modal-stack-open', visibles.length > 0);
  });
}

function _svCrearDialogoSistema(opciones) {
  opciones = opciones || {};
  return new Promise(function(resolve) {
    var tipo = opciones.tipo || 'confirm';
    var textoMensaje = String(opciones.mensaje || '');
    var esPeligro = opciones.peligro != null
      ? !!opciones.peligro
      : /\b(eliminar|borrar|anular|limpiar|definitiv|no se puede deshacer|cancelar esta orden)\b/i.test(textoMensaje);
    var overlay = document.createElement('div');
    overlay.className = 'modal-overlay open sv-system-dialog-overlay';
    overlay.setAttribute('role', tipo === 'alert' ? 'alertdialog' : 'dialog');
    overlay.setAttribute('aria-modal', 'true');

    var panel = document.createElement('div');
    panel.className = 'modal sv-system-dialog';
    var cabecera = document.createElement('div');
    cabecera.className = 'sv-system-dialog-head';
    var icono = document.createElement('span');
    icono.className = 'sv-system-dialog-icon ' + (esPeligro ? 'danger' : 'info');
    icono.innerHTML = '<i class="ti ' + (esPeligro ? 'ti-alert-triangle' : (tipo === 'prompt' ? 'ti-edit' : 'ti-help')) + '"></i>';
    var titulos = document.createElement('div');
    titulos.className = 'sv-system-dialog-titles';
    var titulo = document.createElement('strong');
    titulo.textContent = opciones.titulo || (tipo === 'alert' ? 'Información' : tipo === 'prompt' ? 'Ingresar información' : esPeligro ? 'Confirmar acción sensible' : 'Confirmar acción');
    var subtitulo = document.createElement('span');
    subtitulo.textContent = opciones.subtitulo || 'SisVentas';
    titulos.appendChild(titulo);
    titulos.appendChild(subtitulo);
    cabecera.appendChild(icono);
    cabecera.appendChild(titulos);

    var mensaje = document.createElement('div');
    mensaje.className = 'sv-system-dialog-message';
    mensaje.textContent = textoMensaje;
    panel.appendChild(cabecera);
    panel.appendChild(mensaje);

    var input = null;
    if (tipo === 'prompt') {
      input = document.createElement(opciones.multilinea ? 'textarea' : 'input');
      input.className = 'sv-system-dialog-input';
      if (!opciones.multilinea) input.type = opciones.inputType || 'text';
      input.value = opciones.valor == null ? '' : String(opciones.valor);
      input.placeholder = opciones.placeholder || '';
      if (opciones.multilinea) input.rows = opciones.filas || 3;
      panel.appendChild(input);
    }

    var acciones = document.createElement('div');
    acciones.className = 'sv-system-dialog-actions';
    var terminado = false;
    function cerrar(valor) {
      if (terminado) return;
      terminado = true;
      document.removeEventListener('keydown', teclado, true);
      overlay.remove();
      svSincronizarPilaModales();
      resolve(valor);
    }
    function teclado(ev) {
      if (ev.key === 'Escape' && tipo !== 'alert') { ev.preventDefault(); cerrar(tipo === 'prompt' ? null : false); }
      if (ev.key === 'Enter' && !ev.shiftKey && (!input || input.tagName !== 'TEXTAREA')) {
        ev.preventDefault();
        cerrar(tipo === 'prompt' ? input.value : true);
      }
    }
    if (tipo !== 'alert') {
      var cancelar = document.createElement('button');
      cancelar.type = 'button';
      cancelar.className = 'btn';
      cancelar.textContent = opciones.textoCancelar || 'Cancelar';
      cancelar.onclick = function() { cerrar(tipo === 'prompt' ? null : false); };
      acciones.appendChild(cancelar);
    }
    var aceptar = document.createElement('button');
    aceptar.type = 'button';
    aceptar.className = 'btn ' + (esPeligro ? 'btn-danger' : 'btn-primary');
    aceptar.textContent = opciones.textoAceptar || (tipo === 'alert' ? 'Entendido' : 'Confirmar');
    aceptar.onclick = function() { cerrar(tipo === 'prompt' ? input.value : true); };
    acciones.appendChild(aceptar);
    panel.appendChild(acciones);
    overlay.appendChild(panel);
    document.body.appendChild(overlay);
    document.addEventListener('keydown', teclado, true);
    svSincronizarPilaModales();
    setTimeout(function() { (input || aceptar).focus(); }, 0);
  });
}

function svDialogoSistema(opciones) {
  var ejecutar = function() { return _svCrearDialogoSistema(opciones); };
  var resultado = _svDialogoCola.then(ejecutar, ejecutar);
  _svDialogoCola = resultado.catch(function() {});
  return resultado;
}

function svConfirm(mensaje, opciones) {
  return svDialogoSistema(Object.assign({ tipo:'confirm', mensaje:mensaje }, opciones || {}));
}
function svPrompt(mensaje, valor, opciones) {
  return svDialogoSistema(Object.assign({ tipo:'prompt', mensaje:mensaje, valor:valor }, opciones || {}));
}
function svAlert(mensaje, opciones) {
  return svDialogoSistema(Object.assign({ tipo:'alert', mensaje:mensaje }, opciones || {}));
}

// Los módulos cargados en archivos separados consumen estas funciones desde window.
window.svDialogoSistema = svDialogoSistema;
window.svConfirm = svConfirm;
window.svPrompt = svPrompt;
window.svAlert = svAlert;
window.svSincronizarPilaModales = svSincronizarPilaModales;

document.addEventListener('DOMContentLoaded', function() {
  svSincronizarPilaModales();
  svPrepararModalesGestionables(document);
  if (window.MutationObserver) {
    var observadorModales = new MutationObserver(function(cambios) {
      svSincronizarPilaModales();
      cambios.forEach(function(cambio) {
        cambio.addedNodes.forEach(function(nodo) {
          if (nodo && nodo.nodeType === 1) svPrepararModalesGestionables(nodo);
        });
      });
    });
    observadorModales.observe(document.body, { subtree:true, childList:true, attributes:true, attributeFilter:['class','style'] });
  }
});
function initSearchableSelect(selectId, placeholder) {
  var sel = document.getElementById(selectId);
  if (!sel) return;
  // El select nativo se reutiliza entre productos. Si sus opciones o su valor
  // cambiaron, el control visual existente también debe sincronizarse; de lo
  // contrario conserva la categoría del producto abierto anteriormente.
  if (sel.dataset.ssInit) {
    var inputExistente = document.querySelector('[data-ss-id="' + selectId + '"]');
    var opcionActual = sel.selectedIndex >= 0 ? sel.options[sel.selectedIndex] : null;
    if (inputExistente) inputExistente.value = opcionActual ? opcionActual.text : (placeholder || 'Seleccionar...');
    ssRenderList(selectId, sel.value, '');
    return;
  }
  sel.dataset.ssInit = '1';
  sel.style.display = 'none';
  var ph = placeholder || 'Seleccionar...';
  var currentLabel = sel.selectedIndex >= 0 && sel.options[sel.selectedIndex]
    ? sel.options[sel.selectedIndex].text : ph;

  var wrap = document.createElement('div');
  wrap.className = 'ss-wrap';
  wrap.dataset.ss = selectId;
  sel.parentNode.insertBefore(wrap, sel);
  wrap.appendChild(sel);

  var inp = document.createElement('input');
  inp.type = 'text'; inp.className = 'ss-input';
  inp.readOnly = true; inp.value = currentLabel; inp.placeholder = ph;
  inp.dataset.ssId = selectId;
  inp.onclick = function() { ssToggle(this); };
  wrap.insertBefore(inp, sel);

  var drop = document.createElement('div');
  drop.className = 'ss-drop'; drop.id = 'ss-drop-' + selectId;

  var srch = document.createElement('input');
  srch.type = 'text'; srch.className = 'ss-search'; srch.placeholder = 'Buscar...';
  srch.dataset.ssFor = selectId;
  srch.oninput = function() { ssFilterByData(this); };
  srch.onclick = function(e) { e.stopPropagation(); };

  var list = document.createElement('div');
  list.className = 'ss-list'; list.id = 'ss-list-' + selectId;

  drop.appendChild(srch); drop.appendChild(list);
  document.body.appendChild(drop);

  ssRenderList(selectId, sel.value, '');

  document.addEventListener('click', function(e) {
    if (!e.target.closest('[data-ss="' + selectId + '"]') &&
        !e.target.closest('#ss-drop-' + selectId)) {
      ssClose(selectId);
    }
  });
}

function ssToggle(inp) {
  var id   = inp.dataset.ssId;
  var drop = document.getElementById('ss-drop-' + id);
  if (!drop) return;
  var isOpen = drop.classList.contains('open');
  document.querySelectorAll('.ss-drop.open').forEach(function(d){ d.classList.remove('open'); });
  if (!isOpen) {
    var rect = inp.getBoundingClientRect();
    drop.style.top   = (rect.bottom + 2) + 'px';
    drop.style.left  = rect.left + 'px';
    drop.style.width = Math.max(rect.width, 200) + 'px';
    drop.classList.add('open');
    var srch = drop.querySelector('.ss-search');
    if (srch) { srch.value = ''; ssFilter(srch, id); srch.focus(); }
  }
}

function ssClose(id) {
  var drop = document.getElementById('ss-drop-' + id);
  if (drop) drop.classList.remove('open');
}

function ssFilterByData(inp) {
  var id = inp.dataset.ssFor;
  if (id) ssFilter(inp, id);
}

function ssFilter(inp, id) {
  var sel = document.getElementById(id);
  if (!sel) return;
  ssRenderList(id, sel.value, inp.value);
}

function ssRenderList(id, currentVal, q) {
  var sel  = document.getElementById(id);
  var list = document.getElementById('ss-list-' + id);
  if (!list || !sel) return;
  var opts = Array.from(sel.options).map(function(o){ return { value:o.value, label:o.text }; });
  var filtered = q ? opts.filter(function(o){ return o.label.toLowerCase().includes(q.toLowerCase()); }) : opts;
  if (!filtered.length) { list.innerHTML = '<div class="ss-empty">Sin resultados</div>'; return; }
  list.innerHTML = '';
  filtered.forEach(function(o) {
    var item = document.createElement('div');
    item.className = 'ss-item' + (o.value === currentVal ? ' selected' : '');
    item.textContent = o.label;
    item.dataset.val  = o.value;
    item.dataset.ssId = id;
    item.onmousedown  = function() { ssSelect(this); };
    list.appendChild(item);
  });
}

function ssSelect(item) {
  var id  = item.dataset.ssId;
  var val = item.dataset.val;
  var sel = document.getElementById(id);
  var inp = document.querySelector('[data-ss-id="' + id + '"]');
  if (!sel || !inp) return;
  sel.value = val; inp.value = item.textContent.trim();
  sel.dispatchEvent(new Event('change'));
  ssClose(id);
}

function actualizarSelectCategorias() {
  var cats = window.categoriasData || [];
  ['filter-cat','pf-categoria'].forEach(function(sid) {
    var sel = document.getElementById(sid);
    if (!sel) return;
    sel.innerHTML = '<option value="">Todas las categorías</option>' +
      cats.map(function(c){ return '<option value="'+c+'">'+c+'</option>'; }).join('');
    // Re-inicializar el searchable select si ya existe
    var wrap = sel.parentNode;
    if (wrap && wrap.dataset && wrap.dataset.ss) {
      var inp = wrap.querySelector('.ss-input');
      if (inp) inp.value = sel.options[0] ? sel.options[0].text : '';
      ssRenderList(sid, sel.value, '');
    }
  });
}
