function _fechaEsDelMes(fecha, mesYYYYMM) {
  if (!fecha || !mesYYYYMM) return false;
  // Usar el mismo normalizador del resto del sistema. Algunos registros
  // históricos incluyen hora después de DD/MM/YYYY y antes quedaban fuera de
  // las métricas aunque sí aparecieran correctamente en el listado.
  var fechaLocal = _fechaCalendarioLocal(fecha);
  if (!fechaLocal) return false;
  return fechaLocal.getFullYear() + '-' + String(fechaLocal.getMonth() + 1).padStart(2, '0') === mesYYYYMM;
}

function _fechaEsDia(fecha, dia) {
  var f = String(fecha||'').trim();
  if (!f || !dia) return false;
  var yyyy = dia.getFullYear();
  var mm = String(dia.getMonth()+1).padStart(2,'0');
  var dd = String(dia.getDate()).padStart(2,'0');
  return f.slice(0,10) === (yyyy+'-'+mm+'-'+dd) ||
    f === (dd+'/'+mm+'/'+yyyy) || f === (dd+'-'+mm+'-'+yyyy) ||
    f === (dd+'/'+mm+'/'+String(yyyy).slice(-2));
}

function _fechaCalendarioLocal(fecha) {
  var f = String(fecha || '').trim();
  if (!f) return null;
  var iso = f.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/);
  if (iso) return new Date(Number(iso[1]), Number(iso[2]) - 1, Number(iso[3]), 12, 0, 0);
  var ar = f.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{2,4})/);
  if (ar) {
    var anio = Number(ar[3]);
    if (anio < 100) anio += 2000;
    return new Date(anio, Number(ar[2]) - 1, Number(ar[1]), 12, 0, 0);
  }
  var d = new Date(f);
  return isNaN(d.getTime()) ? null : d;
}

function kpiIva() {
  var hoy = new Date();
  var mesActual = hoy.getFullYear() + '-' + String(hoy.getMonth()+1).padStart(2,'0');
  window._filtrosVentas = { texto:'', estado:'', mes:mesActual, tab:'facturadas' };
  _restaurarControlesFiltrosVentas();
  _aplicarFiltrosVentas();
  notify('Mostrando ventas facturadas de este mes');
}

function renderMetricasVentas() {
  var hoy = new Date();
  var mesActual = hoy.getFullYear() + '-' + String(hoy.getMonth()+1).padStart(2,'0');
  var meses = ['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
  var mesLabel = meses[hoy.getMonth()] + ' ' + hoy.getFullYear();

  var ventas = ventasVisiblesParaUsuario(ventasList || []);
  var ventasMes = ventas.filter(function(v){
    return _fechaEsDelMes(v.fecha, mesActual);
  });

  // Totales del MES
  var totalMes  = ventasMes.reduce(function(s,v){ return s + _svTotalVentaCanonico(v); }, 0);
  var ivaMes    = ventasMes.filter(function(v){ return v.factura; }).reduce(function(s,v){ return s+(parseFloat(v.iva)||0); }, 0);
  var cantMes   = ventasMes.length;

  // Usar la cuenta corriente ya conciliada con el historial real de pagos.
  // Antes esta pantalla sólo miraba `totalPagado` dentro de la venta, por eso
  // podía mostrar $0 aunque el cobro existiera en sisventas/pagos.
  var resumenCC = typeof _svResumenCuentaCorriente === 'function'
    ? _svResumenCuentaCorriente(ventas)
    : { pendiente:0, clientesConSaldo:0 };
  var pendiente = resumenCC.pendiente;
  var clisPend = resumenCC.clientesConSaldo;

  // "Pagado este mes" corresponde a la fecha real del cobro, aunque la venta
  // sea de un mes anterior.
  var pagosMes = (window._historialPagosCompleto || []).filter(function(p) {
    return _svPagoValido(p) && _fechaEsDelMes(p.fecha, mesActual);
  });
  var cobrado = pagosMes.reduce(function(s,p){ return s + (parseFloat(p.monto)||0); }, 0);

  _set('vm-total-mes', '$' + Math.round(totalMes).toLocaleString('es-AR'));
  _set('vm-cobrado',   '$' + Math.round(cobrado).toLocaleString('es-AR'));
  _set('vm-pendiente', '$' + Math.round(pendiente).toLocaleString('es-AR'));
  _set('vm-iva',       '$' + Math.round(ivaMes).toLocaleString('es-AR'));

  // Subtítulos
  var subTotal = document.getElementById('vm-total-sub');
  if (subTotal) subTotal.textContent = cantMes + ' venta' + (cantMes!==1?'s':'') + ' en ' + mesLabel;

  var subCob = document.getElementById('vm-cobrado-sub');
  if (subCob) subCob.textContent = pagosMes.length + ' pago' + (pagosMes.length!==1?'s':'') + ' registrado' + (pagosMes.length!==1?'s':'') + ' en ' + mesLabel;

  var subPend = document.getElementById('vm-pendiente-sub');
  if (subPend) subPend.textContent = clisPend + ' cliente' + (clisPend!==1?'s':'')+' con saldo';

  var subIva = document.getElementById('vm-iva-sub');
  if (subIva) subIva.textContent = 'IVA real · ' + mesLabel;
}
// SISTEMA DE ORDENAMIENTO DE TABLAS
// Se persiste únicamente el criterio de las grillas que tienen ordenamiento
// propio. No se observa ni recorre todo el DOM: cada módulo restaura su estado
// al renderizarse.
var SV_GRID_ORDER_STORAGE = 'sisventas_grid_order_v220';
function _svLeerOrdenGrillas() {
  try {
    var guardado = JSON.parse(localStorage.getItem(SV_GRID_ORDER_STORAGE) || '{}');
    return guardado && typeof guardado === 'object' ? guardado : {};
  } catch(e) { return {}; }
}
function _svGuardarOrdenGrilla(tablaId, estado) {
  if (!tablaId || !estado || !estado.col) return;
  try {
    var guardados = _svLeerOrdenGrillas();
    guardados[tablaId] = { col:estado.col, dir:estado.dir === 'desc' ? 'desc' : 'asc' };
    localStorage.setItem(SV_GRID_ORDER_STORAGE, JSON.stringify(guardados));
  } catch(e) {}
}
var _sortState = _svLeerOrdenGrillas();  // { tablaId: { col: 'nombre', dir: 'asc' } }

function sortTabla(tablaId, col, tipo) {
  var estado = _sortState[tablaId] || { col: null, dir: 'asc' };
  if (estado.col === col) {
    estado.dir = estado.dir === 'asc' ? 'desc' : 'asc';
  } else {
    estado.col = col;
    estado.dir = 'asc';
  }
  _sortState[tablaId] = estado;
  _svGuardarOrdenGrilla(tablaId, estado);
  if (tablaId === 'ventas-tbl' && window._ventasPaginacion) window._ventasPaginacion.pagina = 1;

  document.querySelectorAll('#' + tablaId + ' th[data-sort]').forEach(function(th) {
    var icon = th.querySelector('.sort-icon');
    if (!icon) return;
    if (th.dataset.sort === col) {
      th.setAttribute('aria-sort', estado.dir === 'asc' ? 'ascending' : 'descending');
      icon.className = 'sort-icon ti ' + (estado.dir === 'asc' ? 'ti-chevron-up' : 'ti-chevron-down');
      icon.style.color = 'var(--text)';
    } else {
      th.removeAttribute('aria-sort');
      icon.className = 'sort-icon ti ti-chevrons-up-down';
      icon.style.color = 'var(--text3)';
    }
  });

  // Llamar la función de render correspondiente
  var renders = {
    'cli-tbl':  function() { renderTablaClientes(); },
    'prod-tbl': function() { renderTablaProductos(); },
    'ven-tbl':  function() { if (typeof _aplicarFiltrosVentas === 'function') _aplicarFiltrosVentas(); else renderVentasTabla(); },
    'ventas-tbl': function() { if (typeof _aplicarFiltrosVentas === 'function') _aplicarFiltrosVentas(); else renderVentasTabla(); },
  };
  if (renders[tablaId]) renders[tablaId]();
}

function sortData(lista, tablaId, defaultCol, defaultDir) {
  var estado = _sortState[tablaId];
  var col = estado ? estado.col : defaultCol;
  var dir = estado ? estado.dir : (defaultDir || 'asc');
  if (!col) return lista;

  return lista.slice().sort(function(a, b) {
    var va = a[col];
    var vb = b[col];
    // Numérico
    if (!isNaN(parseFloat(va)) && !isNaN(parseFloat(vb))) {
      return dir === 'asc' ? parseFloat(va) - parseFloat(vb) : parseFloat(vb) - parseFloat(va);
    }
    // Texto
    va = String(va || '').toLowerCase();
    vb = String(vb || '').toLowerCase();
    if (va < vb) return dir === 'asc' ? -1 : 1;
    if (va > vb) return dir === 'asc' ? 1 : -1;
    return 0;
  });
}

var _clientesGruposAbiertos = new Set();
var _clientesLimiteVista = 80;
var _clienteEstructuraDestinoKey = '';
var _clientesIndicePorClave = Object.create(null);
var _clientesRaizPorClave = Object.create(null);
var _clientesGruposCache = [];
var _clientesGrupoPorRaiz = Object.create(null);
var _clientesCacheValida = false;
var _clientesCacheVersion = 0;
var _clientesUltimoRenderVersion = -1;
var _clientesUltimoFiltro = '';

function invalidarCacheClientes() {
  _clientesCacheValida = false;
  _clientesCacheVersion++;
}

function reconstruirCacheClientes() {
  if (_clientesCacheValida) return;
  var lista = clientesData || [];
  var porClave = Object.create(null);
  lista.forEach(function(c) {
    [c && c.fbKey, c && c.id].filter(Boolean).forEach(function(clave) { porClave[String(clave)] = c; });
  });
  var raizPorClave = Object.create(null);
  var gruposPorRaiz = Object.create(null);
  var grupos = [];
  lista.forEach(function(cliente) {
    var estructura = obtenerEstructuraClientePorLegacy(cliente);
    var actual = cliente || null;
    var principalKey = estructura && estructura.principalLegacyFbKey;
    if (principalKey && porClave[String(principalKey)]) actual = porClave[String(principalKey)];
    var vistos = Object.create(null);
    while (actual && actual.clientePrincipalFbKey) {
      var clavePadre = String(actual.clientePrincipalFbKey);
      if (vistos[clavePadre] || !porClave[clavePadre]) break;
      vistos[clavePadre] = true;
      actual = porClave[clavePadre];
    }
    var raiz = actual || cliente;
    var raizKey = String(raiz && (raiz.fbKey || raiz.id) || '');
    [cliente && cliente.fbKey, cliente && cliente.id].filter(Boolean).forEach(function(clave) { raizPorClave[String(clave)] = raiz; });
    if (!gruposPorRaiz[raizKey]) {
      gruposPorRaiz[raizKey] = { raiz:raiz, miembros:[] };
      grupos.push(gruposPorRaiz[raizKey]);
    }
    gruposPorRaiz[raizKey].miembros.push(cliente);
  });
  _clientesIndicePorClave = porClave;
  _clientesRaizPorClave = raizPorClave;
  _clientesGrupoPorRaiz = gruposPorRaiz;
  _clientesGruposCache = grupos;
  _clientesCacheValida = true;
}

function clienteRaizRegistro(cliente) {
  if (!cliente) return null;
  reconstruirCacheClientes();
  return _clientesRaizPorClave[String(cliente.fbKey || '')]
    || _clientesRaizPorClave[String(cliente.id || '')]
    || cliente;
}

function obtenerEstructuraClientePorLegacy(cliente) {
  if (!cliente) return null;
  var claves = [cliente.fbKey, cliente.id].filter(Boolean).map(String);
  var indiceData = typeof clientesUnificadosIndice !== 'undefined' ? clientesUnificadosIndice : {};
  var estructuraData = typeof clientesUnificadosData !== 'undefined' ? clientesUnificadosData : {};
  var indice = claves.map(function(k){ return indiceData && indiceData[k]; }).find(Boolean);
  return indice && estructuraData ? estructuraData[indice.clienteKey] || null : null;
}

function clientesDelGrupo(cliente) {
  reconstruirCacheClientes();
  var raiz = clienteRaizRegistro(cliente);
  if (!raiz) return [];
  var raizKey = String(raiz.fbKey || raiz.id || '');
  var grupo = _clientesGrupoPorRaiz[raizKey];
  return grupo ? grupo.miembros.slice() : [];
}

function _clienteCategoriaSede(cliente) {
  return String(cliente && (cliente.sedeCategoria || cliente.categoriaSede || cliente.empresa) || '').trim();
}

function clienteVinculoOperacion(cliente) {
  cliente = cliente || {};
  var indice = clientesUnificadosIndice[String(cliente.fbKey || '')] || {};
  return {
    clientePrincipalKey: String(indice.clienteKey || cliente.fbKey || cliente.id || ''),
    domicilioFbKey: String(cliente.fbKey || cliente.id || ''),
    domicilioCategoria: _clienteCategoriaSede(cliente) || 'Domicilio principal',
    direccion: String(cliente.dir || cliente.direccion || cliente.domicilio || '')
  };
}

function toggleGrupoCliente(clienteKey) {
  var key = String(clienteKey || '');
  if (_clientesGruposAbiertos.has(key)) _clientesGruposAbiertos.delete(key);
  else _clientesGruposAbiertos.add(key);
  var inp = document.querySelector('#page-clientes .search-input');
  renderTablaClientes(inp ? inp.value : '');
}

function mostrarMasClientes() {
  _clientesLimiteVista += 80;
  var inp = document.querySelector('#page-clientes .search-input');
  renderTablaClientes(inp ? inp.value : '');
}

function abrirNuevaSedeCliente(el) {
  var key = el && el.dataset ? (el.dataset.ckey || el.dataset.cid) : el;
  var cliente = (clientesData || []).find(function(c){ return String(c.fbKey || c.id || '') === String(key || ''); });
  var estructura = obtenerEstructuraClientePorLegacy(cliente);
  if (!cliente || !estructura) { notify('No se pudo resolver el cliente principal para el nuevo domicilio'); return; }
  _clienteEstructuraDestinoKey = estructura.fbKey || estructura.clienteKey || (clientesUnificadosIndice[cliente.fbKey] || {}).clienteKey || '';
  if (!_clienteEstructuraDestinoKey) { notify('La estructura de este cliente aún no está disponible'); return; }
  abrirModalNuevo('cliente');
  setTimeout(function() {
    var partes = String(estructura.nombre || cliente.nombre || '').trim().split(/\s+/);
    var nombre = document.getElementById('nc-nm');
    var apellido = document.getElementById('nc-ap');
    if (nombre) { nombre.value = partes.shift() || ''; nombre.readOnly = true; }
    if (apellido) { apellido.value = partes.join(' '); apellido.readOnly = true; }
    var sede = document.getElementById('nc-sede');
    if (sede) sede.focus();
    _set('modal-nuevo-title', 'Nuevo domicilio — ' + (estructura.nombre || cliente.nombre || 'Cliente'));
  }, 40);
}

// Conservado sólo como referencia hasta finalizar la migración; ningún control de UI lo invoca.
async function unificarClientesFiltradosLegacyInseguro() {
  // La vía anterior quedó deshabilitada de forma explícita: no puede escribir
  // clientePrincipalFbKey aunque alguien conserve un enlace viejo en memoria.
  return abrirRevisionClientesDuplicados();
  var inp = document.querySelector('#page-clientes .search-input');
  var busqueda = String(inp && inp.value || '').trim().toLowerCase();
  if (busqueda.length < 2) {
    notify('Buscá primero el cliente que querés unificar');
    return;
  }
  var candidatos = (clientesData || []).filter(function(c) {
    var texto = [c.nombre,c.id,c.empresa,c.sedeCategoria,c.dir,c.direccion,c.telefono].join(' ').toLowerCase();
    return texto.includes(busqueda);
  });
  if (candidatos.length < 2) {
    notify('La búsqueda debe mostrar al menos dos registros para unificarlos');
    return;
  }
  var detalle = candidatos.map(function(c) {
    return String(c.id || c.fbKey || '') + ' · ' + (c.nombre || 'Sin nombre') + ' · ' + (c.dir || c.direccion || 'Sin dirección') +
      (_clienteCategoriaSede(c) ? ' · ' + _clienteCategoriaSede(c) : '');
  }).join('\n');
  var idPrincipal = await svPrompt(
    'Elegí cuál registro será el cliente principal ingresando su ID.\n\n' + detalle,
    String(candidatos[0].id || candidatos[0].fbKey || ''),
    { titulo:'Unificar clientes', textoAceptar:'Continuar' }
  );
  if (idPrincipal == null) return;
  var principal = candidatos.find(function(c){
    return String(c.id || '') === String(idPrincipal).trim() || String(c.fbKey || '') === String(idPrincipal).trim();
  });
  if (!principal || !principal.fbKey) {
    notify('El ID principal no pertenece a los resultados visibles');
    return;
  }
  var sedes = candidatos.filter(function(c){ return c.fbKey && c.fbKey !== principal.fbKey; });
  if (!await svConfirm(
    'Se mostrará un único cliente “'+(principal.nombre||'')+'” con '+candidatos.length+' domicilios.\n\nLas ventas, OT y cuentas existentes conservarán sus referencias. ¿Confirmar?',
    { titulo:'Confirmar unificación', textoAceptar:'Unificar' }
  )) return;
  if (!window.fbDB || !window.fbUpdate) { notify('Sin conexión Firebase'); return; }
  var updates = {};
  updates[FB_PATHS.clientes + '/' + principal.fbKey + '/clientePrincipalFbKey'] = null;
  sedes.forEach(function(sede) {
    updates[FB_PATHS.clientes + '/' + sede.fbKey + '/clientePrincipalFbKey'] = principal.fbKey;
    if (!_clienteCategoriaSede(sede) && sede.empresa) {
      updates[FB_PATHS.clientes + '/' + sede.fbKey + '/sedeCategoria'] = sede.empresa;
    }
  });
  window.fbUpdate(window.fbRef(window.fbDB), updates)
    .then(function(){
      _clientesGruposAbiertos.add(principal.fbKey);
      notify('Cliente unificado con '+candidatos.length+' direcciones');
    })
    .catch(function(error){ notify('No se pudo unificar: '+error.message); });
}

// Revisión previa a la migración Clientes -> Sedes. La coincidencia de nombre es
// solamente una sugerencia: nunca modifica un cliente, venta u OT por sí sola.
var _clientesRevisionDecisiones = {};
var CLIENTES_REVISION_PATH = 'sisventas/config/migracionClientes/revision';

function _clienteNombreComparable(cliente) {
  return String(cliente && cliente.nombre || '')
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .toLocaleUpperCase('es-AR').replace(/[^A-Z0-9]+/g, ' ')
    .replace(/\s+/g, ' ').trim();
}

function _clienteRevisionClave(nombre) {
  var texto = String(nombre || 'SIN_NOMBRE');
  var hash = 5381;
  for (var i = 0; i < texto.length; i++) hash = ((hash << 5) + hash) ^ texto.charCodeAt(i);
  return 'nombre_' + texto.replace(/[^A-Z0-9]+/g, '_').slice(0, 54) + '_' + (hash >>> 0).toString(36);
}

function obtenerCandidatosClientesDuplicados() {
  var porNombre = {};
  (clientesData || []).forEach(function(cliente) {
    // Los vínculos legacy explícitos ya son una relación conocida, no un candidato.
    if (!cliente || cliente.clientePrincipalFbKey) return;
    var nombre = _clienteNombreComparable(cliente);
    if (nombre.length < 3) return;
    if (!porNombre[nombre]) porNombre[nombre] = [];
    porNombre[nombre].push(cliente);
  });
  return Object.keys(porNombre).filter(function(nombre){ return porNombre[nombre].length > 1; })
    .map(function(nombre) {
      var miembros = porNombre[nombre].sort(function(a,b){
        return String(a.dir || a.direccion || '').localeCompare(String(b.dir || b.direccion || ''), 'es');
      });
      return { clave:_clienteRevisionClave(nombre), nombre:nombre, miembros:miembros };
    })
    .sort(function(a,b){ return b.miembros.length - a.miembros.length || a.nombre.localeCompare(b.nombre, 'es'); });
}

function _clienteClaveEstructura(legacyKeys) {
  var texto = (legacyKeys || []).map(String).sort().join('|');
  var hash = 5381;
  for (var i = 0; i < texto.length; i++) hash = ((hash << 5) + hash) ^ texto.charCodeAt(i);
  return 'cli_' + (hash >>> 0).toString(36);
}

function _clienteDecisionManualValida(decision, estadoEsperado) {
  return !!decision && decision.confirmadaManualmente === true &&
    (!estadoEsperado || decision.estado === estadoEsperado);
}

function construirPlanEstructuraClientes(origen) {
  var clientes = (origen || clientesData || []).filter(Boolean);
  var asignados = {};
  var grupos = [];
  var raizLegacyExplicita = function(cliente) {
    var actual = cliente;
    var vistos = {};
    while (actual && actual.clientePrincipalFbKey) {
      var clave = String(actual.clientePrincipalFbKey);
      if (vistos[clave]) break;
      vistos[clave] = true;
      var siguiente = clientes.find(function(c){ return String(c.fbKey || '') === clave; });
      if (!siguiente) break;
      actual = siguiente;
    }
    return actual || cliente;
  };
  // Primero se conservan relaciones legacy que ya fueron creadas explícitamente.
  clientes.forEach(function(cliente) {
    var raiz = raizLegacyExplicita(cliente);
    var raizKey = String(raiz.fbKey || raiz.id || '');
    if (!raizKey || asignados[raizKey]) return;
    var miembros = clientes.filter(function(c) {
      var r = raizLegacyExplicita(c);
      return String(r.fbKey || r.id || '') === raizKey;
    });
    if (miembros.length > 1) {
      miembros.forEach(function(c){ asignados[String(c.fbKey || c.id || '')] = true; });
      grupos.push(miembros);
    }
  });
  // Luego se aplican los grupos aprobados por nombre normalizado.
  obtenerCandidatosClientesDuplicados().forEach(function(candidato) {
    if (!_clienteDecisionManualValida(_clientesRevisionDecisiones[candidato.clave], 'unificar')) return;
    var miembros = candidato.miembros.filter(function(c){ return !asignados[String(c.fbKey || c.id || '')]; });
    if (miembros.length < 2) return;
    miembros.forEach(function(c){ asignados[String(c.fbKey || c.id || '')] = true; });
    grupos.push(miembros);
  });
  // Todo cliente restante también obtiene su ficha principal con una sola sede.
  clientes.forEach(function(cliente) {
    var key = String(cliente.fbKey || cliente.id || '');
    if (!key || asignados[key]) return;
    asignados[key] = true;
    grupos.push([cliente]);
  });
  return grupos.map(function(miembros) {
    miembros = miembros.slice().sort(function(a,b){ return String(a.fbKey || a.id || '').localeCompare(String(b.fbKey || b.id || '')); });
    var principal = miembros.slice().sort(function(a,b){
      return String(a.nombre || '').localeCompare(String(b.nombre || ''), 'es') || String(a.id || '').localeCompare(String(b.id || ''));
    })[0] || {};
    var legacyKeys = miembros.map(function(c){ return String(c.fbKey || c.id || ''); }).filter(Boolean);
    return {
      clienteKey: _clienteClaveEstructura(legacyKeys),
      nombre: principal.nombre || '',
      principalLegacyFbKey: principal.fbKey || '',
      miembros: miembros,
      legacyKeys: legacyKeys
    };
  });
}

function construirActualizacionesEstructuraClientes(plan, ahora) {
  var clientesUnificados = {};
  var indiceUnificado = {};
  (plan || []).forEach(function(grupo) {
    var sedes = {};
    grupo.miembros.forEach(function(cliente) {
      var legacyKey = String(cliente.fbKey || cliente.id || '');
      var sedeKey = 'sede_' + legacyKey.replace(/[^A-Za-z0-9_-]/g, '_');
      sedes[sedeKey] = {
        legacyFbKey: cliente.fbKey || '', legacyId: cliente.id || '',
        nombreOriginal: cliente.nombre || '', direccion: cliente.dir || cliente.direccion || '',
        categoria: _clienteCategoriaSede(cliente), telefono: cliente.telefono || cliente.tel || '',
        email: cliente.mail || cliente.email || '', activo: cliente.activo !== false
      };
      indiceUnificado[legacyKey] = {
        clienteKey: grupo.clienteKey, sedeKey: sedeKey, actualizadoEn: ahora
      };
    });
    clientesUnificados[grupo.clienteKey] = {
      esquema: 1, nombre: grupo.nombre, principalLegacyFbKey: grupo.principalLegacyFbKey,
      legacyFbKeys: grupo.legacyKeys, cantidadSedes: grupo.miembros.length,
      sedes: sedes, actualizadoEn: ahora
    };
  });
  return {
    'sisventas/clientes_unificados': clientesUnificados,
    'sisventas/clientes_unificados_indice': indiceUnificado,
    'sisventas/config/migracionClientes/estado': {
      esquema: 1, estado: 'completada', clientesPrincipales: (plan || []).length,
      sedesMigradas: (plan || []).reduce(function(n,g){ return n + g.miembros.length; }, 0),
      actualizadoEn: ahora, actualizadoPor: currentUser || 'Administrador'
    }
  };
}

async function generarEstructuraClientesAprobada() {
  if (currentRole !== 'admin') { notify('Solo un administrador puede ejecutar la migración'); return; }
  if (!window.fbDB || !window.fbUpdate) { notify('Sin conexión Firebase'); return; }
  var plan = construirPlanEstructuraClientes();
  if (!plan.length) { notify('No hay clientes para migrar'); return; }
  var candidaturas = obtenerCandidatosClientesDuplicados();
  var pendientes = candidaturas.filter(function(grupo) {
    return !_clienteDecisionManualValida(_clientesRevisionDecisiones[grupo.clave]);
  });
  if (pendientes.length) {
    notify('Falta revisar manualmente '+pendientes.length+' grupo'+(pendientes.length===1?'':'s')+'. No se modificó la estructura.');
    return;
  }
  if (!await svConfirm('Se crearán '+plan.length+' clientes principales y '+(clientesData||[]).length+' domicilios trazables. Los registros actuales, ventas y OT no se modificarán. ¿Generar la nueva estructura?', { titulo:'Generar estructura de clientes', textoAceptar:'Generar estructura' })) return;
  var ahora = Date.now();
  var updates = construirActualizacionesEstructuraClientes(plan, ahora);
  try {
    await window.fbUpdate(window.fbRef(window.fbDB), updates);
    _renderRevisionClientesDuplicados();
    notify('Estructura generada: '+plan.length+' clientes principales y '+(clientesData||[]).length+' domicilios');
  } catch (error) {
    notify('No se pudo generar la estructura: ' + error.message);
  }
}

function _resumenClienteRevision(cliente) {
  var coincide = function(registro) {
    return typeof _svRegistroPerteneceCliente === 'function' && _svRegistroPerteneceCliente(registro, cliente, true);
  };
  return {
    ventas: (ventasList || []).filter(coincide).length,
    ots: (otData || []).filter(coincide).length,
    presupuestos: (pptoData || []).filter(coincide).length
  };
}

function _asegurarModalRevisionClientes() {
  var existente = document.getElementById('modal-revision-clientes');
  if (existente) return existente;
  var modal = document.createElement('div');
  modal.id = 'modal-revision-clientes';
  modal.className = 'modal-overlay clientes-review-overlay';
  modal.onclick = function(ev){ if (ev.target === modal) cerrarRevisionClientesDuplicados(); };
  modal.innerHTML = '<div class="modal clientes-review-modal" role="dialog" aria-modal="true" aria-label="Revisión de clientes repetidos">'+
    '<div class="modal-head"><div><h3><i class="ti ti-users-group"></i> Revisión de posibles clientes repetidos</h3><p>Son coincidencias por nombre. Confirmá manualmente antes de cualquier migración.</p></div><button class="icon-btn" onclick="cerrarRevisionClientesDuplicados()" title="Cerrar"><i class="ti ti-x"></i></button></div>'+
    '<div id="clientes-review-resumen" class="clientes-review-resumen"></div>'+
    '<div id="clientes-review-lista" class="clientes-review-lista"></div>'+
    '<div class="modal-foot"><span>La estructura nueva conserva los registros legacy y sus referencias históricas.</span><div class="flex-end"><button class="btn btn-primary" onclick="generarEstructuraClientesAprobada()"><i class="ti ti-sitemap"></i> Generar estructura aprobada</button><button class="btn" onclick="cerrarRevisionClientesDuplicados()">Cerrar</button></div></div>'+
  '</div>';
  document.body.appendChild(modal);
  return modal;
}

function _renderRevisionClientesDuplicados() {
  var lista = document.getElementById('clientes-review-lista');
  var resumen = document.getElementById('clientes-review-resumen');
  if (!lista || !resumen) return;
  var grupos = obtenerCandidatosClientesDuplicados();
  var pendientes = grupos.filter(function(g){ return !_clienteDecisionManualValida(_clientesRevisionDecisiones[g.clave]); }).length;
  resumen.innerHTML = '<strong>'+grupos.length+'</strong> grupo'+(grupos.length===1?'':'s')+' a revisar · <strong>'+pendientes+'</strong> pendiente'+(pendientes===1?'':'s')+'.';
  if (!grupos.length) {
    lista.innerHTML = '<div class="clientes-review-empty"><i class="ti ti-circle-check"></i> No hay nombres repetidos pendientes de analizar.</div>';
    return;
  }
  lista.innerHTML = grupos.map(function(grupo) {
    var decision = _clientesRevisionDecisiones[grupo.clave] || {};
    var estado = _clienteDecisionManualValida(decision) ? decision.estado : 'pendiente';
    var estadoTexto = estado === 'unificar' ? 'Marcado para unificar' : estado === 'independientes' ? 'Clientes independientes' : 'Pendiente de tu decisión';
    var filas = grupo.miembros.map(function(cliente) {
      var ref = _resumenClienteRevision(cliente);
      var categoria = _clienteCategoriaSede(cliente) || 'Sin categoría';
      return '<tr><td>'+escapeHTML(String(cliente.id || '—'))+'</td><td><strong>'+escapeHTML(cliente.nombre || 'Sin nombre')+'</strong><small>'+escapeHTML(categoria)+'</small></td><td>'+escapeHTML(cliente.dir || cliente.direccion || 'Sin dirección')+'</td><td>'+ref.ventas+' V · '+ref.ots+' OT · '+ref.presupuestos+' P</td></tr>';
    }).join('');
    return '<section class="clientes-review-group estado-'+estado+'">'+
      '<div class="clientes-review-group-head"><div><h4>'+escapeHTML(grupo.nombre)+'</h4><span>'+grupo.miembros.length+' registro'+(grupo.miembros.length===1?'':'s')+' con el mismo nombre</span></div><span class="clientes-review-status">'+estadoTexto+'</span></div>'+
      '<table><thead><tr><th>ID</th><th>Registro / categoría</th><th>Dirección</th><th>Historial</th></tr></thead><tbody>'+filas+'</tbody></table>'+
      '<div class="clientes-review-actions">'+
        '<button class="btn btn-sm '+(estado==='unificar'?'btn-primary':'')+'" onclick="registrarDecisionRevisionCliente(\''+grupo.clave+'\',\'unificar\')"><i class="ti ti-link"></i> Mismo cliente: unificar después</button>'+
        '<button class="btn btn-sm '+(estado==='independientes'?'btn-primary':'')+'" onclick="registrarDecisionRevisionCliente(\''+grupo.clave+'\',\'independientes\')"><i class="ti ti-users"></i> Son independientes</button>'+
        (estado !== 'pendiente' ? '<button class="btn btn-sm" onclick="registrarDecisionRevisionCliente(\''+grupo.clave+'\',\'pendiente\')">Dejar pendiente</button>' : '')+
      '</div></section>';
  }).join('');
}

async function abrirRevisionClientesDuplicados() {
  var modal = _asegurarModalRevisionClientes();
  modal.classList.add('open');
  _renderRevisionClientesDuplicados();
  if (!window.fbDB || !window.fbGet) return;
  try {
    var snap = await window.fbGet(window.fbRef(window.fbDB, CLIENTES_REVISION_PATH));
    _clientesRevisionDecisiones = snap.val() || {};
    _renderRevisionClientesDuplicados();
  } catch (error) {
    notify('Se muestra la revisión local; no se pudieron cargar decisiones guardadas');
  }
}

function cerrarRevisionClientesDuplicados() {
  var modal = document.getElementById('modal-revision-clientes');
  if (modal) modal.classList.remove('open');
}

async function registrarDecisionRevisionCliente(clave, estado) {
  var grupo = obtenerCandidatosClientesDuplicados().find(function(g){ return g.clave === clave; });
  if (!grupo) return;
  if (estado === 'pendiente') delete _clientesRevisionDecisiones[clave];
  else _clientesRevisionDecisiones[clave] = {
    estado: estado,
    nombreNormalizado: grupo.nombre,
    clientesLegacy: grupo.miembros.map(function(c){ return { fbKey:c.fbKey || '', id:c.id || '', nombre:c.nombre || '', direccion:c.dir || c.direccion || '' }; }),
    actualizadoEn: Date.now(),
    actualizadoPor: currentUser || 'Administrador',
    confirmadaManualmente: true
  };
  _renderRevisionClientesDuplicados();
  if (!window.fbDB || !window.fbSet) { notify('Decisión preparada localmente; falta conexión para guardarla'); return; }
  try {
    await window.fbSet(window.fbRef(window.fbDB, CLIENTES_REVISION_PATH + '/' + clave), estado === 'pendiente' ? null : _clientesRevisionDecisiones[clave]);
    notify(estado === 'unificar' ? 'Grupo marcado para migrar más adelante' : estado === 'independientes' ? 'Grupo marcado como independiente' : 'Grupo vuelto a pendiente');
  } catch (error) {
    notify('No se pudo guardar la decisión: ' + error.message);
  }
}

// Compatibilidad con accesos locales antiguos: ya no unifica directamente.
function unificarClientesFiltrados() { abrirRevisionClientesDuplicados(); }

var _clientesRenderProgramado = 0;
function mostrarEstadoCargaClientes(texto) {
  var tbody = document.getElementById('cli-tbody');
  if (!tbody) return;
  tbody.setAttribute('aria-busy', 'true');
  tbody.innerHTML = '<tr class="clientes-loading-row"><td colspan="6" style="text-align:center;padding:30px;color:var(--text2)"><i class="ti ti-loader-2 spin" style="margin-right:8px"></i><strong>'+
    escapeHTML(texto || 'Cargando clientes…')+'</strong><div style="font-size:12px;color:var(--text3);margin-top:5px">Podés seguir usando el sistema mientras se prepara la lista.</div></td></tr>';
}

function programarRenderTablaClientes(filtro, mostrarCarga) {
  var token = ++_clientesRenderProgramado;
  var tbody = document.getElementById('cli-tbody');
  if (mostrarCarga) mostrarEstadoCargaClientes('Preparando clientes…');
  requestAnimationFrame(function() {
    // Un segundo cuadro garantiza que el navegador pinte la página y el
    // estado de carga antes de comenzar a construir las filas.
    requestAnimationFrame(function() {
      setTimeout(function() {
        if (token !== _clientesRenderProgramado || !_svEsPaginaActiva('clientes')) return;
        renderTablaClientes(filtro);
        requestAnimationFrame(function() {
          document.dispatchEvent(new CustomEvent('sisventas:module-ready', { detail:{ page:'clientes' } }));
        });
        var completar = function() {
          if (token !== _clientesRenderProgramado || !_svEsPaginaActiva('clientes')) return;
          if (typeof actualizarStatClientes === 'function') actualizarStatClientes();
          if (typeof prepararAccionesGrilla === 'function') prepararAccionesGrilla('cli-tbl');
        };
        if (typeof requestIdleCallback === 'function') requestIdleCallback(completar, { timeout:700 });
        else setTimeout(completar, 30);
      }, 0);
    });
  });
}

function renderTablaClientes(filtro) {
  var tbody = document.getElementById('cli-tbody');
  if (!tbody) return;
  reconstruirCacheClientes();
  var lista = _clientesGruposCache.slice();
  if (filtro) {
    var f = filtro.toLowerCase();
    lista = lista.filter(function(grupo) {
      return grupo.miembros.some(function(c) {
        return (c.nombre||'').toLowerCase().includes(f) ||
               String(c.id||'').includes(f) ||
               (c.empresa||'').toLowerCase().includes(f) ||
               _clienteCategoriaSede(c).toLowerCase().includes(f) ||
               (c.telefono||'').includes(f) ||
               (c.dir||c.direccion||'').toLowerCase().includes(f);
      });
    });
  }
  lista.sort(function(a,b){ return String(a.raiz.nombre||'').localeCompare(String(b.raiz.nombre||''), 'es'); });
  if (!lista.length) {
    tbody.innerHTML = '<tr><td colspan="6" style="text-align:center;padding:24px;color:var(--text3)">Sin resultados</td></tr>';
    tbody.removeAttribute('aria-busy');
    return;
  }
  var totalGrupos = lista.length;
  var limite = filtro ? 160 : _clientesLimiteVista;
  lista = lista.slice(0, limite);
  var htmlFilas = lista.map(function(grupo) {
    var c = grupo.raiz;
    var miembros = grupo.miembros.slice().sort(function(a,b){
      if (a === c) return -1;
      if (b === c) return 1;
      return String(a.dir||a.direccion||'').localeCompare(String(b.dir||b.direccion||''), 'es');
    });
    var idFmt  = String(c.id || '').padStart(4, '0');
    var activo = c.activo !== false;
    var nombre = c.nombre || '';
    var dir    = miembros.length > 1 ? miembros.length + ' domicilios' : (c.dir || c.direccion || '');
    var tel    = c.telefono || '';
    var categorias = Array.from(new Set(miembros.map(_clienteCategoriaSede).filter(Boolean)));
    var empresa = categorias.length ? '<div class="cli-grupo-categorias">' + categorias.map(function(cat){ return '<span>'+escapeHTML(cat)+'</span>'; }).join('') + '</div>' : '';
    var ckey = String(c.fbKey || c.id || '').replace(/"/g, '');
    var abierto = _clientesGruposAbiertos.has(ckey) || !!filtro;
    var expandir = miembros.length > 1
      ? '<button class="icon-btn cli-grupo-toggle" onclick="event.stopPropagation();toggleGrupoCliente(\''+escapeHTML(ckey)+'\')" title="'+(abierto?'Ocultar':'Ver')+' direcciones"><i class="ti ti-chevron-'+(abierto?'down':'right')+'"></i></button>'
      : '<span class="cli-grupo-toggle-placeholder"></span>';
    var html = '<tr class="cr cli-grupo-row" data-cid="' + escapeHTML(ckey) + '" data-ckey="' + escapeHTML(ckey) + '" onclick="verClienteById(this)" style="cursor:pointer">' +
      '<td style="font-family:monospace;font-size:12px">' + expandir + escapeHTML(idFmt) + '</td>' +
      '<td style="font-weight:500">' + escapeHTML(nombre) + empresa + '</td>' +
      '<td class="hide-mobile" style="color:var(--text2)">' + escapeHTML(dir) + '</td>' +
      '<td class="hide-mobile" style="color:var(--text2)">' + escapeHTML(tel) + '</td>' +
      '<td style="text-align:right"><label class="toggle-sw" onclick="event.stopPropagation()" title="' + (activo ? 'Activo — clic para dar de baja' : 'Inactivo — clic para reactivar') + '"><input type="checkbox" ' + (activo ? 'checked' : '') + ' onchange="event.stopPropagation();toggleActivoCliente(\'' + escapeHTML(ckey) + '\')"><span class="toggle-knob"></span></label></td>' +
      '<td style="text-align:right;white-space:nowrap">' +
        '<button class="icon-btn" data-cid="' + escapeHTML(ckey) + '" data-ckey="' + escapeHTML(ckey) + '" onclick="event.stopPropagation();verClienteById(this)" title="Historial unificado"><i class="ti ti-history" style="font-size:15px"></i></button>' +
        '<button class="icon-btn" data-cid="' + escapeHTML(ckey) + '" data-ckey="' + escapeHTML(ckey) + '" onclick="event.stopPropagation();abrirNuevaSedeCliente(this)" title="Agregar domicilio"><i class="ti ti-map-pin-plus" style="font-size:15px"></i></button>' +
        '<button class="icon-btn" data-cid="' + escapeHTML(ckey) + '" onclick="event.stopPropagation();editarClienteById(this)" title="Editar cliente principal"><i class="ti ti-pencil" style="font-size:15px"></i></button>' +
        '<button class="icon-btn" data-cid="' + escapeHTML(ckey) + '" onclick="event.stopPropagation();eliminarCliente(this)" title="Dar de baja domicilio principal" style="color:var(--text3)" onmouseenter="this.style.color=\'var(--red)\'" onmouseleave="this.style.color=\'var(--text3)\'"><i class="ti ti-user-off" style="font-size:15px"></i></button>' +
      '</td>' +
    '</tr>';
    if (miembros.length > 1 && abierto) {
      html += miembros.map(function(sede) {
        var skey = String(sede.fbKey || sede.id || '');
        var categoria = _clienteCategoriaSede(sede) || (sede === c ? 'Dirección principal' : 'Sin categoría');
        return '<tr class="cli-sede-row">' +
          '<td></td><td><span class="cli-sede-ramal">↳</span><strong>'+escapeHTML(categoria)+'</strong></td>' +
          '<td class="hide-mobile">'+escapeHTML(sede.dir||sede.direccion||'Sin dirección')+'</td>' +
          '<td class="hide-mobile">'+escapeHTML(sede.telefono||sede.tel||'—')+'</td>' +
          '<td></td><td style="text-align:right;white-space:nowrap">' +
            '<button class="icon-btn" data-cid="'+escapeHTML(skey)+'" onclick="event.stopPropagation();editarClienteById(this)" title="Editar este domicilio"><i class="ti ti-pencil"></i></button>' +
            (sede === c ? '' : '<button class="icon-btn" data-cid="'+escapeHTML(skey)+'" onclick="event.stopPropagation();eliminarCliente(this)" title="Dar de baja este domicilio"><i class="ti ti-user-off"></i></button>') +
          '</td></tr>';
      }).join('');
    }
    return html;
  }).join('');
  if (totalGrupos > lista.length) {
    htmlFilas += '<tr><td colspan="6" style="text-align:center;padding:14px"><button class="btn btn-sm" onclick="mostrarMasClientes()">Mostrar 80 más <span style="color:var(--text3)">('+lista.length+' de '+totalGrupos+')</span></button></td></tr>';
  }
  tbody.innerHTML = htmlFilas;
  tbody.removeAttribute('aria-busy');
  _clientesUltimoRenderVersion = _clientesCacheVersion;
  _clientesUltimoFiltro = String(filtro || '');
}
function buscarCliente(val) { programarRenderTablaClientes(val, false); }
function verClienteById(el) {
  var key = el.dataset.ckey || el.dataset.cid;
  var c = (clientesData || []).find(function(x){
    return String(x.fbKey || '') === String(key) || String(x.id || '') === String(key);
  });
  if (c) verHistorialCliente(c.fbKey || c.id);
}
function editarClienteById(el) {
  var id = el.dataset.cid;
  editarCliente(id);
}
// MÓDULO KITS
var KITS_DATA = {};
var _kitComponentesActual = []; // [{pid, codigo, nombre, costo, cantidad}]
var _kitEditandoFbKey = null;

function cargarKits() {
  if (!window.fbDB) return;
  window.fbOnValue(window.fbRef(window.fbDB, 'sisventas/kits'), function(snap) {
    KITS_DATA = snap.val() || {};
    renderTablaKits();
    actualizarStatsKits();
  });
}

function actualizarStatsKits() {
  var lista = Object.values(KITS_DATA);
  _set('kit-stat-total', lista.length);
  if (!lista.length) { _set('kit-stat-costo','$0'); _set('kit-stat-margen','0%'); return; }
  var costoProm = lista.reduce(function(s,k){ return s+(parseFloat(k.costoTotal)||0); },0) / lista.length;
  var margenProm = lista.reduce(function(s,k){ return s+(parseFloat(k.margenPct)||0); },0) / lista.length;
  _set('kit-stat-costo', '$' + Math.round(costoProm).toLocaleString('es-AR'));
  _set('kit-stat-margen', Math.round(margenProm) + '%');
}

function renderTablaKits(filtro) {
  var tbody = document.getElementById('kits-tbody');
  if (!tbody) return;
  var lista = Object.entries(KITS_DATA).map(function(e){ return Object.assign({fbKey:e[0]}, e[1]); });
  if (filtro) {
    var f = filtro.toLowerCase();
    lista = lista.filter(function(k){ return (k.nombre||'').toLowerCase().includes(f) || (k.codigo||'').toLowerCase().includes(f); });
  }
  if (!lista.length) {
    tbody.innerHTML = '<tr><td colspan="8" style="text-align:center;color:var(--text3);padding:24px">'+(filtro?'Sin resultados':'Sin kits armados aún')+'</td></tr>';
    return;
  }
  tbody.innerHTML = lista.map(function(k) {
    var stockDisp = calcularStockDisponibleKit(k);
    var stockColor = stockDisp === 0 ? 'var(--red)' : stockDisp <= 2 ? 'var(--amber)' : 'var(--green)';
    return '<tr>' +
      '<td><span class="badge b-blue">'+escapeHTML(k.codigo||'')+'</span></td>' +
      '<td>'+escapeHTML(k.nombre||'')+'</td>' +
      '<td style="font-size:12px;color:var(--text3)">'+(k.componentes?k.componentes.length:0)+' productos</td>' +
      '<td>$'+Math.round(k.costoTotal||0).toLocaleString('es-AR')+'</td>' +
      '<td>'+(k.margenPct||0)+'%</td>' +
      '<td style="font-weight:600;color:var(--green)">$'+Math.round(k.precioVenta||0).toLocaleString('es-AR')+'</td>' +
      '<td style="color:'+stockColor+';font-weight:600">'+stockDisp+'</td>' +
      '<td style="white-space:nowrap">' +
        '<button class="btn btn-sm btn-icon" onclick="editarKit(\''+k.fbKey+'\')" title="Editar"><i class="ti ti-edit" style="font-size:14px"></i></button>' +
        '<button class="btn btn-sm btn-icon" onclick="eliminarKit(\''+k.fbKey+'\')" title="Eliminar" style="color:var(--text3)"><i class="ti ti-trash" style="font-size:14px"></i></button>' +
      '</td>' +
    '</tr>';
  }).join('');
}

function calcularStockDisponibleKit(kit) {
  if (!kit.componentes || !kit.componentes.length) return 0;
  var minDisponible = Infinity;
  kit.componentes.forEach(function(c) {
    var prod = Object.values(prodData||{}).find(function(p){ return p.fbKey === c.pid || p.codigo === c.codigo; });
    var stockProd = prod ? (parseInt(prod.stock)||0) : 0;
    var disp = Math.floor(stockProd / (c.cantidad||1));
    if (disp < minDisponible) minDisponible = disp;
  });
  return minDisponible === Infinity ? 0 : minDisponible;
}

function filtrarKits(v) { renderTablaKits(v); }

function abrirNuevoKit() {
  _kitEditandoFbKey = null;
  _kitComponentesActual = [];
  _set2('kit-nombre','');
  _set2('kit-descripcion','');
  _set2('kit-margen','30');
  document.getElementById('kit-form-titulo').textContent = 'Nuevo kit';
  renderComponentesKit();
  calcKitTotales();
  poblarCategoriasKit();
  _hide('kits-list-view');
  _block('kit-form-view');
}

function editarKit(fbKey) {
  var k = KITS_DATA[fbKey];
  if (!k) return;
  _kitEditandoFbKey = fbKey;
  _kitComponentesActual = (k.componentes||[]).slice();
  _set2('kit-nombre', k.nombre||'');
  _set2('kit-descripcion', k.descripcion||'');
  _set2('kit-margen', k.margenPct||30);
  document.getElementById('kit-form-titulo').textContent = 'Editar kit — ' + k.codigo;
  poblarCategoriasKit();
  _set2('kit-categoria', k.categoria||'');
  renderComponentesKit();
  calcKitTotales();
  _hide('kits-list-view');
  _block('kit-form-view');
}

function volverListaKits() {
  _hide('kit-form-view');
  _block('kits-list-view');
  renderTablaKits();
}

function poblarCategoriasKit() {
  var sel = document.getElementById('kit-categoria');
  if (!sel) return;
  var cats = [...new Set(Object.values(prodData||{}).map(function(p){ return p.categoria; }).filter(Boolean))].sort();
  sel.innerHTML = '<option value="">— Seleccionar —</option>' + cats.map(function(c){ return '<option value="'+escapeHTML(c)+'">'+escapeHTML(c)+'</option>'; }).join('');
}

function _set2(id, val) { var e = document.getElementById(id); if (e) e.value = val; }

function renderComponentesKit() {
  var tbody = document.getElementById('kit-componentes-tbody');
  if (!tbody) return;
  if (!_kitComponentesActual.length) {
    tbody.innerHTML = '<tr><td colspan="5" style="text-align:center;color:var(--text3);padding:16px">Sin componentes — agregá productos al kit</td></tr>';
    return;
  }
  tbody.innerHTML = _kitComponentesActual.map(function(c, idx) {
    var subtotal = (c.costo||0) * (c.cantidad||1);
    return '<tr>' +
      '<td>'+escapeHTML(c.nombre||'')+' <span style="color:var(--text3);font-size:11px">('+escapeHTML(c.codigo||'')+')</span></td>' +
      '<td>$'+(c.costo||0).toLocaleString('es-AR')+'</td>' +
      '<td><input type="number" min="1" value="'+(c.cantidad||1)+'" style="width:70px" onchange="actualizarCantidadKit('+idx+',this.value)"></td>' +
      '<td style="font-weight:600">$'+Math.round(subtotal).toLocaleString('es-AR')+'</td>' +
      '<td><button class="btn btn-sm btn-icon" onclick="quitarComponenteKit('+idx+')" style="color:var(--red)"><i class="ti ti-x" style="font-size:14px"></i></button></td>' +
    '</tr>';
  }).join('');
}

function actualizarCantidadKit(idx, val) {
  _kitComponentesActual[idx].cantidad = Math.max(1, parseInt(val)||1);
  renderComponentesKit();
  calcKitTotales();
}

function quitarComponenteKit(idx) {
  _kitComponentesActual.splice(idx, 1);
  renderComponentesKit();
  calcKitTotales();
}

function calcKitTotales() {
  var costoTotal = _kitComponentesActual.reduce(function(s,c){ return s + (c.costo||0)*(c.cantidad||1); }, 0);
  var margenPct  = parseFloat(document.getElementById('kit-margen').value) || 0;
  var margenMonto = costoTotal * margenPct / 100;
  var precioVenta = costoTotal + margenMonto;

  _set('kit-calc-costo', '$' + Math.round(costoTotal).toLocaleString('es-AR'));
  _set('kit-calc-margen', '$' + Math.round(margenMonto).toLocaleString('es-AR'));
  _set('kit-calc-margen-pct', margenPct + '%');
  _set('kit-calc-venta', '$' + Math.round(precioVenta).toLocaleString('es-AR'));
}

function abrirSelectorProductoKit() {
  var modal = document.getElementById('kit-selector-modal');
  if (modal) modal.style.display = 'flex';
  filtrarSelectorKit('');
  setTimeout(function(){ var inp = document.getElementById('kit-sel-buscar'); if(inp) inp.focus(); }, 100);
}

function cerrarSelectorProductoKit() {
  var modal = document.getElementById('kit-selector-modal');
  if (modal) modal.style.display = 'none';
}

function filtrarSelectorKit(texto) {
  var cont = document.getElementById('kit-sel-lista');
  if (!cont) return;
  var lista = Object.values(prodData||{});
  if (texto) {
    var f = texto.toLowerCase();
    lista = lista.filter(function(p){
      return (p.nombre||'').toLowerCase().includes(f) || (p.codigo||'').toLowerCase().includes(f);
    });
  }
  lista = lista.slice(0, 50); // limitar resultados
  if (!lista.length) { cont.innerHTML = '<div style="text-align:center;color:var(--text3);padding:16px">Sin resultados</div>'; return; }
  cont.innerHTML = lista.map(function(p) {
    var yaAgregado = _kitComponentesActual.some(function(c){ return c.pid === p.fbKey || c.codigo === p.codigo; });
    return '<div style="display:flex;align-items:center;justify-content:space-between;padding:8px;border-bottom:0.5px solid var(--border);'+(yaAgregado?'opacity:.4':'cursor:pointer')+'" '+
      (yaAgregado?'':'onclick="agregarComponenteKit(\''+p.fbKey+'\')"') + '>' +
      '<div><div style="font-size:13px">'+escapeHTML(p.nombre||'')+'</div><div style="font-size:11px;color:var(--text3)">'+escapeHTML(p.codigo||'')+' · $'+Math.round(p.compra||0).toLocaleString('es-AR')+'</div></div>' +
      (yaAgregado ? '<span style="font-size:11px;color:var(--text3)">Ya agregado</span>' : '<i class="ti ti-plus" style="color:var(--blue)"></i>') +
    '</div>';
  }).join('');
}

function agregarComponenteKit(pid) {
  var p = Object.values(prodData||{}).find(function(x){ return x.fbKey === pid; });
  if (!p) return;
  _kitComponentesActual.push({ pid: p.fbKey, codigo: p.codigo, nombre: p.nombre, costo: parseFloat(p.compra)||0, cantidad: 1 });
  renderComponentesKit();
  calcKitTotales();
  // Mantener el selector abierto para cargar varios componentes seguidos.
  var buscarKit = document.getElementById('kit-sel-buscar');
  if (buscarKit) { buscarKit.value = ''; buscarKit.focus(); }
  filtrarSelectorKit('');
  notify('✓ ' + p.nombre + ' agregado al kit');
}

function guardarKit() {
  var nombre = document.getElementById('kit-nombre').value.trim();
  if (!nombre) { notify('Ingresá un nombre para el kit'); return; }
  if (!_kitComponentesActual.length) { notify('Agregá al menos un producto al kit'); return; }

  var costoTotal = _kitComponentesActual.reduce(function(s,c){ return s + (c.costo||0)*(c.cantidad||1); }, 0);
  var margenPct  = parseFloat(document.getElementById('kit-margen').value) || 0;
  var precioVenta = costoTotal * (1 + margenPct/100);

  var kit = {
    nombre,
    descripcion:  document.getElementById('kit-descripcion').value.trim(),
    categoria:    document.getElementById('kit-categoria').value,
    componentes:  _kitComponentesActual,
    costoTotal:   Math.round(costoTotal*100)/100,
    margenPct,
    precioVenta:  Math.round(precioVenta*100)/100,
    actualizadoPor: currentUser||'',
    ts: Date.now()
  };

  if (_kitEditandoFbKey) {
    kit.codigo = KITS_DATA[_kitEditandoFbKey].codigo;
    window.fbUpdate(window.fbRef(window.fbDB, 'sisventas/kits/'+_kitEditandoFbKey), kit)
      .then(function(){ notify('✓ Kit actualizado'); volverListaKits(); });
  } else {
    var maxNum = Object.values(KITS_DATA).reduce(function(max,k){
      var n = parseInt((k.codigo||'').replace('KIT-',''))||0;
      return n > max ? n : max;
    }, 0);
    kit.codigo = 'KIT-' + String(maxNum+1).padStart(3,'0');
    window.fbPush(window.fbRef(window.fbDB, 'sisventas/kits'), kit)
      .then(function(){ notify('✓ Kit creado: ' + kit.codigo); volverListaKits(); });
  }
}

async function eliminarKit(fbKey) {
  var k = KITS_DATA[fbKey];
  if (!k) return;
  if (!await svConfirm('¿Eliminar el kit "'+k.nombre+'"? Esta acción no se puede deshacer.')) return;
  window.fbRemove(window.fbRef(window.fbDB, 'sisventas/kits/'+fbKey))
    .then(function(){ notify('Kit eliminado'); });
}

function poblarSelectCategorias() {
  var sel = document.getElementById('filter-cat');
  if (!sel) return;
  var cats = [...new Set(Object.values(prodData||{}).map(function(p){ return p.categoria||p.catId||''; }).filter(Boolean))].sort();
  var actual = sel.value;
  sel.innerHTML = '<option value="">Todas las categorías</option>' +
    cats.map(function(c){ return '<option value="'+escapeHTML(c)+'"'+(c===actual?' selected':'')+'>'+escapeHTML(c)+'</option>'; }).join('');
}

var _prodCatsAbiertas = {}; // undefined = abierta por defecto, false = cerrada
var _filtroProductosSinPrecio = false;
// El catálogo es una vista operativa. Las rutinas canónicas de precios recorren
// moneda, proveedores e historial y deben ejecutarse sólo en la auditoría o en
// la ficha individual; hacerlo cientos de veces durante cada render congela la
// interfaz sin aportar información nueva al listado.
var _prodMetricasListaCache = typeof WeakMap !== 'undefined' ? new WeakMap() : null;
var _prodBusquedaListaCache = typeof WeakMap !== 'undefined' ? new WeakMap() : null;
var _prodCategoriasFirma = '';
var _filtroUsoProductos = 'todos';
var _ordenPrecioProductos = '';

function invalidarMetricasListaProductos() {
  _prodMetricasListaCache = typeof WeakMap !== 'undefined' ? new WeakMap() : null;
  _prodBusquedaListaCache = typeof WeakMap !== 'undefined' ? new WeakMap() : null;
  _prodCategoriasFirma = '';
}

function metricasListaProducto(p) {
  p = p || {};
  if (_prodMetricasListaCache && _prodMetricasListaCache.has(p)) {
    return _prodMetricasListaCache.get(p);
  }
  // El listado rápido evita auditorías costosas para cientos de productos,
  // pero un artículo por metro necesita respetar la misma fuente unitaria que
  // usan la ficha y los selectores de presupuesto/venta.
  if (String(p.unidad || '').toLowerCase() === 'metro') {
    var compraMetro = costoUnitarioProveedorPrincipalProducto(p);
    if (compraMetro > 0) {
      var resultadoMetro = {
        compra: compraMetro,
        venta: precioVentaDesdeCostoUnitarioProducto(p, compraMetro)
      };
      if (_prodMetricasListaCache) _prodMetricasListaCache.set(p, resultadoMetro);
      return resultadoMetro;
    }
  }
  var primerPositivo = function(valores) {
    for (var i = 0; i < valores.length; i++) {
      var numero = parseFloat(valores[i]);
      if (numero > 0 && isFinite(numero)) return numero;
    }
    return 0;
  };
  var principal = Array.isArray(p.proveedores) && p.proveedores.length ? p.proveedores[0] : null;
  var compra = primerPositivo([
    p.compraARS, p.precioGremio, p.compra, p.costoRealArs,
    p.precioArsPublicado,
    principal && principal.costoRealArs,
    principal && principal.precioArsPublicado,
    principal && principal.precio
  ]);
  var venta = primerPositivo([
    p.ventaARS, p.precioArsPublicadoVenta, p.venta,
    p.precio_venta, p.precioVenta
  ]);
  var tcConfig = window.TIPO_CAMBIO_CONFIG || {};
  var claveTc = tcConfig.dolarConversion || 'oficial';
  var tc = parseFloat(p.dolarUsadoVenta || p.dolarUsado || tcConfig[claveTc] || tcConfig.oficial) || 0;
  if (compra > 0 && String(p.moneda || '').toUpperCase() === 'USD' && !(parseFloat(p.compraARS) > 0) && tc > 0) {
    compra = Math.round(compra * tc * 100) / 100;
  }
  if (venta > 0 && String(p.monedaVenta || p.moneda || '').toUpperCase() === 'USD' && !(parseFloat(p.ventaARS) > 0) && tc > 0) {
    venta = Math.round(venta * tc * 100) / 100;
  }
  var resultado = { venta: venta, compra: compra };
  if (_prodMetricasListaCache) _prodMetricasListaCache.set(p, resultado);
  return resultado;
}

function productoSinPrecioCatalogo(p) {
  return !(metricasListaProducto(p).venta > 0);
}

function cambiarFiltroUsoProductos(valor) {
  _filtroUsoProductos = String(valor || 'todos');
  renderTablaProductos((document.getElementById('prod-search') || {}).value || '');
}

function cambiarOrdenPrecioProductos(valor) {
  _ordenPrecioProductos = String(valor || '');
  renderTablaProductos((document.getElementById('prod-search') || {}).value || '');
}

function actualizarVistaFiltroProductosSinPrecio(cantidad) {
  var card = document.getElementById('stat-prod-sinprecio-card');
  if (card) {
    card.setAttribute('aria-pressed', _filtroProductosSinPrecio ? 'true' : 'false');
    card.title = _filtroProductosSinPrecio
      ? 'Quitar el filtro de productos sin precio'
      : 'Mostrar únicamente los productos sin precio';
    card.style.borderColor = _filtroProductosSinPrecio ? 'var(--amber)' : '';
    card.style.boxShadow = _filtroProductosSinPrecio ? '0 0 0 1px var(--amber)' : '';
    card.style.background = _filtroProductosSinPrecio ? 'rgba(245,158,11,.08)' : '';
  }
  var chip = document.getElementById('prod-filtro-sinprecio-activo');
  if (chip) {
    chip.innerHTML = '<i class="ti ti-filter"></i> Solo sin precio (' + (parseInt(cantidad, 10) || 0) + ') <i class="ti ti-x"></i>';
    chip.style.display = _filtroProductosSinPrecio ? 'inline-flex' : 'none';
  }
  var sub = document.getElementById('stat-prod-sinprecio-sub');
  if (sub) sub.textContent = _filtroProductosSinPrecio ? 'filtro activo · tocá para quitar' : 'tocá para filtrar';
}

function toggleFiltroProductosSinPrecio() {
  _filtroProductosSinPrecio = !_filtroProductosSinPrecio;
  if (_filtroProductosSinPrecio) {
    // El KPI es global: al abrirlo se eliminan filtros residuales para que la
    // grilla demuestre exactamente la cantidad informada por la tarjeta.
    var buscar = document.getElementById('prod-search');
    var categoria = document.getElementById('filter-cat');
    var uso = document.getElementById('prod-uso-filter');
    if (buscar) buscar.value = '';
    if (categoria) categoria.value = '';
    if (uso) uso.value = 'todos';
    window._prodCategoriaFiltro = '';
    _filtroUsoProductos = 'todos';
  }
  actualizarStatProductos();
  renderTablaProductos((document.getElementById('prod-search') || {}).value || '');
}

function _prodTextosBusqueda(p) {
  p = p || {};
  var proveedores = [];
  if (Array.isArray(p.proveedores)) {
    proveedores = p.proveedores.map(function(pr){ return pr && (pr.nombre || pr.proveedor || pr.name || pr.url) || ''; });
  }
  if (p.proveedor) proveedores.push(p.proveedor);
  if (p.proveedorNombre) proveedores.push(p.proveedorNombre);
  return {
    todo: [
      p.codigo, p.sku, p.nombre, p.descripcion, p.marca, p.categoria, p.catId,
      p.proveedor, p.proveedorNombre, proveedores.join(' ')
    ].join(' '),
    nombre: p.nombre || p.descripcion || '',
    marca: p.marca || '',
    codigo: [p.codigo, p.sku].join(' '),
    descripcion: p.descripcion || '',
    proveedor: proveedores.join(' '),
    categoria: p.categoria || p.catId || ''
  };
}

function _prodNormalizarBusqueda(valor) {
  return String(valor || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, ' ').trim();
}

function _prodTextosBusquedaNormalizados(p) {
  if (_prodBusquedaListaCache && _prodBusquedaListaCache.has(p)) return _prodBusquedaListaCache.get(p);
  var textos = _prodTextosBusqueda(p);
  var normalizados = {};
  Object.keys(textos).forEach(function(campo) { normalizados[campo] = _prodNormalizarBusqueda(textos[campo]); });
  if (_prodBusquedaListaCache) _prodBusquedaListaCache.set(p, normalizados);
  return normalizados;
}

function _prodCoincideBusqueda(p, filtro) {
  var q = _prodNormalizarBusqueda(filtro);
  if (!q) return true;
  var campo = (document.getElementById('prod-search-field') || {}).value || 'todo';
  var textos = _prodTextosBusquedaNormalizados(p);
  var base = textos[campo] !== undefined ? textos[campo] : textos.todo;
  return q.split(/\s+/).every(function(parte){ return base.includes(parte); });
}

function _renderFilaProd(p) {
  var stk = parseInt(p.stock) || 0;
  var stkColor = stk <= 0 ? 'var(--red)' : stk <= (p.stockMin||2) ? 'var(--amber)' : 'var(--green)';
  var metricas = metricasListaProducto(p);
  var pv = metricas.venta;
  var pc = metricas.compra;
  var margen = pv > 0 && pc > 0 ? ((pv-pc)/pv*100).toFixed(1) + '%' : '—';
  var pid = String(p.fbKey || '').replace(/"/g,'');
  var activo = p.activo !== false && String(p.estado || 'activo').toLowerCase() !== 'inactivo';
  var provLista = Array.isArray(p.proveedores) ? p.proveedores : [];
  var tc = window.TIPO_CAMBIO_CONFIG || {};
  var cotiz = parseFloat(tc[tc.dolarConversion || 'oficial']) || 0;
  var pcFmt = (parseFloat(pc)||0).toLocaleString('es-AR', {minimumFractionDigits:2, maximumFractionDigits:2});
  var costoLbl = '$' + pcFmt;
  if (provLista.length > 1) {
    costoLbl += ' <span class="badge b-green" style="font-size:9px">' + provLista.length + ' prov.</span>';
  }
  var nombreProvLbl = provLista.length === 1 ? '<br><span style="font-size:10px;color:var(--text3);font-weight:400">' + escapeHTML(provLista[0].nombre||'') + '</span>' : '';
  var pvFmt = (parseFloat(pv)||0).toLocaleString('es-AR', {minimumFractionDigits:2, maximumFractionDigits:2});
  var imagenVisual = urlImagenProductoVisual(p, '');
  return '<tr class="cr pr" data-pid="'+pid+'" data-cat="'+(p.categoria||'')+'" onclick="verProductoById(this)" style="cursor:pointer;'+(activo?'':'opacity:.62')+'">' +
    '<td>'+(imagenVisual?'<img class="prod-row-img" src="'+escapeHTML(imagenVisual)+'" loading="lazy" decoding="async" onerror="this.style.display=\'none\'">'
      :'<div class="prod-row-img prod-row-img-placeholder"><i class="ti ti-photo"></i></div>')+'</td>'+
    '<td style="font-family:monospace;font-size:12px">'+(p.codigo||'')+'</td>'+
    '<td style="font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+(p.esManoDeObra?'<i class="ti ti-tool" style="font-size:13px;color:var(--blue);margin-right:4px"></i>':'')+(p.nombre||p.descripcion||'')+'</td>'+
    '<td class="hide-mobile" style="font-size:12px;color:var(--text3);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+(p.descripcion||'—')+'</td>'+
    '<td style="text-align:right;font-weight:600;color:'+stkColor+'">'+stk+'</td>'+
    '<td style="text-align:right">$'+pvFmt+'</td>'+
    '<td style="text-align:right">'+costoLbl+'</td>'+
    '<td style="text-align:right;color:var(--green)">'+margen+nombreProvLbl+'</td>'+
    '<td style="padding-left:12px">'+
      '<label class="toggle-sw" onclick="event.stopPropagation()" title="'+(activo?'Desactivar':'Activar')+' producto" style="vertical-align:middle;margin-right:5px"><input type="checkbox" '+(activo?'checked':'')+' onchange="event.stopPropagation();toggleActivoProducto(\''+pid+'\',this.checked)"><span class="toggle-knob"></span></label>'+
      '<button class="icon-btn" data-pid="'+pid+'" onclick="event.stopPropagation();editarProductoById(this)" title="Editar"><i class="ti ti-pencil" style="font-size:15px"></i></button>'+
      '<button class="icon-btn" data-pid="'+pid+'" onclick="event.stopPropagation();eliminarProducto(this)" title="Eliminar" style="color:var(--text3)" onmouseenter="this.style.color=\'var(--red)\'" onmouseleave="this.style.color=\'var(--text3)\'"><i class="ti ti-trash" style="font-size:15px"></i></button></td>'+
  '</tr>';
}

function renderTablaProductos(filtro) {
  var tbody = document.getElementById('prod-tbody');
  if (!tbody) return;
  // Los refrescos en tiempo real posteriores a guardar o eliminar no deben
  // borrar la búsqueda que el usuario todavía ve en pantalla.
  if (filtro === undefined || filtro === null) {
    filtro = (document.getElementById('prod-search') || {}).value || '';
  }
  var lista = prodData ? Object.values(prodData) : [];
  if (!_prodCategoriasFirma) {
    poblarSelectCategorias();
    _prodCategoriasFirma = 'lista-vigente';
  }
  var catFiltro = window._prodCategoriaFiltro || (document.getElementById('filter-cat')||{}).value || '';
  if (catFiltro) lista = lista.filter(function(p){ return String(p.categoria || p.catId || 'Sin categoría') === String(catFiltro); });
  if (_filtroProductosSinPrecio) lista = lista.filter(productoSinPrecioCatalogo);
  if (_filtroUsoProductos === 'sinventas') lista = lista.filter(function(p){ return !productoTieneVentasHistoricas(p); });
  if (_filtroUsoProductos === 'inactivos') lista = lista.filter(function(p){ return p.activo === false || String(p.estado || '').toLowerCase() === 'inactivo'; });
  // Ordenamiento específico y liviano: trabaja sobre los productos que esta
  // grilla ya va a dibujar, sin observadores globales ni recorridos del DOM.
  var ordenProductos = _sortState['prod-tbl'];
  function ordenarProductos(items) {
    if (_ordenPrecioProductos) {
      var partesOrdenPrecio = _ordenPrecioProductos.split('-');
      var campoPrecio = partesOrdenPrecio[0] === 'compra' ? 'compra' : 'venta';
      var dirPrecio = partesOrdenPrecio[1] === 'asc' ? 1 : -1;
      return items.slice().sort(function(a,b){ return (metricasListaProducto(a)[campoPrecio] - metricasListaProducto(b)[campoPrecio]) * dirPrecio; });
    }
    if (!ordenProductos || !ordenProductos.col) {
      return items.slice().sort(function(a,b){ return (a.nombre||'').localeCompare(b.nombre||''); });
    }
    var dir = ordenProductos.dir === 'desc' ? -1 : 1;
    return items.slice().sort(function(a,b) {
      function valor(p) {
        if (ordenProductos.col === 'codigo') return p.codigo || p.cod || '';
        if (ordenProductos.col === 'nombre') return p.nombre || p.nombreCorto || '';
        if (ordenProductos.col === 'descrip') return p.descripcion || p.descripcionLarga || '';
        if (ordenProductos.col === 'stock') return p.stock || 0;
        if (ordenProductos.col === 'venta') return metricasListaProducto(p).venta;
        if (ordenProductos.col === 'compra') return metricasListaProducto(p).compra;
        if (ordenProductos.col === 'margen') {
          var venta = metricasListaProducto(p).venta;
          var compra = metricasListaProducto(p).compra;
          return venta > 0 && compra > 0 ? (venta-compra)/venta*100 : 0;
        }
        return p[ordenProductos.col];
      }
      var va = valor(a), vb = valor(b);
      if (['stock','venta','compra','margen'].indexOf(ordenProductos.col) >= 0) {
        return ((parseFloat(va)||0) - (parseFloat(vb)||0)) * dir;
      }
      return String(va||'').localeCompare(String(vb||''), 'es', {numeric:true, sensitivity:'base'}) * dir;
    });
  }

  // Con búsqueda activa → vista plana
  if (filtro && filtro.trim()) {
    lista = lista.filter(function(p) { return _prodCoincideBusqueda(p, filtro); });
    lista = ordenarProductos(lista);
    if (!lista.length) {
      tbody.innerHTML = '<tr><td colspan="9" style="text-align:center;padding:24px;color:var(--text3)">'+(_filtroProductosSinPrecio ? 'No hay productos sin precio que coincidan con la búsqueda "'+escapeHTML(filtro)+'"' : 'Sin resultados para "'+escapeHTML(filtro)+'"')+'</td></tr>';
      _estadoBusquedaProductos('0 resultados', 'ok');
      return;
    }
    tbody.innerHTML = lista.map(_renderFilaProd).join('');
    prepararAccionesGrilla('prod-tbl');
    _estadoBusquedaProductos(lista.length + ' resultado' + (lista.length === 1 ? '' : 's'), 'ok');
    return;
  }

  // Sin búsqueda → vista agrupada por categoría
  window._prodGrupos = {};
  var grupos = window._prodGrupos;
  lista.forEach(function(p) {
    var cat = p.categoria || p.catId || 'Sin categoría';
    if (!grupos[cat]) grupos[cat] = [];
    grupos[cat].push(p);
  });
  var cats = Object.keys(grupos).sort(function(a,b){ return a.localeCompare(b); });

  if (!cats.length) {
    tbody.innerHTML = '<tr><td colspan="9" style="text-align:center;padding:24px;color:var(--text3)">'+(_filtroProductosSinPrecio ? 'No hay productos sin precio'+(catFiltro ? ' en esta categoría' : '') : 'Sin productos cargados')+'</td></tr>';
    return;
  }

  var html = '';
  cats.forEach(function(cat) {
    var prods = ordenarProductos(grupos[cat]);
    var abierta = _prodCatsAbiertas[cat] !== false; // abierta por defecto
    var catId = 'cat-' + cat.replace(/[^a-zA-Z0-9]/g,'_');
    var catStyle = 'cursor:pointer;background:var(--bg3);border-left:3px solid var(--blue);user-select:none';
    var iconStyle = 'font-size:10px;color:var(--blue);display:inline-block;transition:transform .2s;' + (abierta ? 'transform:rotate(90deg)' : '');
    html += '<tr class="prod-cat-row" onclick="toggleProdCat(\''+escapeHTML(cat)+'\')" style="'+catStyle+'">' +
      '<td colspan="9" style="padding:12px 14px">' +
      '<div style="display:flex;align-items:center;gap:10px">' +
      '<span id="icon-'+catId+'" style="'+iconStyle+'">&#9658;</span>' +
      '<span style="font-size:13px;font-weight:600;color:var(--text)">'+escapeHTML(cat)+'</span>' +
      '<span style="font-size:11px;color:var(--text3);background:var(--bg2);border:0.5px solid var(--border);border-radius:99px;padding:1px 8px">'+prods.length+' producto'+(prods.length!==1?'s':'')+'</span>' +
      '</div></td></tr>';
    if (abierta) {
      html += prods.map(_renderFilaProd).join('');
    }
  });
  tbody.innerHTML = html;
  prepararAccionesGrilla('prod-tbl');
  _estadoBusquedaProductos('');
}

var _todasColapsadas = false;

function toggleTodasCats() {
  _todasColapsadas = !_todasColapsadas;
  Object.keys(window._prodGrupos || {}).forEach(function(cat) {
    _prodCatsAbiertas[cat] = !_todasColapsadas;
  });
  // Re-renderizar la tabla
  renderTablaProductos((document.getElementById('prod-search')||{}).value||'');
  var label = document.getElementById('label-colapsar-cats');
  var icon  = document.getElementById('icon-colapsar-cats');
  if (label) label.textContent = _todasColapsadas ? 'Expandir todo' : 'Colapsar todo';
  if (icon)  icon.className = _todasColapsadas ? 'ti ti-layout-rows' : 'ti ti-layout-list';
}

function toggleProdCat(cat) {
  _prodCatsAbiertas[cat] = (_prodCatsAbiertas[cat] === true) ? false : true;
  var abierta = _prodCatsAbiertas[cat] !== false;
  var catId = 'cat-' + cat.replace(/[^a-zA-Z0-9]/g,'_');
  var icon = document.getElementById('icon-'+catId);
  if (icon) icon.style.transform = abierta ? 'rotate(90deg)' : '';
  // Re-renderizar solo las filas de esa categoría
  var tbody = document.getElementById('prod-tbody');
  if (!tbody) return;
  var rows = tbody.querySelectorAll('.cr[data-cat="'+CSS.escape(cat)+'"]');
  if (abierta) {
    // Necesita re-render completo para insertar filas
    renderTablaProductos((document.getElementById('prod-search')||{}).value||'');
  } else {
    rows.forEach(function(r){ r.remove(); });
  }
}

var _prodBusquedaTimer = null;
function _estadoBusquedaProductos(texto, tipo) {
  var el = document.getElementById('prod-search-status');
  if (!el) return;
  el.style.color = tipo === 'ok' ? 'var(--green)' : 'var(--text3)';
  el.innerHTML = texto || '';
}
function buscarProducto(val) {
  var texto = String(val || '');
  clearTimeout(_prodBusquedaTimer);
  if (!texto.trim()) {
    _estadoBusquedaProductos('');
    renderTablaProductos('');
    return;
  }
  _estadoBusquedaProductos('<i class="ti ti-loader-2 ti-spin"></i> Buscando...');
  _prodBusquedaTimer = setTimeout(function() { renderTablaProductos(texto); }, 120);
}
function verProductoById(el) {
  var tr = el.closest ? el.closest('[data-pid]') : el;
  var pid = tr ? tr.dataset.pid : el.dataset.pid;
  var p = prodData ? Object.values(prodData).find(function(x){ return String(x.fbKey) === String(pid); }) : null;
  if (p) verProducto(p.fbKey);
}
function editarProductoById(el) {
  var pid = el.dataset.pid;
  var p = prodData ? Object.values(prodData).find(function(x){ return String(x.fbKey) === String(pid); }) : null;
  if (p) editarProducto(p.fbKey);
}
function editarProducto(id) { abrirFormProducto(id); }
function volverListaVentas() {
  var dv  = document.getElementById('venta-detalle-view');
  var lv  = document.getElementById('ventas-list-view') || document.getElementById('venta-list-view');
  var origen = window._ventaDesdeHistorialOrigen;
  if (origen) {
    window._ventaDesdeHistorialOrigen = null;
    if (dv)  dv.style.display  = 'none';
    var st1o = document.getElementById('ventas-list-stats-global');
    if (st1o) st1o.style.display = '';
    showPage(origen, null);
    if (origen === 'gastos' && window._gastosRetornoVenta) {
      setTimeout(function() {
        var estado = window._gastosRetornoVenta || {};
        ['gas-buscar','gas-f-mes','gas-f-tipo','gas-f-estado','gas-f-empleado'].forEach(function(id) {
          var campo = document.getElementById(id);
          if (campo && estado[id] != null) campo.value = estado[id];
        });
        window._filtroGastosKpiActivo = estado.kpi || '';
        if (typeof filtrarGastos === 'function') filtrarGastos(true);
        window._gastosRetornoVenta = null;
      }, 80);
    }
    return;
  }
  if (dv)  dv.style.display  = 'none';
  var st1 = document.getElementById('ventas-list-stats-global');
  if (st1) st1.style.display = '';
  if (lv)  lv.style.display  = '';
  _restaurarControlesFiltrosVentas();
  _aplicarFiltrosVentas();
}
function actualizarSugerenciasCliente() {
  // el filterCli funcione con los datos reales
}
// DROPDOWN GLOBAL DE BÚSQUEDA — todos los buscadores del sistema
// position:fixed, nunca cortado por ningún contenedor
var _gDropEl = null;
var _gDropInputRef = null;

function _crearDropBusqueda() {
  if (document.getElementById('busq-drop-global')) return document.getElementById('busq-drop-global');
  var d = document.createElement('div');
  d.id = 'busq-drop-global';
  d.style.cssText = 'display:none;position:fixed;z-index:9998;background:var(--bg2);border:0.5px solid var(--border2);border-radius:var(--radius);box-shadow:0 4px 16px rgba(0,0,0,.14);max-height:260px;overflow-y:auto';
  document.body.appendChild(d);
  var _closeDrop = function(e) {
    var drop = document.getElementById('busq-drop-global');
    if (drop && !drop.contains(e.target) && e.target !== _gDropInputRef) {
      drop.style.display = 'none';
    }
  };
  document.addEventListener('mousedown',  _closeDrop);
  document.addEventListener('touchstart', _closeDrop, {passive:true});
  window.addEventListener('scroll', function(){ var d=document.getElementById('busq-drop-global'); if(d) d.style.display='none'; }, true);
  return d;
}

function _mostrarDropGlobal(inputEl, html) {
  var d = _crearDropBusqueda();
  _gDropEl = d;
  _gDropInputRef = inputEl;
  d.innerHTML = html;
  d.style.display = 'block';
  var rect = inputEl.getBoundingClientRect();
  d.style.top   = (rect.bottom + 3) + 'px';
  d.style.left  = rect.left + 'px';
  d.style.width = Math.max(rect.width, 260) + 'px';
  var dr = d.getBoundingClientRect();
  if (dr.right  > window.innerWidth  - 8) d.style.left = Math.max(8, window.innerWidth  - dr.width  - 8) + 'px';
  if (dr.bottom > window.innerHeight - 8) d.style.top  = Math.max(8, rect.top - dr.height - 3) + 'px';
}

function _ocultarDropGlobal() {
  var d = document.getElementById('busq-drop-global');
  if (d) d.style.display = 'none';
}

function filterCli(val) {
  var v = (typeof val === 'string' ? val : '').trim().toLowerCase();
  var inp = document.getElementById('cli-inp');
  if (!inp) return;
  var fbSeleccionado = String((document.getElementById('cli-fbkey') || {}).value || '');
  var clienteSeleccionado = (clientesData || []).find(function(c){ return String(c.fbKey || '') === fbSeleccionado; });
  if (fbSeleccionado && (!clienteSeleccionado || String(clienteSeleccionado.nombre || '').trim().toLowerCase() !== v)) {
    var fbLimpiar = document.getElementById('cli-fbkey'); if (fbLimpiar) fbLimpiar.value = '';
    var idLimpiar = document.getElementById('id-cli'); if (idLimpiar) idLimpiar.value = '';
    var dirLimpiar = document.getElementById('cli-dir-hidden'); if (dirLimpiar) dirLimpiar.value = '';
    mostrarDomicilioOperacionSeleccionado('cli-domicilio-seleccion', null);
  }
  var lista = (clientesData || []).filter(function(c){ return c && c.activo !== false; });
  var matches = v
    ? lista.filter(function(c){ return (c.nombre||'').toLowerCase().includes(v)||(c.empresa||'').toLowerCase().includes(v)||String(c.id||'').includes(v); })
    : lista.slice(0,8);
  if (!matches.length) { _ocultarDropGlobal(); return; }
  var html = matches.slice(0,10).map(function(c) {
    var empresa = c.empresa ? '<div style="font-size:11px;color:var(--text3)">'+escapeHTML(c.empresa)+'</div>' : '';
    var categoria = _clienteCategoriaSede(c) || 'Domicilio';
    return '<div class="di" style="padding:8px 12px;cursor:pointer;border-bottom:0.5px solid var(--border)" onmousedown="_gSelCliById(\''+String(c.fbKey||c.id)+'\')">' +
      '<div style="font-weight:500;font-size:13px">'+escapeHTML(c.nombre)+'</div>'+empresa+
      '<div style="font-size:11px;color:var(--text3)"><strong>'+escapeHTML(categoria)+'</strong>'+(c.dir?' · '+escapeHTML(c.dir):'')+(c.telefono?' · '+escapeHTML(c.telefono):'')+'</div>'+
    '</div>';
  }).join('');
  _mostrarDropGlobal(inp, html);
}

function _gSelCliById(id) {
  var c = (clientesData||[]).find(function(x){ return String(x.fbKey||'')===String(id) || String(x.id)===String(id); });
  if (!c) return;
  selCli(c.id, c.nombre, c.dir||c.direccion||c.domicilio||'', c.fbKey||c.id||'');
}

function selCli(id, nombre, dir, fbKey) {
  var inp  = document.getElementById('cli-inp');
  var idEl = document.getElementById('id-cli');
  var dirEl= document.getElementById('cli-dir-hidden');
  var fbEl = document.getElementById('cli-fbkey');
  if (inp)  inp.value  = nombre;
  if (idEl) idEl.value = String(id).padStart(4,'0');
  if (dirEl)dirEl.value= dir || '';
  if (fbEl) fbEl.value = fbKey || '';
  var cliente = (clientesData || []).find(function(c){ return String(c.fbKey || c.id || '') === String(fbKey || id || ''); });
  mostrarDomicilioOperacionSeleccionado('cli-domicilio-seleccion', cliente);
  _ocultarDropGlobal();
}

function mostrarDomicilioOperacionSeleccionado(elementoId, cliente) {
  var el = document.getElementById(elementoId);
  if (!el) return;
  if (!cliente) { el.style.display = 'none'; el.textContent = ''; return; }
  var vinculo = clienteVinculoOperacion(cliente);
  var domicilioId = String(cliente.id || '').trim();
  var domicilioIdVisible = domicilioId ? domicilioId.padStart(4, '0') : 'Sin ID';
  el.style.display = '';
  el.innerHTML = '<i class="ti ti-map-pin"></i> <strong>Domicilio ID '+escapeHTML(domicilioIdVisible)+'</strong> · '+escapeHTML(vinculo.domicilioCategoria)+(vinculo.direccion ? ' · '+escapeHTML(vinculo.direccion) : ' · Sin dirección cargada');
}
// $n(num) → "1.234.567" | $m(num) → "$1.234.567" | $p(str) → float
window.$n = function(n, dec) {
  return (parseFloat(n)||0).toLocaleString('es-AR', {
    minimumFractionDigits: dec||0, maximumFractionDigits: dec||0
  });
};
window.$m = function(n, dec) { return '$' + window.$n(n, dec); };
function svFechaLocalISO(fecha) {
  var d = fecha instanceof Date ? fecha : new Date(fecha == null ? Date.now() : fecha);
  if (isNaN(d.getTime())) d = new Date();
  return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
}
function svMesLocalISO(fecha) { return svFechaLocalISO(fecha).slice(0, 7); }
window.svFechaLocalISO = svFechaLocalISO;
window.svMesLocalISO = svMesLocalISO;
window.$p = function(s) {
  s = String(s||'').replace(/[^0-9,.-]/g,'');
  if (s.includes('.') && s.includes(',')) {
    return s.lastIndexOf(',') > s.lastIndexOf('.')
      ? parseFloat(s.replace(/\./g,'').replace(',','.'))
      : parseFloat(s.replace(/,/g,''));
  }
  if (s.includes('.')) {
    var p = s.split('.');
    if (p.length > 2 || (p.length===2 && p[1].length===3)) s = s.replace(/\./g,'');
    return parseFloat(s)||0;
  }
  if (s.includes(',')) {
    var p2 = s.split(',');
    if (p2.length > 2 || (p2.length===2 && p2[1].length===3)) s = s.replace(/,/g,'');
    else s = s.replace(',','.');
  }
  return parseFloat(s)||0;
};
