async function headersCotizadorProtegido(forzarRenovacion) {
  var usuarioFirebase = window.fbAuth && window.fbAuth.currentUser;
  if (!usuarioFirebase || typeof usuarioFirebase.getIdToken !== 'function') {
    throw new Error('La sesión venció. Volvé a ingresar para usar el cotizador.');
  }
  var token = await usuarioFirebase.getIdToken(forzarRenovacion === true);
  if (!token) throw new Error('No se pudo validar la sesión del cotizador');
  return {
    'Content-Type': 'application/json',
    'X-Frontend-Key': SISVENTAS_FUNCTIONS.frontendKey,
    'Authorization': 'Bearer ' + token
  };
}

function normalizarIdentidadCliente(valor) {
  return String(valor||'').toLowerCase().trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'');
}

function resolverClienteDeVenta(venta) {
  if (!venta) return null;
  var clientes = Array.isArray(clientesData) ? clientesData : Object.values(clientesData||{});
  var ids = [venta.clienteFbKey, venta.clienteKey, venta.clienteId, venta.idCliente, venta.idClienteOriginal, venta.fbKeyCliente, venta.id_cli].filter(Boolean).map(String);
  if (ids.length) {
    var porId = clientes.find(function(cliente) {
      return [cliente.fbKey, cliente.id, cliente.key, cliente.codigo].filter(Boolean).map(String).some(function(id){ return ids.includes(id); });
    });
    if (porId) return porId;
  }
  var buscado = normalizarIdentidadCliente(venta.cliente || venta.clienteNombre || venta.razonSocial || '');
  if (!buscado) return null;
  return clientes.find(function(cliente) {
    var nombre = cliente.nombre || cliente.nombre1 || '';
    var apellido = cliente.apellido || cliente.apellidos || '';
    return [nombre, nombre+' '+apellido, apellido+' '+nombre, cliente.empresa, cliente.razonSocial, cliente.razon_social, cliente.cliente]
      .filter(Boolean).map(normalizarIdentidadCliente).includes(buscado);
  }) || null;
}

function obtenerCuitClienteVenta(venta) {
  var cliente = resolverClienteDeVenta(venta);
  var valor = venta.clienteCuit || venta.cuitCliente || venta.cuit || (cliente && (cliente.cuit || cliente.CUIT || cliente.cuitDni || cliente.documentoFiscal || cliente.dniFiscal)) || '';
  var digitos = String(valor).replace(/\D/g,'');
  return digitos.length === 11 ? digitos : '';
}

function esperarReintentoCotizador(ms, signal) {
  return new Promise(function(resolve, reject) {
    if (signal && signal.aborted) {
      reject(new DOMException('Proceso detenido', 'AbortError'));
      return;
    }
    var timer = setTimeout(resolve, ms);
    if (signal) signal.addEventListener('abort', function() {
      clearTimeout(timer);
      reject(new DOMException('Proceso detenido', 'AbortError'));
    }, { once:true });
  });
}

async function solicitarLoteCotizadorConReintentos(payload, signal, alReintentar) {
  var demoras = [2000, 5000, 10000];
  var ultimoError = null;
  for (var intento = 0; intento <= demoras.length; intento++) {
    try {
      var respuesta = await fetch(SISVENTAS_FUNCTIONS.cotizadorProveedor + '/cotizar-lote', {
        method:'POST',
        headers:await headersCotizadorProtegido(intento > 0 && ultimoError && ultimoError.status === 401),
        signal:signal,
        body:JSON.stringify(payload)
      });
      var texto = await respuesta.text();
      var datos = null;
      try { datos = texto ? JSON.parse(texto) : null; } catch (errorJson) {}
      if (respuesta.ok) return { respuesta:respuesta, datos:datos };
      var errorHttp = new Error((datos && (datos.mensaje || datos.error)) || ('El cotizador respondió HTTP ' + respuesta.status));
      errorHttp.status = respuesta.status;
      errorHttp.transitorio = [401, 429, 500, 502, 503, 504].indexOf(respuesta.status) >= 0;
      throw errorHttp;
    } catch (error) {
      if ((signal && signal.aborted) || (error && error.name === 'AbortError')) throw error;
      ultimoError = error;
      var esRed = /failed to fetch|networkerror|network request failed/i.test(String(error && error.message || error));
      var puedeReintentar = error && error.transitorio || esRed;
      if (!puedeReintentar || intento >= demoras.length) throw error;
      if (typeof alReintentar === 'function') alReintentar(intento + 1, demoras.length, error);
      await esperarReintentoCotizador(demoras[intento], signal);
    }
  }
  throw ultimoError || new Error('No se pudo consultar el cotizador');
}

function obtenerRazonSocialClienteVenta(venta) {
  var cliente = resolverClienteDeVenta(venta);
  return String(
    venta.clienteRazonSocial || venta.razonSocialFiscal || venta.razon_social ||
    (cliente && (cliente.razonSocial || cliente.razon_social)) || ''
  ).trim();
}

function validarCuitArgentino(valor) {
  var cuit = String(valor || '').replace(/\D/g, '');
  if (!/^\d{11}$/.test(cuit)) return false;
  var pesos = [5,4,3,2,7,6,5,4,3,2];
  var suma = pesos.reduce(function(total, peso, i){ return total + parseInt(cuit[i],10) * peso; }, 0);
  var verificador = 11 - (suma % 11);
  if (verificador === 11) verificador = 0;
  else if (verificador === 10) verificador = 9;
  return verificador === parseInt(cuit[10], 10);
}

async function consultarCuitClienteEnArca() {
  var campo = document.getElementById('nc-cuit');
  var boton = document.getElementById('btn-consultar-cuit-arca');
  var cuit = String((campo || {}).value || '').replace(/\D/g, '');
  if (!validarCuitArgentino(cuit)) { notify('Ingresá un CUIT válido de 11 dígitos'); if (campo) campo.focus(); return; }
  var textoAnterior = boton ? boton.innerHTML : '';
  if (boton) { boton.disabled=true; boton.innerHTML='<i class="ti ti-loader-2 ti-spin"></i> Consultando ARCA...'; }
  try {
    var respuesta = await fetch(SISVENTAS_FUNCTIONS.emitirFactura, {
      method:'POST', headers:{ 'Content-Type':'application/json', 'X-Frontend-Key':SISVENTAS_FUNCTIONS.frontendKey },
      body:JSON.stringify({ accion:'consultar_cuit', cuit:cuit })
    });
    var resultado = await respuesta.json().catch(function(){ return {}; });
    if (!respuesta.ok || resultado.error || !resultado.datos) throw new Error(resultado.mensaje || 'No se encontraron datos para este CUIT');
    mostrarVistaPreviaCuitArca(resultado.datos, resultado.advertencias || []);
  } catch (e) {
    notify('No se pudo consultar el CUIT: ' + e.message);
  } finally {
    if (boton) { boton.disabled=false; boton.innerHTML=textoAnterior; }
  }
}

