var notifT;
var PERMISOS_DEFAULT = {
  admin:          { bloqueados: [] },
  administrativo: { bloqueados: ['usuarios','configuracion','rentabilidad','tesoreria'] },
  vendedor:       { bloqueados: ['usuarios','configuracion','rentabilidad','empleados','vacaciones','reportes','estadisticas','proveedores','ordenes','cuentacorriente','creditofiscal','facturas','gastos','tesoreria','actualizadorprecios','tablero'] },
  tecnico_vendedor:{ bloqueados: ['usuarios','configuracion','rentabilidad','empleados','vacaciones','reportes','estadisticas','proveedores','ordenes','cuentacorriente','creditofiscal','facturas','gastos','tesoreria','actualizadorprecios','tablero'] },
  tecnico:        { bloqueados: ['usuarios','configuracion','rentabilidad','empleados','vacaciones','reportes','estadisticas','proveedores','ordenes','cuentacorriente','detalle','venta','presupuesto','cobranzas','creditofiscal','facturas','caja','gastos','clientes','productos','kits','tesoreria','actualizadorprecios','asistente','tablero'] }
};
var PERMISOS_ROLES = JSON.parse(JSON.stringify(PERMISOS_DEFAULT));
// Los permisos se guardaban antes de que existieran varios módulos. Al leer una
// configuración anterior se incorporan solamente los módulos nuevos que, por
// defecto, están bloqueados para ese rol. Así Kits no queda abierto para un
// técnico por la mera ausencia de la casilla en una configuración histórica.
// Una vez guardada la tabla actualizada, _version permite que el admin decida
// explícitamente cualquier excepción sin que una carga posterior la revierta.
var PERMISOS_VERSION_ACTUAL = 4;
var MODULOS_AGREGADOS_A_PERMISOS = ['asistente','kits','actualizadorprecios','ctaemp','tesoreria','notificaciones','tablero','facturas'];
function normalizarPermisosRolesGuardados(data) {
  var origen = data && typeof data === 'object' ? data : {};
  var version = Number(origen._version || 0);
  var normalizados = {};
  Object.keys(PERMISOS_DEFAULT).forEach(function(rol) {
    var guardado = origen[rol] && Array.isArray(origen[rol].bloqueados)
      ? origen[rol].bloqueados.slice()
      : (PERMISOS_DEFAULT[rol].bloqueados || []).slice();
    var permitidos = origen[rol] && Array.isArray(origen[rol].permitidos)
      ? origen[rol].permitidos.slice()
      : [];
    var acciones = origen[rol] && origen[rol].acciones && typeof origen[rol].acciones === 'object'
      ? JSON.parse(JSON.stringify(origen[rol].acciones))
      : {};
    if (version < PERMISOS_VERSION_ACTUAL) {
      MODULOS_AGREGADOS_A_PERMISOS.forEach(function(modulo) {
        if ((PERMISOS_DEFAULT[rol].bloqueados || []).includes(modulo) && !guardado.includes(modulo)) {
          guardado.push(modulo);
        }
      });
    }
    normalizados[rol] = {
      bloqueados: Array.from(new Set(guardado)),
      permitidos: Array.from(new Set(permitidos)),
      acciones: acciones
    };
  });
  normalizados._version = version;
  return normalizados;
}
function aplicarPermisosRolesGuardados(data) {
  PERMISOS_ROLES = normalizarPermisosRolesGuardados(data);
}
// Fuente única para decisiones de permisos en botones/acciones.
// Mantiene compatibilidad con la solapa Configuración → Roles, que hoy gobierna
// visibilidad/acceso por módulo. Las acciones finas usan esta base para evitar
// validaciones dispersas por nombre de rol.
function rolActualNormalizado() {
  return window.SisVentas && window.SisVentas.Access
    ? window.SisVentas.Access.current()
    : String(currentRole || '').toLowerCase();
}
function esAdmin() { return rolActualNormalizado() === 'admin'; }
function esAdministrativo() { return rolActualNormalizado() === 'administrativo'; }
function esTecnico() { return rolActualNormalizado() === 'tecnico'; }
function esAdminOAdministrativo() { return esAdmin() || esAdministrativo(); }
function permisoModulo(idModulo) {
  if (idModulo === 'actualizadorprecios' && !esAdminOAdministrativo()) return false;
  if (idModulo === 'historialcliente') idModulo = 'clientes';
  if (!esAdmin() && esModuloNuevoSinRegistro(idModulo)) {
    var cfgNuevo = (PERMISOS_ROLES[rolActualNormalizado()] || PERMISOS_DEFAULT[rolActualNormalizado()] || {});
    if (!(cfgNuevo.permitidos || []).includes(idModulo)) return false;
  }
  if (window.SisVentas && window.SisVentas.Access) {
    if (idModulo === 'tesoreria' && !esAdmin()) return false;
    return window.SisVentas.Access.canAccess(idModulo, PERMISOS_ROLES, PERMISOS_DEFAULT);
  }
  if (!idModulo) return false;
  if (esAdmin()) return true;
  if (idModulo === 'tesoreria') return false;
  var cfg = (PERMISOS_ROLES[rolActualNormalizado()] || PERMISOS_DEFAULT[rolActualNormalizado()] || { bloqueados: [] });
  return (cfg.bloqueados || []).indexOf(idModulo) === -1;
}
function puedeEditarVentaPermiso(v) {
  var autorizado = typeof window.tienePermiso === 'function'
    ? window.tienePermiso('ventas.editar', { venta:v })
    : esAdminOAdministrativo();
  return autorizado && permisoModulo('detalle') && !ventaTienePagoTotal(v) && !ventaEstaAnulada(v);
}
function puedeEditarPresupuestoPermiso(p) {
  var autorizado = typeof window.tienePermiso === 'function'
    ? window.tienePermiso('presupuestos.editar', { presupuesto:p })
    : esAdminOAdministrativo();
  return autorizado && permisoModulo('presupuesto') && pptoPuedeEditar(p);
}

