// Todas las ubicaciones visibles consumen el único valor del marcador central.
if (typeof window.aplicarVersionSisVentas === 'function') window.aplicarVersionSisVentas(document);

// Compara la versión que está corriendo en pantalla contra la que realmente está
// que el propio chequeo caiga en el mismo caché que estamos tratando de detectar).
// SISTEMA DE VERSIÓN EN TIEMPO REAL VÍA FIREBASE
// En vez de hacer polling contra GitHub Pages (que tiene CDN con caché
// de hasta 10 minutos y no es confiable), escuchamos el nodo
// sisventas/config/version en Firebase Realtime DB — que es tiempo
// real garantizado. Cuando subís una versión nueva, actualizás ese
// nodo y todos los clientes conectados se actualizan al instante.

var _listenerVersionActivo = false;
var _versionNuevaDisponible = null;
var _actualizandoAhora = false; // evitar disparar dos veces
var _verificacionVersionEnCurso = false;
var _reintentoVersionTimer = null;
var _pausaActualizacionAvisada = false;
var _ultimoChequeoAppPublicada = 0;

function _limpiarControlIntentosActualizacion() {
  try {
    sessionStorage.removeItem('sisventas_update_target');
    sessionStorage.removeItem('sisventas_update_attempts');
    sessionStorage.removeItem('sisventas_update_last_attempt');
  } catch(e) {}
  _pausaActualizacionAvisada = false;
}

// Si esta versión ya alcanzó (o superó) el objetivo guardado por una pestaña
// anterior, el contador deja de tener sentido y no debe bloquear el futuro.
(function limpiarIntentosCumplidosAlAbrir() {
  try {
    var objetivo = sessionStorage.getItem('sisventas_update_target') || '';
    if (!objetivo || !_versionMasNueva(objetivo + '-firebase', APP_CONFIG.VERSION)) {
      _limpiarControlIntentosActualizacion();
    }
  } catch(e) {}
})();

function _mostrarBotonActualizacion(versionNueva) {
  _versionNuevaDisponible = versionNueva;
  var verLbl = versionNueva.replace('-firebase','');
  var lbl = document.getElementById('up-btn-actualizar-lbl');
  var btn = document.getElementById('up-btn-actualizar');
  var badge = document.getElementById('gear-update-badge');
  if (lbl) lbl.textContent = 'Actualizar a ' + verLbl;
  if (btn) btn.style.display = '';
  if (badge) badge.style.display = '';
}

function _versionMasNueva(a, b) {
  function partes(version) {
    var match=String(version||'').match(/(\d+)(?:\.(\d+))?(?:\.(\d+))?/);
    return match ? [Number(match[1]||0),Number(match[2]||0),Number(match[3]||0)] : [0,0,0];
  }
  var va=partes(a), vb=partes(b);
  for(var i=0;i<3;i++){ if(va[i]!==vb[i]) return va[i]>vb[i]; }
  return false;
}

function _extraerVersionPublicada(texto, tipo) {
  var patrones = tipo === 'index'
    ? [/VERSION:\s*['"]([^'"]+)['"]/]
    : tipo === 'app'
      ? [/VERSION:\s*['"]([^'"]+)['"]/]
      : [/SISVENTAS_PWA_VERSION\s*=\s*['"]([^'"]+)['"]/];
  for (var i = 0; i < patrones.length; i++) {
    var match = String(texto || '').match(patrones[i]);
    if (match) return String(match[1] || '').replace('-firebase','') + '-firebase';
  }
  return '';
}

function _verificarVersionPublicadaCompleta(versionObjetivo) {
  var cb = Date.now();
  var opciones = { cache:'no-store', headers:{ 'Pragma':'no-cache', 'Cache-Control':'no-cache' } };
  function cargarTexto(ruta) {
    var separador = ruta.indexOf('?') >= 0 ? '&' : '?';
    return fetch(ruta + separador + '_deploy=' + cb, opciones).then(function(r){ return r.ok ? r.text() : ''; });
  }
  return cargarTexto('./index.html').then(function(indexHtml) {
    if (!_versionCoincideObjetivo(_extraerVersionPublicada(indexHtml, 'index'), versionObjetivo)) return false;
    // La página ejecuta copias inmutables app.vX y version.vX. Verificar los
    // src exactos evita recargar durante un deploy parcialmente propagado.
    var appMatch = indexHtml.match(/<script[^>]+src=["'](\.\/js\/app\.v[0-9.]+\.js)["']/i);
    var coreMatch = indexHtml.match(/<script[^>]+src=["'](\.\/js\/core\/version\.v[0-9.]+\.js)["']/i);
    if (!appMatch || !coreMatch) return false;
    return Promise.all([
      cargarTexto(appMatch[1]),
      cargarTexto(coreMatch[1]),
      cargarTexto('./sw.js')
    ]).then(function(contenidos) {
      var versionSw = ((contenidos[2].match(/const\s+CACHE\s*=\s*['"]sisventas-([^'"]+)['"]/) || [])[1] || '') + '-firebase';
      return [
        _extraerVersionPublicada(contenidos[0], 'app'),
        _extraerVersionPublicada(contenidos[1], 'core'),
        versionSw
      ].every(function(v) { return _versionCoincideObjetivo(v, versionObjetivo); });
    });
  }).catch(function() { return false; });
}

function _versionCoincideObjetivo(versionPublicada, versionObjetivo) {
  return !!versionPublicada && (versionPublicada === versionObjetivo || _versionMasNueva(versionPublicada, versionObjetivo));
}

// Punto de entrada único: Firebase puede avisar antes de que termine el deploy,
// por eso la recarga sólo comienza cuando los tres archivos principales coinciden.
function _dispararActualizacion(versionNueva) {
  if (_actualizandoAhora) return;
  if (!_versionMasNueva(versionNueva, APP_CONFIG.VERSION)) {
    _limpiarControlIntentosActualizacion();
    return;
  }
  if (_verificacionVersionEnCurso) return;
  _verificacionVersionEnCurso = true;
  _verificarVersionPublicadaCompleta(versionNueva).then(function(publicada) {
    _verificacionVersionEnCurso = false;
    if (!publicada) {
      clearTimeout(_reintentoVersionTimer);
      _reintentoVersionTimer = setTimeout(function(){ _dispararActualizacion(versionNueva); }, 30000);
      return;
    }
    if (window.fbDB && window.fbGet && window.fbSet) {
      var versionRef = window.fbRef(window.fbDB, 'sisventas/config/version');
      window.fbGet(versionRef).then(function(snap) {
        var vigente = snap.val() || '';
        if (!vigente || _versionMasNueva(versionNueva, vigente)) return window.fbSet(versionRef, versionNueva);
      }).catch(function(){});
    }
    if (window._sisventasProcesoCriticoActivo) {
      _versionNuevaDisponible = versionNueva;
      _mostrarBotonActualizacion(versionNueva);
      if (!window._sisventasActualizacionDiferidaAvisada) {
        window._sisventasActualizacionDiferidaAvisada = true;
        notify('Hay una versión nueva lista. Se aplicará cuando vos elijas, sin interrumpir la actualización de precios.');
      }
      return;
    }
    _actualizandoAhora = true;
    actualizarAutomaticamente(APP_CONFIG.VERSION, versionNueva);
  });
}

// Respaldo de baja frecuencia: si por un error de publicación el archivo
// liviano version.js quedara atrasado, index.html sigue siendo la fuente real
// de la aplicación activa. No usamos app.js: es un alias histórico y puede no
// coincidir con el archivo inmutable app.vX que carga la página.
function _chequearAppPublicadaComoRespaldo(callback) {
  var ahora = Date.now();
  if (_ultimoChequeoAppPublicada && ahora - _ultimoChequeoAppPublicada < 15 * 60 * 1000) {
    if (callback) callback('');
    return;
  }
  _ultimoChequeoAppPublicada = ahora;
  fetch('./index.html?_version_fallback=' + ahora, {
    cache: 'no-store',
    headers: { 'Pragma':'no-cache', 'Cache-Control':'no-cache' }
  })
    .then(function(r){ return r.ok ? r.text() : ''; })
    .then(function(source) {
      var versionApp = _extraerVersionPublicada(source, 'index');
      if (versionApp && _versionMasNueva(versionApp, APP_CONFIG.VERSION)) {
        _dispararActualizacion(versionApp);
      }
      if (callback) callback(versionApp);
    })
    .catch(function(){ if (callback) callback(''); });
}

// Chequea la fuente liviana publicada y actualiza si hay versión nueva.
function _chequearGitHub(callback) {
  fetch('./js/core/version.js?_v=' + Date.now(), {
    cache: 'no-store',
    headers: { 'Pragma': 'no-cache', 'Cache-Control': 'no-cache' }
  })
    .then(function(r) { return r.ok ? r.text() : null; })
    .then(function(source) {
      if (!source) return;
      var m = source.match(/SISVENTAS_PWA_VERSION\s*=\s*'([^']+)'/);
      if (!m) return;
      var vGitHub = m[1] + '-firebase';
      if (_versionMasNueva(vGitHub, APP_CONFIG.VERSION)) {
        // La verificación completa publica Firebase recién cuando todo el
        // deploy está disponible; nunca anunciar una versión parcial.
        _dispararActualizacion(vGitHub);
        if (callback) callback(vGitHub);
        return;
      }
      _chequearAppPublicadaComoRespaldo(function(versionApp) {
        if (callback) callback(versionApp || vGitHub);
      });
    })
    .catch(function(){ _chequearAppPublicadaComoRespaldo(callback); });
}

function iniciarListenerVersion() {
  if (_listenerVersionActivo) return;
  if (!window.fbDB) return;
  _listenerVersionActivo = true;

  // Listener Firebase — detecta cuando OTRO cliente actualiza el nodo
  try {
    window.fbOnValue(
      window.fbRef(window.fbDB, 'sisventas/config/version'),
      function(snap) {
        var versionFirebase = snap.val();
        if (!versionFirebase) return;
        if (_versionMasNueva(versionFirebase, APP_CONFIG.VERSION)) {
          _dispararActualizacion(versionFirebase);
        }
        // Un cliente nunca vuelve a escribir su versión local en Firebase: una
        // pestaña antigua no puede rebajar la versión global.
      }
    );
  } catch (e) {
    // El watchdog HTTP debe seguir funcionando aunque una sesión no pueda
    // suscribirse temporalmente a Firebase (independiente del rol/permisos).
    _listenerVersionActivo = false;
  }
}

var _watchdogVersionTimer = null;
function iniciarWatchdogVersion() {
  if (_watchdogVersionTimer) return;
  _watchdogVersionTimer = setInterval(function() {
    if (document.visibilityState !== 'hidden') _chequearGitHub();
  }, 60 * 1000);
}

var _chequeoVersionIniciado = false;
function iniciarChequeoPeriodicoVersion() {
  // Siempre se inicia: no depende de Firebase, del rol ni de sus permisos.
  iniciarWatchdogVersion();
  if (_chequeoVersionIniciado) {
    if (window.fbDB) iniciarListenerVersion();
    return;
  }
  _chequeoVersionIniciado = true;

  // Chequeo inmediato contra GitHub al arrancar
  _chequearGitHub();

  // Listener Firebase en tiempo real
  if (window.fbDB) iniciarListenerVersion();
}

// Si el navegador suspendió la pestaña o el listener fue interrumpido durante
// el login, al regresar verificamos de inmediato sin esperar diez minutos.
document.addEventListener('visibilitychange', function() {
  if (document.visibilityState === 'visible' && isAuthenticated) {
    iniciarChequeoPeriodicoVersion();
    _chequearGitHub();
  }
});
window.addEventListener('focus', function() {
  if (isAuthenticated) {
    iniciarChequeoPeriodicoVersion();
    _chequearGitHub();
  }
});
window.addEventListener('online', function() {
  if (isAuthenticated) {
    iniciarChequeoPeriodicoVersion();
    _chequearGitHub();
  }
});

function actualizarAutomaticamente(versionActual, versionNueva) {
  var verActual = (versionActual || APP_CONFIG.VERSION || '').replace('-firebase','');
  var verNueva  = (versionNueva  || '').replace('-firebase','');

  if (verNueva) {
    var claveObjetivo = 'sisventas_update_target';
    var claveIntentos = 'sisventas_update_attempts';
    var claveUltimoIntento = 'sisventas_update_last_attempt';
    var objetivoAnterior = '';
    var intentos = 0;
    var ahoraIntento = Date.now();
    var ultimoIntento = 0;
    try {
      objetivoAnterior = sessionStorage.getItem(claveObjetivo) || '';
      ultimoIntento = parseInt(sessionStorage.getItem(claveUltimoIntento), 10) || 0;
      // Un intento viejo no pertenece al mismo ciclo. Esto permite que una
      // pestaña reabierta se recupere sola en lugar de quedar bloqueada.
      intentos = objetivoAnterior === verNueva && (ahoraIntento - ultimoIntento) < 120000
        ? (parseInt(sessionStorage.getItem(claveIntentos), 10) || 0) + 1
        : 1;
      sessionStorage.setItem(claveObjetivo, verNueva);
      sessionStorage.setItem(claveIntentos, String(intentos));
      sessionStorage.setItem(claveUltimoIntento, String(ahoraIntento));
    } catch(e) {}
    if (intentos > 2) {
      _actualizandoAhora = false;
      _mostrarBotonActualizacion(verNueva + '-firebase');
      if (!_pausaActualizacionAvisada) {
        _pausaActualizacionAvisada = true;
        notify('La actualización esperará un minuto y volverá a intentarlo. También podés usar “Actualizar ahora”.');
      }
      clearTimeout(_reintentoVersionTimer);
      _reintentoVersionTimer = setTimeout(function() {
        _limpiarControlIntentosActualizacion();
        _dispararActualizacion(verNueva + '-firebase');
      }, 60000);
      return;
    }
  }

  var prev = document.getElementById('overlay-actualizando');
  if (prev) prev.remove();

  var paginaActual = '';
  var paginaActiva = document.querySelector('.page.active');
  if (paginaActiva) paginaActual = paginaActiva.id.replace('page-', '');

  var overlay = document.createElement('div');
  overlay.id = 'overlay-actualizando';
  overlay.style.cssText = 'position:fixed;inset:0;z-index:99999;background:var(--bg,#080e1a);display:flex;flex-direction:column;align-items:center;justify-content:center;gap:16px';
  overlay.innerHTML =
    // Logo / ícono de la app (igual que el favicon)
    '<svg width="48" height="48" viewBox="0 0 100 100" xmlns="http://www.w3.org/2000/svg" style="margin-bottom:4px">' +
      '<rect width="100" height="100" rx="20" fill="#1a2332"/>' +
      '<path d="M30 65 L50 30 L70 65 M38 50 L62 50" stroke="#3ddc84" stroke-width="8" stroke-linecap="round" stroke-linejoin="round" fill="none"/>' +
    '</svg>' +
    '<div style="font-weight:700;font-size:18px;color:var(--text,#fff);letter-spacing:.3px">Actualizando SisVentas</div>' +
    // Versión de → a
    (verActual && verNueva ?
      '<div style="display:flex;align-items:center;gap:10px;font-size:13px">' +
        '<span style="color:var(--text3,#6b7fa3);font-family:monospace">' + verActual + '</span>' +
        '<i class="ti ti-arrow-right" style="color:var(--green,#3ddc84);font-size:14px"></i>' +
        '<span style="color:var(--green,#3ddc84);font-family:monospace;font-weight:600">' + verNueva + '</span>' +
      '</div>'
    : '<div style="font-size:13px;color:var(--text3,#6b7fa3)">Descargando versión nueva...</div>') +
    '<div style="width:220px;height:3px;background:var(--bg2,#1a2332);border-radius:4px;overflow:hidden;margin-top:12px">' +
      '<div id="upd-bar" style="height:100%;width:0%;background:var(--green,#3ddc84);border-radius:4px;transition:width 2.5s linear"></div>' +
    '</div>' +
    '<div style="font-size:11px;color:var(--text3,#6b7fa3);margin-top:4px">No cerrés esta ventana</div>';
  document.body.appendChild(overlay);

  setTimeout(function(){ var b = document.getElementById('upd-bar'); if(b) b.style.width='100%'; }, 50);

  if (paginaActual) {
    try { sessionStorage.setItem('sisventas_pagina_previa', paginaActual); } catch(e){}
  }
  try { sessionStorage.setItem('sisventas_version_previa', APP_CONFIG.VERSION); } catch(e){}

  setTimeout(function() {
    if ('serviceWorker' in navigator) {
      navigator.serviceWorker.getRegistrations().then(function(regs) {
        return Promise.all(regs.map(function(reg) { return reg.unregister(); }));
      }).catch(function(){}).finally(function() {
        if (window.caches && caches.keys) {
          caches.keys().then(function(names) {
            return Promise.all(names.map(function(name) { return caches.delete(name); }));
          }).finally(function() {
            window.location.replace(window.location.pathname + '?app_version=' + encodeURIComponent(verNueva) + '&cb=' + Date.now() + window.location.hash);
          });
        } else {
          window.location.replace(window.location.pathname + '?app_version=' + encodeURIComponent(verNueva) + '&cb=' + Date.now() + window.location.hash);
        }
      });
    } else {
      window.location.replace(window.location.pathname + '?app_version=' + encodeURIComponent(verNueva) + '&cb=' + Date.now() + window.location.hash);
    }
  }, 2800);
}
function restaurarPaginaPostActualizacion() {
  try {
    var pagPrevia    = sessionStorage.getItem('sisventas_pagina_previa');
    var verPrevia    = sessionStorage.getItem('sisventas_version_previa');
    if (!pagPrevia && !verPrevia) return;
    sessionStorage.removeItem('sisventas_pagina_previa');
    sessionStorage.removeItem('sisventas_version_previa');

    // La restauración puede ocurrir antes de que Firebase recupere la sesión.
    // Guardamos la novedad para mostrarla cuando rol y permisos estén listos.
    _guardarNovedadActualizacionPendiente(verPrevia, APP_CONFIG.VERSION);

    // Navegar al módulo donde estaba el usuario
    setTimeout(function() {
      if (pagPrevia && _sesionListaParaNovedad() && typeof showPage === 'function') {
        var btn = document.querySelector('[onclick*="' + pagPrevia + '"]');
        showPage(pagPrevia, btn);
      }
      _mostrarNovedadActualizacionPendiente();
    }, 1500);
  } catch(e){}
}

var _SV_NOVEDAD_PENDIENTE_KEY = 'sisventas_novedad_actualizacion_pendiente';

function _normalizarRangoNovedad(verAnterior, verNueva) {
  var actual = String(APP_CONFIG.VERSION || '');
  var hasta = String(verNueva || actual);
  if (!hasta || _versionMasNueva(actual, hasta)) hasta = actual;
  var desde = String(verAnterior || '');
  if (desde && (desde.replace('-firebase','') === hasta.replace('-firebase','') || !_versionMasNueva(hasta, desde))) {
    desde = '';
  }
  return { desde:desde, hasta:hasta };
}

function _guardarNovedadActualizacionPendiente(verAnterior, verNueva) {
  try {
    var rango = _normalizarRangoNovedad(verAnterior, verNueva);
    localStorage.setItem(_SV_NOVEDAD_PENDIENTE_KEY, JSON.stringify({
      desde: rango.desde,
      hasta: rango.hasta,
      guardadaEn: Date.now()
    }));
    window._svNovedadPendienteMostrada = '';
  } catch(e){}
}

function _leerNovedadActualizacionPendiente() {
  try {
    var raw = localStorage.getItem(_SV_NOVEDAD_PENDIENTE_KEY);
    return raw ? JSON.parse(raw) : null;
  } catch(e) { return null; }
}

function _sesionListaParaNovedad() {
  var app = document.getElementById('screen-app');
  return !!(isAuthenticated && currentUserUid && currentRole && app && app.classList.contains('visible'));
}

function _limpiarNovedadActualizacionPendiente() {
  try { localStorage.removeItem(_SV_NOVEDAD_PENDIENTE_KEY); } catch(e){}
  window._svNovedadPendienteMostrada = '';
}

function cerrarPopupActualizacion() {
  var popup = document.getElementById('popup-actualizado');
  if (popup) popup.remove();
  if (_sesionListaParaNovedad()) _limpiarNovedadActualizacionPendiente();
}

function _mostrarNovedadActualizacionPendiente() {
  var pendiente = _leerNovedadActualizacionPendiente();
  if (!pendiente || !_sesionListaParaNovedad()) return;
  // En el salto a V3 la bienvenida tiene prioridad. La novedad permanece
  // guardada y se abre recién cuando el usuario termina esa presentación.
  if (typeof window.svBienvenidaV3Pendiente === 'function' && window.svBienvenidaV3Pendiente()) return;
  var rango = _normalizarRangoNovedad(pendiente.desde, pendiente.hasta);
  var marca = rango.hasta;
  if (window._svNovedadPendienteMostrada === marca || document.getElementById('popup-actualizado')) return;
  window._svNovedadPendienteMostrada = marca;
  _mostrarPopupActualizacion(rango.desde, rango.hasta);
}

function _mostrarPopupActualizacion(verAnterior, verNueva) {
  var rango = _normalizarRangoNovedad(verAnterior, verNueva);
  verAnterior = rango.desde;
  verNueva = rango.hasta;
  _guardarNovedadActualizacionPendiente(verAnterior, verNueva);
  if (!_sesionListaParaNovedad()) return;
  window._svNovedadPendienteMostrada = String(verNueva || APP_CONFIG.VERSION || '');
  var prev = document.getElementById('popup-actualizado');
  if (prev) prev.remove();

  var desdeStr = verAnterior ? verAnterior.replace('-firebase','') : '';
  var hastaStr = (verNueva||'').replace('-firebase','');
  // El dorado se reserva exclusivamente para el lanzamiento 2.x -> 3.0.0.
  // Las próximas versiones y parches vuelven al verde habitual.
  var esLanzamientoV3 = /^v?2\./.test(desdeStr) && /^v?3\.0\.0$/.test(hastaStr);
  var acentoNovedad = esLanzamientoV3 ? '#f6c453' : 'var(--green)';
  var fondoAcentoNovedad = esLanzamientoV3 ? 'rgba(246,196,83,.13)' : 'var(--green-bg)';
  var notasVersion = (APP_CONFIG.RELEASE_NOTES || []).map(function(nota) {
    return '<div style="display:flex;align-items:flex-start;gap:8px;text-align:left"><i class="ti ti-check" style="color:' + acentoNovedad + ';font-size:14px;margin-top:2px;flex-shrink:0"></i><span>' + escapeHTML(nota) + '</span></div>';
  }).join('');
  var novedad = APP_CONFIG.RELEASE_FEATURE || null;
  var puedeAbrirNovedad = novedad && (!novedad.page || typeof permisoModulo !== 'function' || permisoModulo(novedad.page));
  var accionesNovedad = puedeAbrirNovedad ?
    '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:10px">' +
      '<button onclick="abrirNovedadVersion(false)" style="flex:1;min-width:180px;padding:11px;border-radius:var(--radius);border:0.5px solid ' + acentoNovedad + ';background:' + fondoAcentoNovedad + ';color:' + acentoNovedad + ';font-weight:700;font-size:13px;cursor:pointer;font-family:inherit"><i class="ti ti-external-link" style="margin-right:5px"></i>' + escapeHTML(novedad.actionLabel || 'Ver función nueva') + '</button>' +
      (novedad.tour ? '<button onclick="abrirNovedadVersion(true)" style="flex:1;min-width:180px;padding:11px;border-radius:var(--radius);border:0.5px solid var(--blue);background:var(--blue-bg);color:var(--blue);font-weight:700;font-size:13px;cursor:pointer;font-family:inherit"><i class="ti ti-route" style="margin-right:5px"></i>' + escapeHTML(novedad.tourLabel || 'Recorrido guiado') + '</button>' : '') +
    '</div>' : '';

  var overlay = document.createElement('div');
  overlay.id = 'popup-actualizado';
  overlay.style.cssText = 'position:fixed;inset:0;z-index:99999;display:flex;align-items:center;justify-content:center;padding:20px;background:rgba(0,0,0,.35)';
  overlay.innerHTML =
    '<div style="background:var(--bg2);border-radius:var(--radius-lg);padding:30px 32px;max-width:480px;width:100%;max-height:88vh;overflow:auto;box-shadow:0 20px 60px rgba(0,0,0,.5);text-align:center;position:relative;border:0.5px solid var(--border2)">' +
      // Ícono animado
      '<div style="width:64px;height:64px;border-radius:50%;background:' + fondoAcentoNovedad + ';display:flex;align-items:center;justify-content:center;margin:0 auto 16px">' +
        '<i class="ti ti-rocket" style="font-size:28px;color:' + acentoNovedad + '"></i>' +
      '</div>' +
      // Título
      '<div style="font-weight:700;font-size:20px;color:var(--text);margin-bottom:6px">¡Sistema actualizado!</div>' +
      '<div style="font-size:13px;color:var(--text3);margin-bottom:20px">SisVentas se actualizó automáticamente</div>' +
      // Versiones
      (desdeStr ?
        '<div style="display:flex;align-items:center;justify-content:center;gap:10px;margin-bottom:20px;padding:10px 16px;background:var(--bg3);border-radius:var(--radius)">' +
          '<span style="font-family:monospace;font-size:13px;color:var(--text3)">' + desdeStr + '</span>' +
          '<i class="ti ti-arrow-right" style="color:' + acentoNovedad + ';font-size:14px"></i>' +
          '<span style="font-family:monospace;font-size:14px;font-weight:700;color:' + acentoNovedad + '">' + hastaStr + '</span>' +
        '</div>'
      : '<div style="font-family:monospace;font-size:16px;font-weight:700;color:' + acentoNovedad + ';margin-bottom:20px">' + hastaStr + '</div>') +
      // Resumen de cambios
      (notasVersion ? '<div style="padding:12px 14px;background:var(--bg3);border:0.5px solid var(--border);border-radius:var(--radius);font-size:12px;color:var(--text2);line-height:1.45;margin-bottom:20px;display:flex;flex-direction:column;gap:8px"><div style="font-size:11px;font-weight:800;color:var(--text);text-transform:uppercase;letter-spacing:.5px">Qué cambió</div>' + notasVersion + '</div>' : '') +
      '<div style="font-size:11px;color:var(--text3);margin-bottom:20px">Todo funcionando correctamente. Seguís exactamente donde estabas.</div>' +
      accionesNovedad +
      // Botón
      '<button onclick="cerrarPopupActualizacion()" ' +
        'style="width:100%;padding:12px;border-radius:var(--radius);border:none;background:' + acentoNovedad + ';color:#080e1a;font-weight:700;font-size:14px;cursor:pointer;font-family:inherit;letter-spacing:.3px">' +
        '✓ Entendido, ¡gracias!' +
      '</button>' +
    '</div>';

  document.body.appendChild(overlay);
  // Cerrar con Escape
  document.addEventListener('keydown', function handler(e) {
    if (e.key === 'Escape') {
      cerrarPopupActualizacion();
      document.removeEventListener('keydown', handler);
    }
  });
}

function _abrirDestinoNovedad(novedad, conRecorrido) {
  if (!novedad) return;
  var popup = document.getElementById('popup-actualizado');
  if (popup) popup.remove();
  _limpiarNovedadActualizacionPendiente();
  if (novedad.history) {
    abrirHistorialActualizaciones();
    return;
  }
  if (novedad.page && typeof showPage === 'function') {
    showPage(novedad.page, document.querySelector('[onclick*="' + novedad.page + '"]'));
  }
  if (conRecorrido && novedad.tour) {
    setTimeout(function () {
      if (typeof window.iniciarRecorridoNovedad === 'function') window.iniciarRecorridoNovedad(novedad.tour);
      else notify('El recorrido todavía no está disponible');
    }, 650);
  }
}

function abrirNovedadVersion(conRecorrido) {
  _abrirDestinoNovedad(APP_CONFIG.RELEASE_FEATURE || null, conRecorrido);
}

function abrirNovedadHistorial(indice, conRecorrido) {
  var historial = APP_CONFIG.RELEASE_HISTORY || [];
  var entrada = historial[parseInt(indice, 10)];
  if (!entrada || !entrada.feature) return;
  var modal = document.getElementById('modal-historial-actualizaciones');
  if (modal) modal.remove();
  _abrirDestinoNovedad(entrada.feature, conRecorrido);
}

function abrirHistorialActualizaciones() {
  var anterior = document.getElementById('modal-historial-actualizaciones');
  if (anterior) anterior.remove();
  var historial = APP_CONFIG.RELEASE_HISTORY || [];
  var versionActual = String(APP_CONFIG.VERSION || '').replace('-firebase', '');
  var tarjetas = historial.map(function (entrada, indice) {
    var esVersionMayor = entrada.major === true || /^v?\d+\.0\.0(?:\D|$)/.test(String(entrada.version || ''));
    var colorVersion = esVersionMayor ? '#f6c453' : 'var(--green)';
    var bordeTarjeta = esVersionMayor ? 'rgba(246,196,83,.55)' : 'var(--border)';
    var fondoTarjeta = esVersionMayor ? 'linear-gradient(135deg,rgba(246,196,83,.12),var(--bg3) 58%)' : 'var(--bg3)';
    var feature = entrada.feature || null;
    var puedeAbrir = feature && !feature.history && (!feature.page || typeof permisoModulo !== 'function' || permisoModulo(feature.page));
    var notas = (entrada.notes || []).map(function (nota) {
      return '<div style="display:flex;gap:7px;align-items:flex-start"><i class="ti ti-check" style="color:var(--green);margin-top:2px;flex-shrink:0"></i><span>' + escapeHTML(nota) + '</span></div>';
    }).join('');
    var acciones = puedeAbrir ?
      '<div style="display:flex;gap:7px;flex-wrap:wrap;margin-top:12px">' +
        '<button class="btn btn-sm" onclick="abrirNovedadHistorial(' + indice + ',false)"><i class="ti ti-external-link"></i> ' + escapeHTML(feature.actionLabel || 'Abrir función') + '</button>' +
        (feature.tour ? '<button class="btn btn-sm btn-primary" onclick="abrirNovedadHistorial(' + indice + ',true)"><i class="ti ti-route"></i> ' + escapeHTML(feature.tourLabel || 'Hacer recorrido guiado') + '</button>' : '') +
      '</div>' : '';
    return '<article style="padding:15px 16px;background:' + fondoTarjeta + ';border:0.5px solid ' + bordeTarjeta + ';border-radius:var(--radius);text-align:left">' +
      '<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:12px;margin-bottom:7px">' +
        '<div><div style="display:flex;align-items:center;gap:7px;flex-wrap:wrap"><strong style="font-family:monospace;color:' + colorVersion + ';font-size:13px">' + escapeHTML(entrada.version || '') + '</strong>' +
        (entrada.version === versionActual ? '<span class="badge ' + (esVersionMayor ? 'b-amber' : 'b-green') + '">Actual</span>' : '') + '</div>' +
        '<div style="font-weight:750;font-size:14px;color:var(--text);margin-top:5px">' + escapeHTML(entrada.title || 'Actualización') + '</div></div>' +
        '<span style="font-size:10px;color:var(--text3);white-space:nowrap">' + escapeHTML(entrada.date || '') + '</span>' +
      '</div>' +
      '<div style="font-size:12px;line-height:1.45;color:var(--text2);display:flex;flex-direction:column;gap:5px">' + notas + '</div>' + acciones +
    '</article>';
  }).join('');

  var overlay = document.createElement('div');
  overlay.id = 'modal-historial-actualizaciones';
  overlay.style.cssText = 'position:fixed;inset:0;z-index:99998;display:flex;align-items:center;justify-content:center;padding:18px;background:rgba(0,0,0,.48)';
  overlay.innerHTML =
    '<div style="width:min(680px,100%);max-height:88vh;overflow:hidden;background:var(--bg2);border:0.5px solid var(--border2);border-radius:var(--radius-lg);box-shadow:0 22px 65px rgba(0,0,0,.55);display:flex;flex-direction:column">' +
      '<div style="padding:18px 20px 14px;border-bottom:0.5px solid var(--border);display:flex;align-items:flex-start;gap:12px">' +
        '<div style="width:42px;height:42px;border-radius:50%;background:var(--green-bg);color:var(--green);display:flex;align-items:center;justify-content:center;flex-shrink:0"><i class="ti ti-rocket" style="font-size:21px"></i></div>' +
        '<div style="flex:1"><div style="font-size:18px;font-weight:750;color:var(--text)">Novedades de SisVentas</div><div style="font-size:12px;color:var(--text3);margin-top:3px">Los avisos que cerraste siguen acá. Podés abrir cada función y repetir sus recorridos cuando quieras.</div></div>' +
        '<button class="icon-btn" onclick="document.getElementById(\'modal-historial-actualizaciones\').remove()" aria-label="Cerrar"><i class="ti ti-x"></i></button>' +
      '</div>' +
      '<div style="padding:14px;display:flex;flex-direction:column;gap:10px;overflow:auto">' + (tarjetas || '<div style="padding:25px;text-align:center;color:var(--text3)">Todavía no hay novedades registradas.</div>') + '</div>' +
    '</div>';
  overlay.addEventListener('click', function (event) { if (event.target === overlay) overlay.remove(); });
  document.body.appendChild(overlay);
}

function mostrarAvisoVersionNueva(versionNueva) {
  if (document.getElementById('aviso-version-nueva')) return;
  var div = document.createElement('div');
  div.id = 'aviso-version-nueva';
  div.style.cssText = 'position:fixed;left:50%;bottom:24px;transform:translateX(-50%);z-index:9999;background:var(--bg2,#1a2332);border:0.5px solid var(--green,#3ddc84);border-radius:12px;padding:12px 16px;display:flex;align-items:center;gap:12px;box-shadow:0 8px 24px rgba(0,0,0,.4);font-size:13px;color:#fff;max-width:92vw';
  div.innerHTML =
    '<span>Hay una versión nueva ('+versionNueva.replace('-firebase','')+') — guardá tu venta y actualizá cuando puedas.</span>' +
    '<button onclick="actualizarAutomaticamente()" style="background:#3ddc84;color:#080e1a;border:none;border-radius:8px;padding:8px 14px;font-weight:600;font-size:13px;white-space:nowrap;cursor:pointer">Actualizar ahora</button>';
  document.body.appendChild(div);
}

// Fuerza una recarga real saltando el caché del navegador.
function forzarActualizacionApp() {
  actualizarAutomaticamente(APP_CONFIG.VERSION, '');
}
// Chequeo de versión: arranca con firebase-ready (cubre sesiones ya abiertas)
// y también en _completarLogin (cubre nuevos logins). El setInterval de 5min
document.addEventListener('firebase-ready', function() {
  setTimeout(function() {
    if (typeof iniciarChequeoPeriodicoVersion === 'function') iniciarChequeoPeriodicoVersion();
    if (typeof restaurarPaginaPostActualizacion === 'function') restaurarPaginaPostActualizacion();
  }, 2000);
});

let isAuthenticated = false;
let currentUser = ''; // nombre visible de la sesión; debe existir antes de que Notificaciones consulte el contexto
let currentUserUid = ''; // uid de Firebase Auth — clave de presencia en Firebase
let currentUserEmail = ''; // email normalizado — permite cruzar presencia con sisventas/usuarios
// Convierte un string de número en cualquier formato regional a número JS (punto decimal).
// Casos que maneja:
//   "105.245"     → 105245  (punto = miles, >3 dígitos después)
//   "1.234,56"    → 1234.56 (formato AR: punto=miles, coma=decimal)
//   "1,234.56"    → 1234.56 (formato US: coma=miles, punto=decimal)
//   "105,245"     → 105245  (coma = miles, 3 dígitos después)
//   "10,50"       → 10.50   (coma = decimal, 2 dígitos después)
//   "$105.245"    → 105245  (símbolo $ ignorado)
//   "105245"      → 105245  (sin separadores)
function normalizarNumeroExcel(texto) {
  if (!texto) return '';
  var t = String(texto).trim();
  // Quitar símbolo $ y espacios
  t = t.replace(/[$\s]/g, '');
  if (!t) return '';

  var tieneComa  = t.indexOf(',') !== -1;
  var tienePunto = t.indexOf('.') !== -1;

  if (tieneComa && tienePunto) {
    // Ambos presentes — el que está último es el decimal
    var posComa  = t.lastIndexOf(',');
    var posPunto = t.lastIndexOf('.');
    if (posComa > posPunto) {
      // Formato AR: 1.234,56 — punto=miles, coma=decimal
      t = t.replace(/\./g, '').replace(',', '.');
    } else {
      // Formato US: 1,234.56 — coma=miles, punto=decimal
      t = t.replace(/,/g, '');
    }
  } else if (tienePunto && !tieneComa) {
    var partesPunto = t.split('.');
    var despuesPunto = partesPunto[partesPunto.length - 1];
    if (partesPunto.length > 2) {
      // Múltiples puntos — son separadores de miles (ej: 1.234.567)
      t = t.replace(/\./g, '');
    } else if (despuesPunto.length === 3) {
      // Exactamente 3 dígitos después del punto → miles (ej: 105.245)
      t = t.replace('.', '');
    }
    // 1 o 2 dígitos después → decimal (ej: 10.50, 10.5) — dejar como está
  } else if (tieneComa && !tienePunto) {
    var partesComa = t.split(',');
    var despuesComa = partesComa[partesComa.length - 1];
    if (partesComa.length > 2 || despuesComa.length === 3) {
      // Múltiples comas o 3 dígitos → separador de miles
      t = t.replace(/,/g, '');
    } else {
      // 1 o 2 dígitos → decimal
      t = t.replace(',', '.');
    }
  }

  var num = parseFloat(t);
  return isNaN(num) ? '' : String(num);
}

// Interceptar pegado en todos los inputs numéricos del sistema
document.addEventListener('paste', function(e) {
  var target = e.target;
  if (!target || target.tagName !== 'INPUT' || target.type !== 'number') return;
  var pasted = (e.clipboardData || window.clipboardData).getData('text');
  if (!pasted) return;
  if (/^-?\d+(\.\d+)?$/.test(pasted.trim())) return;
  var limpio = normalizarNumeroExcel(pasted);
  if (limpio === '') return;
  e.preventDefault();
  target.value = limpio;
  target.dispatchEvent(new Event('input', { bubbles: true }));
});

function svTextoLegible(value) {
  var texto = String(value == null ? '' : value);
  // Compatibilidad con textos históricos que fueron interpretados una vez
  // como Windows-1252/Latin-1 aunque originalmente eran UTF-8. No se modifica
  // Firebase: la reparación se aplica únicamente al mostrar el dato.
  var pares = [
    ['\u00C3\u00A1','á'], ['\u00C3\u00A9','é'], ['\u00C3\u00AD','í'], ['\u00C3\u00B3','ó'], ['\u00C3\u00BA','ú'], ['\u00C3\u00B1','ñ'],
    ['\u00C3\u0081','Á'], ['\u00C3\u0089','É'], ['\u00C3\u008D','Í'], ['\u00C3\u0093','Ó'], ['\u00C3\u009A','Ú'], ['\u00C3\u0091','Ñ'],
    ['\u00C2\u00BF','¿'], ['\u00C2\u00A1','¡'], ['\u00C2\u00B0','°'], ['\u00C2\u00B7','·'], ['\u00C2\u00BA','º'],
    ['\u00E2\u20AC\u201D','—'], ['\u00E2\u20AC\u201C','–'], ['\u00E2\u20AC\u00A2','•'],
    ['\u00E2\u20AC\u02DC','‘'], ['\u00E2\u20AC\u2122','’'], ['\u00E2\u20AC\u0153','“'], ['\u00E2\u20AC\u009D','”'],
    ['\u00E2\u2020\u2019','→'], ['\u00E2\u2020\u0091','↑'], ['\u00E2\u2020\u201C','↓'],
    ['\u00E2\u0153\u201C','✓'], ['\u00E2\u0153\u201D','✔'], ['\u00E2\u0153\u2022','✕'],
    ['\u00EF\u00B8\u008F','️']
  ];
  pares.forEach(function(par) { texto = texto.split(par[0]).join(par[1]); });
  return texto;
}
window.svTextoLegible = svTextoLegible;

function escapeHTML(value) {
  return svTextoLegible(value).replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
}
// FORMATO DE MONTOS TIPO CALCULADORA
// Mientras se escribe, se agregan separadores de miles automáticamente
// (formato argentino: punto de miles, coma decimal). El punto del teclado
// numérico actúa como la coma decimal, igual que en la calculadora de Windows.
// queda disponible en input.dataset.raw (string tipo "1234.56", listo para
// parseFloat) y en la función getMontoRaw(input) para usar en los cálculos.

// Usar esto en vez de parseFloat(input.value) para estos campos.
function getMontoRaw(input) {
  if (!input) return 0;
  return parseFloat(input.dataset.raw || '0') || 0;
}

// Formatea un número a texto con separador de miles argentino, sin forzar
// decimales si no los tiene (para que no se vea "1.234,00" mientras se escribe).
function _formatMontoVisual(enteroStr, decStr, tieneComa) {
  var entero = enteroStr.replace(/^0+(?=\d)/, '') || '0'; // sin ceros a la izquierda, salvo "0" solo
  var conMiles = entero.replace(/\B(?=(\d{3})+(?!\d))/g, '.');
  if (tieneComa) return conMiles + ',' + (decStr || '');
  return conMiles;
}

// Convierte un input type="number" en un campo con formato tipo calculadora.
function initMoneyInput(input) {
  if (!input || input.dataset.moneyInit) return;
  input.dataset.moneyInit = '1';
  input.type = 'text';
  input.inputMode = 'decimal';
  input.autocomplete = 'off';

  // Valor inicial: lo que ya tenía el input (viene de value="..." en el HTML)
  var inicial = parseFloat(input.value) || 0;
  input.dataset.raw = String(inicial);
  if (inicial !== 0) {
    var fijo = parseInt(input.dataset.moneyFixed, 10);
    var inicialTexto = isFinite(fijo) ? inicial.toFixed(fijo) : String(inicial);
    var partes = inicialTexto.split('.');
    if (isFinite(fijo)) input.dataset.tieneComa = '1';
    input.value = _formatMontoVisual(partes[0], (partes[1]||'').slice(0,2), isFinite(fijo) || !!partes[1]);
  } else {
    input.value = input.getAttribute('placeholder') ? '' : '0';
  }

  input.addEventListener('keydown', function(e) {
    // igual que en la calculadora de Windows — no escribe un "." literal de más.
    if (e.key === '.' || e.key === ',') {
      e.preventDefault();
      if (!input.dataset.tieneComa) {
        input.dataset.tieneComa = '1';
        _refrescarMoneyVisual(input);
      }
    }
  });

  input.addEventListener('input', function() {
    // se recalcule solo (como una calculadora real).
    var soloDigitos = input.value.replace(/\D/g, '');
    var tieneComa = !!input.dataset.tieneComa;
    if (tieneComa) {
      var dec = soloDigitos.slice(-2);
      var ent = soloDigitos.slice(0, -2) || '0';
      input.dataset.raw = ent + '.' + dec;
      input.value = _formatMontoVisual(ent, dec, true);
    } else {
      input.dataset.raw = soloDigitos || '0';
      input.value = soloDigitos ? _formatMontoVisual(soloDigitos, '', false) : '';
    }
    // Disparar un evento 'change'-like liviano para que el código que ya
    // escucha oninput en el input siga funcionando con el valor correcto.
  }, true); // captura, para correr ANTES que el oninput inline del HTML

  input.addEventListener('blur', function() {
    if (!input.value) { input.dataset.raw = '0'; }
    var fijo = parseInt(input.dataset.moneyFixed, 10);
    if (isFinite(fijo)) {
      var numero = parseFloat(input.dataset.raw || '0') || 0;
      var partes = numero.toFixed(fijo).split('.');
      input.dataset.raw = numero.toFixed(fijo);
      input.dataset.tieneComa = '1';
      input.value = _formatMontoVisual(partes[0], partes[1] || '', true);
    }
  });

  input.addEventListener('focus', function() { input.select(); });
}

function _refrescarMoneyVisual(input) {
  var raw = input.dataset.raw || '0';
  var partes = raw.split('.');
  input.value = _formatMontoVisual(partes[0], (partes[1]||'').slice(0,2), !!input.dataset.tieneComa);
}

// Inicializa todos los inputs con data-money="1" dentro de un contenedor
// (o todo el documento si no se pasa contenedor). Llamar después de cualquier
// innerHTML que inserte filas/formularios con campos de monto nuevos.
function initMoneyInputsEn(contenedor) {
  var root = contenedor || document;
  root.querySelectorAll('[data-money="1"]').forEach(initMoneyInput);
}

function asegurarDesplazamientoTablas(contenedor) {
  var root = contenedor && contenedor.querySelectorAll ? contenedor : document;
  var tablas = [];
  if (root.matches && root.matches('table')) tablas.push(root);
  root.querySelectorAll('table').forEach(function(tabla){ tablas.push(tabla); });
  tablas.forEach(function(tabla) {
    if (!tabla.parentNode || tabla.closest('.table-wrap') || tabla.classList.contains('no-auto-scroll')) return;
    var wrap = document.createElement('div');
    wrap.className = 'table-wrap sv-auto-grid-wrap';
    tabla.parentNode.insertBefore(wrap, tabla);
    wrap.appendChild(tabla);
  });
}

// ACCIONES RESPONSIVAS, INICIALIZADAS SÓLO EN LA GRILLA QUE ACABA DE RENDERIZARSE.
// Los botones originales siguen siendo la única acción real; el menú compacto
// solamente los presenta mejor cuando no entran en celular o tablet.
function prepararAccionesGrilla(tablaRef) {
  var tabla = typeof tablaRef === 'string' ? document.getElementById(tablaRef) : tablaRef;
  if (!tabla) return;
  if (!window._svGridActionsCloseReady) {
    window._svGridActionsCloseReady = true;
    document.addEventListener('click', function() {
      document.querySelectorAll('.sv-grid-actions-menu.abierto').forEach(function(menu) {
        menu.classList.remove('abierto');
        var trigger = menu.parentElement && menu.parentElement.querySelector('.sv-grid-actions-trigger');
        if (trigger) trigger.setAttribute('aria-expanded', 'false');
      });
    });
  }
  tabla.classList.add('sv-responsive-grid');
  var encabezados = Array.from(tabla.querySelectorAll('thead th'));
  if (!encabezados.length) return;
  var indiceAcciones = encabezados.findIndex(function(th, indice) {
    var texto = String(th.textContent || '').trim();
    return /^(acciones?|opciones?)$/i.test(texto) || (!texto && indice === encabezados.length - 1);
  });
  if (indiceAcciones < 0) return;
  var encabezadoAcciones = encabezados[indiceAcciones];
  if (encabezadoAcciones && !String(encabezadoAcciones.textContent || '').replace(/\s+/g, ' ').trim()) {
    encabezadoAcciones.dataset.svColumnLabel = 'Acciones';
    var rotuloAcciones = document.createElement('span');
    rotuloAcciones.className = 'sv-actions-header-label';
    rotuloAcciones.textContent = 'Acciones';
    encabezadoAcciones.insertBefore(rotuloAcciones, encabezadoAcciones.firstChild || null);
  }
  tabla.querySelectorAll('tbody tr').forEach(function(fila) {
    var celda = fila.cells && fila.cells[indiceAcciones];
    if (!celda || celda.dataset.svActionsReady === '1') return;
    // Algunas grillas agrupan sus controles dentro de un contenedor. Tomar
    // todas las acciones reales de la celda permite aplicar el mismo patrón
    // visual sin obligar a cada módulo a construir un HTML diferente.
    var controles = Array.from(celda.querySelectorAll('button,a,[role="button"]')).filter(function(el) {
      return !el.classList.contains('sv-grid-actions-trigger') && !el.closest('.sv-grid-actions-menu');
    });
    controles.forEach(function(control) {
      var etiquetaControl = String(control.getAttribute('aria-label') || control.title || control.textContent || '').trim();
      control.classList.add('sv-grid-action-button');
      if (/eliminar|anular|baja|quitar|cancelar/i.test(etiquetaControl)) control.classList.add('sv-grid-action-danger');
      else if (/abrir|ver|editar|imprimir|duplicar|historial|detalle/i.test(etiquetaControl)) control.classList.add('sv-grid-action-standard');
      if (!etiquetaControl || /whatsapp/i.test(etiquetaControl) || control.querySelector('.sv-mobile-action-label')) return;
      var textoMovil = document.createElement('span');
      textoMovil.className = 'sv-mobile-action-label';
      textoMovil.textContent = etiquetaControl;
      control.appendChild(textoMovil);
      control.setAttribute('aria-label', etiquetaControl);
    });
    if (controles.length < 2) return;
    celda.dataset.svActionsReady = '1';
    celda.classList.add('sv-grid-actions-cell');
    // En OT la acción principal es abrir la orden. En tablet/móvil no puede
    // quedar escondida detrás del menú contextual: es el acceso al trabajo.
    var accionPrincipal = tabla.hasAttribute('data-sv-keep-primary-action') ? controles.shift() : null;
    if (accionPrincipal) {
      accionPrincipal.classList.add('sv-grid-actions-primary');
      accionPrincipal.title = accionPrincipal.title || 'Abrir orden de trabajo';
      accionPrincipal.setAttribute('aria-label', accionPrincipal.getAttribute('aria-label') || 'Abrir orden de trabajo');
    }
    var originales = document.createElement('span');
    originales.className = 'sv-grid-actions-original';
    controles.forEach(function(control){ originales.appendChild(control); });
    var trigger = document.createElement('button');
    trigger.type = 'button';
    trigger.className = 'btn btn-sm btn-icon sv-grid-actions-trigger';
    trigger.title = 'Más acciones';
    trigger.setAttribute('aria-label', 'Más acciones');
    trigger.setAttribute('aria-expanded', 'false');
    trigger.innerHTML = '<i class="ti ti-dots-vertical"></i>';
    var menu = document.createElement('div');
    menu.className = 'sv-grid-actions-menu';
    controles.forEach(function(control) {
      var item = document.createElement('button');
      item.type = 'button';
      item.className = 'sv-grid-actions-item';
      var icono = control.querySelector('i');
      var texto = String(control.getAttribute('aria-label') || control.title || control.textContent || 'Acción').trim();
      item.innerHTML = (icono ? '<i class="' + escapeHTML(icono.className) + '"></i>' : '') +
        '<span>' + escapeHTML(texto || 'Acción') + '</span>';
      item.addEventListener('click', function(ev) {
        ev.preventDefault();
        ev.stopPropagation();
        menu.classList.remove('abierto');
        trigger.setAttribute('aria-expanded', 'false');
        if (!control.disabled) control.click();
      });
      menu.appendChild(item);
    });
    trigger.addEventListener('click', function(ev) {
      ev.preventDefault();
      ev.stopPropagation();
      document.querySelectorAll('.sv-grid-actions-menu.abierto').forEach(function(otro) {
        if (otro !== menu) otro.classList.remove('abierto');
      });
      var abrir = !menu.classList.contains('abierto');
      menu.classList.toggle('abierto', abrir);
      trigger.setAttribute('aria-expanded', abrir ? 'true' : 'false');
    });
    if (accionPrincipal) celda.appendChild(accionPrincipal);
    celda.appendChild(originales);
    celda.appendChild(trigger);
    celda.appendChild(menu);
  });
  if (window.SisVentas && typeof window.SisVentas.prepareResizablePage === 'function') {
    window.SisVentas.prepareResizablePage(tabla);
  }
}

function _svTextoColumnaTarjeta(th, indice, total) {
  if (!th) return indice === total - 1 ? 'Acciones' : 'Dato';
  var explicito = th.getAttribute('data-sv-column-label') || th.getAttribute('aria-label') || '';
  var texto = String(explicito || th.textContent || '').replace(/\s+/g, ' ').trim();
  if (!texto && indice === total - 1) return 'Acciones';
  return texto || 'Dato';
}

// Todas las grillas comparten la misma representación en celular. Las tablas
// continúan intactas en escritorio; sólo se añaden metadatos para que cada fila
// pueda presentarse como una tarjeta legible cuando el ancho es reducido.
function prepararTarjetasMovilesGrilla(tabla) {
  if (!tabla || !tabla.querySelector || tabla.matches('.no-mobile-cards,[data-sv-mobile-cards="off"]')) return;
  var filasCabecera = Array.from(tabla.querySelectorAll('thead tr'));
  var cabecera = filasCabecera.length ? filasCabecera[filasCabecera.length - 1] : null;
  var encabezados = cabecera ? Array.from(cabecera.children).filter(function(el){ return el.tagName === 'TH'; }) : [];
  if (!encabezados.length || !tabla.tBodies || !tabla.tBodies.length) return;
  tabla.classList.add('sv-mobile-card-grid');
  Array.from(tabla.tBodies).forEach(function(tbody) {
    Array.from(tbody.rows).forEach(function(fila) {
      if (fila.dataset.svCardReady === '1' && fila.cells.length === encabezados.length) return;
      fila.dataset.svCardReady = '1';
      Array.from(fila.cells).forEach(function(celda, indice) {
        var etiqueta = _svTextoColumnaTarjeta(encabezados[indice], indice, encabezados.length);
        celda.dataset.label = etiqueta;
        celda.classList.toggle('sv-card-actions', /^(acciones?|opciones?)$/i.test(etiqueta));
        celda.classList.toggle('sv-card-wide', celda.colSpan > 1 || /^(cliente|producto|descripci[oó]n|concepto|observaci[oó]n|detalle|direcci[oó]n)$/i.test(etiqueta));
      });
    });
  });
  prepararAccionesGrilla(tabla);
}

function inicializarGrillasEn(contenedor) {
  var root = contenedor && contenedor.querySelectorAll ? contenedor : document;
  var tablas = [];
  if (root.matches && root.matches('table')) tablas.push(root);
  if (root.closest) {
    var contenedora = root.closest('table');
    if (contenedora) tablas.push(contenedora);
  }
  root.querySelectorAll('table').forEach(function(tabla){ tablas.push(tabla); });
  Array.from(new Set(tablas)).forEach(function(tabla) {
    prepararTarjetasMovilesGrilla(tabla);
    if (window.SisVentas && typeof window.SisVentas.prepareResizablePage === 'function') {
      window.SisVentas.prepareResizablePage(tabla);
    }
  });
}

function instalarDesplazamientoTablas() {
  asegurarDesplazamientoTablas(document);
  inicializarGrillasEn(document);
  if (window._svGridObserver) return;
  var tablasPendientes = new Set();
  var programado = false;
  function procesarPendientes() {
    programado = false;
    var tablas = Array.from(tablasPendientes);
    tablasPendientes.clear();
    tablas.forEach(function(tabla) {
      asegurarDesplazamientoTablas(tabla);
      prepararTarjetasMovilesGrilla(tabla);
    });
  }
  window._svGridObserver = new MutationObserver(function(cambios) {
    cambios.forEach(function(cambio) {
      cambio.addedNodes.forEach(function(nodo) {
        if (!nodo || nodo.nodeType !== 1) return;
        if (nodo.matches && nodo.matches('table')) tablasPendientes.add(nodo);
        if (nodo.closest) {
          var tablaContenedora = nodo.closest('table');
          if (tablaContenedora) tablasPendientes.add(tablaContenedora);
        }
        if (nodo.querySelectorAll) {
          nodo.querySelectorAll('table').forEach(function(tabla){ tablasPendientes.add(tabla); });
        }
      });
    });
    if (tablasPendientes.size && !programado) {
      programado = true;
      window.requestAnimationFrame(procesarPendientes);
    }
  });
  window._svGridObserver.observe(document.body, { childList:true, subtree:true });
}

