function ventaValidaParaMetricas(v) {
  if (!v) return false;
  var estado = String(v.estado || v.estadoPago || '').toLowerCase();
  return v.anulada !== true && estado !== 'anulada' && estado !== 'cancelada' && estado !== 'cancelado';
}
