// Las imágenes históricas de productos suelen apuntar al sitio del proveedor.
// Al mostrarse por primera vez se archivan, sin Storage, con el mismo criterio
// de los comprobantes de Gastos: Data URL comprimida dentro de Realtime DB.
// La cola serial evita descargar y procesar muchas imágenes al mismo tiempo.
var _imagenesProductoArchivoCola = [];
var _imagenesProductoArchivoPendientes = {};
var _imagenesProductoArchivoFallidas = {};
var _imagenesProductoArchivoProcesando = false;

function imagenProductoEsRemotaArchivable(src) {
  var valor = String(src || '').trim();
  return /^https:\/\//i.test(valor) && !/firebasestorage\.googleapis\.com/i.test(valor);
}

function urlImagenProductoParaArchivo(src) {
  try {
    var parsed = new URL(String(src || ''), location.href);
    if (parsed.origin === location.origin) return parsed.href;
    var baseProxy = /^(127\.0\.0\.1|localhost)$/.test(location.hostname)
      ? 'http://127.0.0.1:8787'
      : SISVENTAS_FUNCTIONS.cotizadorProveedor;
    return baseProxy + '/imagen-producto?url=' + encodeURIComponent(parsed.href) + '&key=' + encodeURIComponent(SISVENTAS_FUNCTIONS.frontendKey);
  } catch (_) {
    return String(src || '');
  }
}

function productoPorClaveImagen(clave) {
  return Object.values(prodData || {}).find(function(p) {
    return String(p.fbKey || p.id || p.codigo || '') === String(clave || '');
  }) || null;
}

function comprimirImagenProductoAdjunta(blob) {
  return new Promise(function(resolve, reject) {
    var url = URL.createObjectURL(blob);
    var imagen = new Image();
    imagen.onload = function() {
      try {
        var limite = 520;
        var escala = Math.min(1, limite / Math.max(imagen.naturalWidth || 1, imagen.naturalHeight || 1));
        var canvas = document.createElement('canvas');
        canvas.width = Math.max(1, Math.round((imagen.naturalWidth || 1) * escala));
        canvas.height = Math.max(1, Math.round((imagen.naturalHeight || 1) * escala));
        var ctx = canvas.getContext('2d', { alpha:true });
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        ctx.drawImage(imagen, 0, 0, canvas.width, canvas.height);
        var data = canvas.toDataURL('image/webp', 0.78);
        if (!data || data.length > 300000) data = canvas.toDataURL('image/jpeg', 0.68);
        if (!data || data.length > 300000) throw new Error('La imagen comprimida continúa siendo demasiado grande');
        resolve(data);
      } catch (error) {
        reject(error);
      } finally {
        URL.revokeObjectURL(url);
      }
    };
    imagen.onerror = function() { URL.revokeObjectURL(url); reject(new Error('No se pudo decodificar la imagen')); };
    imagen.src = url;
  });
}

async function archivarImagenProductoRemota(tarea) {
  var producto = productoPorClaveImagen(tarea.clave);
  if (!producto || !producto.fbKey) return;
  var src = String(producto.imagenUrl || tarea.src || '').trim();
  if (!imagenProductoEsRemotaArchivable(src)) return;
  var respuesta = await fetch(urlImagenProductoParaArchivo(src), { cache:'force-cache' });
  if (!respuesta.ok) throw new Error('HTTP ' + respuesta.status);
  var tipo = String(respuesta.headers.get('content-type') || '');
  if (tipo && tipo.indexOf('image/') !== 0) throw new Error('El proveedor no devolvió una imagen');
  var dataUrl = await comprimirImagenProductoAdjunta(await respuesta.blob());
  var cambios = {
    imagenUrl: dataUrl,
    imagenUrlOriginal: producto.imagenUrlOriginal || src,
    imagenGuardadaMetodo: 'adjunto_base64',
    imagenGuardadaEn: Date.now(),
    imagenGuardadaBytes: dataUrl.length
  };
  await window.fbUpdate(window.fbRef(window.fbDB, FB_PATHS.productos + '/' + producto.fbKey), cambios);
  Object.assign(producto, cambios);
}

function procesarColaArchivoImagenesProducto() {
  if (_imagenesProductoArchivoProcesando || !_imagenesProductoArchivoCola.length) return;
  if (!window.fbDB || !window.fbUpdate || !window.fbRef) return;
  _imagenesProductoArchivoProcesando = true;
  var tarea = _imagenesProductoArchivoCola.shift();
  archivarImagenProductoRemota(tarea).catch(function(error) {
    _imagenesProductoArchivoFallidas[tarea.clave] = true;
    console.warn('[Productos] No se pudo archivar la imagen externa', tarea && tarea.src, error);
  }).finally(function() {
    delete _imagenesProductoArchivoPendientes[tarea.clave];
    _imagenesProductoArchivoProcesando = false;
    setTimeout(procesarColaArchivoImagenesProducto, 120);
  });
}

function programarArchivoImagenProducto(clave, src) {
  // El navegador ya cachea las URLs remotas. No volver a incrustarlas como
  // Base64 en Firebase: eso hace que cada snapshot del catálogo pese megabytes.
  return;
}

function urlImagenProductoVisual(producto, alternativa) {
  producto = producto || {};
  var actual = String(producto.imagenUrl || alternativa || '').trim();
  var original = String(producto.imagenUrlOriginal || '').trim();
  if (/^data:image\//i.test(actual) && /^https?:\/\//i.test(original)) return original;
  return actual;
}

function imagenProductoItemHTML(item, extraClass) {
  var prod = productoDesdeItem(item);
  var src = urlImagenProductoVisual(prod, item.imagenUrl || item.productoImagenUrl || '');
  var clave = (prod && (prod.fbKey || prod.id || prod.codigo)) || item.pid || item.productoFbKey || item.codigo || '';
  var cls = escapeHTML('item-prod-img ' + (extraClass || ''));
  if (src) {
    return '<img class="'+cls+'" src="'+escapeHTML(src)+'" loading="lazy" decoding="async" onerror="this.style.display=\'none\'">';
  }
  return '<span class="'+cls+' item-prod-img-placeholder"><i class="ti ti-photo"></i></span>';
}
function jsStringAttr(valor) {
  return String(valor || '').replace(/\\/g, '\\\\').replace(/'/g, "\\'").replace(/\n/g, ' ');
}
var editingProdId = null;

var prodProveedoresActuales = [];
var _cotizacionProductoSecuencia = 0;
var _cotizacionProductoActiva = null;
var prodImagenArchivoTemp = null; // File pendiente de subir a Storage al guardar
var prodImagenBase64Temp = null;  // Preview local mientras no se guardó
var prodImagenUrlActual = '';     // URL final (sea de Storage o pegada a mano)

function firmaEstadoCotizacionProducto(proveedores, codigo, nombre) {
  return JSON.stringify({
    productoId:String(editingProdId || ''),
    codigo:String(codigo || '').trim(),
    nombre:String(nombre || '').trim(),
    urlGeneral:String(((document.getElementById('pf-cod-web') || {}).value) || '').trim(),
    proveedores:(proveedores || []).map(function(item) {
      var actual = prodProveedoresActuales[item.idx] || {};
      return [
        Number(item.idx),
        String(actual.proveedorKey || actual.proveedorFbKey || '').trim(),
        String(actual.nombre || actual.proveedor || '').trim().toLowerCase(),
        String(actual.url || '').trim(),
        parsePrecioProveedorARS(actual.precio || 0),
        actual.sinIva === true
      ];
    })
  });
}

function cotizacionProductoSigueActiva(contexto) {
  if (!contexto || _cotizacionProductoActiva !== contexto || contexto.secuencia !== _cotizacionProductoSecuencia) return false;
  if (String(editingProdId || '') !== contexto.productoId) return false;
  var form = document.getElementById('prod-form-view');
  if (!form || getComputedStyle(form).display === 'none') return false;
  var codigo = (document.getElementById('pf-codigo') || {}).value || '';
  var nombre = (document.getElementById('pf-nombre') || {}).value || (document.getElementById('pf-descripcion') || {}).value || '';
  return firmaEstadoCotizacionProducto(contexto.proveedores, codigo, nombre) === contexto.firma;
}

function cancelarCotizacionProductoEditor() {
  _cotizacionProductoSecuencia++;
  _cotizacionProductoActiva = null;
  var box = document.getElementById('pf-proveedores-cotizacion-resultado');
  if (box) {
    box.innerHTML = '';
    box.style.display = 'none';
  }
  restaurarBotonCotizacionProveedores();
}

function margenProductoDefault() {
  var n = parseFloat(window._margenProductoDefault);
  return isFinite(n) && n >= 0 ? n : 30;
}

function obtenerDolarReferenciaProducto() {
  var cfg = window.TIPO_CAMBIO_CONFIG || {};
  var tipo = cfg.dolarConversion || 'oficial';
  var valor = parseFloat(cfg[tipo]) || parseFloat(cfg.oficial) || parseFloat(cfg.blue) || parseFloat(cfg.mep) || 0;
  if (!valor && window._tipoCambioActual && window._tipoCambioActual.venta) {
    tipo = 'venta';
    valor = parseFloat(window._tipoCambioActual.venta) || 0;
  }
  return { tipo: tipo, valor: valor };
}

function esProveedorTecnoprices(nombreProveedor) {
  return /tecnoprices/i.test(String(nombreProveedor || '').trim());
}

function normalizarUrlProveedorProducto(url, nombreProveedor) {
  var u = String(url || '').trim();
  if (!u) return '';
  if (/^https?:\/\//i.test(u)) return u;
  // Un código numérico no identifica al proveedor. Sólo Tecnoprices usa
  // oficialmente este atajo; en cualquier otra fila se conserva como código.
  if (/^\d+$/.test(u) && esProveedorTecnoprices(nombreProveedor)) {
    return 'https://www.tecnoprices.com/' + u;
  }
  return u;
}

function normalizarUrlComparacionProveedor(url) {
  var u = normalizarUrlProveedorProducto(url);
  return String(u || '')
    .trim()
    .replace(/^https?:\/\//i, '')
    .replace(/^www\./i, '')
    .replace(/[?#].*$/, '')
    .replace(/\/+$/, '')
    .toLowerCase();
}

function urlsProveedorEquivalentes(a, b) {
  var ua = normalizarUrlComparacionProveedor(a);
  var ub = normalizarUrlComparacionProveedor(b);
  return !!ua && !!ub && ua === ub;
}

function resultadoCotizacionUsaUrlExacta(match, resultado, respuesta) {
  if (!match || !match.urlProducto) return true;
  resultado = resultado || {};
  respuesta = respuesta || {};
  var urlRes = String(resultado.url || '').trim();
  if (!urlRes || !urlsProveedorEquivalentes(match.url, urlRes)) return false;
  var textoControl = [
    resultado.error,
    resultado.observaciones,
    resultado.producto,
    resultado.detalle,
    respuesta.observaciones
  ].filter(Boolean).join(' ').toLowerCase();
  if (/no fue accesible|no accesible|inaccesible|categor[ií]a|p[aá]gina de categor|resultado de b[uú]squeda|b[uú]squeda|requiere login|iniciar sesi[oó]n|verificaci[oó]n manual|producto parecido|otra secci[oó]n/.test(textoControl)) {
    return false;
  }
  return true;
}

function parsePrecioProveedorARS(valor) {
  if (typeof valor === 'number') return valor;
  var s = String(valor || '').replace(/[^\d,.-]/g, '').trim();
  if (!s) return 0;
  if (typeof normalizarNumeroExcel === 'function') {
    var nExcel = parseFloat(normalizarNumeroExcel(s));
    if (nExcel > 0) return nExcel;
  }
  var lastComma = s.lastIndexOf(',');
  var lastDot = s.lastIndexOf('.');
  if (lastComma > lastDot) s = s.replace(/\./g, '').replace(',', '.');
  else if (lastDot > lastComma) s = s.replace(/,/g, '');
  return parseFloat(s) || 0;
}

function alicuotaIvaProveedorProducto(pv, ivaProducto) {
  pv = pv || {};
  var declarada = parseFloat(pv.ivaAlicuota);
  if (isFinite(declarada) && declarada >= 0 && declarada <= 100) return declarada;
  var producto = parseFloat(ivaProducto);
  if (isFinite(producto) && producto >= 0 && producto <= 100) return producto;
  return 21;
}

function factorIvaProveedorProducto(pv, ivaProducto) {
  return pv && pv.sinIva ? 1 + (alicuotaIvaProveedorProducto(pv, ivaProducto) / 100) : 1;
}

function costoRealProveedorProducto(pv, ivaProducto) {
  pv = pv || {};
  var guardado = parseFloat(pv.costoRealArs) || 0;
  if (guardado > 0) return guardado;
  var publicado = parseFloat(pv.precioArsPublicado || pv.precio) || 0;
  return publicado > 0 ? publicado * factorIvaProveedorProducto(pv, ivaProducto) : 0;
}

// El proveedor informa el precio de su presentación (por ejemplo, una bobina).
// Para productos fraccionados por metro, el catálogo opera siempre con el valor
// unitario: costo de la presentación / metros declarados en la ficha.
function costoUnitarioProveedorProducto(p, pv) {
  var costoPresentacion = costoRealProveedorProducto(pv, p && p.iva);
  if (!(costoPresentacion > 0)) return 0;
  var unidadesPorPresentacion = metrosPorPresentacionProducto(p);
  return Math.round((costoPresentacion / unidadesPorPresentacion) * 100) / 100;
}

function costoUnitarioProveedorPrincipalProducto(p) {
  var proveedor = _proveedorPrincipalProductoSinReconciliar(p);
  // Los productos anteriores a la grilla de proveedores conservan proveedor,
  // precio y URL en campos legacy. proveedoresVinculadosProducto los normaliza
  // en memoria para que también reciban la misma conversión por metro.
  if (!proveedor) {
    var proveedoresLegacy = proveedoresVinculadosProducto(p);
    proveedor = proveedoresLegacy.length ? proveedoresLegacy[0] : null;
  }
  return proveedor ? costoUnitarioProveedorProducto(p, proveedor) : 0;
}

function precioVentaDesdeCostoUnitarioProducto(p, costoUnitario) {
  var costo = parseFloat(costoUnitario) || 0;
  if (!(costo > 0)) return 0;
  var margen = parseFloat(p && p.margenDeseado);
  if (!isFinite(margen) || margen < 0 || margen > 500) margen = margenProductoDefault();
  return Math.round(costo * (1 + margen / 100) * 100) / 100;
}

function completarReferenciaProveedorProducto(pv, urlFallback, origen) {
  pv = Object.assign({}, pv || {});
  var tc = obtenerDolarReferenciaProducto();
  var precio = parseFloat(pv.precio) || parseFloat(pv.precioArsPublicado) || 0;
  var monedaDeclarada = String(pv.moneda || pv.monedaPublicada || pv.monedaPrecio || '').toUpperCase();
  var origenTexto = String(origen || pv.actualizadoOrigen || '').toLowerCase();
  var esLegacyUsd = precio > 0 && tc.valor > 0 && (
    monedaDeclarada === 'USD' ||
    ((origenTexto.indexOf('legacy') >= 0 || origenTexto === '') && precio < 100)
  );
  var precioUsdLegacy = esLegacyUsd ? precio : 0;
  if (esLegacyUsd) {
    precio = Math.round(precio * tc.valor * 100) / 100;
  }
  var url = normalizarUrlProveedorProducto(pv.url || urlFallback || '', pv.nombre || pv.proveedor || '');
  var costoReal = precio > 0 ? precio * factorIvaProveedorProducto(pv) : 0;
  pv.nombre = String(pv.nombre || pv.proveedor || '').trim();
  pv.precio = Math.round(precio * 100) / 100;
  pv.precioArsPublicado = pv.precio;
  pv.monedaPublicada = 'ARS';
  if (esLegacyUsd) pv.monedaOriginalLegacy = 'USD';
  pv.sinIva = !!pv.sinIva;
  pv.costoRealArs = Math.round(costoReal * 100) / 100;
  pv.url = url;
  if (tc.valor > 0 && pv.precio > 0) {
    pv.dolarUsado = tc.valor;
    pv.dolarTipo = tc.tipo;
    pv.precioUsdReferencia = precioUsdLegacy || Math.round((pv.precio / tc.valor) * 100) / 100;
    pv.costoRealUsdReferencia = Math.round((pv.costoRealArs / tc.valor) * 100) / 100;
  }
  pv.actualizado = pv.actualizado || new Date().toISOString().slice(0,10);
  pv.actualizadoEn = pv.actualizadoEn || Date.now();
  pv.actualizadoOrigen = esLegacyUsd ? 'legacy-usd-convertido-ars' : (origen || pv.actualizadoOrigen || 'manual');
  return pv;
}

function _primerNumeroPositivoProducto(valores) {
  for (var i = 0; i < valores.length; i++) {
    var n = parseFloat(valores[i]);
    if (n > 0 && isFinite(n)) return n;
  }
  return 0;
}

function _costoRaizProductoSinAuditar(p) {
  p = p || {};
  return _primerNumeroPositivoProducto([p.compraARS, p.precioGremio, p.compra, p.costoRealArs, p.precioArsPublicado]);
}

function _proveedorPrincipalProductoSinReconciliar(p) {
  p = p || {};
  var lista = Array.isArray(p.proveedores) ? p.proveedores.filter(Boolean) : [];
  if (!lista.length) return null;
  var nombre = String(p.proveedor || p.nom_prov || '').trim().toLowerCase();
  var encontrado = nombre ? lista.find(function(pv) {
    return String((pv && (pv.nombre || pv.proveedor)) || '').trim().toLowerCase() === nombre;
  }) : null;
  if (encontrado) return encontrado;
  return lista.reduce(function(mejor, pv) {
    var costoPv = _primerNumeroPositivoProducto([pv.costoRealArs, pv.precioArsPublicado, pv.precio]);
    var costoMejor = _primerNumeroPositivoProducto([mejor && mejor.costoRealArs, mejor && mejor.precioArsPublicado, mejor && mejor.precio]);
    return costoPv > 0 && (!(costoMejor > 0) || costoPv < costoMejor) ? pv : mejor;
  }, lista[0]);
}

function _costoProveedorProductoSinAuditar(p, pv) {
  pv = pv || _proveedorPrincipalProductoSinReconciliar(p);
  if (!pv) return 0;
  var costo = parseFloat(pv.costoRealArs) || 0;
  if (costo > 0) return costo;
  var publicado = _primerNumeroPositivoProducto([pv.precioArsPublicado, pv.precio]);
  return publicado > 0 ? publicado * factorIvaProveedorProducto(pv, p && p.iva) : 0;
}

function _tiposCambioAuditoriaProducto(p, pv) {
  var actual = obtenerDolarReferenciaProducto();
  var valores = [
    p && p.tcGuardado,
    p && p.dolarUsadoVenta,
    p && p.dolarUsado,
    p && p.precioVentaCorregidoDuplicacionDolarTc,
    pv && pv.dolarUsado,
    actual && actual.valor
  ];
  return valores.map(function(x){ return parseFloat(x) || 0; }).filter(function(x, idx, arr) {
    return x > 100 && arr.findIndex(function(y){ return Math.abs(y - x) < 0.01; }) === idx;
  });
}

function _relacionCercanaProducto(valor, referencia, tolerancia) {
  valor = parseFloat(valor) || 0;
  referencia = parseFloat(referencia) || 0;
  if (!(valor > 0) || !(referencia > 0)) return false;
  var ratio = valor / referencia;
  return ratio >= 1 - tolerancia && ratio <= 1 + tolerancia;
}

// Migración puntual respaldada por los importes observados antes y después del
// actualizador del 21/07/2026. Se exige código + costo + venta: no alcanza con
// que un producto sea caro, por lo que un importe legítimo nunca entra acá.
var _PRECIOS_CONTAMINADOS_CONFIRMADOS_20260721 = {
  'P-60853': { costo:93379345, venta:133399059, tc:1495 },
  'P-16403': { costo:46466170, venta:66380243, tc:1495 },
  'P-7209':  { costo:58244751, venta:83206781, tc:1495 }
};

function _migracionConfirmadaActualizador20260721(p, costoGuardado, ventaGuardada) {
  var codigo = String((p && p.codigo) || '').trim().toUpperCase().replace(/\s+/g, '');
  var confirmado = _PRECIOS_CONTAMINADOS_CONFIRMADOS_20260721[codigo];
  if (!confirmado) return null;
  if (!_relacionCercanaProducto(costoGuardado, confirmado.costo, 0.005)) return null;
  if (!_relacionCercanaProducto(ventaGuardada, confirmado.venta, 0.005)) return null;
  return {
    costoGuardado: costoGuardado,
    costoCorregido: Math.round((costoGuardado / confirmado.tc) * 100) / 100,
    ventaGuardada: ventaGuardada,
    ventaCorregida: Math.round((ventaGuardada / confirmado.tc) * 100) / 100,
    tipoCambio: confirmado.tc,
    proveedorConfirma: false,
    forzarMigracion: true,
    origen: 'migracion-confirmada-actualizador-20260721'
  };
}

// Auditoría general del mismo incidente. El lote dejó costo y venta en ARS
// multiplicados nuevamente por la cotización, mientras compraUSD/ventaUSD
// conservaron por accidente los importes ARS previos. Se exigen ambos pares,
// el mismo factor y una relación comercial razonable para no corregir por un
// simple umbral de precio.
function _migracionGeneralActualizador20260721(p, costoGuardado, ventaGuardada) {
  if (!(costoGuardado >= 5000000) || !(ventaGuardada >= 5000000)) return null;
  var costoReferencia = parseFloat(p && p.compraUSD) || 0;
  var ventaReferencia = parseFloat(p && p.ventaUSD) || 0;
  if (!(costoReferencia > 0) || !(ventaReferencia > 0)) return null;

  var proveedor = _proveedorPrincipalProductoSinReconciliar(p);
  var origen = String((p && (p.precioActualizadoOrigen || p.precioVentaActualizadoOrigen)) || (proveedor && proveedor.actualizadoOrigen) || '').toLowerCase();
  var origenActualizador = /biosegur|free_electron|tecnoprices|mercado_libre|url_exacta|scraping|actualizador|proveedor/.test(origen);
  if (!origenActualizador) return null;

  var tiposCambio = _tiposCambioAuditoriaProducto(p, proveedor);
  for (var i = 0; i < tiposCambio.length; i++) {
    var tc = tiposCambio[i];
    var costoCorregido = Math.round((costoGuardado / tc) * 100) / 100;
    var ventaCorregida = Math.round((ventaGuardada / tc) * 100) / 100;
    if (!(costoCorregido >= 100) || costoCorregido > 2000000) continue;
    if (!(ventaCorregida >= 100) || ventaCorregida > 5000000) continue;
    if (!_relacionCercanaProducto(costoCorregido, costoReferencia, 0.03)) continue;
    if (!_relacionCercanaProducto(ventaCorregida, ventaReferencia, 0.03)) continue;
    if (!_precioVentaRazonableRespectoCosto(ventaCorregida, costoCorregido)) continue;
    return {
      costoGuardado: costoGuardado,
      costoCorregido: costoCorregido,
      ventaGuardada: ventaGuardada,
      ventaCorregida: ventaCorregida,
      tipoCambio: tc,
      proveedorConfirma: false,
      forzarMigracion: true,
      origen: 'auditoria-general-actualizador-20260721'
    };
  }
  return null;
}

// El actualizador de proveedores llegó a aceptar importes que ya estaban en ARS
// como si fueran USD y los multiplicó otra vez por la cotización. Se auditan
// costo y venta juntos: la reparación solo se habilita cuando el proveedor, la
// corrección anterior o la relación costo/venta corroboran el mismo factor.
function detectarProductoArsDuplicadoPorDolar(p) {
  p = p || {};
  var costoGuardado = _costoRaizProductoSinAuditar(p);
  var ventaGuardada = _primerNumeroPositivoProducto([p.ventaARS, p.precioArsPublicadoVenta, p.venta, p.precio_venta, p.precioVenta]);
  if (!(costoGuardado > 0) && !(ventaGuardada > 0)) return null;

  var migracionConfirmada = _migracionConfirmadaActualizador20260721(p, costoGuardado, ventaGuardada);
  if (migracionConfirmada) return migracionConfirmada;

  var migracionGeneral = _migracionGeneralActualizador20260721(p, costoGuardado, ventaGuardada);
  if (migracionGeneral) return migracionGeneral;

  var proveedor = _proveedorPrincipalProductoSinReconciliar(p);
  var costoProveedor = _costoProveedorProductoSinAuditar(p, proveedor);
  var tiposCambio = _tiposCambioAuditoriaProducto(p, proveedor);
  var ventaContaminadaAnterior = parseFloat(p.precioVentaCorregidoDuplicacionDolarAntes) || 0;
  var margen = parseFloat(p.margenDeseado);

  for (var i = 0; i < tiposCambio.length; i++) {
    var tc = tiposCambio[i];
    var costoDividido = costoGuardado > 0 ? Math.round((costoGuardado / tc) * 100) / 100 : 0;
    var ventaDividida = ventaGuardada > 0 ? Math.round((ventaGuardada / tc) * 100) / 100 : 0;
    var proveedorConfirma = costoProveedor > 0 && costoGuardado / costoProveedor > 50 && _relacionCercanaProducto(costoDividido, costoProveedor, 0.12);
    var repeticionConfirmada = ventaContaminadaAnterior > 0 && _relacionCercanaProducto(ventaGuardada, ventaContaminadaAnterior, 0.02);
    var parejaConfirma = costoDividido > 0 && ventaDividida > 0 && _precioVentaRazonableRespectoCosto(ventaDividida, costoDividido);
    var origenActualizador = /(?:biosegur|free_electron|tecnoprices|mercado_libre|proveedor).*?(?:lote|url_exacta|actualizador)/i.test(String(p.precioActualizadoOrigen || p.precioVentaActualizadoOrigen || ''));

    // Para una primera contaminación exigimos el costo anterior del proveedor.
    // Si el mismo importe ya había sido reparado, esa auditoría previa también
    // es una prueba inequívoca y permite recuperar costo y venta en conjunto.
    if (!proveedorConfirma && !repeticionConfirmada) continue;
    if (!parejaConfirma && !(ventaDividida > 0 && costoProveedor > 0 && _precioVentaRazonableRespectoCosto(ventaDividida, costoProveedor))) continue;
    if (!origenActualizador && !repeticionConfirmada) continue;

    var costoCorregido = proveedorConfirma ? Math.round(costoProveedor * 100) / 100 : costoDividido;
    var ventaCorregida = ventaDividida;
    if (!(ventaCorregida > 0) && costoCorregido > 0 && isFinite(margen) && margen >= 0) {
      ventaCorregida = Math.round(costoCorregido * (1 + margen / 100) * 100) / 100;
    }
    if (!(costoCorregido > 0) || !(ventaCorregida > 0) || !_precioVentaRazonableRespectoCosto(ventaCorregida, costoCorregido)) continue;
    return {
      costoGuardado: costoGuardado,
      costoCorregido: costoCorregido,
      ventaGuardada: ventaGuardada,
      ventaCorregida: ventaCorregida,
      tipoCambio: tc,
      proveedorConfirma: proveedorConfirma,
      origen: repeticionConfirmada ? 'reincidencia-actualizador' : 'proveedor-confirma-factor-dolar'
    };
  }
  return null;
}

// Detecta registros heredados cuya cifra quedó guardada en la moneda equivocada.
// No usa solamente un umbral: exige que, después de convertir, costo y venta
// vuelvan a tener una relación comercial razonable. Los servicios quedan fuera
// porque pueden tener costos simbólicos y márgenes deliberadamente atípicos.
function detectarPrecioLegacyMonedaProducto(p) {
  p = p || {};
  if (typeof esProductoManoDeObra === 'function' && esProductoManoDeObra(p)) return null;
  var costoGuardado = _costoRaizProductoSinAuditar(p);
  var ventaGuardada = _primerNumeroPositivoProducto([p.ventaARS, p.precioArsPublicadoVenta, p.venta, p.precio_venta, p.precioVenta]);
  var tcInfo = obtenerDolarReferenciaProducto();
  var tc = parseFloat(p.tcGuardado || p.dolarUsadoVenta || p.dolarUsado || (tcInfo && tcInfo.valor)) || 0;
  if (!(tc > 100)) return null;

  if (costoGuardado >= 5000000 && ventaGuardada >= 5000000) {
    var costoDividido = Math.round((costoGuardado / tc) * 100) / 100;
    var ventaDividida = Math.round((ventaGuardada / tc) * 100) / 100;
    if (costoDividido >= 100 && costoDividido <= 2000000 &&
        ventaDividida >= 100 && ventaDividida <= 5000000 &&
        _precioVentaRazonableRespectoCosto(ventaDividida, costoDividido)) {
      return {
        tipo:'ars_multiplicado_por_dolar',
        costoGuardado:costoGuardado,
        costoCorregido:costoDividido,
        ventaGuardada:ventaGuardada,
        ventaCorregida:ventaDividida,
        tipoCambio:tc,
        origen:'auditoria-matematica-costo-venta'
      };
    }
  }

  if (costoGuardado > 0 && costoGuardado < 5000 && ventaGuardada >= 100) {
    var costoConvertido = Math.round(costoGuardado * tc * 100) / 100;
    if (_precioVentaRazonableRespectoCosto(ventaGuardada, costoConvertido)) {
      return {
        tipo:'costo_usd_legacy',
        costoGuardado:costoGuardado,
        costoCorregido:costoConvertido,
        ventaGuardada:ventaGuardada,
        ventaCorregida:ventaGuardada,
        tipoCambio:tc,
        origen:'auditoria-matematica-costo-usd'
      };
    }
  }

  if (ventaGuardada > 0 && ventaGuardada < 5000 && costoGuardado >= 100) {
    var ventaConvertida = Math.round(ventaGuardada * tc * 100) / 100;
    var margen = parseFloat(p.margenDeseado);
    if (isFinite(margen) && margen >= 0 && margen <= 500) {
      ventaConvertida = Math.round(costoGuardado * (1 + margen / 100) * 100) / 100;
    }
    if (_precioVentaRazonableRespectoCosto(ventaConvertida, costoGuardado)) {
      return {
        tipo:'venta_usd_legacy',
        costoGuardado:costoGuardado,
        costoCorregido:costoGuardado,
        ventaGuardada:ventaGuardada,
        ventaCorregida:ventaConvertida,
        tipoCambio:tc,
        origen:'auditoria-matematica-venta-usd'
      };
    }
  }
  return null;
}

function precioGremioARSDesdeProducto(p) {
  p = p || {};
  var auditoriaProducto = detectarProductoArsDuplicadoPorDolar(p);
  if (auditoriaProducto && auditoriaProducto.costoCorregido > 0) return auditoriaProducto.costoCorregido;
  var legacyMoneda = detectarPrecioLegacyMonedaProducto(p);
  if (legacyMoneda && legacyMoneda.costoCorregido > 0) return legacyMoneda.costoCorregido;
  // Para metros, el proveedor es la fuente de la presentación y este valor
  // devuelve el costo por metro. Así ficha, buscador, presupuestos y ventas
  // nuevas comparten exactamente el mismo cálculo.
  if (String(p.unidad || '').toLowerCase() === 'metro') {
    var costoMetroProveedor = costoUnitarioProveedorPrincipalProducto(p);
    if (costoMetroProveedor > 0) return costoMetroProveedor;
  }
  var proveedorPrincipal = Array.isArray(p.proveedores) && p.proveedores.length ? p.proveedores[0] : null;
  var tc = obtenerDolarReferenciaProducto();
  // Los campos normalizados del producto son la fuente operativa. Antes se
  // priorizaba precioArsPublicado, por lo que un valor viejo del proveedor
  // podía ocultar una edición manual recién guardada en compraARS.
  var candidatos = [
    p.compraARS,
    p.precioGremio,
    p.compra,
    p.costoRealArs,
    p.precioArsPublicado,
    proveedorPrincipal && proveedorPrincipal.costoRealArs,
    proveedorPrincipal && proveedorPrincipal.precioArsPublicado,
    proveedorPrincipal && proveedorPrincipal.precio
  ];
  for (var i = 0; i < candidatos.length; i++) {
    var n = parseFloat(candidatos[i]);
    if (n > 0) {
      var monedaProv = String((proveedorPrincipal && (proveedorPrincipal.moneda || proveedorPrincipal.monedaPublicada || proveedorPrincipal.monedaPrecio)) || '').toUpperCase();
      var origenProv = String((proveedorPrincipal && proveedorPrincipal.actualizadoOrigen) || '').toLowerCase();
      var pareceUsdLegacy = tc.valor > 0 && n < 100 && (monedaProv === 'USD' || origenProv.indexOf('legacy') >= 0);
      return pareceUsdLegacy ? Math.round(n * tc.valor * 100) / 100 : n;
    }
  }
  var compraLegacy = parseFloat(p.compra) || 0;
  if (compraLegacy > 0 && String(p.moneda || '').toUpperCase() === 'USD' && tc.valor > 0) {
    return Math.round(compraLegacy * tc.valor * 100) / 100;
  }
  return compraLegacy || 0;
}

function reconciliarCostoProductoConProveedorPrincipal(p, proveedores) {
  var lista = Array.isArray(proveedores) ? proveedores.map(function(pv){ return Object.assign({}, pv); }) : [];
  if (!lista.length) return lista;
  var costoRaiz = parseFloat(p && (p.compraARS || p.precioGremio || p.compra)) || 0;
  if (!(costoRaiz > 0)) return lista;
  var nombrePrincipal = String((p && (p.proveedor || p.nom_prov)) || '').trim().toLowerCase();
  var idx = nombrePrincipal ? lista.findIndex(function(pv){
    return String((pv && (pv.nombre || pv.proveedor)) || '').trim().toLowerCase() === nombrePrincipal;
  }) : -1;
  if (idx < 0 && lista.length === 1) idx = 0;
  if (idx < 0) return lista;
  var pv = lista[idx];
  var metrosPresentacion = metrosPorPresentacionProducto(p);
  var costoPresentacionEsperado = costoRaiz * metrosPresentacion;
  var costoProveedor = costoRealProveedorProducto(pv, p && p.iva);
  if (Math.abs(costoProveedor - costoPresentacionEsperado) <= 0.009) return lista;
  var publicado = costoPresentacionEsperado / factorIvaProveedorProducto(pv, p && p.iva);
  pv.precio = Math.round(publicado * 100) / 100;
  pv.precioArsPublicado = pv.precio;
  pv.costoRealArs = Math.round(costoPresentacionEsperado * 100) / 100;
  pv.actualizadoOrigen = 'manual-sincronizado';
  lista[idx] = pv;
  return lista;
}

// Fuente única para el precio de venta que ve el usuario. Los registros nuevos
// guardan ventaARS; solo se convierte venta cuando el producto es realmente USD.
function precioVentaCanonicoProducto(p) {
  p = p || {};
  var auditoriaProducto = detectarProductoArsDuplicadoPorDolar(p);
  if (auditoriaProducto && auditoriaProducto.ventaCorregida > 0) {
    return {
      precioARS: auditoriaProducto.ventaCorregida,
      precioOrigen: auditoriaProducto.ventaGuardada,
      monedaOrigen: 'ARS_CORREGIDO_ACTUALIZADOR'
    };
  }
  var legacyMoneda = detectarPrecioLegacyMonedaProducto(p);
  if (legacyMoneda && legacyMoneda.ventaCorregida > 0) {
    return {
      precioARS: legacyMoneda.ventaCorregida,
      precioOrigen: legacyMoneda.ventaGuardada,
      monedaOrigen: 'ARS_CORREGIDO_LEGACY'
    };
  }
  var duplicadoDolar = detectarVentaArsDuplicadaPorDolar(p);
  if (duplicadoDolar) {
    return {
      precioARS: duplicadoDolar.precioCorregido,
      precioOrigen: duplicadoDolar.precioGuardado,
      monedaOrigen: 'ARS_CORREGIDO_DUPLICACION_DOLAR'
    };
  }
  // El precio de venta de un producto por metro parte del costo unitario de
  // proveedor; nunca del valor total de la bobina guardado en datos antiguos.
  if (String(p.unidad || '').toLowerCase() === 'metro') {
    var costoMetroVenta = costoUnitarioProveedorPrincipalProducto(p);
    if (costoMetroVenta > 0) {
      return {
        precioARS: precioVentaDesdeCostoUnitarioProducto(p, costoMetroVenta),
        precioOrigen: costoMetroVenta,
        monedaOrigen: 'PROVEEDOR_POR_METRO'
      };
    }
  }
  var ventaARS = parseFloat(p.ventaARS || p.precioArsPublicadoVenta || 0) || 0;
  if (ventaARS > 0) {
    var costoCanonico = precioGremioARSDesdeProducto(p);
    if (costoCanonico > 100 && ventaARS < costoCanonico * 0.2) {
      var margenCanonico = parseFloat(p.margenDeseado);
      if (!isFinite(margenCanonico) || margenCanonico < 0 || margenCanonico > 500) margenCanonico = margenProductoDefault();
      return {
        precioARS: Math.round(costoCanonico * (1 + margenCanonico / 100) * 100) / 100,
        precioOrigen: ventaARS,
        monedaOrigen: 'ARS_CORREGIDO_VENTA_INSUFICIENTE'
      };
    }
    return { precioARS: ventaARS, precioOrigen: ventaARS, monedaOrigen: 'ARS' };
  }
  var venta = parseFloat(p.venta || p.precio_venta || p.precioVenta || 0) || 0;
  var moneda = String(p.moneda || p.monedaVenta || 'ARS').toUpperCase();
  if (moneda === 'USD') {
    var tc = obtenerDolarReferenciaProducto();
    return { precioARS: tc.valor > 0 ? Math.round(venta * tc.valor * 100) / 100 : 0, precioOrigen: venta, monedaOrigen: 'USD' };
  }
  var costoVentaLegacy = precioGremioARSDesdeProducto(p);
  if (venta > 0 && costoVentaLegacy > 100 && venta < costoVentaLegacy * 0.2) {
    var margenVentaLegacy = parseFloat(p.margenDeseado);
    if (!isFinite(margenVentaLegacy) || margenVentaLegacy < 0 || margenVentaLegacy > 500) margenVentaLegacy = margenProductoDefault();
    return {
      precioARS: Math.round(costoVentaLegacy * (1 + margenVentaLegacy / 100) * 100) / 100,
      precioOrigen: venta,
      monedaOrigen: 'ARS_CORREGIDO_VENTA_INSUFICIENTE'
    };
  }
  return { precioARS: venta, precioOrigen: venta, monedaOrigen: 'ARS' };
}

function _precioVentaRazonableRespectoCosto(precio, costo) {
  var valor = parseFloat(precio) || 0;
  var costoArs = parseFloat(costo) || 0;
  if (!(valor > 0) || !(costoArs > 0)) return false;
  var relacion = valor / costoArs;
  return relacion >= 0.8 && relacion <= 10;
}

// Detecta el patrón exacto de la conversión duplicada: un precio ARS
// desproporcionado que, al dividirlo por el dólar usado, vuelve a quedar en una
// relación comercial razonable con el costo ARS del mismo producto.
function detectarVentaArsDuplicadaPorDolar(p) {
  p = p || {};
  var auditoriaProducto = detectarProductoArsDuplicadoPorDolar(p);
  if (auditoriaProducto) {
    return {
      precioGuardado: auditoriaProducto.ventaGuardada,
      precioCorregido: auditoriaProducto.ventaCorregida,
      costoARS: auditoriaProducto.costoCorregido,
      tipoCambio: auditoriaProducto.tipoCambio,
      origen: auditoriaProducto.origen
    };
  }
  var precioGuardado = parseFloat(p.ventaARS || p.precioArsPublicadoVenta || p.venta || p.precio_venta || p.precioVenta || 0) || 0;
  var costoARS = precioGremioARSDesdeProducto(p);
  if (!(precioGuardado > 0) || !(costoARS > 0) || precioGuardado / costoARS < 50) return null;

  var tcActual = obtenerDolarReferenciaProducto();
  var tipoCambioGuardado = parseFloat(p.tcGuardado || p.dolarUsadoVenta || p.dolarUsado || 0) || 0;
  var tipoCambio = tipoCambioGuardado > 100 ? tipoCambioGuardado : (parseFloat(tcActual.valor) || 0);
  var ventaUsdGuardada = parseFloat(p.ventaUSD || 0) || 0;
  var candidatos = [];
  if (ventaUsdGuardada > 0 && _precioVentaRazonableRespectoCosto(ventaUsdGuardada, costoARS)) {
    candidatos.push({ valor: ventaUsdGuardada, origen: 'ventaUSD_contenia_ars' });
  }
  if (tipoCambio > 100) {
    var dividido = Math.round((precioGuardado / tipoCambio) * 100) / 100;
    if (_precioVentaRazonableRespectoCosto(dividido, costoARS)) candidatos.push({ valor: dividido, origen: 'venta_ars_dividida_tc' });
  }
  if (!candidatos.length) return null;

  var margen = parseFloat(p.margenDeseado);
  var esperado = isFinite(margen) && margen >= 0 ? costoARS * (1 + margen / 100) : 0;
  candidatos.sort(function(a,b){
    if (!(esperado > 0)) return 0;
    return Math.abs(a.valor - esperado) - Math.abs(b.valor - esperado);
  });
  return {
    precioGuardado: precioGuardado,
    precioCorregido: candidatos[0].valor,
    costoARS: costoARS,
    tipoCambio: tipoCambio,
    origen: candidatos[0].origen
  };
}

var _reparacionVentasDuplicadasDolarEnCurso = false;

function _corregirProveedoresDuplicadosPorDolar(p, auditado) {
  if (!auditado || !(auditado.costoCorregido > 0) || !(auditado.tipoCambio > 100) || !Array.isArray(p && p.proveedores)) return null;
  var huboCambios = false;
  var lista = p.proveedores.map(function(original) {
    var pv = Object.assign({}, original || {});
    var cambioProveedor = false;
    ['precio','precioArsPublicado','costoRealArs'].forEach(function(campo) {
      var guardado = parseFloat(pv[campo]) || 0;
      if (!(guardado > auditado.costoCorregido * 50)) return;
      var dividido = Math.round((guardado / auditado.tipoCambio) * 100) / 100;
      var relacionCosto = dividido / auditado.costoCorregido;
      if (relacionCosto < 0.65 || relacionCosto > 1.25) return;
      pv[campo] = dividido;
      huboCambios = true;
      cambioProveedor = true;
    });
    if (cambioProveedor) {
      var publicado = _primerNumeroPositivoProducto([pv.precioArsPublicado, pv.precio]);
      var costo = _primerNumeroPositivoProducto([pv.costoRealArs, publicado]);
      pv.precioUsdReferencia = publicado > 0 ? Math.round((publicado / auditado.tipoCambio) * 100) / 100 : 0;
      pv.costoRealUsdReferencia = costo > 0 ? Math.round((costo / auditado.tipoCambio) * 100) / 100 : 0;
      pv.dolarUsado = auditado.tipoCambio;
      pv.actualizadoOrigen = 'reparacion-actualizador-proveedores';
    }
    return pv;
  });
  return huboCambios ? lista : null;
}

function repararVentasArsDuplicadasPorDolar() {
  if (_reparacionVentasDuplicadasDolarEnCurso || !window.fbDB || String(currentRole || '').toLowerCase() !== 'admin') return;
  var productosAuditables = Object.values(prodData || {}).filter(function(p){ return p && p.fbKey; });
  if (!productosAuditables.length) return;
  _reparacionVentasDuplicadasDolarEnCurso = true;
  var cambios = {};
  var afectados = [];
  var ahora = Date.now();
  productosAuditables.forEach(function(p) {
    var auditadoProducto = detectarProductoArsDuplicadoPorDolar(p);
    var auditado = auditadoProducto || detectarVentaArsDuplicadaPorDolar(p);
    if (!auditado) return;
    var base = FB_PATHS.productos + '/' + p.fbKey + '/';
    var ventaCorregida = auditadoProducto ? auditadoProducto.ventaCorregida : auditado.precioCorregido;
    var ventaGuardada = auditadoProducto ? auditadoProducto.ventaGuardada : auditado.precioGuardado;
    var costoCorregido = auditadoProducto ? auditadoProducto.costoCorregido : 0;
    var costoGuardado = auditadoProducto ? auditadoProducto.costoGuardado : 0;
    cambios[base + 'venta'] = ventaCorregida;
    cambios[base + 'ventaARS'] = ventaCorregida;
    cambios[base + 'precioArsPublicadoVenta'] = ventaCorregida;
    cambios[base + 'moneda'] = 'ARS';
    cambios[base + 'monedaVenta'] = 'ARS';
    cambios[base + 'monedaOperativa'] = 'ARS';
    if (costoCorregido > 0) {
      cambios[base + 'compra'] = costoCorregido;
      cambios[base + 'compraARS'] = costoCorregido;
      cambios[base + 'precioGremio'] = costoCorregido;
      cambios[base + 'costoRealArs'] = costoCorregido;
      var publicadoRaiz = parseFloat(p.precioArsPublicado) || 0;
      if (publicadoRaiz > costoCorregido * 50) cambios[base + 'precioArsPublicado'] = Math.round((publicadoRaiz / auditado.tipoCambio) * 100) / 100;
    }
    var proveedoresCorregidos = auditadoProducto ? _corregirProveedoresDuplicadosPorDolar(p, auditadoProducto) : null;
    if (proveedoresCorregidos) cambios[base + 'proveedores'] = proveedoresCorregidos;
    if (auditado.tipoCambio > 0) {
      cambios[base + 'ventaUSD'] = Math.round((ventaCorregida / auditado.tipoCambio) * 100) / 100;
      if (costoCorregido > 0) cambios[base + 'compraUSD'] = Math.round((costoCorregido / auditado.tipoCambio) * 100) / 100;
    }
    cambios[base + 'precioVentaCorregidoDuplicacionDolarEn'] = ahora;
    cambios[base + 'precioVentaCorregidoDuplicacionDolarPor'] = currentUser || 'Admin';
    cambios[base + 'precioVentaCorregidoDuplicacionDolarAntes'] = ventaGuardada;
    cambios[base + 'precioVentaCorregidoDuplicacionDolarTc'] = auditado.tipoCambio;
    cambios[base + 'precioVentaActualizadoOrigen'] = 'reparacion-actualizador-proveedores';
    cambios[base + 'precioActualizadoOrigen'] = 'reparacion-actualizador-proveedores';
    cambios[base + 'precioActualizadorReparacionBackup'] = {
      ts: ahora,
      usuario: currentUser || 'Admin',
      compra: parseFloat(p.compra) || null,
      compraARS: parseFloat(p.compraARS) || null,
      precioGremio: parseFloat(p.precioGremio) || null,
      costoRealArs: parseFloat(p.costoRealArs) || null,
      venta: parseFloat(p.venta) || null,
      ventaARS: parseFloat(p.ventaARS) || null,
      compraUSD: parseFloat(p.compraUSD) || null,
      ventaUSD: parseFloat(p.ventaUSD) || null,
      moneda: p.moneda || null,
      monedaVenta: p.monedaVenta || null,
      proveedores: Array.isArray(p.proveedores) ? p.proveedores : null
    };
    cambios[base + 'auditoriaPrecioUltima'] = {
      ts: ahora,
      usuario: currentUser || 'Admin',
      motivo: auditadoProducto ? auditadoProducto.origen : auditado.origen,
      tipoCambio: auditado.tipoCambio,
      costoAntes: costoGuardado || null,
      costoDespues: costoCorregido || null,
      ventaAntes: ventaGuardada,
      ventaDespues: ventaCorregida
    };
    afectados.push(p.codigo || p.nombre || p.fbKey);
  });
  if (!afectados.length) {
    _reparacionVentasDuplicadasDolarEnCurso = false;
    return;
  }
  window.fbUpdate(window.fbRef(window.fbDB), cambios).then(function(){
    notify('✓ Auditoría terminada: ' + afectados.length + ' producto' + (afectados.length === 1 ? '' : 's') + ' reparado' + (afectados.length === 1 ? '' : 's'));
    if (typeof registrarActividad === 'function') registrarActividad('Auditoría del actualizador de proveedores', afectados.length + ' corregidos: ' + afectados.slice(0,40).join(', '));
  }).catch(function(e){
    console.error('[Productos] No se pudo reparar la duplicación del dólar', e);
    notify('No se pudo completar la auditoría automática de precios');
  }).finally(function(){
    _reparacionVentasDuplicadasDolarEnCurso = false;
  });
}

function _origenAuditoriaPrecioProducto(p) {
  p = p || {};
  var proveedor = _proveedorPrincipalProductoSinReconciliar(p) || {};
  return String(
    p.precioActualizadoOrigen || p.precioVentaActualizadoOrigen ||
    proveedor.actualizadoOrigen || p.actualizadoOrigen || 'sin origen'
  ).trim();
}

function _backupsAuditoriaPrecioProducto(p) {
  p = p || {};
  return [
    p.precioActualizadorReparacionBackup,
    p.auditoriaPrecioBackup20260723,
    p.auditoriaPrecioBackup
  ].filter(function(x){ return x && typeof x === 'object'; });
}

function _backupConfirmaCorreccionPrecio(p, correccion) {
  if (!correccion) return false;
  return _backupsAuditoriaPrecioProducto(p).some(function(backup) {
    var costo = _primerNumeroPositivoProducto([backup.compraARS, backup.precioGremio, backup.compra, backup.costoRealArs]);
    var venta = _primerNumeroPositivoProducto([backup.ventaARS, backup.precioArsPublicadoVenta, backup.venta]);
    var costoCoincide = !(correccion.costoCorregido > 0) || (costo > 0 && _relacionCercanaProducto(costo, correccion.costoCorregido, 0.035));
    var ventaCoincide = !(correccion.ventaCorregida > 0) || (venta > 0 && _relacionCercanaProducto(venta, correccion.ventaCorregida, 0.035));
    return costoCoincide && ventaCoincide;
  });
}

function _correccionPrecioTienePrueba(p, correccion) {
  if (!correccion) return false;
  if (correccion.proveedorConfirma || correccion.forzarMigracion) return true;
  if (_backupConfirmaCorreccionPrecio(p, correccion)) return true;
  var moneda = String(p.moneda || '').toUpperCase();
  var monedaVenta = String(p.monedaVenta || p.moneda || '').toUpperCase();
  if (correccion.tipo === 'costo_usd_legacy' && moneda === 'USD') return true;
  if (correccion.tipo === 'venta_usd_legacy' && monedaVenta === 'USD') return true;
  var origen = _origenAuditoriaPrecioProducto(p).toLowerCase();
  return /reparacion|duplicacion|actualizador|scraping|url_exacta|biosegur|free_electron|tecnoprices|mercado_libre/.test(origen) &&
    /proveedor-confirma|reincidencia|migracion-confirmada|auditoria-general/.test(String(correccion.origen || ''));
}

function _detalleProveedoresAuditoriaPrecio(p, costoRaiz) {
  var lista = Array.isArray(p && p.proveedores) ? p.proveedores.filter(Boolean) : [];
  var hallazgos = [];
  lista.forEach(function(pv) {
    var nombre = String(pv.nombre || pv.proveedor || 'Proveedor');
    var urlProveedor = String(pv.url || '').trim();
    var hostProveedor = '';
    try { hostProveedor = new URL(normalizarUrlProveedorProducto(urlProveedor, nombre)).hostname.toLowerCase(); } catch (_) {}
    var dominioIncompatible =
      (/(^|\.)tecnoprices\.com$/.test(hostProveedor) && !esProveedorTecnoprices(nombre)) ||
      (/(^|\.)biosegur\.com\.ar$/.test(hostProveedor) && !/biosegur/i.test(nombre)) ||
      (/(^|\.)free-electron\.com\.ar$/.test(hostProveedor) && !/free[\s-]*electron/i.test(nombre)) ||
      (((/(^|\.)mercadolibre\.com\.ar$/.test(hostProveedor)) || hostProveedor === 'meli.la') && !/mercado\s*libre|mercadolibre/i.test(nombre));
    if (dominioIncompatible) {
      hallazgos.push(nombre + ': la URL pertenece a otro proveedor (' + hostProveedor + ')');
    } else if (/^\d+$/.test(urlProveedor) && !esProveedorTecnoprices(nombre)) {
      hallazgos.push(nombre + ': tiene un código numérico, pero falta una URL verificable del proveedor');
    }
    var publicado = _primerNumeroPositivoProducto([pv.precioArsPublicado, pv.precio]);
    var costo = _costoProveedorProductoSinAuditar(p, pv);
    var costoDeclarado = parseFloat(pv.costoRealArs) || 0;
    var costoCalculado = publicado > 0 ? publicado * factorIvaProveedorProducto(pv, p && p.iva) : 0;
    if (costoDeclarado > 0 && costoCalculado > 0 && !_relacionCercanaProducto(costoDeclarado, costoCalculado, 0.08)) {
      hallazgos.push(nombre + ': el costo guardado no coincide con el precio publicado y su IVA');
    }
    if (costoRaiz > 0 && costo > 0) {
      var relacion = costo / costoRaiz;
      if (relacion < 0.2 || relacion > 5) {
        hallazgos.push(nombre + ': difiere más de 5 veces del costo principal');
      }
    }
  });
  return hallazgos;
}

function _motivoManualAuditoriaPrecio(p, costoRaw, ventaRaw, correccionCandidata) {
  var motivos = [];
  var origen = _origenAuditoriaPrecioProducto(p);
  var esServicio = typeof esProductoManoDeObra === 'function' && esProductoManoDeObra(p);
  var ratio = costoRaw > 0 && ventaRaw > 0 ? ventaRaw / costoRaw : 0;
  if (correccionCandidata) {
    motivos.push('Hay una conversión posible, pero falta una prueba independiente para aplicarla');
  }
  if (!esServicio && costoRaw >= 5000000) motivos.push('Costo extraordinario');
  if (!esServicio && ventaRaw >= 5000000) motivos.push('Precio de venta extraordinario');
  if (!esServicio && ratio > 0 && (ratio < 0.65 || ratio > 10)) motivos.push('Relación costo/venta fuera del rango operativo');
  var ultimoBackup = _backupsAuditoriaPrecioProducto(p)[0];
  if (ultimoBackup) {
    var costoBackup = _primerNumeroPositivoProducto([ultimoBackup.compraARS, ultimoBackup.precioGremio, ultimoBackup.compra, ultimoBackup.costoRealArs]);
    if (costoBackup > 0 && costoRaw > 0 && (costoRaw / costoBackup > 10 || costoBackup / costoRaw > 10)) {
      motivos.push('El costo actual difiere más de 10 veces del respaldo anterior');
    }
  }
  motivos = motivos.concat(_detalleProveedoresAuditoriaPrecio(p, costoRaw));
  return {
    motivos:motivos.filter(function(motivo, indice, todos){ return todos.indexOf(motivo) === indice; }),
    origen:origen,
    ratio:ratio
  };
}

function auditarIntegridadPreciosCatalogo() {
  var seguros = [];
  var manuales = [];
  var sinPrecio = [];
  Object.values(prodData || {}).forEach(function(p) {
    if (!p || !p.fbKey) return;
    var costoRaw = _costoRaizProductoSinAuditar(p);
    var ventaRaw = _primerNumeroPositivoProducto([p.ventaARS, p.precioArsPublicadoVenta, p.venta, p.precio_venta, p.precioVenta]);
    var variacionPendiente = variacionPrecioPendienteProducto(p);
    if (variacionPendiente) {
      manuales.push({
        producto:p,
        costo:costoRaw,
        venta:ventaRaw,
        motivo:'Variación excepcional pendiente de aprobación',
        motivos:['Variación excepcional pendiente de aprobación'],
        origen:variacionPendiente.origen || _origenAuditoriaPrecioProducto(p),
        variacionPendiente:variacionPendiente
      });
      return;
    }
    var ultimaAuditoria = p.auditoriaPrecioUltima && typeof p.auditoriaPrecioUltima === 'object' ? p.auditoriaPrecioUltima : null;
    var ajusteYaAplicado = !!(ultimaAuditoria &&
      String(p.moneda || '').toUpperCase() === 'ARS' &&
      String(p.monedaVenta || p.moneda || '').toUpperCase() === 'ARS' &&
      _relacionCercanaProducto(costoRaw, Number(ultimaAuditoria.costoDespues || 0), 0.001) &&
      _relacionCercanaProducto(ventaRaw, Number(ultimaAuditoria.ventaDespues || 0), 0.001));
    var correccionProveedor = ajusteYaAplicado ? null : detectarProductoArsDuplicadoPorDolar(p);
    var correccionLegacy = (ajusteYaAplicado || correccionProveedor) ? null : detectarPrecioLegacyMonedaProducto(p);
    var correccion = correccionProveedor || correccionLegacy;
    if (correccion && _correccionPrecioTienePrueba(p, correccion)) {
      var soloMetadatos =
        Math.abs(Number(correccion.costoCorregido || 0) - Number(correccion.costoGuardado || 0)) < 0.01 &&
        Math.abs(Number(correccion.ventaCorregida || 0) - Number(correccion.ventaGuardada || 0)) < 0.01;
      seguros.push({ producto:p, correccion:correccion, origen:_origenAuditoriaPrecioProducto(p), soloMetadatos:soloMetadatos });
      return;
    }
    if (!(costoRaw > 0) || !(ventaRaw > 0)) {
      sinPrecio.push({
        producto:p,
        costo:costoRaw,
        venta:ventaRaw,
        motivo:!(costoRaw > 0) && !(ventaRaw > 0) ? 'Faltan costo y precio de venta' : (!(costoRaw > 0) ? 'Falta costo' : 'Falta precio de venta'),
        origen:_origenAuditoriaPrecioProducto(p)
      });
      return;
    }
    var diagnostico = _motivoManualAuditoriaPrecio(p, costoRaw, ventaRaw, correccion);
    if (diagnostico.motivos.length) {
      manuales.push({
        producto:p,
        costo:costoRaw,
        venta:ventaRaw,
        motivo:diagnostico.motivos.join(' · '),
        motivos:diagnostico.motivos,
        origen:diagnostico.origen,
        ratio:diagnostico.ratio,
        correccionSugerida:correccion || null
      });
    }
  });
  return {
    total:Object.values(prodData || {}).filter(function(p){ return p && p.fbKey; }).length,
    seguros:seguros,
    manuales:manuales,
    sinPrecio:sinPrecio
  };
}

function cerrarAuditoriaIntegridadPrecios() {
  var modal = document.getElementById('modal-auditoria-precios');
  if (modal) modal.remove();
}

var _auditoriaPreciosEstadoRetorno = null;

function capturarEstadoAuditoriaIntegridadPrecios() {
  var modal = document.getElementById('modal-auditoria-precios');
  if (!modal) return { busqueda:'', scrollTop:0, detalles:[], listas:[] };
  var buscador = modal.querySelector('input[placeholder^="Buscar por código"]');
  var cuerpo = modal.querySelector('.modal-body');
  var detalles = Array.from(modal.querySelectorAll('details'));
  return {
    busqueda: buscador ? buscador.value : '',
    scrollTop: cuerpo ? cuerpo.scrollTop : 0,
    detalles: detalles.map(function(detalle){ return !!detalle.open; }),
    listas: detalles.map(function(detalle){
      var lista = detalle.querySelector('div[style*="overflow:auto"]');
      return lista ? lista.scrollTop : 0;
    })
  };
}

function restaurarEstadoAuditoriaIntegridadPrecios(estado) {
  var modal = document.getElementById('modal-auditoria-precios');
  if (!modal || !estado) return;
  var buscador = modal.querySelector('input[placeholder^="Buscar por código"]');
  if (buscador) {
    buscador.value = estado.busqueda || '';
    filtrarAuditoriaIntegridadPrecios(buscador.value);
  }
  var detalles = Array.from(modal.querySelectorAll('details'));
  detalles.forEach(function(detalle, indice){
    if (Array.isArray(estado.detalles) && typeof estado.detalles[indice] === 'boolean') detalle.open = estado.detalles[indice];
    var lista = detalle.querySelector('div[style*="overflow:auto"]');
    if (lista && Array.isArray(estado.listas)) lista.scrollTop = Number(estado.listas[indice] || 0);
  });
  var cuerpo = modal.querySelector('.modal-body');
  if (cuerpo) cuerpo.scrollTop = Number(estado.scrollTop || 0);
}

function abrirProductoDesdeAuditoriaIntegridadPrecios(fbKey) {
  var clave = String(fbKey || '');
  var producto = prodData ? Object.values(prodData).find(function(p){
    return p && String(p.fbKey || '') === clave;
  }) : null;
  if (!clave || !producto) {
    notify('No se encontró el producto seleccionado');
    return;
  }
  _auditoriaPreciosEstadoRetorno = capturarEstadoAuditoriaIntegridadPrecios();
  cerrarAuditoriaIntegridadPrecios();
  svNavegarDirecto('productos', function(){
    verProducto(producto.fbKey, 'auditoria-integral-precios');
  }, document.querySelector('[onclick*="productos"]'));
}

function timestampEstadoPrecioProveedor(valor) {
  var numerico = Number(valor);
  if (isFinite(numerico) && numerico > 0) return numerico;
  var fecha = Date.parse(String(valor || ''));
  return isFinite(fecha) && fecha > 0 ? fecha : 0;
}

function variacionPrecioEsArtefactoSeparadorMiles(precioActual, precioCandidato) {
  if (!(precioActual > 0) || !(precioCandidato > 0)) return false;
  var relacion = precioActual / precioCandidato;
  return relacion >= 990 && relacion <= 1010;
}

function variacionPrecioPendienteEsObsoleta(proveedor, pendiente) {
  proveedor = proveedor || {};
  pendiente = pendiente || {};
  var candidato = parsePrecioProveedorARS(pendiente.precioCandidatoArs || pendiente.precioCandidato || 0);
  if (!(candidato > 0)) return true;
  var actual = parsePrecioProveedorARS(proveedor.precioArsPublicado || proveedor.precio || 0);
  if (actual > 0) {
    var tolerancia = Math.max(0.02, actual * 0.0001);
    if (Math.abs(actual - candidato) <= tolerancia) return true;
    // Versiones anteriores llegaron a interpretar "$ 33,023.93" como $ 33,02.
    if (variacionPrecioEsArtefactoSeparadorMiles(actual, candidato)) return true;
  }
  var detectadaEn = timestampEstadoPrecioProveedor(pendiente.detectadaEn);
  var actualizadaEn = Math.max(
    timestampEstadoPrecioProveedor(proveedor.actualizadoEn || proveedor.actualizado),
    timestampEstadoPrecioProveedor(proveedor.disponibilidadActualizadaEn)
  );
  return detectadaEn > 0 && actualizadaEn >= detectadaEn;
}

function variacionPrecioPendienteProducto(producto) {
  var proveedores = proveedoresVinculadosProducto(producto || {});
  for (var idx = 0; idx < proveedores.length; idx++) {
    var pv = proveedores[idx] || {};
    var pendiente = pv.variacionPendienteAprobacion;
    if (!pendiente || typeof pendiente !== 'object') continue;
    if (variacionPrecioPendienteEsObsoleta(pv, pendiente)) continue;
    var candidato = parsePrecioProveedorARS(pendiente.precioCandidatoArs || pendiente.precioCandidato || 0);
    var anterior = parsePrecioProveedorARS(pendiente.precioAnteriorArs || pendiente.precioAnterior || pv.precio || 0);
    if (!(candidato > 0)) continue;
    return {
      proveedorIdx:idx,
      proveedor:pv.nombre || pv.proveedor || pendiente.proveedor || 'Proveedor',
      precioAnteriorArs:anterior,
      precioCandidatoArs:candidato,
      variacionPct:anterior > 0 ? ((candidato / anterior - 1) * 100) : 0,
      detectadaEn:Number(pendiente.detectadaEn || 0) || 0,
      origen:pendiente.origen || pv.actualizadoOrigen || 'cotizador-online'
    };
  }
  return null;
}

var _limpiezaVariacionesPrecioObsoletasEnCurso = false;
function limpiarVariacionesPrecioObsoletas() {
  if (_limpiezaVariacionesPrecioObsoletasEnCurso) return;
  if (!window.fbDB || !['admin','administrativo'].includes(String(currentRole || '').toLowerCase())) return;
  if (!Object.keys(prodData || {}).length) return;
  var entradas = [];
  var productosAfectados = [];
  Object.values(prodData || {}).forEach(function(producto) {
    if (!producto || !producto.fbKey || !Array.isArray(producto.proveedores)) return;
    var cambio = false;
    var cambiosProducto = {};
    var proveedores = producto.proveedores.map(function(proveedor, proveedorIdx) {
      var copia = Object.assign({}, proveedor || {});
      if (copia.variacionPendienteAprobacion && variacionPrecioPendienteEsObsoleta(copia, copia.variacionPendienteAprobacion)) {
        copia.variacionPendienteAprobacion = null;
        cambiosProducto['proveedores/' + proveedorIdx + '/variacionPendienteAprobacion'] = null;
        cambio = true;
      }
      return copia;
    });
    if (!cambio) return;
    entradas.push({ fbKey:String(producto.fbKey), changes:cambiosProducto });
    productosAfectados.push({ producto:producto, proveedores:proveedores });
  });
  if (!entradas.length) return;
  _limpiezaVariacionesPrecioObsoletasEnCurso = true;
  productosPersistirLote(entradas, function() {
    var updates = {};
    entradas.forEach(function(entrada) {
      Object.keys(entrada.changes).forEach(function(ruta) {
        updates[entrada.fbKey + '/' + ruta] = entrada.changes[ruta];
      });
    });
    return window.fbUpdate(window.fbRef(window.fbDB, FB_PATHS.productos), updates);
  }).then(function() {
    productosAfectados.forEach(function(item) { item.producto.proveedores = item.proveedores; });
    console.info('[Precios] Se limpiaron ' + entradas.length + ' producto(s) con propuestas obsoletas');
  }).catch(function(error) {
    console.warn('[Precios] No se pudieron limpiar propuestas obsoletas', error);
  }).finally(function() {
    _limpiezaVariacionesPrecioObsoletasEnCurso = false;
  });
}

function datosVariacionBloqueadaResultado(resultado) {
  var actual = resultado;
  var visitados = [];
  for (var nivel = 0; nivel < 5 && actual && typeof actual === 'object'; nivel++) {
    visitados.push(actual);
    actual = actual.raw;
  }
  var codigo = '';
  var anterior = 0;
  var candidato = 0;
  var mensaje = '';
  visitados.forEach(function(item) {
    if (!codigo && item.codigo) codigo = String(item.codigo);
    if (!anterior) anterior = parsePrecioProveedorARS(item.precioAnteriorArs || item.precioAnterior);
    if (!candidato) candidato = parsePrecioProveedorARS(item.precioCandidatoArs || item.precioCandidato);
    if (!mensaje) mensaje = String(item.mensaje || item.error || '');
  });
  if (!candidato && mensaje) {
    var partes = mensaje.match(/anterior ARS\s+([\d.,]+),\s*recibido ARS\s+([\d.,]+)/i);
    if (partes) {
      anterior = parsePrecioProveedorARS(partes[1]);
      candidato = parsePrecioProveedorARS(partes[2]);
      codigo = 'PRICE_VARIATION_REQUIRES_APPROVAL';
    }
  }
  return {
    requiereAprobacion: candidato > 0 && (codigo === 'PRICE_VARIATION_REQUIRES_APPROVAL' || anterior > 0),
    codigo: codigo,
    precioAnteriorArs: anterior,
    precioCandidatoArs: candidato,
    mensaje: mensaje
  };
}

function mostrarVariacionPrecioPendienteEnEditor() {
  var box = document.getElementById('pf-proveedores-cotizacion-resultado');
  if (!box) return false;
  box.innerHTML = '';
  box.style.display = 'none';
  var filas = [];
  (prodProveedoresActuales || []).forEach(function(pv, idx) {
    var pendiente = variacionPrecioPendienteProducto({ proveedores:[pv] });
    if (!pendiente) return;
    var anterior = pendiente.precioAnteriorArs;
    var candidato = pendiente.precioCandidatoArs;
    var variacion = pendiente.variacionPct;
    var botonId = 'aprobar-variacion-pendiente-' + idx;
    filas.push('<div style="padding:11px;border:1px solid rgba(245,158,11,.45);border-radius:9px;background:rgba(245,158,11,.08);margin-top:7px">' +
      '<div style="font-size:12px;font-weight:800;color:var(--amber);margin-bottom:7px"><i class="ti ti-shield-exclamation"></i> Precio bloqueado pendiente de aprobación · ' + escapeHTML(pv.nombre || pv.proveedor || 'Proveedor') + '</div>' +
      '<div style="display:flex;flex-wrap:wrap;gap:8px 18px;font-size:12px;margin-bottom:9px"><span>Anterior: <strong>$' + anterior.toLocaleString('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2}) + '</strong></span><span>Nuevo: <strong style="color:var(--green)">$' + candidato.toLocaleString('es-AR',{minimumFractionDigits:2,maximumFractionDigits:2}) + '</strong></span><span>Variación: <strong style="color:var(--amber)">' + (variacion >= 0 ? '+' : '') + variacion.toFixed(1) + '%</strong></span></div>' +
      (String(currentRole || '').toLowerCase() === 'admin'
        ? '<button id="' + botonId + '" class="btn btn-sm" type="button" onclick="aprobarVariacionPrecioProveedor(' + idx + ',' + candidato + ',' + anterior + ',\'' + botonId + '\')"><i class="ti ti-check"></i> Aprobar nuevo precio</button>'
        : '<div style="font-size:11px;color:var(--text3)">La aprobación excepcional debe realizarla un administrador.</div>') +
      '</div>');
  });
  if (!filas.length) return false;
  box.style.display = 'block';
  box.innerHTML = '<strong>Variaciones pendientes</strong>' + filas.join('') + '<div style="font-size:11px;color:var(--amber);margin-top:8px"><i class="ti ti-alert-circle"></i> Aprobar prepara el cambio; Guardar producto lo confirma definitivamente.</div>';
  return true;
}

function revisarYAprobarVariacionPrecio(fbKey, origen) {
  if (String(currentRole || '').toLowerCase() !== 'admin') {
    notify('Solo el administrador puede aprobar una variación excepcional de precio');
    return;
  }
  var producto = Object.values(prodData || {}).find(function(p){ return p && String(p.fbKey || '') === String(fbKey || ''); });
  if (!producto || !variacionPrecioPendienteProducto(producto)) {
    notify('Esta propuesta ya no está pendiente. Volvé a cotizar el producto si necesitás revisarla.');
    return;
  }
  if (origen === 'auditoria') {
    _auditoriaPreciosEstadoRetorno = capturarEstadoAuditoriaIntegridadPrecios();
    cerrarAuditoriaIntegridadPrecios();
  } else if (origen === 'revision') {
    _prodRevisionRetorno = capturarEstadoRevisionPrecios();
    _prodDetalleOrigenAntesForm = 'revision-precios';
    var modal = document.getElementById('modal-revision-precios');
    if (modal) modal.remove();
  }
  svNavegarDirecto('productos', function(){
    abrirFormProducto(producto.fbKey);
  }, document.querySelector('[onclick*="productos"]'));
  setTimeout(function(){
    if (mostrarVariacionPrecioPendienteEnEditor()) {
      var box = document.getElementById('pf-proveedores-cotizacion-resultado');
      if (box) box.scrollIntoView({ behavior:'smooth', block:'center' });
    }
  }, 80);
}

function _filaAuditoriaPrecio(item, segura) {
  var p = item.producto || {};
  var c = item.correccion || {};
  var costoAntes = segura ? c.costoGuardado : item.costo;
  var ventaAntes = segura ? c.ventaGuardada : item.venta;
  var costoDespues = segura ? c.costoCorregido : 0;
  var ventaDespues = segura ? c.ventaCorregida : 0;
  var etiqueta = segura
    ? (item.soloMetadatos ? 'Moneda antigua; los importes ya están correctos' : (c.tipo === 'costo_usd_legacy' ? 'Costo USD heredado' : c.tipo === 'venta_usd_legacy' ? 'Venta USD heredada' : 'Conversión duplicada'))
    : item.motivo;
  var origen = item.origen || _origenAuditoriaPrecioProducto(p);
  var pendiente = item.variacionPendiente || null;
  var textoBusqueda = [p.codigo, p.nombre, p.descripcion, p.proveedor, origen, etiqueta].join(' ').toLowerCase();
  return '<div data-auditoria-precio="1" data-auditoria-texto="' + escapeHTML(textoBusqueda) + '" style="display:grid;grid-template-columns:minmax(150px,1.4fr) minmax(180px,1.35fr) minmax(160px,1fr);gap:10px;align-items:center;padding:10px 2px;border-bottom:.5px solid var(--border)">' +
    '<button type="button" onclick="abrirProductoDesdeAuditoriaIntegridadPrecios(\'' + escapeHTML(String(p.fbKey || '')) + '\')" style="appearance:none;border:0;background:none;padding:0;text-align:left;color:var(--text);cursor:pointer;min-width:0"><strong>' + escapeHTML(p.codigo || 'Sin código') + '</strong><br><span style="font-size:11px;color:var(--text3)">' + escapeHTML(p.nombre || p.descripcion || '') + '</span></button>' +
    '<div style="font-size:11px;color:var(--text3)">' + escapeHTML(etiqueta || 'Revisión') + '<br><span>Costo $' + Number(costoAntes || 0).toLocaleString('es-AR',{maximumFractionDigits:2}) + ' · Venta $' + Number(ventaAntes || 0).toLocaleString('es-AR',{maximumFractionDigits:2}) + '</span><br><span style="font-size:10px">Origen: ' + escapeHTML(origen || 'sin origen') + '</span></div>' +
    '<div style="font-size:11px;' + (segura ? 'color:var(--green)' : 'color:var(--amber)') + '">' + (segura ? (item.soloMetadatos ? '<strong>Se normaliza a ARS</strong><br>sin cambiar los importes' : 'Quedará: costo $' + Number(costoDespues || 0).toLocaleString('es-AR',{maximumFractionDigits:2}) + '<br>venta $' + Number(ventaDespues || 0).toLocaleString('es-AR',{maximumFractionDigits:2})) : (pendiente ? '<strong>Anterior $' + Number(pendiente.precioAnteriorArs || 0).toLocaleString('es-AR',{maximumFractionDigits:2}) + ' → nuevo $' + Number(pendiente.precioCandidatoArs || 0).toLocaleString('es-AR',{maximumFractionDigits:2}) + '</strong><br><button class="btn btn-sm" style="margin-top:6px" onclick="revisarYAprobarVariacionPrecio(\'' + escapeHTML(String(p.fbKey || '')) + '\',\'auditoria\')"><i class="ti ti-check"></i> Revisar y aprobar</button>' : '<strong>No se modifica solo</strong><br>Tocá el producto para decidir')) + '</div>' +
  '</div>';
}

function _filaSinPrecioAuditoria(item) {
  return _filaAuditoriaPrecio(item, false);
}

function abrirAuditoriaIntegridadPrecios() {
  if (String(currentRole || '').toLowerCase() !== 'admin') { notify('Solo el administrador puede auditar el catálogo'); return; }
  cerrarAuditoriaIntegridadPrecios();
  var auditoria = auditarIntegridadPreciosCatalogo();
  var overlay = document.createElement('div');
  overlay.id = 'modal-auditoria-precios';
  overlay.className = 'modal-overlay';
  overlay.style.display = 'flex';
  overlay.innerHTML =
    '<div class="modal" style="width:min(980px,96vw);max-width:980px;max-height:92vh;display:flex;flex-direction:column">' +
      '<div class="modal-head"><div><strong><i class="ti ti-shield-check" style="color:var(--blue);margin-right:7px"></i>Auditoría integral de precios</strong><div style="font-size:11px;color:var(--text3);margin-top:4px">Analiza todo el catálogo sin modificar ventas históricas.</div></div><button class="icon-btn" onclick="cerrarAuditoriaIntegridadPrecios()" aria-label="Cerrar"><i class="ti ti-x"></i></button></div>' +
      '<div class="modal-body" style="overflow:auto">' +
        '<div class="metrics" style="grid-template-columns:repeat(4,minmax(120px,1fr));margin-bottom:14px">' +
          '<div class="metric"><div class="m-label">Catálogo</div><div class="m-value">' + auditoria.total + '</div><div class="m-sub">productos analizados</div></div>' +
          '<div class="metric"><div class="m-label">Ajuste seguro</div><div class="m-value" style="color:var(--green)">' + auditoria.seguros.length + '</div><div class="m-sub">importe o moneda comprobados</div></div>' +
          '<div class="metric"><div class="m-label">Revisión manual</div><div class="m-value" style="color:var(--amber)">' + auditoria.manuales.length + '</div><div class="m-sub">no se tocarán solos</div></div>' +
          '<div class="metric"><div class="m-label">Sin precio completo</div><div class="m-value">' + auditoria.sinPrecio.length + '</div><div class="m-sub">para completar</div></div>' +
        '</div>' +
        '<div style="padding:10px 12px;border-radius:10px;background:var(--green-bg);color:var(--green);font-size:12px;margin-bottom:12px"><i class="ti ti-lock-check"></i> Cada ajuste exige una prueba adicional, guarda una copia completa y muestra claramente si cambia un importe o si sólo normaliza la moneda a ARS. No modifica comprobantes, presupuestos ni ventas emitidas.</div>' +
        '<div style="display:flex;gap:9px;align-items:center;margin-bottom:10px"><input class="search-input" style="flex:1" placeholder="Buscar por código, producto, proveedor u origen…" oninput="filtrarAuditoriaIntegridadPrecios(this.value)"><span id="auditoria-precios-contador" style="font-size:11px;color:var(--text3);white-space:nowrap">' + (auditoria.seguros.length + auditoria.manuales.length + auditoria.sinPrecio.length) + ' casos visibles</span></div>' +
        '<details open><summary style="cursor:pointer;font-weight:800;padding:8px 0">Ajustes seguros (' + auditoria.seguros.length + ')</summary><div style="max-height:310px;overflow:auto">' + (auditoria.seguros.map(function(x){ return _filaAuditoriaPrecio(x, true); }).join('') || '<div style="padding:14px;color:var(--text3)">No se detectaron ajustes automáticos pendientes.</div>') + '</div></details>' +
        '<details style="margin-top:10px"><summary style="cursor:pointer;font-weight:800;padding:8px 0">Revisión manual (' + auditoria.manuales.length + ')</summary><div style="max-height:260px;overflow:auto">' + (auditoria.manuales.map(function(x){ return _filaAuditoriaPrecio(x, false); }).join('') || '<div style="padding:14px;color:var(--text3)">Sin casos manuales extraordinarios.</div>') + '</div></details>' +
        '<details style="margin-top:10px"><summary style="cursor:pointer;font-weight:800;padding:8px 0">Precios incompletos (' + auditoria.sinPrecio.length + ')</summary><div style="max-height:260px;overflow:auto">' + (auditoria.sinPrecio.map(_filaSinPrecioAuditoria).join('') || '<div style="padding:14px;color:var(--text3)">Todos los productos tienen costo y precio de venta.</div>') + '</div></details>' +
      '</div>' +
      '<div style="display:flex;justify-content:flex-end;gap:8px;padding:14px 18px;border-top:.5px solid var(--border)"><button class="btn" onclick="cerrarAuditoriaIntegridadPrecios()">Cerrar</button><button class="btn btn-primary" id="btn-reparar-auditoria-precios" ' + (auditoria.seguros.length ? '' : 'disabled') + ' onclick="repararCasosSegurosIntegridadPrecios()"><i class="ti ti-tool"></i> Aplicar ' + auditoria.seguros.length + ' ajustes seguros</button></div>' +
    '</div>';
  overlay._auditoria = auditoria;
  document.body.appendChild(overlay);
  if (_auditoriaPreciosEstadoRetorno) {
    var estadoRetorno = _auditoriaPreciosEstadoRetorno;
    _auditoriaPreciosEstadoRetorno = null;
    requestAnimationFrame(function(){ restaurarEstadoAuditoriaIntegridadPrecios(estadoRetorno); });
  }
}

async function repararCasosSegurosIntegridadPrecios() {
  var modal = document.getElementById('modal-auditoria-precios');
  var auditoria = modal && modal._auditoria;
  if (!auditoria || !auditoria.seguros.length || !window.fbDB) return;
  if (!await svConfirm('Se aplicarán ' + auditoria.seguros.length + ' ajustes con respaldo previo. Algunos sólo normalizan la moneda sin cambiar importes. Los casos dudosos no se modificarán. ¿Continuar?')) return;
  var btn = document.getElementById('btn-reparar-auditoria-precios');
  if (btn) { btn.disabled = true; btn.innerHTML = '<i class="ti ti-loader-2" style="display:inline-block;animation:spin 1s linear infinite"></i> Reparando…'; }
  var cambios = {};
  var ahora = Date.now();
  auditoria.seguros.forEach(function(item) {
    var p = item.producto;
    var c = item.correccion;
    var base = FB_PATHS.productos + '/' + p.fbKey + '/';
    cambios[base + 'auditoriaPrecioBackup20260723'] = {
      ts:ahora,
      usuario:currentUser || 'Admin',
      compra:p.compra || null,
      compraARS:p.compraARS || null,
      precioGremio:p.precioGremio || null,
      costoRealArs:p.costoRealArs || null,
      venta:p.venta || null,
      ventaARS:p.ventaARS || null,
      precioArsPublicadoVenta:p.precioArsPublicadoVenta || null,
      compraUSD:p.compraUSD || null,
      ventaUSD:p.ventaUSD || null,
      moneda:p.moneda || null,
      monedaVenta:p.monedaVenta || null,
      proveedores:Array.isArray(p.proveedores) ? p.proveedores : null
    };
    cambios[base + 'compra'] = c.costoCorregido;
    cambios[base + 'compraARS'] = c.costoCorregido;
    cambios[base + 'precioGremio'] = c.costoCorregido;
    cambios[base + 'costoRealArs'] = c.costoCorregido;
    cambios[base + 'venta'] = c.ventaCorregida;
    cambios[base + 'ventaARS'] = c.ventaCorregida;
    cambios[base + 'precioArsPublicadoVenta'] = c.ventaCorregida;
    cambios[base + 'moneda'] = 'ARS';
    cambios[base + 'monedaVenta'] = 'ARS';
    cambios[base + 'monedaOperativa'] = 'ARS';
    cambios[base + 'tcGuardado'] = c.tipoCambio;
    cambios[base + 'compraUSD'] = Math.round((c.costoCorregido / c.tipoCambio) * 100) / 100;
    cambios[base + 'ventaUSD'] = Math.round((c.ventaCorregida / c.tipoCambio) * 100) / 100;
    cambios[base + 'auditoriaPrecioUltima'] = {
      ts:ahora,
      usuario:currentUser || 'Admin',
      motivo:c.origen || c.tipo || 'auditoria-integral',
      costoAntes:c.costoGuardado,
      costoDespues:c.costoCorregido,
      ventaAntes:c.ventaGuardada,
      ventaDespues:c.ventaCorregida,
      tipoCambio:c.tipoCambio
    };
    if (Array.isArray(p.proveedores) && p.proveedores.length && c.costoCorregido !== c.costoGuardado) {
      var temporal = Object.assign({}, p, { compra:c.costoCorregido, compraARS:c.costoCorregido, precioGremio:c.costoCorregido, costoRealArs:c.costoCorregido });
      cambios[base + 'proveedores'] = reconciliarCostoProductoConProveedorPrincipal(temporal, p.proveedores);
    }
  });
  try {
    await window.fbUpdate(window.fbRef(window.fbDB), cambios);
    if (typeof registrarActividad === 'function') registrarActividad('Auditoría integral de precios', auditoria.seguros.length + ' ajustes seguros aplicados');
    notify('✓ Se aplicaron ' + auditoria.seguros.length + ' ajustes con respaldo');
    cerrarAuditoriaIntegridadPrecios();
    if (typeof renderTablaProductos === 'function') renderTablaProductos();
  } catch (e) {
    console.error('[Productos] Error en auditoría integral', e);
    notify('No se pudo completar la reparación: ' + (e.message || 'error'));
    if (btn) { btn.disabled = false; btn.innerHTML = '<i class="ti ti-tool"></i> Reintentar reparación'; }
  }
}

async function normalizarTodosProductosARS() {
  if (String(currentRole || '').toLowerCase() !== 'admin') { notify('Solo el administrador puede ejecutar esta normalización'); return; }
  if (!window.fbDB || typeof window.fbUpdate !== 'function') { notify('Sin conexión con Firebase'); return; }
  var productos = Object.values(prodData || {}).filter(function(p){ return p && p.fbKey; });
  if (!productos.length) { notify('No hay productos para normalizar'); return; }
  var dolar = obtenerDolarReferenciaProducto();
  var marcadosUsd = 0;
  var sinVenta = 0;
  var cambios = {};
  productos.forEach(function(p) {
    var monedaAnterior = String(p.moneda || p.monedaVenta || 'ARS').toUpperCase();
    if (monedaAnterior === 'USD') marcadosUsd++;
    var compraARS = precioGremioARSDesdeProducto(p);
    var auditado = detectarVentaArsDuplicadaPorDolar(p);
    var ventaARS = parseFloat(p.ventaARS || p.precioArsPublicadoVenta || 0) || 0;
    if (auditado) ventaARS = auditado.precioCorregido;
    if (!ventaARS) {
      var ventaBase = parseFloat(p.venta || p.precio_venta || p.precioVenta || 0) || 0;
      var ventaUSD = parseFloat(p.ventaUSD || 0) || 0;
      if (monedaAnterior === 'USD' && dolar.valor > 0) {
        // Algunos registros legacy estaban etiquetados USD aunque el importe
        // ya era ARS. Si su relación con el costo ARS es razonable, se conserva
        // sin volver a multiplicarlo por el dólar.
        if (_precioVentaRazonableRespectoCosto(ventaUSD, compraARS)) ventaARS = ventaUSD;
        else if (_precioVentaRazonableRespectoCosto(ventaBase, compraARS)) ventaARS = ventaBase;
        else ventaARS = Math.round((ventaUSD || ventaBase) * dolar.valor * 100) / 100;
      } else ventaARS = ventaBase;
    }
    if (!ventaARS) sinVenta++;
    var base = FB_PATHS.productos + '/' + p.fbKey + '/';
    cambios[base + 'moneda'] = 'ARS';
    cambios[base + 'monedaVenta'] = 'ARS';
    if (ventaARS > 0) {
      cambios[base + 'venta'] = ventaARS;
      cambios[base + 'ventaARS'] = ventaARS;
      if (dolar.valor > 0) cambios[base + 'ventaUSD'] = Math.round((ventaARS / dolar.valor) * 100) / 100;
    }
    if (compraARS > 0) {
      cambios[base + 'compra'] = compraARS;
      cambios[base + 'compraARS'] = compraARS;
      cambios[base + 'precioGremio'] = compraARS;
      if (dolar.valor > 0) cambios[base + 'compraUSD'] = Math.round((compraARS / dolar.valor) * 100) / 100;
    }
    cambios[base + 'normalizadoArsEn'] = Date.now();
    cambios[base + 'normalizadoArsPor'] = currentUser || 'Admin';
  });
  var mensaje = 'Se normalizarán ' + productos.length + ' productos a pesos argentinos.\n\n' +
    marcadosUsd + ' estaban marcados como USD.\n' +
    (sinVenta ? sinVenta + ' no tienen precio de venta y conservarán ese campo vacío.\n' : '') +
    '\nSe usarán primero los valores ARS ya guardados; no se volverán a multiplicar por el dólar. ¿Continuar?';
  if (!await svConfirm(mensaje)) return;
  window.fbUpdate(window.fbRef(window.fbDB), cambios).then(function(){
    notify('✓ ' + productos.length + ' productos normalizados a ARS');
  }).catch(function(e){ notify('No se pudo completar la normalización: ' + e.message); });
}

var PRECIO_VIGENCIA_DIAS_DEFAULT = 5;

function diasVigenciaPrecios() {
  var dias = parseInt(window._diasVigenciaPrecios, 10);
  return isFinite(dias) && dias >= 1 ? Math.min(dias, 365) : PRECIO_VIGENCIA_DIAS_DEFAULT;
}

function precioVigenciaMs() {
  return diasVigenciaPrecios() * 24 * 60 * 60 * 1000;
}

function proveedoresVinculadosProducto(p) {
  p = p || {};
  if (Array.isArray(p.proveedores) && p.proveedores.length) {
    return p.proveedores.map(function(pv) { return Object.assign({}, pv || {}); });
  }
  var nombreLegacy = String(p.proveedor || p.nom_prov || '').trim();
  var urlLegacy = normalizarUrlProveedorProducto(p.codWeb || p.urlProveedor || p.url || '');
  if (!nombreLegacy && !urlLegacy) return [];
  var maestro = (proveedoresData || []).find(function(prov) {
    return String((prov && prov.nombre) || '').trim().toLowerCase() === nombreLegacy.toLowerCase();
  });
  return [{
    nombre: nombreLegacy || (maestro && maestro.nombre) || 'Proveedor',
    proveedorKey: (maestro && (maestro.fbKey || maestro.key || maestro.id)) || '',
    precio: parseFloat(p.precioArsPublicado || p.precioGremio || p.compraARS || p.compra || 0) || 0,
    precioArsPublicado: parseFloat(p.precioArsPublicado || p.precioGremio || p.compraARS || p.compra || 0) || 0,
    costoRealArs: parseFloat(p.costoRealArs || p.precioGremio || p.compraARS || p.compra || 0) || 0,
    sinIva: !!p.sinIva,
    url: urlLegacy,
    actualizado: p.fechaActualizacionPrecio || '',
    actualizadoEn: parseFloat(p.precioActualizadoEn || p.actualizadoEn || 0) || 0,
    actualizadoOrigen: 'legacy'
  }];
}

function productosProveedoresV3Invocar(metodo, argumentos, fallback) {
  var bridge = window.SisVentas && window.SisVentas.V3Bridge;
  if (!bridge || typeof bridge.invoke !== 'function') {
    return typeof fallback === 'function' ? fallback() : fallback;
  }
  return bridge.invoke('productosProveedores', metodo, argumentos || [], fallback);
}

function proveedorPersistirGuardar(proveedor) {
  return Promise.resolve().then(function() {
    return productosProveedoresV3Invocar('saveProvider', [proveedor], function() {
      if (!window.fbDB) throw new Error('Sin conexión Firebase');
      var datos = Object.assign({}, proveedor || {});
      var fbKey = String(datos.fbKey || '').trim();
      delete datos.fbKey;
      if (fbKey) {
        return window.fbUpdate(window.fbRef(window.fbDB, 'sisventas/proveedores/' + fbKey), datos)
          .then(function() { return Object.assign({}, datos, { fbKey:fbKey }); });
      }
      return window.fbPush(window.fbRef(window.fbDB, 'sisventas/proveedores'), datos).then(function(ref) {
        return Object.assign({}, datos, { fbKey:ref && ref.key || '' });
      });
    });
  });
}

