// El catálogo de Roles parte de los módulos conocidos, pero también incorpora
// cualquier ruta nueva agregada al menú. De esa forma un módulo no puede
// aparecer en la aplicación sin aparecer en Configuración → Roles. Las rutas
// detectadas automáticamente son conservadoras: ningún rol no admin accede
// hasta que el administrador marque la casilla y guarde la configuración.
function obtenerTodosModulosRoles() {
  var modulos = TODOS_MODULOS.map(function(mod) { return Object.assign({}, mod); });
  var conocidos = new Set(modulos.map(function(mod) { return mod.id; }));
  document.querySelectorAll('.nav-item[onclick*="showPage"]').forEach(function(el) {
    var match = String(el.getAttribute('onclick') || '').match(/showPage\('([^']+)'/);
    if (!match || conocidos.has(match[1])) return;
    conocidos.add(match[1]);
    modulos.push({
      id: match[1],
      label: String(el.textContent || match[1]).replace(/\s+/g, ' ').trim(),
      nuevo: true
    });
  });
  return modulos;
}
function esModuloNuevoSinRegistro(idModulo) {
  return !TODOS_MODULOS.some(function(mod) { return mod.id === idModulo; });
}
function permisoConfiguradoParaRol(idModulo, rol) {
  if (rol === 'admin') return true;
  var cfg = (PERMISOS_ROLES[rol] || PERMISOS_DEFAULT[rol] || {});
  if ((cfg.bloqueados || []).includes(idModulo)) return false;
  return !esModuloNuevoSinRegistro(idModulo) || (cfg.permitidos || []).includes(idModulo);
}
// DASHBOARD WIDGETS — configuración por rol
var DASH_WIDGETS_DEF = [
  { id: 'metricas_globales',  label: 'Métricas globales (ventas, deuda, IVA)',  defaults: { admin:true, administrativo:false, vendedor:false, tecnico_vendedor:false, tecnico:false } },
  { id: 'grafico_barras',     label: 'Gráfico ventas 7 días',                   defaults: { admin:true, administrativo:false, vendedor:false, tecnico_vendedor:false, tecnico:false } },
  { id: 'ots_pendientes',     label: 'Órdenes de trabajo pendientes',            defaults: { admin:true, administrativo:false, vendedor:false, tecnico_vendedor:false, tecnico:false } },
  { id: 'rentabilidad',       label: 'Rentabilidad del mes',                     defaults: { admin:true, administrativo:false, vendedor:false, tecnico_vendedor:false, tecnico:false } },
  { id: 'mi_actividad',       label: 'Mi actividad (mis ventas y pptos)',         defaults: { admin:false, administrativo:true, vendedor:true, tecnico_vendedor:true, tecnico:false } },
  { id: 'mis_ots',            label: 'Mis órdenes de trabajo asignadas',          defaults: { admin:false, administrativo:false, vendedor:false, tecnico_vendedor:true, tecnico:true } },
  { id: 'btn_ia',             label: '🤖 Botón Asistente IA',                    defaults: { admin:true, administrativo:true, vendedor:true, tecnico_vendedor:true, tecnico:true } },
  { id: 'btn_chat',           label: '💬 Botón Chat interno',                    defaults: { admin:true, administrativo:true, vendedor:true, tecnico_vendedor:true, tecnico:true } },
];

var DASH_WIDGETS_CONFIG = {}; // se carga desde Firebase

function renderCfgDashWidgets() {
  var tbody = document.getElementById('cfg-dash-widgets-tbody');
  if (!tbody) return;
  var roles = ['admin','administrativo','vendedor','tecnico_vendedor','tecnico'];
  tbody.innerHTML = DASH_WIDGETS_DEF.map(function(w) {
    var celdas = roles.map(function(rol) {
      var cfgWidget = DASH_WIDGETS_CONFIG[w.id];
      var val = cfgWidget && Object.prototype.hasOwnProperty.call(cfgWidget, rol)
        ? cfgWidget[rol]
        : w.defaults[rol];
      var adminNoAplica = rol === 'admin' && w.id === 'mi_actividad';
      // Admin ve todo salvo widgets personales que no aplican al rol.
      var disabled = rol === 'admin' ? 'disabled' : '';
      var checked  = (adminNoAplica ? false : (rol === 'admin' ? true : !!val)) ? 'checked' : '';
      return '<td style="text-align:center;padding:10px 16px">' +
        '<input type="checkbox" id="dw_'+w.id+'_'+rol+'" '+checked+' '+disabled+
        ' style="width:16px;height:16px;accent-color:var(--blue);cursor:'+(disabled?'not-allowed':'pointer')+'"></td>';
    }).join('');
    return '<tr style="border-bottom:0.5px solid var(--border)">' +
      '<td style="padding:10px 12px;color:var(--text2)">'+escapeHTML(w.label)+'</td>' +
      celdas + '</tr>';
  }).join('');
}

function guardarDashWidgets() {
  var config = {};
  DASH_WIDGETS_DEF.forEach(function(w) {
    config[w.id] = {
      admin:          w.id === 'mi_actividad' ? false : true,
      administrativo: !!(document.getElementById('dw_'+w.id+'_administrativo')||{}).checked,
      vendedor:       !!(document.getElementById('dw_'+w.id+'_vendedor')||{}).checked,
      tecnico_vendedor:!!(document.getElementById('dw_'+w.id+'_tecnico_vendedor')||{}).checked,
      tecnico:        !!(document.getElementById('dw_'+w.id+'_tecnico')||{}).checked
    };
  });
  DASH_WIDGETS_CONFIG = config;
  aplicarVisibilidadBotonesFlotantes();
  if (window.fbDB) {
    window.fbSet(window.fbRef(window.fbDB, 'sisventas/config/dashWidgets'), config)
      .then(function(){ notify('✓ Configuración de dashboard guardada'); });
  }
}

function aplicarVisibilidadBotonesFlotantes() {
  var esCompacto = window.innerWidth <= 1024;
  // Chat
  var cfg = DASH_WIDGETS_CONFIG['btn_chat'];
  var chatVisible = cfg ? !!cfg[currentRole] : (currentRole !== 'vendedor');
  var chatBtn = document.getElementById('chat-fab');
  if (chatBtn && chatBtn._inicializado) chatBtn.style.display = chatVisible ? 'flex' : 'none';
  // En escritorio la IA tiene botón propio; en móvil/tablet vive dentro del botón +.
  var cfgIA = DASH_WIDGETS_CONFIG['btn_ia'];
  var iaVisible = cfgIA ? !!cfgIA[currentRole] : true;
  var iaBtn = document.getElementById('ia-fab');
  if (iaBtn) iaBtn.style.display = (!esCompacto && iaVisible && iaBtn._inicializado) ? 'flex' : 'none';
  var fab = document.getElementById('fab-container');
  if (fab) {
    fab.style.display = esCompacto ? 'flex' : 'none';
    fab.classList.remove('hidden');
    if (!esCompacto && fabOpen) closeFab();
  }
}

// La composición cambia al redimensionar: escritorio = chat + IA; compacto = chat + botón +.
// Una sola rutina evita conservar el estado visual del ancho con el que se inició sesión.
(function() {
  var timerFlotantes = null;
  window.addEventListener('resize', function() {
    clearTimeout(timerFlotantes);
    timerFlotantes = setTimeout(function() {
      if (typeof aplicarVisibilidadBotonesFlotantes === 'function') aplicarVisibilidadBotonesFlotantes();
    }, 80);
  }, { passive:true });
})();

function cargarDashWidgets() {
  if (!window.fbDB) return;
  window.fbGet(window.fbRef(window.fbDB, 'sisventas/config/dashWidgets')).then(function(snap) {
    if (snap.val()) DASH_WIDGETS_CONFIG = snap.val();
    renderCfgDashWidgets();
    applyDashWidgets();
    var chatBtn = document.getElementById('chat-fab');
    var iaBtn   = document.getElementById('ia-fab');
    if (chatBtn) chatBtn._inicializado = true;
    if (iaBtn)   iaBtn._inicializado   = true;
    if (typeof aplicarVisibilidadBotonesFlotantes === 'function') aplicarVisibilidadBotonesFlotantes();
  }).catch(function(){
    renderCfgDashWidgets();
    // Sin config — mostrar ambos por defecto
    var chatBtn = document.getElementById('chat-fab');
    if (chatBtn) { chatBtn._inicializado = true; chatBtn.style.display = 'flex'; }
  });
}

function applyDashWidgets() {
  var rol = currentRole;
  DASH_WIDGETS_DEF.forEach(function(w) {
    var cfgWidget = DASH_WIDGETS_CONFIG[w.id];
    var visible = cfgWidget && Object.prototype.hasOwnProperty.call(cfgWidget, rol)
      ? !!cfgWidget[rol]
      : !!w.defaults[rol];
    // Mapear widget ID a elemento del DOM
    var elIds = {
      metricas_globales: ['dash-metricas-globales'],
      grafico_barras:    ['dash-row2-admin'],
      ots_pendientes:    ['dash-row2-admin'],
      rentabilidad:      ['dash-rentabilidad-card'],
      mi_actividad:      currentRole === 'admin' ? [] : ['dash-administrativo-card'],
      mis_ots:           ['dash-tecnico-card'],
      ultimas_ventas:    ['dash-ultimas-ventas-card'],
      btn_ia:            [],
      btn_chat:          []
    }[w.id] || [];
    elIds.forEach(function(id) {
      var el = document.getElementById(id);
      if (!el) return;
      // mis_ots nunca para admin
      if (w.id === 'mis_ots' && currentRole === 'admin') { el.style.display = 'none'; return; }
      // btn_chat y btn_ia se manejan en aplicarVisibilidadBotonesFlotantes()
      el.style.display = visible ? '' : 'none';
    });
    // metricas_globales y grafico_barras comparten el mismo contenedor row2
    // ya manejado por el id dash-row2-admin y dash-metricas-globales
  });
}

function cargarPermisosRoles() {
  if (!window.fbDB) return;
  window.fbGet(window.fbRef(window.fbDB, 'sisventas/config/permisos')).then(function(snap) {
    var data = snap.val();
    if (data) aplicarPermisosRolesGuardados(data);
    if (typeof applyRole === 'function') applyRole();
  });
}

function renderTablaRoles() {
  // Releer siempre el valor real desde Firebase antes de pintar, para evitar
  // mostrar el valor por defecto si la carga inicial (al hacer login) todavía
  // no había terminado cuando el admin entra a esta pestaña.
  if (window.fbDB) {
    window.fbGet(window.fbRef(window.fbDB, 'sisventas/config/permisos')).then(function(snap) {
      var data = snap.val();
      if (data) aplicarPermisosRolesGuardados(data);
      _renderTablaRolesUI();
    }).catch(function(){ _renderTablaRolesUI(); });
  } else {
    _renderTablaRolesUI();
  }
}

// Las dos decisiones comerciales sensibles quedan visibles desde el primer
// ingreso a Roles; no dependen de descubrir una fila plegada.
var ROLES_MODULOS_EXPANDIDOS = { detalle:true, presupuesto:true };

function _renderTablaRolesUI() {
  var cont = document.getElementById('cfg-roles-tabla');
  if (!cont) return;
  var roles = ['admin','administrativo','vendedor','tecnico_vendedor','tecnico'];
  var rolLabels = { admin:'Admin', administrativo:'Administrativo', vendedor:'Vendedor', tecnico_vendedor:'Técnico-vendedor', tecnico:'Técnico' };
  var accionesCatalogo = window.SISVENTAS_PERMISOS_ACCION || {};
  var accionLabels = {
    verDashboard:'Ver indicadores', ver:'Ver', crear:'Crear', editar:'Editar', eliminar:'Eliminar',
    registrar:'Registrar', anular:'Anular', pagar:'Pagar', fijo:'Configurar fijos',
    moverPresupuesto:'Mover a presupuesto', contadoSinFactura:'Contado sin factura',
    aprobarMovimiento:'Aprobar movimientos', eliminarMovimiento:'Eliminar movimientos',
    impersonar:'Ingresar como usuario', limpiar:'Limpiar', migrar:'Migrar',
    duplicados:'Resolver duplicados', normalizar:'Normalizar datos', seedDemo:'Crear datos demo'
  };
  var permisoLabels = {
    'ventas.verTodas':'Ver ventas de todos',
    'ventas.verMargen':'Ver margen y costo de ventas (solo Admin)',
    'presupuestos.verMargen':'Ver margen y costo de presupuestos (solo Admin)',
    'credenciales.ver':'Ver credenciales',
    'credenciales.editar':'Editar credenciales',
    'credenciales.eliminar':'Eliminar credenciales'
  };
  function accionesModulo(idModulo) {
    return Object.keys(accionesCatalogo).filter(function(permiso) {
      return accionesCatalogo[permiso] && accionesCatalogo[permiso].modulo === idModulo;
    });
  }
  function valorAccion(permiso, rol) {
    if (rol === 'admin') return true;
    if (permiso === 'ventas.verMargen' || permiso === 'presupuestos.verMargen') return false;
    var regla = accionesCatalogo[permiso] || {};
    var cfg = PERMISOS_ROLES[rol] || PERMISOS_DEFAULT[rol] || {};
    var partes = permiso.split('.');
    var grupo = cfg.acciones && cfg.acciones[partes[0]];
    var clave = partes.slice(1).join('_');
    if (grupo && Object.prototype.hasOwnProperty.call(grupo, clave)) return !!grupo[clave];
    if (regla.admin) return false;
    if (regla.roles) return regla.roles.indexOf(rol) >= 0;
    return permisoConfiguradoParaRol(regla.modulo, rol);
  }
  var html = '<div style="overflow-x:auto"><table style="width:100%;font-size:13px">';
  html += '<thead><tr><th style="text-align:left;padding:8px 12px;font-weight:600;min-width:220px">Módulo / acción</th>';
  roles.forEach(function(r){ html += '<th style="text-align:center;padding:8px 12px;font-weight:600">'+rolLabels[r]+'</th>'; });
  html += '</tr></thead><tbody>';
  obtenerTodosModulosRoles().forEach(function(mod) {
    var acciones = accionesModulo(mod.id);
    var expandido = !!ROLES_MODULOS_EXPANDIDOS[mod.id];
    html += '<tr style="border-top:1px solid var(--border2);background:var(--bg3)">';
    html += '<td style="padding:0;font-weight:650"><button type="button" onclick="toggleAccionesModuloRol(\''+mod.id+'\')" '+(!acciones.length?'disabled':'')+' style="width:100%;border:0;background:transparent;color:inherit;padding:10px 12px;text-align:left;display:flex;align-items:center;gap:8px;cursor:'+(acciones.length?'pointer':'default')+';font-family:inherit">'+
      '<i class="ti '+(acciones.length?(expandido?'ti-chevron-down':'ti-chevron-right'):'ti-minus')+'" data-role-chevron="'+mod.id+'" style="width:14px;color:'+(acciones.length?'var(--blue)':'var(--text3)')+'"></i>'+
      '<span><span style="display:block">'+mod.label+'</span><span style="display:block;font-size:10px;color:var(--text3);font-weight:400;margin-top:2px">'+(acciones.length?'Tocá para configurar acciones':'Sin acciones adicionales')+'</span></span></button></td>';
    roles.forEach(function(r) {
      var checked = permisoConfiguradoParaRol(mod.id, r);
      var disabled = (r === 'admin' || mod.id === 'dashboard') ? 'disabled title="Siempre visible"' : '';
      html += '<td style="text-align:center;padding:8px">';
      html += '<label style="display:inline-flex;align-items:center;gap:5px;font-size:11px;color:var(--text2)"><input type="checkbox" data-rol="'+r+'" data-mod="'+mod.id+'" onchange="actualizarAccionesModuloRol(this)" '+(checked?'checked':'')+' '+disabled+' style="width:16px;height:16px;cursor:pointer;accent-color:var(--blue)"> Ver</label>';
      html += '</td>';
    });
    html += '</tr>';
    acciones.forEach(function(permiso) {
      var nombre = permiso.split('.').slice(1).join('_');
      html += '<tr data-role-action-mod="'+mod.id+'" style="display:'+(expandido?'table-row':'none')+';border-bottom:0.5px solid var(--border);background:var(--bg2)"><td style="padding:7px 12px 7px 42px;color:var(--text2)"><i class="ti ti-corner-down-right" style="font-size:12px;color:var(--text3);margin-right:6px"></i>'+(permisoLabels[permiso] || accionLabels[nombre] || nombre.replace(/_/g,' '))+'</td>';
      roles.forEach(function(r) {
        var moduloVisible = permisoConfiguradoParaRol(mod.id, r);
        var admin = r === 'admin';
        var margenSoloAdmin = permiso === 'ventas.verMargen' || permiso === 'presupuestos.verMargen';
        var bloqueado = admin || !moduloVisible || margenSoloAdmin;
        html += '<td style="text-align:center;padding:7px"><input type="checkbox" data-rol="'+r+'" data-perm="'+permiso+'" data-parent-mod="'+mod.id+'" '+(valorAccion(permiso,r)?'checked':'')+' '+(bloqueado?'disabled':'')+' style="width:15px;height:15px;accent-color:var(--green);cursor:'+(bloqueado?'not-allowed':'pointer')+'"></td>';
      });
      html += '</tr>';
    });
  });
  html += '</tbody></table></div>';
  cont.innerHTML = html;
}

function toggleAccionesModuloRol(idModulo) {
  var filas = document.querySelectorAll('#cfg-roles-tabla tr[data-role-action-mod="'+idModulo+'"]');
  if (!filas.length) return;
  var expandir = !ROLES_MODULOS_EXPANDIDOS[idModulo];
  ROLES_MODULOS_EXPANDIDOS[idModulo] = expandir;
  filas.forEach(function(fila){ fila.style.display = expandir ? 'table-row' : 'none'; });
  var icono = document.querySelector('#cfg-roles-tabla [data-role-chevron="'+idModulo+'"]');
  if (icono) {
    icono.classList.toggle('ti-chevron-right', !expandir);
    icono.classList.toggle('ti-chevron-down', expandir);
  }
}

function actualizarAccionesModuloRol(chkModulo) {
  if (!chkModulo) return;
  document.querySelectorAll('#cfg-roles-tabla input[data-perm][data-rol="'+chkModulo.dataset.rol+'"][data-parent-mod="'+chkModulo.dataset.mod+'"]')
    .forEach(function(chk) {
      chk.disabled = !chkModulo.checked;
      chk.style.cursor = chk.disabled ? 'not-allowed' : 'pointer';
      chk.closest('td').style.opacity = chk.disabled ? '.45' : '1';
    });
}

function guardarPermisosRoles() {
  var checks = document.querySelectorAll('#cfg-roles-tabla input[type=checkbox]');
  var roles = ['admin','administrativo','vendedor','tecnico_vendedor','tecnico'];
  var nuevos = { _version: PERMISOS_VERSION_ACTUAL };
  roles.forEach(function(r){ nuevos[r] = { bloqueados:[], permitidos:[], acciones:{} }; });
  checks.forEach(function(chk) {
    var rol = chk.dataset.rol;
    if (!rol || rol === 'admin' || !nuevos[rol]) return;
    var mod = chk.dataset.mod;
    if (mod) {
      if (!chk.checked) nuevos[rol].bloqueados.push(mod);
      else if (esModuloNuevoSinRegistro(mod)) nuevos[rol].permitidos.push(mod);
      return;
    }
    var permiso = chk.dataset.perm;
    if (!permiso) return;
    var partes = permiso.split('.');
    var grupo = partes.shift();
    var accion = partes.join('_');
    if (!nuevos[rol].acciones[grupo]) nuevos[rol].acciones[grupo] = {};
    nuevos[rol].acciones[grupo][accion] = !!chk.checked;
  });
  Object.assign(PERMISOS_ROLES, nuevos);
  if (window.fbDB) {
    window.fbSet(window.fbRef(window.fbDB,'sisventas/config/permisos'), nuevos)
      .then(function(){ notify('✓ Permisos guardados — aplican al próximo login'); });
  }
}

async function restaurarPermisosDefault() {
  if (!await svConfirm('¿Restaurar los permisos de todos los roles a los valores por defecto del sistema?\nEsto descarta cualquier personalización guardada.')) return;
  PERMISOS_ROLES = JSON.parse(JSON.stringify(PERMISOS_DEFAULT));
  PERMISOS_ROLES._version = PERMISOS_VERSION_ACTUAL;
  renderTablaRoles();
  if (window.fbDB) {
    window.fbSet(window.fbRef(window.fbDB,'sisventas/config/permisos'), PERMISOS_ROLES)
      .then(function(){ notify('✓ Permisos restaurados a los valores por defecto'); });
  } else {
    notify('✓ Permisos restaurados (sin conexión, no se guardó)');
  }
}
const SIDEBAR_PIN_KEY = 'sisventas_sidebar_pinned';
function sidebarDesktopActivo() {
  return !!(window.matchMedia && window.matchMedia('(min-width:1101px)').matches);
}
function sidebarEstaAnclado() {
  try { return localStorage.getItem(SIDEBAR_PIN_KEY) === '1'; }
  catch (e) { return false; }
}
function aplicarEstadoSidebarDesktop() {
  const sb = document.querySelector('.sidebar');
  const btn = document.getElementById('sidebar-pin-btn');
  if (!sb) return;
  const escritorio = sidebarDesktopActivo();
  const anclado = escritorio && sidebarEstaAnclado();
  sb.classList.toggle('desktop-autohide', escritorio && !anclado);
  sb.classList.toggle('sidebar-pinned', anclado);
  if (btn) {
    btn.classList.toggle('is-pinned', anclado);
    btn.setAttribute('aria-pressed', anclado ? 'true' : 'false');
    btn.title = anclado ? 'Desanclar menú lateral' : 'Anclar menú lateral';
    const texto = btn.querySelector('span');
    if (texto) texto.textContent = anclado ? 'Desanclar menú' : 'Anclar menú';
  }
}
function toggleSidebarPin(event) {
  if (event) {
    event.preventDefault();
    event.stopPropagation();
  }
  if (!sidebarDesktopActivo()) return;
  const siguiente = sidebarEstaAnclado() ? '0' : '1';
  try { localStorage.setItem(SIDEBAR_PIN_KEY, siguiente); } catch (e) {}
  aplicarEstadoSidebarDesktop();
}
window.addEventListener('resize', aplicarEstadoSidebarDesktop);
document.addEventListener('DOMContentLoaded', aplicarEstadoSidebarDesktop);
aplicarEstadoSidebarDesktop();
function toggleSidebar() {
  const sb = document.querySelector('.sidebar');
  const ov = document.getElementById('mob-overlay');
  const open = sb.classList.toggle('open');
  ov.style.display = open ? 'block' : 'none';
  document.body.style.overflow = open ? 'hidden' : '';
}
function closeSidebarMobile() {
  const sb = document.querySelector('.sidebar');
  const ov = document.getElementById('mob-overlay');
  sb.classList.remove('open');
  ov.style.display = 'none';
  document.body.style.overflow = '';
}

// Cerrar sidebar al navegar en mobile
// closeSidebarMobile integrado en showPage directamente
function _rangoFechasPeriodo(periodo) {
  var hoy = new Date();
  var desde, hasta;
  if (periodo === 'mes_actual') {
    desde = new Date(hoy.getFullYear(), hoy.getMonth(), 1);
    hasta = new Date(hoy.getFullYear(), hoy.getMonth()+1, 0, 23,59,59);
  } else if (periodo === 'mes_anterior') {
    desde = new Date(hoy.getFullYear(), hoy.getMonth()-1, 1);
    hasta = new Date(hoy.getFullYear(), hoy.getMonth(), 0, 23,59,59);
  } else if (periodo === 'ult_3_meses') {
    desde = new Date(hoy.getFullYear(), hoy.getMonth()-2, 1);
    hasta = new Date(hoy.getFullYear(), hoy.getMonth()+1, 0, 23,59,59);
  } else { // anio_actual
    desde = new Date(hoy.getFullYear(), 0, 1);
    hasta = new Date(hoy.getFullYear(), 11, 31, 23,59,59);
  }
  return { desde: desde, hasta: hasta };
}

function _parsearFechaFlexible(f) {
  if (!f) return null;
  var partes;
  if (f.indexOf('-') !== -1) { // YYYY-MM-DD
    partes = f.split('-');
    return new Date(parseInt(partes[0]), parseInt(partes[1])-1, parseInt(partes[2]));
  } else if (f.indexOf('/') !== -1) { // DD/MM/YYYY
    partes = f.split('/');
    return new Date(parseInt(partes[2]), parseInt(partes[1])-1, parseInt(partes[0]));
  }
  return null;
}

function _rentVentaValida(v) {
  return ventaValidaParaMetricas(v);
}

function _rentGastoValido(g) {
  if (!g) return false;
  var estado = String(g.estado || '').toLowerCase();
  return ['rechazado','rechazada','anulado','anulada','cancelado','cancelada'].indexOf(estado) === -1;
}

function _rentEsComision(g) {
  var tipo = String(g && (g.tipoPagable || g.tipo || g.tipomov) || '').toLowerCase();
  var desc = String(g && g.descripcion || '').toLowerCase();
  return tipo === 'comision' || tipo === 'comisión' || desc.indexOf('comisi') >= 0;
}

function _rentComisionAprobada(g) {
  if (!_rentEsComision(g) || !_rentGastoValido(g)) return false;
  var estado = String(g.estado || '').toLowerCase();
  return ['aprobado','aprobada','pendiente_pago','pagado_parcial','pagada_parcial','pagado','pagada'].indexOf(estado) >= 0;
}

function _rentIngresoNetoVenta(v) {
  var total = parseFloat(v && (v.total != null ? v.total : v.totalVenta)) || 0;
  var subtotal = parseFloat(v && v.subtotal) || 0;
  var iva = v && v.conIva === false ? 0 : (parseFloat(v && v.iva) || 0);
  if (subtotal > 0) return subtotal;
  return Math.max(0, total - iva);
}

function _rentCostoVenta(v) {
  v = v || {};
  // Algunas ventas históricas conservaron un costoTotal incorrecto o ya
  // desactualizado. Cuando hay detalle, los costos de los ítems son la fuente
  // contable más precisa y también permiten auditar de dónde sale el total.
  var items = Array.isArray(v.items)
    ? v.items
    : (v.items && typeof v.items === 'object' ? Object.values(v.items) : []);
  if (items.length) return items.reduce(function(s, item) {
    if (typeof obtenerCostoItemVenta === 'function') return s + obtenerCostoItemVenta(item);
    return s + (parseFloat(item.costoTotalCompra || item.costoTotal || item.costo) || 0);
  }, 0);
  var guardado = parseFloat(v.costoTotal) || 0;
  return isFinite(guardado) && guardado > 0 ? guardado : 0;
}

// Fuente única para Rentabilidad: trabaja por devengado, sin IVA y sin anulados.
// Las comisiones se reconocen cuando fueron aprobadas, aunque todavía no se hayan pagado.
function calcularRentabilidadCanonica(rango, ventasFuente, gastosFuente) {
  var ventasPeriodo = (ventasFuente || ventasList || []).filter(function(v) {
    if (!_rentVentaValida(v)) return false;
    var f = _parsearFechaFlexible(v.fecha || '');
    return f && f >= rango.desde && f <= rango.hasta;
  });
  var gastosPeriodo = (gastosFuente || gastosData || []).filter(function(g) {
    if (!_rentGastoValido(g)) return false;
    if (_rentEsComision(g) && !_rentComisionAprobada(g)) return false;
    var f = _parsearFechaFlexible(g.fecha || '');
    return f && f >= rango.desde && f <= rango.hasta;
  });
  var ingresosNetos = ventasPeriodo.reduce(function(s,v){ return s + _rentIngresoNetoVenta(v); }, 0);
  var descuentos = ventasPeriodo.reduce(function(s,v){ return s + (parseFloat(v.descuento)||0); }, 0);
  var iva = ventasPeriodo.reduce(function(s,v){ return s + (v.conIva === false ? 0 : (parseFloat(v.iva)||0)); }, 0);
  var costosCorregidos = [];
  var costoProductos = ventasPeriodo.reduce(function(s,v){
    var itemsVenta = Array.isArray(v.items) ? v.items : (v.items && typeof v.items === 'object' ? Object.values(v.items) : []);
    itemsVenta.forEach(function(item){
      var auditado = _costoItemVentaAuditado(item);
      if (auditado.corregido) costosCorregidos.push({ venta:v.id || v.fbKey || '', producto:item.cod || item.codigo || item.desc || '', guardado:auditado.guardado, usado:auditado.costo, motivo:auditado.motivo });
    });
    return s + _rentCostoVenta(v);
  }, 0);
  var comisiones = gastosPeriodo.filter(_rentComisionAprobada).reduce(function(s,g){ return s + (parseFloat(g.monto)||0); }, 0);
  var otrosGastosLista = gastosPeriodo.filter(function(g){ return !_rentEsComision(g); });
  var otrosGastos = otrosGastosLista.reduce(function(s,g){ return s + (parseFloat(g.monto)||0); }, 0);
  var gananciaComercial = ingresosNetos - costoProductos - comisiones;
  var resultadoNeto = gananciaComercial - otrosGastos;
  return {
    ventas: ventasPeriodo,
    gastos: gastosPeriodo,
    costosCorregidos: costosCorregidos,
    otrosGastosLista: otrosGastosLista,
    ingresosBrutos: ingresosNetos + descuentos,
    ingresosNetos: ingresosNetos,
    descuentos: descuentos,
    iva: iva,
    costoProductos: costoProductos,
    comisiones: comisiones,
    otrosGastos: otrosGastos,
    egresos: costoProductos + comisiones + otrosGastos,
    gananciaComercial: gananciaComercial,
    resultadoNeto: resultadoNeto,
    margenComercial: ingresosNetos > 0 ? gananciaComercial / ingresosNetos * 100 : 0,
    margenNeto: ingresosNetos > 0 ? resultadoNeto / ingresosNetos * 100 : 0
  };
}

// Normaliza cualquier fecha almacenada (DD/MM/YYYY o YYYY-MM-DD) al formato
// visual único del sistema: DD-MM-YYYY. Esto no modifica el valor persistido.
function _mostrarFecha(f) {
  if (!f) return '—';
  // Quitar hora si viene pegada (ej: "25/06/2026 01:30" o "2026-06-25T01:30")
  var clean = String(f).trim().replace(/[T ].*$/, '').trim();
  if (clean.indexOf('/') !== -1) {
    var p = clean.split('/');
    if (p.length === 3) return p[0].padStart(2,'0') + '-' + p[1].padStart(2,'0') + '-' + p[2].slice(0,4);
    return clean;
  }
  if (clean.indexOf('-') !== -1) {
    var q = clean.split('-');
    if (q.length === 3) return q[2].padStart(2,'0') + '-' + q[1].padStart(2,'0') + '-' + q[0];
    return clean;
  }
  return clean;
}

function formatearMontoRentabilidad(monto) {
  var valor = Number(monto) || 0;
  return (valor < 0 ? '-$' : '$') + Math.round(Math.abs(valor)).toLocaleString('es-AR');
}

function calcRentabilidad() {
  var selEl = document.getElementById('rent-periodo');
  var periodo = selEl ? selEl.value : 'mes_actual';
  var rango = _rangoFechasPeriodo(periodo);

  var resumen = calcularRentabilidadCanonica(rango);
  var ventasPeriodo = resumen.ventas;
  var ingresos = resumen.ingresosNetos;
  var costoProductos = resumen.costoProductos;
  var utilidad = resumen.resultadoNeto;
  var margen = resumen.margenNeto;

  var auditEl = document.getElementById('rent-auditoria-calculos');
  if (auditEl) {
    auditEl.style.display = resumen.costosCorregidos.length ? 'flex' : 'none';
    auditEl.innerHTML = resumen.costosCorregidos.length
      ? '<i class="ti ti-shield-check"></i><span>Auditoría automática: se corrigieron ' + resumen.costosCorregidos.length + ' costo' + (resumen.costosCorregidos.length !== 1 ? 's' : '') + ' histórico' + (resumen.costosCorregidos.length !== 1 ? 's' : '') + ' que habían sido reconvertidos erróneamente de ARS a USD. No se modificaron ventas ni comprobantes.</span>'
      : '';
  }

  _set('rent-ingresos', '$' + Math.round(ingresos).toLocaleString('es-AR'));
  _set('rent-ingresos-sub', ventasPeriodo.length + ' venta' + (ventasPeriodo.length !== 1 ? 's' : '') + ' · sin IVA');
  _set('rent-egresos', '$' + Math.round(costoProductos + resumen.comisiones).toLocaleString('es-AR'));
  _set('rent-comercial', '$' + Math.round(resumen.gananciaComercial).toLocaleString('es-AR'));
  _set('rent-gastos-operativos', '$' + Math.round(resumen.otrosGastos).toLocaleString('es-AR'));
  var comercialEl = document.getElementById('rent-comercial');
  if (comercialEl) comercialEl.style.color = resumen.gananciaComercial >= 0 ? 'var(--green)' : 'var(--red)';
  var utilEl = document.getElementById('rent-utilidad');
  utilEl.textContent = formatearMontoRentabilidad(utilidad);
  utilEl.style.color = utilidad >= 0 ? 'var(--green)' : 'var(--red)';
  var margenEl = document.getElementById('rent-margen');
  var margenSubEl = document.getElementById('rent-margen-sub');
  margenEl.textContent = margen.toFixed(1) + '%';
  if (margen < 15) { margenEl.style.color='var(--red)'; margenSubEl.textContent='margen bajo'; }
  else if (margen <= 20) { margenEl.style.color='var(--amber)'; margenSubEl.textContent='margen regular'; }
  else { margenEl.style.color='var(--green)'; margenSubEl.textContent='ganancia perfecta'; }

  // Desglose de gastos por categoría para el estado de resultados
  var gastosPorCategoria = {};
  // Contadores específicos de personal
  var totalSueldos = 0, totalHsExtra = 0, totalAguinaldo = 0, totalOtrosPersonal = 0;

  resumen.otrosGastosLista.forEach(function(g) {
    var cat = (g.categoria || 'Otro');
    var desc = (g.descripcion || '').toLowerCase();
    var tipo = (g.tipo || g.tipomov || '').toLowerCase();

    // Detectar si es un gasto de personal y de qué tipo
    var esPersonal = cat.toLowerCase() === 'personal' ||
                     desc.includes('sueldo') || desc.includes('salario') ||
                     desc.includes('haber') || desc.includes('aguinaldo') ||
                     desc.includes('hs extra') || desc.includes('hora extra') ||
                     tipo === 'sueldo' || tipo === 'hextra' || tipo === 'aguinaldo';

    if (esPersonal) {
      var monto = parseFloat(g.monto) || 0;
      if (desc.includes('aguinaldo') || desc.includes('sac') || tipo === 'aguinaldo') {
        totalAguinaldo += monto;
      } else if (desc.includes('hs extra') || desc.includes('hora extra') ||
                 desc.includes('h. extra') || tipo === 'hextra') {
        totalHsExtra += monto;
      } else if (desc.includes('sueldo') || desc.includes('salario') ||
                 desc.includes('haber') || tipo === 'sueldo') {
        totalSueldos += monto;
      } else {
        totalOtrosPersonal += monto;
      }
    } else {
      gastosPorCategoria[cat] = (gastosPorCategoria[cat]||0) + (parseFloat(g.monto)||0);
    }
  });

  var filas = [];
  filas.push({ concepto: 'Ventas antes de descuentos (sin IVA)', monto: resumen.ingresosBrutos, esTotal:false, signo:1 });
  if (resumen.descuentos > 0) filas.push({ concepto: 'Descuentos aplicados', monto: -resumen.descuentos, esTotal:false, signo:-1 });
  filas.push({ concepto: 'Ingresos netos sin IVA', monto: ingresos, esTotal:false, signo:1, esGrupo:true });
  if (resumen.iva > 0) filas.push({ concepto: 'IVA facturado (no integra la ganancia)', monto: resumen.iva, esTotal:false, signo:0, esSubItem:true });
  filas.push({ concepto: 'Costo de productos y mano de obra vendidos', monto: -costoProductos, esTotal:false, signo:-1 });
  if (resumen.comisiones > 0) filas.push({ concepto: 'Comisiones aprobadas', monto: -resumen.comisiones, esTotal:false, signo:-1 });
  filas.push({ concepto: 'Ganancia comercial', monto: resumen.gananciaComercial, esTotal:true, signo:resumen.gananciaComercial>=0?1:-1 });

  // Personal con desglose
  var totalPersonal = totalSueldos + totalHsExtra + totalAguinaldo + totalOtrosPersonal;
  if (totalPersonal > 0) {
    filas.push({ concepto: 'Gastos — Personal', monto: -totalPersonal, esTotal:false, signo:-1, esGrupo:true });
    if (totalSueldos > 0)    filas.push({ concepto: '↳ Sueldos', monto: -totalSueldos, signo:-1, esSubItem:true });
    if (totalHsExtra > 0)    filas.push({ concepto: '↳ Horas extra', monto: -totalHsExtra, signo:-1, esSubItem:true });
    if (totalAguinaldo > 0)  filas.push({ concepto: '↳ Aguinaldo (SAC)', monto: -totalAguinaldo, signo:-1, esSubItem:true });
    if (totalOtrosPersonal > 0) filas.push({ concepto: '↳ Otros personal', monto: -totalOtrosPersonal, signo:-1, esSubItem:true });
  }

  Object.keys(gastosPorCategoria).forEach(function(cat) {
    filas.push({ concepto: 'Gastos — ' + cat, monto: -gastosPorCategoria[cat], esTotal:false, signo:-1 });
  });
  filas.push({ concepto: 'Resultado neto de la empresa', monto: utilidad, esTotal:true, signo: utilidad>=0?1:-1 });

  var tbody = document.getElementById('rent-tbody');
  if (tbody) {
    tbody.innerHTML = filas.map(function(f) {
      var color = f.signo > 0 ? 'var(--green)' : (f.signo < 0 ? 'var(--red)' : 'var(--amber)');
      var estilo = f.esTotal ? 'font-weight:700;border-top:1.5px solid var(--border2)'
                 : f.esGrupo ? 'font-weight:600'
                 : f.esSubItem ? 'color:var(--text3)' : '';
      var indent = f.esSubItem ? 'padding-left:20px;font-size:12px' : '';
      return '<tr style="' + estilo + '">' +
        '<td style="' + indent + '">' + escapeHTML(f.concepto) + '</td>' +
        '<td class="tr" style="color:' + color + ';font-weight:' + (f.esTotal?'700':f.esGrupo?'600':'500') + ';' + indent + '">' +
          formatearMontoRentabilidad(f.monto) + '</td>' +
      '</tr>';
    }).join('');
  }
}

var _ccFiltroActual = 'pendiente';

function setFiltroCC(filtro) {
  _ccFiltroActual = filtro;
  ['pendiente','todos','aldia'].forEach(function(f) {
    var btn = document.getElementById('cc-filtro-' + f);
    if (btn) btn.className = 'btn btn-sm' + (f === filtro ? ' btn-primary' : '');
  });
  buscarCC((document.getElementById('cc-buscador')||{}).value || '');
}

function buscarCC(q) {
  var rows = document.querySelectorAll('#cc-tbody .ccrow');
  var txt = (q||'').toLowerCase();
  var visibles = 0;
  rows.forEach(function(r) {
    var matchTxt     = !txt || r.textContent.toLowerCase().includes(txt);
    var saldo        = parseFloat(r.dataset.saldo || 0);
    var esPendiente  = saldo > 0;
    var matchFiltro  = _ccFiltroActual === 'todos' ? true
                     : _ccFiltroActual === 'pendiente' ? esPendiente : !esPendiente;
    var show = matchTxt && matchFiltro;
    r.style.display = show ? '' : 'none';
    if (show) visibles++;
  });
  var contador = document.getElementById('cc-contador');
  if (contador) contador.textContent = visibles + ' cliente' + (visibles !== 1 ? 's' : '');
}
function verCuentaClienteReal(clienteRef) {
  var mapaCC = window._ccMapActual || {};
  var d = mapaCC[clienteRef] || Object.values(mapaCC).find(function(item){ return item && item.nombre === clienteRef; });
  if (!d) { notify('Cliente sin datos de cuenta corriente'); return; }
  var nombre = d.nombre || String(clienteRef || '');
  window._ccNombreActual = nombre;
  window._ccClienteKeyActual = d.clienteFbKey || d.key || String(clienteRef || '');
  var card = document.querySelector('#page-cuentacorriente .card');
  var metrics = document.querySelector('#page-cuentacorriente .metrics');
  if (card) card.style.display = 'none';
  if (metrics) metrics.style.display = 'none';
  _block('cc-detail');

  var saldo = d.total - d.cobrado;
  var initials = nombre.split(' ').filter(Boolean).slice(0,2).map(function(w){return w[0];}).join('').toUpperCase() || '—';
  _set('cc-avatar', initials);
  _set('cc-nombre', nombre);
  document.getElementById('cc-estado-lbl').innerHTML = saldo > 0 ? '<span class="badge b-amber">Pendiente</span>' : '<span class="badge b-green">Al día</span>';
  _set('cc-saldo-lbl', 'Saldo: $' + Math.round(saldo).toLocaleString('es-AR'));
  _set('cc-total', '$' + Math.round(d.total).toLocaleString('es-AR'));
  _set('cc-cobrado', '$' + Math.round(d.cobrado).toLocaleString('es-AR'));
  var saldoEl = document.getElementById('cc-saldo');
  saldoEl.textContent = '$' + Math.round(saldo).toLocaleString('es-AR');
  saldoEl.style.color = saldo > 0 ? 'var(--amber)' : 'var(--text3)';
  var card2 = document.getElementById('cc-saldo-card');
  card2.style.background = saldo > 0 ? 'var(--amber-bg)' : 'var(--bg3)';
  function _ccVentaPertenece(v) {
    var keys = [v && v.clienteFbKey, v && v.clienteKey, v && v.clienteId, v && v.idCliente, v && v.idClienteOriginal].map(function(x){ return String(x||'').trim(); }).filter(Boolean);
    if (d.clienteFbKey && keys.indexOf(String(d.clienteFbKey)) >= 0) return true;
    if (d.legacyId && keys.indexOf(String(d.legacyId)) >= 0) return true;
    return !keys.length && v && _svTxtNombre(v.cliente) === _svTxtNombre(nombre);
  }
  function _ccPagoPertenece(p) {
    var keys = [p && p.clienteFbKey, p && p.clienteKey, p && p.clienteId, p && p.idCliente].map(function(x){ return String(x||'').trim(); }).filter(Boolean);
    if (d.clienteFbKey && keys.indexOf(String(d.clienteFbKey)) >= 0) return true;
    if (d.legacyId && keys.indexOf(String(d.legacyId)) >= 0) return true;
    return !keys.length && p && _svTxtNombre(p.cliente) === _svTxtNombre(nombre);
  }
  function _ccFechaOrden(fecha, ts) {
    var valor = String(fecha || '').trim();
    var partes = valor.split(/[\/-]/);
    if (partes.length === 3) {
      if (partes[0].length === 4) return new Date(partes[0] + '-' + String(partes[1]).padStart(2, '0') + '-' + String(partes[2]).padStart(2, '0') + 'T12:00:00').getTime() || 0;
      if (partes[2].length === 4) return new Date(partes[2] + '-' + String(partes[1]).padStart(2, '0') + '-' + String(partes[0]).padStart(2, '0') + 'T12:00:00').getTime() || 0;
    }
    return parseFloat(ts) || 0;
  }
  var movs = [];
  var ventasCuenta = (ventasList||[]).filter(_ccVentaPertenece);
  var pagosCuenta = (window._pagosListaActual||[]).filter(function(p) {
    if (p && (p.anulado || String(p.estado || '').toLowerCase() === 'anulado')) return false;
    return _ccPagoPertenece(p) && (!window._svPagoValido || window._svPagoValido(p));
  });
  ventasCuenta.forEach(function(v) {
    var ventaTs = _ccFechaOrden(v.fecha, v.ts);
    movs.push({
      fecha: v.fecha || '',
      concepto: 'Venta ' + (v.id||v.fbKey||''),
      tipo: 'Venta',
      debe: _svTotalVentaCanonico(v),
      haber: 0,
      ts: ventaTs,
      orden: 0
    });
    var vistos = {};
    var pagosVenta = _svPagosCanonicosVenta(v).filter(function(p) {
      if (typeof _svRegistroPerteneceVenta === 'function' && !_svRegistroPerteneceVenta(p, v)) return false;
      var monto = parseFloat(p.monto) || 0;
      if (monto <= 0) return false;
      var firma = [p.fecha||'', monto, String(p.medio||p.medioPago||'').toLowerCase(), p.venta||p.ventaId||p.ventaFbKey||''].join('|');
      var clave = p.fbKey || p.id || p.key || firma;
      if (vistos[clave] || (!p.fbKey && vistos[firma])) return false;
      vistos[clave] = true;
      vistos[firma] = true;
      return true;
    });
    var sumaPagos = pagosVenta.reduce(function(total, p) { return total + (parseFloat(p.monto) || 0); }, 0);
    var objetivoCobrado = Math.min(_svTotalVentaCanonico(v), pagosVenta.length ? sumaPagos : _svResumenPagoLegacyVenta(v));
    var grupos = {};
    pagosVenta.forEach(function(p) {
      var medio = p.medio || p.medioPago || 'Efectivo';
      var fecha = p.fecha || v.fecha || '';
      var claveGrupo = fecha + '|' + String(medio).toLowerCase();
      if (!grupos[claveGrupo]) grupos[claveGrupo] = { fecha:fecha, medio:medio, monto:0, ts:_ccFechaOrden(fecha, p.ts) };
      grupos[claveGrupo].monto += parseFloat(p.monto) || 0;
    });
    var restante = objetivoCobrado;
    Object.keys(grupos).map(function(key) { return grupos[key]; }).sort(function(a,b) { return a.ts - b.ts; }).forEach(function(grupo) {
      var aplicado = Math.min(restante, grupo.monto);
      if (aplicado <= 0) return;
      movs.push({
        fecha: grupo.fecha,
        concepto: 'Pago — ' + (v.id || v.fbKey || '') + ' (' + grupo.medio + ')',
        tipo: 'Pago',
        debe: 0,
        haber: aplicado,
        ts: grupo.ts,
        orden: 1
      });
      restante -= aplicado;
    });
    if (restante > 0.009) {
      var fechaDirecta = (Object.keys(grupos).map(function(key) { return grupos[key]; }).sort(function(a,b) { return b.ts - a.ts; })[0] || {}).fecha || v.fecha || '';
      movs.push({
        fecha: fechaDirecta,
        concepto: 'Pago registrado — ' + (v.id || v.fbKey || ''),
        tipo: 'Pago',
        debe: 0,
        haber: restante,
        ts: _ccFechaOrden(fechaDirecta, v.ts),
        orden: 1
      });
    }
  });
  var debeDetallado = movs.reduce(function(total, m) { return total + (Number(m.debe) || 0); }, 0);
  var haberDetallado = movs.reduce(function(total, m) { return total + (Number(m.haber) || 0); }, 0);
  var cargoConciliado = Math.max(0, (Number(d.total) || 0) - debeDetallado);
  var pagoConciliado = Math.max(0, (Number(d.cobrado) || 0) - haberDetallado);
  if (cargoConciliado > 0.009) {
    movs.push({
      fecha: '',
      concepto: 'Cargo conciliado en cuenta',
      tipo: 'Ajuste',
      debe: cargoConciliado,
      haber: 0,
      ts: 0,
      orden: -1
    });
  }
  if (pagoConciliado > 0.009) {
    movs.push({
      fecha: d.ultimoPago || '',
      concepto: 'Pago conciliado en cuenta',
      tipo: 'Pago',
      debe: 0,
      haber: pagoConciliado,
      ts: _ccFechaOrden(d.ultimoPago, 0),
      orden: 1
    });
  }
  movs.sort(function(a,b){ return a.ts - b.ts || (a.orden || 0) - (b.orden || 0); });

  var saldoCorrido = 0;
  movs.forEach(function(m) {
    saldoCorrido += m.debe - m.haber;
    m.saldo = saldoCorrido;
  });
  window._ccExtractoActual = {
    clienteKey: window._ccClienteKeyActual,
    nombre: nombre,
    total: Number(d.total) || 0,
    cobrado: Number(d.cobrado) || 0,
    saldo: Number(saldo) || 0,
    movimientos: movs.map(function(m) {
      return {
        fecha: m.fecha || '',
        concepto: m.concepto || '',
        tipo: m.tipo || '',
        debe: Number(m.debe) || 0,
        haber: Number(m.haber) || 0,
        saldo: Number(m.saldo) || 0,
        ts: Number(m.ts) || 0
      };
    })
  };
  aplicarFiltroExtractoCuentaCorriente();
}

function _ccTimestampFechaInput(valor, finDelDia) {
  var partes = String(valor || '').split('-').map(Number);
  if (partes.length !== 3 || !partes[0] || !partes[1] || !partes[2]) return null;
  return new Date(partes[0], partes[1] - 1, partes[2], finDelDia ? 23 : 0, finDelDia ? 59 : 0, finDelDia ? 59 : 0, finDelDia ? 999 : 0).getTime();
}

function _ccFechaInputLegible(valor) {
  var ts = _ccTimestampFechaInput(valor, false);
  return ts === null ? '' : new Date(ts).toLocaleDateString('es-AR');
}

function _ccVistaExtractoFiltrada(extracto) {
  extracto = extracto || {};
  var desdeValor = (document.getElementById('cc-extracto-desde') || {}).value || '';
  var hastaValor = (document.getElementById('cc-extracto-hasta') || {}).value || '';
  var desdeTs = _ccTimestampFechaInput(desdeValor, false);
  var hastaTs = _ccTimestampFechaInput(hastaValor, true);
  if (desdeTs !== null && hastaTs !== null && desdeTs > hastaTs) {
    return { valido:false, mensaje:'La fecha Desde no puede ser posterior a Hasta' };
  }
  var todos = Array.isArray(extracto.movimientos) ? extracto.movimientos : [];
  var saldoAnterior = 0;
  if (desdeTs !== null) {
    todos.forEach(function(m) {
      if ((Number(m.ts) || 0) < desdeTs) saldoAnterior = Number(m.saldo) || 0;
    });
  }
  var movimientos = todos.filter(function(m) {
    var ts = Number(m.ts) || 0;
    return (desdeTs === null || ts >= desdeTs) && (hastaTs === null || ts <= hastaTs);
  });
  var saldoFinal = movimientos.length
    ? Number(movimientos[movimientos.length - 1].saldo) || 0
    : (desdeTs !== null ? saldoAnterior : 0);
  return {
    valido: true,
    movimientos: movimientos,
    saldoAnterior: saldoAnterior,
    saldoFinal: saldoFinal,
    desdeValor: desdeValor,
    hastaValor: hastaValor,
    desdeLabel: _ccFechaInputLegible(desdeValor),
    hastaLabel: _ccFechaInputLegible(hastaValor),
    filtrado: desdeTs !== null || hastaTs !== null
  };
}

function aplicarFiltroExtractoCuentaCorriente() {
  var extracto = window._ccExtractoActual;
  if (!extracto) return;
  var vista = _ccVistaExtractoFiltrada(extracto);
  if (!vista.valido) {
    notify(vista.mensaje);
    return;
  }
  window._ccVistaExtractoActual = vista;
  var rows = vista.movimientos.map(function(m) {
    var ventaId = m.tipo === 'Venta' ? (m.concepto.replace('Venta ','')) : null;
    var trStyle = ventaId ? 'cursor:pointer;touch-action:pan-x pan-y' : '';
    var trClick = ventaId ? 'onclick="verVentaDesdeHistorial(\''+ventaId+'\',this)"' : '';
    return '<tr style="'+trStyle+'" '+trClick+' onmouseenter="if(this.onclick)this.style.background=\'var(--bg3)\'" onmouseleave="this.style.background=\'\'">' +
      '<td>' + escapeHTML(typeof _mostrarFecha === 'function' ? _mostrarFecha(m.fecha) : m.fecha) + '</td>' +
      '<td style="color:'+(ventaId?'var(--blue)':'')+'">'+escapeHTML(m.concepto)+(ventaId?' <i class="ti ti-external-link" style="font-size:10px;opacity:.6"></i>':'')+'</td>' +
      '<td style="text-align:right">' + (m.debe ? '$'+Math.round(m.debe).toLocaleString('es-AR') : '—') + '</td>' +
      '<td style="text-align:right;color:var(--green)">' + (m.haber ? '$'+Math.round(m.haber).toLocaleString('es-AR') : '—') + '</td>' +
      '<td style="text-align:right;font-weight:500">$' + Math.round(m.saldo).toLocaleString('es-AR') + '</td>' +
    '</tr>';
  }).join('');
  var saldoAnteriorRow = vista.filtrado && vista.desdeValor
    ? '<tr style="background:var(--bg3)"><td>' + escapeHTML(vista.desdeLabel) + '</td><td style="font-weight:500">Saldo anterior al período</td><td style="text-align:right">—</td><td style="text-align:right">—</td><td style="text-align:right;font-weight:600">$' + Math.round(vista.saldoAnterior).toLocaleString('es-AR') + '</td></tr>'
    : '';

  var tablaMovimientos = document.getElementById('cc-movimientos');
  if (!tablaMovimientos) return;
  tablaMovimientos.innerHTML =
    '<thead><tr><th>Fecha</th><th>Concepto</th><th style="text-align:right">Debe</th><th style="text-align:right">Haber</th><th style="text-align:right">Saldo</th></tr></thead>' +
    '<tbody>' + saldoAnteriorRow + (rows || '<tr><td colspan="5" style="text-align:center;color:var(--text3);padding:20px">Sin movimientos en el período seleccionado</td></tr>') + '</tbody>';
  var info = document.getElementById('cc-extracto-periodo-info');
  if (info) {
    info.style.display = vista.filtrado ? 'block' : 'none';
    info.textContent = vista.filtrado
      ? vista.movimientos.length + ' movimiento' + (vista.movimientos.length === 1 ? '' : 's') + ' en el período · Saldo al cierre: ' + _ccFormatoImporteExtracto(vista.saldoFinal)
      : '';
  }
  asegurarDesplazamientoTablas(tablaMovimientos);
  inicializarGrillasEn(tablaMovimientos);
}

function limpiarFiltroExtractoCuentaCorriente() {
  var desde = document.getElementById('cc-extracto-desde');
  var hasta = document.getElementById('cc-extracto-hasta');
  if (desde) desde.value = '';
  if (hasta) hasta.value = '';
  aplicarFiltroExtractoCuentaCorriente();
}

function _ccFormatoImporteExtracto(valor) {
  var numero = Number(valor) || 0;
  var usaCentavos = Math.abs(numero - Math.round(numero)) > 0.004;
  return '$ ' + numero.toLocaleString('es-AR', {
    minimumFractionDigits: usaCentavos ? 2 : 0,
    maximumFractionDigits: 2
  });
}

function _ccClienteParaExtracto(extracto) {
  var lista = clientesData || [];
  var key = String((extracto && extracto.clienteKey) || '').trim();
  var nombre = _svTxtNombre((extracto && extracto.nombre) || '');
  return lista.find(function(cliente) {
    return key && (String(cliente.fbKey || '') === key || String(cliente.id || '') === key);
  }) || lista.find(function(cliente) {
    var completo = ((cliente.nombre || '') + ' ' + (cliente.apellidos || cliente.apellido || '')).trim();
    return nombre && (_svTxtNombre(cliente.nombre || '') === nombre || _svTxtNombre(completo) === nombre);
  }) || {};
}

function _ccAbrirVistaPreviaExtracto(html, nombreCliente) {
  var anterior = document.getElementById('cc-extracto-vista-previa');
  if (anterior && anterior.parentNode) anterior.parentNode.removeChild(anterior);

  var modal = document.createElement('div');
  modal.id = 'cc-extracto-vista-previa';
  modal.style.cssText = 'position:fixed;inset:0;z-index:10050;background:rgba(3,7,18,.86);display:flex;align-items:center;justify-content:center;padding:18px';

  var panel = document.createElement('div');
  panel.style.cssText = 'width:min(1050px,100%);height:min(94vh,920px);background:var(--bg2);border:1px solid var(--border2);border-radius:14px;overflow:hidden;display:flex;flex-direction:column;box-shadow:0 24px 80px rgba(0,0,0,.45)';

  var encabezado = document.createElement('div');
  encabezado.style.cssText = 'display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 14px;border-bottom:1px solid var(--border);flex-wrap:wrap';

  var titulo = document.createElement('strong');
  titulo.textContent = 'Vista previa · Extracto de ' + String(nombreCliente || 'cliente');
  titulo.style.cssText = 'min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap';

  var acciones = document.createElement('div');
  acciones.style.cssText = 'display:flex;gap:8px;flex-wrap:wrap';

  var btnImprimir = document.createElement('button');
  btnImprimir.type = 'button';
  btnImprimir.className = 'btn btn-sm btn-primary';
  btnImprimir.innerHTML = '<i class="ti ti-printer"></i> Imprimir / guardar PDF';

  var btnMaximizar = document.createElement('button');
  btnMaximizar.type = 'button';
  btnMaximizar.className = 'btn btn-sm';
  btnMaximizar.title = 'Maximizar';
  btnMaximizar.innerHTML = '<i class="ti ti-maximize"></i>';

  var btnCerrar = document.createElement('button');
  btnCerrar.type = 'button';
  btnCerrar.className = 'btn btn-sm';
  btnCerrar.innerHTML = '<i class="ti ti-x"></i> Cerrar';

  var marco = document.createElement('iframe');
  marco.title = 'Vista previa del extracto de cuenta corriente';
  marco.style.cssText = 'width:100%;height:100%;border:0;background:#fff';
  marco.srcdoc = html;

  function cerrar() {
    if (modal.parentNode) modal.parentNode.removeChild(modal);
  }
  var maximizado = false;
  var desplazamiento = { x:0, y:0 };
  function actualizarPanel() {
    if (maximizado) {
      panel.style.width = 'calc(100vw - 20px)';
      panel.style.height = 'calc(100vh - 20px)';
      panel.style.borderRadius = '10px';
      panel.style.transform = 'none';
      btnMaximizar.title = 'Restaurar';
      btnMaximizar.innerHTML = '<i class="ti ti-minimize"></i>';
    } else {
      panel.style.width = 'min(1050px,100%)';
      panel.style.height = 'min(94vh,920px)';
      panel.style.borderRadius = '14px';
      panel.style.transform = 'translate(' + desplazamiento.x + 'px,' + desplazamiento.y + 'px)';
      btnMaximizar.title = 'Maximizar';
      btnMaximizar.innerHTML = '<i class="ti ti-maximize"></i>';
    }
  }
  btnCerrar.addEventListener('click', cerrar);
  btnMaximizar.addEventListener('click', function() {
    maximizado = !maximizado;
    actualizarPanel();
  });
  encabezado.style.cursor = 'move';
  encabezado.style.userSelect = 'none';
  encabezado.style.touchAction = 'none';
  encabezado.addEventListener('pointerdown', function(evento) {
    if (maximizado || (evento.pointerType === 'mouse' && evento.button !== 0) || evento.target.closest('button')) return;
    var inicioX = evento.clientX;
    var inicioY = evento.clientY;
    var baseX = desplazamiento.x;
    var baseY = desplazamiento.y;
    encabezado.setPointerCapture(evento.pointerId);
    function mover(ev) {
      desplazamiento.x = baseX + ev.clientX - inicioX;
      desplazamiento.y = baseY + ev.clientY - inicioY;
      panel.style.transform = 'translate(' + desplazamiento.x + 'px,' + desplazamiento.y + 'px)';
    }
    function terminar(ev) {
      encabezado.removeEventListener('pointermove', mover);
      encabezado.removeEventListener('pointerup', terminar);
      encabezado.removeEventListener('pointercancel', terminar);
      if (encabezado.hasPointerCapture(ev.pointerId)) encabezado.releasePointerCapture(ev.pointerId);
    }
    encabezado.addEventListener('pointermove', mover);
    encabezado.addEventListener('pointerup', terminar);
    encabezado.addEventListener('pointercancel', terminar);
  });
  modal.addEventListener('click', function(evento) { if (evento.target === modal) cerrar(); });
  btnImprimir.addEventListener('click', function() {
    try {
      marco.contentWindow.focus();
      marco.contentWindow.print();
    } catch (error) {
      notify('No se pudo abrir la impresión del extracto: ' + error.message);
    }
  });

  acciones.appendChild(btnImprimir);
  acciones.appendChild(btnMaximizar);
  acciones.appendChild(btnCerrar);
  encabezado.appendChild(titulo);
  encabezado.appendChild(acciones);
  panel.appendChild(encabezado);
  panel.appendChild(marco);
  modal.appendChild(panel);
  document.body.appendChild(modal);
}

function imprimirExtractoCuentaCorriente() {
  var extracto = window._ccExtractoActual;
  if (!extracto || !extracto.nombre) {
    notify('Abrí primero la cuenta de un cliente para generar su extracto');
    return;
  }

  var vista = _ccVistaExtractoFiltrada(extracto);
  if (!vista.valido) { notify(vista.mensaje); return; }
  var cliente = _ccClienteParaExtracto(extracto);
  var movimientos = vista.movimientos;
  var empresa = {
    nombre: (document.getElementById('cfg-empresa-nombre') || {}).value || 'Nixa',
    dir: (document.getElementById('cfg-empresa-dir') || {}).value || '',
    tel: (document.getElementById('cfg-empresa-tel') || {}).value || '',
    cuit: (document.getElementById('cfg-empresa-cuit') || {}).value || ''
  };
  var logoImpresion = logoImpresionActualUrl();
  var logo = logoImpresion
    ? '<img src="' + escapeHTML(logoImpresion) + '" alt="' + escapeHTML(empresa.nombre) + '">'
    : '<div class="marca">' + escapeHTML(empresa.nombre) + '</div>';
  var identificacion = cliente.cuit || cliente.cuil || cliente.dni || cliente.documento || '';
  var direccion = cliente.direccion || cliente.domicilio || cliente.dir || '';
  var telefono = cliente.telefono || cliente.tel || cliente.celular || '';
  var email = cliente.email || cliente.correo || '';
  var fechas = movimientos.filter(function(m) { return m.ts > 0; }).map(function(m) { return m.ts; });
  var desde = vista.desdeLabel || (fechas.length ? new Date(Math.min.apply(Math, fechas)).toLocaleDateString('es-AR') : 'Inicio de la cuenta');
  var hasta = vista.hastaLabel || (fechas.length ? new Date(Math.max.apply(Math, fechas)).toLocaleDateString('es-AR') : 'Sin movimientos');
  var emitido = new Date().toLocaleString('es-AR', { day:'2-digit', month:'2-digit', year:'numeric', hour:'2-digit', minute:'2-digit' });
  var filaSaldoAnterior = vista.filtrado && vista.desdeValor
    ? '<tr class="saldo-anterior"><td>' + escapeHTML(vista.desdeLabel) + '</td><td><strong>Saldo anterior al período</strong></td><td class="num">—</td><td class="num">—</td><td class="num saldo">' + _ccFormatoImporteExtracto(vista.saldoAnterior) + '</td></tr>'
    : '';
  var filas = filaSaldoAnterior + movimientos.map(function(m) {
    var fecha = typeof _mostrarFecha === 'function' ? _mostrarFecha(m.fecha) : m.fecha;
    return '<tr>' +
      '<td class="fecha">' + escapeHTML(fecha || '—') + '</td>' +
      '<td>' + escapeHTML(m.concepto || 'Movimiento') + '</td>' +
      '<td class="num">' + (m.debe ? _ccFormatoImporteExtracto(m.debe) : '—') + '</td>' +
      '<td class="num credito">' + (m.haber ? _ccFormatoImporteExtracto(m.haber) : '—') + '</td>' +
      '<td class="num saldo">' + _ccFormatoImporteExtracto(m.saldo) + '</td>' +
    '</tr>';
  }).join('');
  var totalDebe = movimientos.reduce(function(total, m) { return total + (Number(m.debe) || 0); }, 0);
  var totalHaber = movimientos.reduce(function(total, m) { return total + (Number(m.haber) || 0); }, 0);
  var contacto = [direccion, telefono && ('Tel. ' + telefono), email].filter(Boolean).map(escapeHTML).join(' · ');
  var datosEmpresa = [empresa.cuit && ('CUIT ' + empresa.cuit), empresa.dir, empresa.tel && ('Tel. ' + empresa.tel)].filter(Boolean).map(escapeHTML).join(' · ');
  var tituloDocumento = 'Extracto de cuenta - ' + String(extracto.nombre || 'Cliente');

  var html = '<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>' + escapeHTML(tituloDocumento) + '</title>' +
    '<style>@page{size:A4;margin:12mm}*{box-sizing:border-box}body{font-family:Arial,Helvetica,sans-serif;color:#172033;margin:0;font-size:11px;line-height:1.35}.cabecera{display:flex;justify-content:space-between;gap:24px;align-items:flex-start;border-bottom:2px solid #172033;padding-bottom:13px;margin-bottom:16px}.empresa img{height:48px;max-width:180px;object-fit:contain}.marca{font-size:25px;font-weight:800}.empresa-datos{color:#526078;margin-top:6px;max-width:440px}.doc{text-align:right}.doc h1{font-size:19px;margin:0 0 5px}.doc div{color:#526078}.cliente{border:1px solid #ccd4df;border-radius:8px;padding:11px 13px;margin-bottom:14px}.cliente strong{font-size:14px}.cliente .datos{color:#526078;margin-top:4px}.resumen{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:9px;margin-bottom:14px}.resumen>div{border:1px solid #ccd4df;border-radius:8px;padding:9px 11px}.resumen span{display:block;text-transform:uppercase;font-size:9px;letter-spacing:.7px;color:#64748b;margin-bottom:3px}.resumen b{font-size:14px}.resumen .final{border-color:#9aa9bc;background:#f4f7fa}table{width:100%;border-collapse:collapse;table-layout:fixed}thead{display:table-header-group}th{background:#edf1f5;text-transform:uppercase;font-size:9px;letter-spacing:.45px;color:#42516a;text-align:left}th,td{border-bottom:1px solid #d9e0e8;padding:7px 6px;vertical-align:top}th:nth-child(1),td:nth-child(1){width:14%}th:nth-child(2),td:nth-child(2){width:38%}th:nth-child(n+3),td:nth-child(n+3){width:16%}.num{text-align:right;white-space:nowrap}.credito{color:#137443}.saldo{font-weight:700}.saldo-anterior{background:#f4f7fa}.vacio{text-align:center;color:#64748b;padding:25px}.pie{margin-top:18px;padding-top:9px;border-top:1px solid #ccd4df;color:#64748b;font-size:9px;display:flex;justify-content:space-between;gap:15px}.nota{margin-top:10px;color:#526078;font-size:9px}@media(max-width:650px){.cabecera{display:block}.doc{text-align:left;margin-top:12px}.resumen{grid-template-columns:1fr}.hoja{min-width:720px}body{overflow:auto}}@media print{body{-webkit-print-color-adjust:exact;print-color-adjust:exact}.hoja{min-width:0}}</style></head><body><main class="hoja">' +
    '<header class="cabecera"><div class="empresa">' + logo + '<div class="empresa-datos">' + datosEmpresa + '</div></div><div class="doc"><h1>Extracto de cuenta corriente</h1><div>Emitido: ' + escapeHTML(emitido) + '</div><div>Período: ' + escapeHTML(desde) + ' al ' + escapeHTML(hasta) + '</div></div></header>' +
    '<section class="cliente"><strong>' + escapeHTML(extracto.nombre) + '</strong>' + (identificacion ? '<div>CUIT / DNI: ' + escapeHTML(identificacion) + '</div>' : '') + '<div class="datos">' + (contacto || 'Sin datos de contacto registrados') + '</div></section>' +
    '<section class="resumen">' + (vista.filtrado && vista.desdeValor ? '<div><span>Saldo anterior</span><b>' + _ccFormatoImporteExtracto(vista.saldoAnterior) + '</b></div>' : '') + '<div><span>Cargos del período</span><b>' + _ccFormatoImporteExtracto(totalDebe) + '</b></div><div><span>Pagos del período</span><b>' + _ccFormatoImporteExtracto(totalHaber) + '</b></div><div class="final"><span>Saldo al cierre</span><b>' + _ccFormatoImporteExtracto(vista.saldoFinal) + '</b></div></section>' +
    '<table><thead><tr><th>Fecha</th><th>Concepto</th><th class="num">Debe</th><th class="num">Haber</th><th class="num">Saldo</th></tr></thead><tbody>' + (filas || '<tr><td colspan="5" class="vacio">Sin movimientos registrados</td></tr>') + '</tbody></table>' +
    '<div class="nota">Debe: cargos generados por ventas. Haber: pagos aplicados. El saldo surge de la diferencia acumulada entre ambos.</div>' +
    '<footer class="pie"><span>Documento informativo para el cliente.</span><span>' + escapeHTML(empresa.nombre) + '</span></footer></main></body></html>';

  _ccAbrirVistaPreviaExtracto(html, extracto.nombre);
}

function irAVentaDesdeCobranza(ventaId) {
  if (!ventaId || ventaId === '—') return;
  var vid = String(ventaId).trim();
  var num = vid.replace(/[^0-9]/g, '');
  var v = _svResolverVentaRegistro({ ventaId: vid, venta: vid, idVenta: vid });
  if (!v) { notify('Venta ' + vid + ' no encontrada'); return; }
  window._ventaDesdeHistorialOrigen = 'cobranzas';
  // Navegar al módulo de ventas primero, luego mostrar el detalle
  window._ventaDesdeHistorialOrigen = 'cobranzas';
  // Ocultar la lista antes de navegar para evitar el flash
  svNavegarDirecto('detalle', function() {
    verDetalleVenta(v.id);
    window._ventaDesdeHistorialOrigen = null;
  }, document.querySelector('[onclick*=detalle]'));
}

function irACobranzasDesdeCC() {
  // Ir a cobranzas precargando el cliente actual
  var nombre = window._ccNombreActual || '';
  var clienteKey = window._ccClienteKeyActual || '';
  var ccData = clienteKey && window._ccMapActual ? window._ccMapActual[clienteKey] : null;
  showPage('cobranzas', document.querySelector('[onclick*=cobranzas]'));
  if (nombre) {
    setTimeout(function() {
      // Precargar el nombre del cliente en el campo de cobranzas
      var cliEl = document.getElementById('cob-cliente');
      if (cliEl) cliEl.value = nombre;
      var ventasPendientes = (ventasList||[]).filter(function(v){
        var keys = [v.clienteFbKey, v.clienteKey, v.clienteId, v.idCliente, v.idClienteOriginal].map(function(x){ return String(x||'').trim(); });
        var porKey = ccData && ((ccData.clienteFbKey && keys.indexOf(String(ccData.clienteFbKey)) >= 0) || (ccData.legacyId && keys.indexOf(String(ccData.legacyId)) >= 0));
        return (porKey || (!ccData && _svTxtNombre(v.cliente) === _svTxtNombre(nombre))) && !ventaTienePagoTotal(v);
      }).sort(function(a,b){ return (b.fecha||'').localeCompare(a.fecha||''); });
      if (ventasPendientes.length) {
        var vp = ventasPendientes[0];
        irACobranzasConVenta(vp.id);
      }
    }, 150);
  }
}

function verClienteDesdeCC() {
  var nombre = window._ccNombreActual || '';
  var clienteKey = window._ccClienteKeyActual || '';
  if (!nombre && !clienteKey) return;
  var cli = (clientesData||[]).find(function(c){
    var nombreCli = _svTxtNombre(c.nombre || '');
    var nombreCompleto = _svTxtNombre((c.nombre||'') + ' ' + (c.apellidos||c.apellido||''));
    var nombreBuscado = _svTxtNombre(nombre);
    return String(c.fbKey||'') === String(clienteKey) ||
      String(c.id||'') === String(clienteKey) ||
      (!!nombreBuscado && (nombreCli === nombreBuscado || nombreCompleto === nombreBuscado));
  });
  if (!cli) { notify('Cliente no encontrado en el sistema'); return; }
  svNavegarDirecto('clientes', function(){ if (typeof verHistorialCliente === 'function') verHistorialCliente(cli.fbKey||String(cli.id), nombre); }, document.querySelector('[onclick*=clientes]'));
}

function verVentaDesdeHistorial(ventaId, trEl) {
  var v = _svResolverVentaRegistro(ventaId);
  if (!v) { notify('Venta no encontrada'); return; }
  window._ventaDesdeHistorialOrigen = 'cuentacorriente';
  // Ocultar lista para evitar flash
  svNavegarDirecto('detalle', function() {
    verDetalleVenta(v.id);
    window._ventaDesdeHistorialOrigen = 'cuentacorriente';
  }, document.querySelector('[onclick*=detalle]'));
}

function verEmpleado(id) {
  const e = empData[id];
  if (!e) return;
  _hide('emp-list-view');
  _block('emp-detail-view');
  var iniciales = (e.nombre||'—').trim().split(/\s+/).map(function(p){return p[0]||'';}).slice(0,2).join('').toUpperCase();
  const av = document.getElementById('det-avatar');
  av.textContent = iniciales || '—';
  av.style.background = 'var(--blue-bg)';
  av.style.color = 'var(--blue)';
  _set('det-nombre',e.nombre||'—');
  setChildren(document.getElementById('det-cat'), [makeBadge(e.cargo || 'Sin cargo', 'b-blue')]);
  setChildren(document.getElementById('det-estado'), [makeBadge(e.activo!==false ? 'Activo' : 'Inactivo', e.activo!==false ? 'b-green' : 'b-red')]);
  _set('det-ingreso', e.fechaIngreso ? 'Ingresó: '+e.fechaIngreso : 'Fecha de inicio no cargada');
  var cargoInfo = e.cargoId ? CARGOS_DATA[e.cargoId] : null;
  _set('det-base', cargoInfo ? '$'+Math.round((parseFloat(cargoInfo.valorHora)||0)*8).toLocaleString('es-AR') : '—');
  var comCalc = (typeof calcularComisionEmpleado === 'function') ? calcularComisionEmpleado(e, new Date().toISOString().slice(0,7)) : null;
  _set('det-comisiones', comCalc ? '$'+Math.round(comCalc.comision||0).toLocaleString('es-AR') : '—');
  _set('det-comisiones-sub', 'este mes');
  _set('det-hextra', cargoInfo ? '$'+Math.round(parseFloat(cargoInfo.valorHoraExtra)||0).toLocaleString('es-AR') : '—');
  _set('det-hextra-sub', 'valor hora extra');
  var totalAprox = (cargoInfo ? (parseFloat(cargoInfo.valorHora)||0)*8*(parseFloat(cargoInfo.diasMes)||0) : 0) + (comCalc ? (comCalc.comision||0) : 0);
  _set('det-total', '$'+Math.round(totalAprox).toLocaleString('es-AR'));
  _set('det-total-sub', 'mensual aprox.');
  document.getElementById('det-dni').value = e.dni||'';
  document.getElementById('det-tel').value = e.telefono||'';
  document.getElementById('det-email').value = e.mail||'';
  document.getElementById('det-dir').value = e.direccion||'';
}
function volverlista() {
  _block('emp-list-view');
  _hide('emp-detail-view');
}

function toggleUserPanel() {
  if (typeof closeSidebarMobile === 'function') closeSidebarMobile();
  document.body.style.overflow = ''; // limpiar overflow del sidebar
  var panel = document.getElementById('user-panel');
  var overlay = document.getElementById('user-panel-overlay');
  if (!panel) return;
  var isOpen = panel.style.display === 'block';
  if (isOpen) {
    panel.style.display = 'none';
    if (overlay) overlay.style.display = 'none';
    return;
  }
  // Posicionar relativo al botón para evitar problemas de viewport/stacking
  var btn = document.getElementById('btn-gear');
  if (btn) {
    var rect = btn.getBoundingClientRect();
    panel.style.top    = (rect.bottom + 4) + 'px';
    panel.style.right  = (window.innerWidth - rect.right) + 'px';
    panel.style.left   = 'auto';
  }
  panel.style.zIndex  = '999999';
  panel.style.display = 'block';
  panel.offsetHeight; // forzar repaint
  if (overlay) setTimeout(function() { overlay.style.display = 'block'; overlay.style.zIndex = '999998'; }, 50);
  if (typeof window.aplicarVersionSisVentas === 'function') window.aplicarVersionSisVentas(document);
}
function cerrarUserPanel() {
  const panel = document.getElementById('user-panel');
  const overlay = document.getElementById('user-panel-overlay');
  if (panel) panel.style.display = 'none';
  if (overlay) overlay.style.display = 'none';
}
