// Abrir ficha
function abrirFichaEquipo(fbKey) {
  var eq = equiposData.find(function(e){ return e.fbKey === fbKey; });
  if (!eq) return;
  equipoActual = fbKey;
  eqFotosTemp = [];
  document.getElementById('eq-ficha-titulo').textContent = eq.descripcion || 'Ficha de equipo';
  // Llenar campos
  var _v = function(id, val){ var el=document.getElementById(id); if(el) el.value=val||''; };
  _v('eq-f-cat',       eq.categoria||'Alarmas');
  _v('eq-f-modelo',    eq.modelo||'');
  _v('eq-f-desc',      eq.descripcion||'');
  _v('eq-f-serie',     eq.serie||'');
  _v('eq-f-serie2',    eq.serie2||'');
  _v('eq-f-cliente',   eq.cliente||'');
  _v('eq-f-dir',       eq.dir||'');
  _v('eq-f-fecha',     eq.fechaInstalacion||'');
  _v('eq-f-garantia',  eq.garantiaMeses||'12');
  _v('eq-f-estado',    eq.estado||'operativo');
  _v('eq-f-venta',     eq.venta||'');
  _v('eq-f-obs',       eq.obs||'');
  // Llenar select técnico
  var selTec = document.getElementById('eq-f-tecnico');
  if (selTec) {
    var opts = '<option value="">— Seleccionar —</option>';
    Object.values(empData||{}).forEach(function(e){ if(e.activo!==false) opts+='<option value="'+escapeHTML(e.nombre)+'">'+escapeHTML(e.nombre)+'</option>'; });
    selTec.innerHTML = opts;
    selTec.value = eq.tecnico||'';
  }
  // Fotos
  renderFotosEquipo(eq.fotos||{});
  // Historial intervenciones
  renderHistorialEquipo(eq.intervenciones||{});
  // Mostrar ficha
  document.getElementById('eq-lista-view').style.display = 'none';
  document.getElementById('eq-ficha-view').style.display = '';
}

function abrirNuevoEquipo() {
  equipoActual = null;
  eqFotosTemp = [];
  var _c = function(id){ var el=document.getElementById(id); if(el) el.value=''; };
  ['eq-f-cat','eq-f-modelo','eq-f-desc','eq-f-serie','eq-f-serie2','eq-f-cliente','eq-f-dir','eq-f-fecha','eq-f-venta','eq-f-obs'].forEach(_c);
  document.getElementById('eq-f-fecha').value = new Date().toISOString().split('T')[0];
  document.getElementById('eq-f-garantia').value = '12';
  document.getElementById('eq-f-estado').value = 'operativo';
  document.getElementById('eq-ficha-titulo').textContent = 'Nuevo equipo';
  renderFotosEquipo({});
  renderHistorialEquipo({});
  var selTec = document.getElementById('eq-f-tecnico');
  if (selTec) {
    var opts = '<option value="">— Seleccionar —</option>';
    Object.values(empData||{}).forEach(function(e){ if(e.activo!==false) opts+='<option>'+escapeHTML(e.nombre)+'</option>'; });
    selTec.innerHTML = opts;
  }
  document.getElementById('eq-lista-view').style.display = 'none';
  document.getElementById('eq-ficha-view').style.display = '';
}

function volverListaEquipos() {
  document.getElementById('eq-ficha-view').style.display = 'none';
  document.getElementById('eq-lista-view').style.display = '';
  equipoActual = null;
}

function guardarEquipo() {
  if (!window.fbDB) { notify('Sin conexión'); return; }
  var g = function(id){ var el=document.getElementById(id); return el?el.value.trim():''; };
  var datos = {
    categoria:       g('eq-f-cat'),
    modelo:          g('eq-f-modelo'),
    descripcion:     g('eq-f-desc'),
    serie:           g('eq-f-serie'),
    serie2:          g('eq-f-serie2'),
    cliente:         g('eq-f-cliente'),
    dir:             g('eq-f-dir'),
    tecnico:         g('eq-f-tecnico'),
    fechaInstalacion:g('eq-f-fecha'),
    garantiaMeses:   g('eq-f-garantia'),
    estado:          g('eq-f-estado'),
    venta:           g('eq-f-venta'),
    obs:             g('eq-f-obs'),
  };
  if (!datos.descripcion && !datos.modelo) { notify('Ingresá descripción o modelo'); return; }
  var promesa = equipoActual
    ? window.fbUpdate(window.fbRef(window.fbDB, 'sisventas/equipos/'+equipoActual), datos)
    : (datos.ts = Date.now(), window.fbPush(window.fbRef(window.fbDB, 'sisventas/equipos'), datos).then(function(ref){ equipoActual = ref.key; return ref; }));
  promesa.then(function(){
    // Subir fotos pendientes
    if (eqFotosTemp.length) subirFotosEquipo();
    else { notify(equipoActual ? 'Equipo actualizado' : 'Equipo guardado'); volverListaEquipos(); }
  }).catch(function(e){ notify('Error: '+e.message); });
}

// Fotos del equipo
function agregarFotosEquipo(input) {
  var files = Array.from(input.files||[]);
  files.forEach(function(file){
    eqFotosTemp.push(file);
    var reader = new FileReader();
    reader.onload = function(e) {
      var grid = document.getElementById('eq-fotos-grid');
      if (!grid) return;
      // Quitar placeholder
      grid.querySelectorAll('.foto-placeholder').forEach(function(el){ el.remove(); });
      var img = document.createElement('img');
      img.src = e.target.result;
      img.className = 'rel-foto-thumb';
      img.title = 'Foto pendiente de guardar';
      img.style.opacity = '.6';
      grid.appendChild(img);
    };
    reader.readAsDataURL(file);
  });
}

function renderFotosEquipo(fotosObj) {
  var grid = document.getElementById('eq-fotos-grid');
  if (!grid) return;
  var fotos = Object.values(fotosObj||{});
  if (!fotos.length) {
    grid.innerHTML = '<div class="foto-placeholder" style="color:var(--text3);font-size:12px;text-align:center;padding:20px;grid-column:1/-1">Sin fotos. Tocá el botón para agregar.</div>';
    return;
  }
  grid.innerHTML = fotos.map(function(f){
    return '<img src="'+f.url+'" class="rel-foto-thumb" onclick="window.open(\''+f.url+'\',\'_blank\')" title="'+(f.fecha||'')+'">';
  }).join('');
}

function subirFotosEquipo() {
  if (!equipoActual || !eqFotosTemp.length || !window.fbStorage) return;
  var pendientes = eqFotosTemp.length;
  eqFotosTemp.forEach(function(file) {
    var path = 'sisventas/equipos/'+equipoActual+'/fotos/'+Date.now()+'_'+file.name;
    var ref = window.fbStorageRef(window.fbStorage, path);
    window.fbUploadBytes(ref, file).then(function(snap){ return window.fbGetDownloadURL(snap.ref); })
    .then(function(url){
      window.fbPush(window.fbRef(window.fbDB, 'sisventas/equipos/'+equipoActual+'/fotos'), {
        url: url, fecha: new Date().toLocaleDateString('es-AR'), tecnico: currentUser||''
      });
      pendientes--;
      if (pendientes === 0) { notify('Equipo y fotos guardados'); eqFotosTemp = []; volverListaEquipos(); }
    }).catch(function(){ pendientes--; if(pendientes===0){ notify('Equipo guardado (error en algunas fotos)'); volverListaEquipos(); } });
  });
}
function abrirRelevamiento() {
  if (!equipoActual) { notify('Guardá el equipo primero'); return; }
  var eq = equiposData.find(function(e){ return e.fbKey === equipoActual; });
  relFotosTemp = [];
  relTipoSel   = '';
  relEstadoSel = eq ? (eq.estado||'operativo') : 'operativo';
  document.getElementById('rel-equipo-nombre').textContent  = eq ? (eq.descripcion||eq.modelo||'—') : '—';
  document.getElementById('rel-equipo-cliente').textContent = eq ? (eq.cliente||'—') : '—';
  document.getElementById('rel-equipo-serie').textContent   = eq ? ('N° serie: '+(eq.serie||'—')) : '—';
  document.getElementById('rel-trabajo').value = '';
  document.getElementById('rel-prox-visita').value = '';
  document.getElementById('rel-fotos-grid').innerHTML = '';
  document.getElementById('rel-checklist').innerHTML = '<div style="color:var(--text3);font-size:13px;text-align:center;padding:12px">Seleccioná un tipo de intervención</div>';
  document.querySelectorAll('.btn-tipo-rel').forEach(function(b){ b.classList.remove('activo'); });
  document.querySelectorAll('.btn-estado-rel').forEach(function(b){
    b.style.background = 'var(--bg3)'; b.style.border = '1px solid var(--border)'; b.style.color = 'var(--text)';
  });
  document.getElementById('modal-relevamiento').style.display = 'block';
}

function cerrarRelevamiento() { document.getElementById('modal-relevamiento').style.display = 'none'; }

function selTipoRel(btn) {
  document.querySelectorAll('.btn-tipo-rel').forEach(function(b){ b.classList.remove('activo'); });
  btn.classList.add('activo');
  relTipoSel = btn.dataset.tipo;
  var items = CHECKLISTS_EQ[relTipoSel] || [];
  document.getElementById('rel-checklist').innerHTML = items.map(function(item, i){
    return '<div class="check-item" onclick="toggleCheck(this)" id="chk-'+i+'">' +
      '<input type="checkbox" onclick="event.stopPropagation();this.closest(\'.check-item\').classList.toggle(\'checked\',this.checked)">' +
      '<span>'+escapeHTML(item)+'</span></div>';
  }).join('');
}

function toggleCheck(el) {
  var chk = el.querySelector('input[type=checkbox]');
  if (chk) { chk.checked = !chk.checked; el.classList.toggle('checked', chk.checked); }
}

function selEstadoRel(btn) {
  document.querySelectorAll('.btn-estado-rel').forEach(function(b){
    b.style.background='var(--bg3)'; b.style.border='1px solid var(--border)'; b.style.color='var(--text)';
  });
  btn.style.background = 'var(--text)'; btn.style.color = 'var(--bg2)'; btn.style.border = '1px solid var(--text)';
  relEstadoSel = btn.dataset.est;
}

function agregarFotosRel(input) {
  var files = Array.from(input.files||[]);
  files.forEach(function(file){
    relFotosTemp.push(file);
    var reader = new FileReader();
    reader.onload = function(e) {
      var grid = document.getElementById('rel-fotos-grid');
      var img = document.createElement('img');
      img.src = e.target.result; img.className = 'rel-foto-thumb'; img.style.opacity='.7';
      grid.appendChild(img);
    };
    reader.readAsDataURL(file);
  });
}

function guardarRelevamiento() {
  if (!equipoActual || !window.fbDB) { notify('Sin conexión'); return; }
  if (!relTipoSel) { notify('Seleccioná el tipo de intervención'); return; }
  var trabajo = document.getElementById('rel-trabajo').value.trim();
  if (!trabajo) { notify('Describí el trabajo realizado'); return; }
  // Recopilar checklist
  var checks = {};
  document.querySelectorAll('#rel-checklist .check-item').forEach(function(el, i){
    checks[i] = { texto: el.querySelector('span').textContent, ok: el.querySelector('input').checked };
  });
  var intervencion = {
    tipo:       relTipoSel,
    fecha:      new Date().toISOString(),
    tecnico:    currentUser || '',
    trabajo:    trabajo,
    estado:     relEstadoSel,
    proxVisita: document.getElementById('rel-prox-visita').value || '',
    checks:     checks,
    fotos:      {}
  };
  var path = 'sisventas/equipos/'+equipoActual+'/intervenciones';
  window.fbUpdate(window.fbRef(window.fbDB, 'sisventas/equipos/'+equipoActual), { estado: relEstadoSel });
  window.fbPush(window.fbRef(window.fbDB, path), intervencion).then(function(refNuevo){
    var keyRel = refNuevo.key;
    // Subir fotos si hay
    if (relFotosTemp.length && window.fbStorage) {
      relFotosTemp.forEach(function(file){
        var fRef = window.fbStorageRef(window.fbStorage, 'sisventas/equipos/'+equipoActual+'/relevamientos/'+keyRel+'/'+Date.now()+'_'+file.name);
        window.fbUploadBytes(fRef, file).then(function(snap){ return window.fbGetDownloadURL(snap.ref); })
        .then(function(url){
          window.fbPush(window.fbRef(window.fbDB, path+'/'+keyRel+'/fotos'), { url:url, ts:Date.now() });
        });
      });
    }
    notify('Relevamiento guardado ✓');
    cerrarRelevamiento();
    // Recargar ficha
    setTimeout(function(){ abrirFichaEquipo(equipoActual); }, 800);
  }).catch(function(e){ notify('Error: '+e.message); });
}

function renderHistorialEquipo(intervObj) {
  var lista = Object.entries(intervObj||{}).map(function(e){ return Object.assign({fbKey:e[0]},e[1]); })
    .sort(function(a,b){ return new Date(b.fecha)-new Date(a.fecha); });
  var cont = document.getElementById('eq-historial-lista');
  var cnt  = document.getElementById('eq-historial-count');
  if (cnt) cnt.textContent = lista.length ? lista.length + ' registro' + (lista.length>1?'s':'') : '';
  if (!cont) return;
  if (!lista.length) {
    cont.innerHTML = '<div style="padding:20px;text-align:center;color:var(--text3);font-size:13px">Sin intervenciones registradas</div>';
    return;
  }
  var tipoIcon = {instalacion:'📦',mantenimiento:'🔧',reparacion:'🛠️',relevamiento:'🔍',garantia:'🛡️',otro:'📋'};
  var estClr   = {operativo:'var(--green)',alerta:'var(--amber)',mantenimiento:'var(--blue)',baja:'var(--red)'};
  cont.innerHTML = lista.map(function(iv){
    var fecha = iv.fecha ? new Date(iv.fecha).toLocaleDateString('es-AR',{day:'2-digit',month:'2-digit',year:'2-digit',hour:'2-digit',minute:'2-digit'}) : '—';
    var checks = iv.checks ? Object.values(iv.checks) : [];
    var ok = checks.filter(function(c){ return c.ok; }).length;
    var cantFotos = iv.fotos ? Object.keys(iv.fotos).length : 0;
    return '<div style="padding:12px 0;border-bottom:0.5px solid var(--border)">' +
      '<div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px;margin-bottom:6px">' +
        '<div style="display:flex;align-items:center;gap:8px">' +
          '<span style="font-size:18px">'+(tipoIcon[iv.tipo]||'📋')+'</span>' +
          '<div>' +
            '<div style="font-size:13px;font-weight:500">'+(iv.tipo?iv.tipo.charAt(0).toUpperCase()+iv.tipo.slice(1):'—')+'</div>' +
            '<div style="font-size:11px;color:var(--text3)">'+(iv.tecnico||'—')+' · '+fecha+'</div>' +
          '</div>' +
        '</div>' +
        '<span style="font-size:11px;font-weight:600;color:'+(estClr[iv.estado]||'var(--text3)')+'">'+((iv.estado||'').charAt(0).toUpperCase()+(iv.estado||'').slice(1))+'</span>' +
      '</div>' +
      '<div style="font-size:12px;color:var(--text2);margin-bottom:6px">'+escapeHTML(iv.trabajo||'')+'</div>' +
      '<div style="display:flex;gap:12px;font-size:11px;color:var(--text3)">' +
        (checks.length ? '<span>✓ '+ok+'/'+checks.length+' checks</span>' : '') +
        (cantFotos ? '<span>📷 '+cantFotos+' foto'+(cantFotos>1?'s':'')+'</span>' : '') +
        (iv.proxVisita ? '<span>📅 Próx: '+iv.proxVisita.split('-').reverse().join('/')+'</span>' : '') +
      '</div>' +
    '</div>';
  }).join('');
}
function abrirScannerSerie(targetField) {
  scannerTargetField = targetField || 'eq-f-serie';
  var modal = document.getElementById('modal-scanner');
  if (!modal) return;
  modal.style.display = 'flex';
  // Pedir acceso a cámara
  navigator.mediaDevices.getUserMedia({ video: { facingMode: 'environment', width:{ideal:1280}, height:{ideal:720} } })
    .then(function(stream) {
      scannerStream = stream;
      var video = document.getElementById('scanner-video');
      video.srcObject = stream;
    })
    .catch(function(err) {
      notify('No se pudo acceder a la cámara: ' + err.message);
      cerrarScanner();
      // Fallback: prompt manual
      capturarManual();
    });
}

function cerrarScanner() {
  if (scannerStream) { scannerStream.getTracks().forEach(function(t){ t.stop(); }); scannerStream = null; }
  document.getElementById('modal-scanner').style.display = 'none';
}

function capturarFrame() {
  var video  = document.getElementById('scanner-video');
  var canvas = document.getElementById('scanner-canvas');
  if (!video || !canvas) return;
  canvas.width  = video.videoWidth;
  canvas.height = video.videoHeight;
  var ctx = canvas.getContext('2d');
  ctx.drawImage(video, 0, 0);
  // Recortar zona central (el rectángulo de escaneo)
  var x = Math.floor(canvas.width/2 - 140);
  var y = Math.floor(canvas.height/2 - 60);
  var imgData = ctx.getImageData(x, y, 280, 120);
  // Mostrar la imagen capturada brevemente
  var resultado = document.getElementById('scanner-resultado');
  resultado.textContent = '📸 Imagen capturada. Usá la entrada manual para escribir el N° de serie visto.';
  // ofrecemos el resultado visual para que el técnico lo tipee
  setTimeout(function() {
    capturarManual();
  }, 1500);
}

async function capturarManual() {
  cerrarScanner();
  var serie = await svPrompt('Ingresá el N° de serie:');
  if (serie && serie.trim()) {
    var campo = document.getElementById(scannerTargetField);
    if (campo) { campo.value = serie.trim(); campo.focus(); }
    notify('N° de serie cargado: ' + serie.trim());
  }
}

