  gastoRapidoFotoBase64 = null;
  document.getElementById('gr-fecha').value = new Date().toISOString().split('T')[0];
  _setMontoInput(document.getElementById('gr-monto'), 0);
  document.getElementById('gr-descripcion').value = '';
