function previewFotoGastoRapido(input) {
  var file = input.files[0];
  if (!file) return;
  if (file.size > 800 * 1024) { notify('La foto no puede superar 800KB'); input.value=''; return; }
  var reader = new FileReader();
  reader.onload = function(e) {
    gastoRapidoFotoBase64 = e.target.result;
    document.getElementById('gr-foto-preview').innerHTML = '<img src="'+e.target.result+'" style="max-width:100%;border-radius:var(--radius);margin-top:6px">';
  };
  reader.readAsDataURL(file);
}

function guardarGastoRapido() {
  var monto = getMontoRaw(document.getElementById('gr-monto'));
  var desc  = document.getElementById('gr-descripcion').value.trim();
  if (!desc)  { notify('Ingresá una descripción'); return; }
  if (!monto) { notify('Ingresá el monto'); return; }
  if (!window.fbDB) { notify('Sin conexión'); return; }

  var pagueYo = document.getElementById('gr-pagado-yo').checked;
  var miEmpleado = null;
  if (pagueYo) {
    miEmpleado = Object.values(empData||{}).find(function(e) {
      return (e.mail||'').toLowerCase() === (currentUser||'').toLowerCase() || e.nombre === currentUser;
    });
  }

  var datos = {
    fecha:          document.getElementById('gr-fecha').value,
    vencimiento:    '',
    tipo:           'Variable',
    categoria:      document.getElementById('gr-categoria').value,
    descripcion:    desc,
    monto:          monto,
    montoPagado:    pagueYo ? 0 : monto,  // si lo pagó un técnico, queda pendiente hasta reembolso
    estado:         pagueYo ? 'pendiente' : 'pagado',
    medio:          document.getElementById('gr-medio').value,
    proveedor:      '',
    comprobante:    '',
    empleadoId:     miEmpleado ? miEmpleado.fbKey : null,
    empleadoNombre: miEmpleado ? miEmpleado.nombre : null,
    reembolsado:    false,
    esFijoBase:     false,
    fotoBase64:     gastoRapidoFotoBase64 || null,
    usuario:        currentUser || '',
    ts:             Date.now()
  };

  window.fbPush(window.fbRef(window.fbDB, 'sisventas/gastos'), datos)
    .then(function() {
      if (miEmpleado) {
        notify('✓ Gasto cargado · $'+monto.toLocaleString('es-AR')+' visible en tu cuenta corriente');
      } else {
        notify('✓ Gasto cargado correctamente');
      }
      cerrarGastoRapido();
    })
    .catch(function(e){ notify('Error: '+e.message); });
}
