var asistState = {
  rubro:    null,
  paso:     0,
  respuestas: {},
  multiSel: []
};

function iniciarAsistente(rubro) {
  asistState = { rubro: rubro, paso: 0, respuestas: {}, multiSel: [] };
  document.getElementById('asist-inicio').style.display     = 'none';
  document.getElementById('asist-preguntas').style.display  = '';
  document.getElementById('asist-resumen').style.display    = 'none';
  mostrarPaso();
}

function mostrarPaso() {
  var cfg  = ASIST_RUBROS[asistState.rubro];
  var paso = cfg.pasos[asistState.paso];
  var total = cfg.pasos.length;

  document.getElementById('asist-paso-label').textContent = 'Paso '+(asistState.paso+1)+' de '+total;
  document.getElementById('asist-rubro-label').textContent = cfg.nombre;
  document.getElementById('asist-progress-bar').style.width = ((asistState.paso)/total*100)+'%';
  document.getElementById('asist-pregunta-titulo').textContent = paso.titulo;
  document.getElementById('asist-pregunta-desc').textContent   = paso.desc||'';
  document.getElementById('asist-input-num').style.display     = 'none';
  document.getElementById('asist-opciones').style.display      = '';

  if (paso.tipo === 'numero') {
    document.getElementById('asist-opciones').style.display  = 'none';
    document.getElementById('asist-input-num').style.display = '';
    document.getElementById('asist-num-val').value = asistState.respuestas[paso.id] || paso.default || 1;
    return;
  }

  asistState.multiSel = asistState.respuestas[paso.id] || [];
  var html = paso.opciones.map(function(op) {
    var sel = Array.isArray(asistState.multiSel) && asistState.multiSel.includes(op.id);
    return '<button class="asist-opcion-btn'+(sel?' selected':'')+'" onclick="seleccionarOpcion(\''+op.id+'\',\''+paso.tipo+'\')">' +
      '<span class="asist-opcion-ico"><i class="ti '+op.ico+'"></i></span>' +
      '<div style="flex:1"><div class="asist-opcion-titulo">'+op.titulo+'</div><div class="asist-opcion-desc">'+op.desc+'</div></div>' +
      '<span class="asist-opcion-check"><i class="ti ti-check"></i></span>' +
    '</button>';
  }).join('');

  if (paso.tipo === 'multi') {
    html += '<button class="btn btn-primary" style="width:100%;margin-top:12px;padding:14px;font-size:15px" onclick="asistConfirmarMulti()">Continuar <i class="ti ti-arrow-right"></i></button>';
  }
  document.getElementById('asist-opciones').innerHTML = html;
}

function seleccionarOpcion(id, tipo) {
  if (tipo === 'multi') {
    var idx = asistState.multiSel.indexOf(id);
    if (idx >= 0) asistState.multiSel.splice(idx,1);
    else asistState.multiSel.push(id);
    document.querySelectorAll('.asist-opcion-btn').forEach(function(btn, i) {
      var cfg  = ASIST_RUBROS[asistState.rubro];
      var paso = cfg.pasos[asistState.paso];
      var opId = paso.opciones[i] ? paso.opciones[i].id : null;
      btn.classList.toggle('selected', asistState.multiSel.includes(opId));
    });
  } else {
    // Selección única → avanza automáticamente
    var cfg  = ASIST_RUBROS[asistState.rubro];
    var paso = cfg.pasos[asistState.paso];
    asistState.respuestas[paso.id] = id;
    asistAvanzar();
  }
}

function asistConfirmarMulti() {
  var cfg  = ASIST_RUBROS[asistState.rubro];
  var paso = cfg.pasos[asistState.paso];
  if (!asistState.multiSel.length) { notify('Seleccioná al menos una opción'); return; }
  asistState.respuestas[paso.id] = asistState.multiSel.slice();
  asistAvanzar();
}

function asistAjustarNum(delta) {
  var inp = document.getElementById('asist-num-val');
  inp.value = Math.max(1, (parseInt(inp.value)||1) + delta);
}

function asistConfirmarNum() {
  var cfg  = ASIST_RUBROS[asistState.rubro];
  var paso = cfg.pasos[asistState.paso];
  var val  = parseInt(document.getElementById('asist-num-val').value)||1;
  asistState.respuestas[paso.id] = val;
  asistAvanzar();
}

function asistAvanzar() {
  var cfg = ASIST_RUBROS[asistState.rubro];
  asistState.paso++;
  if (asistState.paso >= cfg.pasos.length) {
    mostrarResumenAsistente();
  } else {
    mostrarPaso();
  }
}

function asistVolver() {
  if (asistState.paso === 0) {
    // Volver al inicio
    document.getElementById('asist-inicio').style.display    = '';
    document.getElementById('asist-preguntas').style.display = 'none';
  } else {
    asistState.paso--;
    mostrarPaso();
  }
}

function asistVolverAPreguntas() {
  asistState.paso = ASIST_RUBROS[asistState.rubro].pasos.length - 1;
  document.getElementById('asist-resumen').style.display    = 'none';
  document.getElementById('asist-preguntas').style.display  = '';
  mostrarPaso();
}
var asistProductosSel = [];

function mostrarResumenAsistente() {
  document.getElementById('asist-preguntas').style.display = 'none';
  document.getElementById('asist-resumen').style.display   = '';
  var cfg = ASIST_RUBROS[asistState.rubro];
  document.getElementById('asist-res-titulo').textContent  = 'Sistema recomendado — '+cfg.nombre;
  document.getElementById('asist-res-sub').textContent     = resumirRespuestas();
  asistProductosSel = cfg.calcularProductos(asistState.respuestas);
  renderProductosAsistente();
}

function resumirRespuestas() {
  var partes = [];
  Object.entries(asistState.respuestas).forEach(function(e) {
    var v = Array.isArray(e[1]) ? e[1].join(', ') : e[1];
    partes.push(v);
  });
  return partes.join(' · ');
}

function renderProductosAsistente() {
  var cont  = document.getElementById('asist-productos-lista');
  var total = 0;
  cont.innerHTML = asistProductosSel.map(function(p, i) {
    var sinPrecio = !p.precio || p.precio <= 0;
    var sub = p.precio * p.qty;
    total += sub;
    return '<div class="asist-prod-row">' +
      imagenProductoItemHTML({ pid:p.productoFbKey, cod:p.sku, imagenUrl:p.imagenUrl }, 'asist-prod-thumb') +
      '<div class="asist-prod-info">' +
        '<div class="asist-prod-nombre">'+escapeHTML(p.nombre)+(sinPrecio ? ' <span class="badge b-red" style="font-size:9px" title="Sin precio cargado en el sistema — no se puede cotizar hasta corregirlo">Sin precio</span>' : '')+'</div>' +
        '<div class="asist-prod-sku">'+escapeHTML(p.sku||'')+'</div>' +
      '</div>' +
      '<div class="asist-qty">' +
        '<button onclick="asistCambiarQty('+i+',-1)" '+(sinPrecio?'disabled':'')+'>−</button>' +
        '<input type="number" value="'+p.qty+'" min="0" max="200" onchange="asistSetQty('+i+',this.value)" class="asist-qty-inp-'+i+'" '+(sinPrecio?'disabled title="Sin precio cargado, no se puede modificar la cantidad"':'')+'>' +
        '<button onclick="asistCambiarQty('+i+',1)" '+(sinPrecio?'disabled':'')+'>+</button>' +
      '</div>' +
      '<div class="asist-prod-precio" style="margin-left:12px;min-width:80px;text-align:right">' +
        '<div style="font-weight:600;color:'+(sinPrecio?'var(--red)':'')+'">$'+sub.toLocaleString('es-AR')+'</div>' +
        '<div style="font-size:11px;color:var(--text3)">$'+p.precio.toLocaleString('es-AR')+' c/u</div>' +
      '</div>' +
    '</div>';
  }).join('');
  document.getElementById('asist-total').textContent = '$'+total.toLocaleString('es-AR');

  var hayItemsSinPrecio = asistProductosSel.some(function(p){ return !p.precio || p.precio <= 0; });
  var avisoEl = document.getElementById('asist-aviso-sin-precio');
  if (avisoEl) avisoEl.style.display = hayItemsSinPrecio ? '' : 'none';
}

function asistCambiarQty(idx, delta) {
  var p = asistProductosSel[idx];
  if (!p.precio || p.precio <= 0) { notify('Este ítem no tiene precio cargado, no se puede modificar la cantidad'); return; }
  var nuevaQty = Math.max(0, Math.min(200, (p.qty||0) + delta));
  p.qty = nuevaQty;
  renderProductosAsistente();
}
function asistSetQty(idx, val) {
  var p = asistProductosSel[idx];
  if (!p.precio || p.precio <= 0) { notify('Este ítem no tiene precio cargado, no se puede modificar la cantidad'); renderProductosAsistente(); return; }
  var nuevaQty = Math.max(0, Math.min(200, parseInt(val)||0));
  p.qty = nuevaQty;
  renderProductosAsistente();
}

function asistGenerarPresupuesto() {
  var cliInp = document.getElementById('asist-cli-inp');
  var cli    = cliInp.value.trim();
  var clienteAsistenteKey = String(cliInp.dataset.clienteKey || '').trim();
  var clienteAsistente = clienteAsistenteKey
    ? (clientesData||[]).find(function(c){ return String(c.fbKey || c.id || '') === clienteAsistenteKey; })
    : null;
  if (!clienteAsistente) { notify('Seleccioná el cliente desde la lista antes de generar el presupuesto'); return; }
  var obs    = document.getElementById('asist-obs').value.trim();
  var prods  = asistProductosSel.filter(function(p){ return p.qty>0; });
  if (!prods.length) { notify('No hay productos en el sistema'); return; }

  var itemSinPrecio = prods.find(function(p){ return !p.precio || p.precio <= 0; });
  if (itemSinPrecio) { notify('No se puede generar el presupuesto: "'+itemSinPrecio.nombre+'" no tiene precio cargado'); return; }

  var total  = prods.reduce(function(s,p){ return s+p.precio*p.qty; },0);
  var cfg    = ASIST_RUBROS[asistState.rubro];

  var ppto = {
    id:          '',
    numero:      '',
    cliente:     clienteAsistente.nombre || cli,
    clienteFbKey: clienteAsistente.fbKey || clienteAsistente.id || '',
    clienteKey:   clienteAsistente.fbKey || clienteAsistente.id || '',
    clienteId:    clienteAsistente.id || clienteAsistente.fbKey || '',
    fecha:       new Date().toISOString().split('T')[0],
    estado:      'borrador',
    observaciones: obs || ('Generado por asistente: '+cfg.nombre),
    items:       prods.map(function(p){ return { descripcion:p.nombre, qty:p.qty, precio:p.precio, sub:p.precio*p.qty }; }),
    subtotal:    total,
    conIva:      false,
    total:       total,
    ts:          Date.now(),
    usuario:     currentUser||''
  };

  if (!window.fbDB) { notify('Sin conexión'); return; }
  reservarSiguientePptoId()
    .then(function(numPpto) {
      ppto.id = numPpto;
      ppto.numero = numPpto;
      return pptoPersistirGuardar(ppto).then(function(){ return numPpto; });
    })
    .then(function(numPpto) {
      notify('✓ Presupuesto '+numPpto+' creado — $'+total.toLocaleString('es-AR'));
      // Volver al inicio del asistente
      setTimeout(function() {
        document.getElementById('asist-resumen').style.display  = 'none';
        document.getElementById('asist-inicio').style.display   = '';
        // Ir a ver el presupuesto
        showPage('presupuesto', document.querySelector('[onclick*=presupuesto]'));
      }, 1000);
    })
    .catch(function(e){ notify('Error: '+e.message); });
}

function buscarProductoEnDB(palabrasClave, qty) {
  // Busca en prodData el producto que mejor coincida
  var prods = prodData ? Object.values(prodData) : [];
  var claves = palabrasClave.toLowerCase().split(' ');
  var mejor = prods.find(function(p) {
    var desc = (p.descripcion||p.nombre||'').toLowerCase();
    return claves.every(function(c){ return desc.includes(c); });
  });
  if (mejor) {
    var precioReal = parseFloat(mejor.venta) || 0;
    if (precioReal <= 0) return null; // sin precio de venta válido, usar el de referencia en vez de cotizar gratis
    return { nombre: mejor.descripcion||mejor.nombre, sku: mejor.codigo, precio: precioReal, qty: qty, productoFbKey:mejor.fbKey||mejor.id||'', imagenUrl:mejor.imagenUrl||'' };
  }
  return null;
}

function prod(nombre, sku, precio, qty) {
  // Primero busca en la base de datos real, sino usa los valores de referencia
  var enDB = buscarProductoEnDB(nombre, qty);
  return enDB || { nombre: nombre, sku: sku, precio: precio, qty: qty };
}

function calcularProductosAlarma(r) {
  var zonas = r.zonas || 4;
  var lista = [];
  // Panel según zonas
  if (zonas <= 8)       lista.push(prod('Panel Garnet PG-380', 'PG-380',  85000, 1));
  else if (zonas <= 16) lista.push(prod('Panel Garnet PG-380 A', 'PG-380A', 110000, 1));
  else if (zonas <= 32) lista.push(prod('Panel Garnet PG-396', 'PG-396',  185000, 1));
  else                  lista.push(prod('Panel Garnet PG-396 Plus', 'PG-396+', 220000, 1));
  // Teclado
  lista.push(prod('Teclado LCD Garnet KP-140', 'KP-140', 45000, 1));
  // Comunicación
  var com = r.comunicacion;
  if (com==='gsm'||com==='gsm_ip')   lista.push(prod('Módulo GSM Garnet', 'GSM-MOD', 35000, 1));
  if (com==='ip'||com==='gsm_ip')    lista.push(prod('Módulo IP Garnet', 'IP-MOD', 28000, 1));
  // Sensores
  var sens = r.sensores || ['pir'];
  var cantPIR = 0, cantMag = 0;
  if (sens.includes('pir'))      { cantPIR = Math.ceil(zonas*0.6); lista.push(prod('Sensor PIR Garnet 426i', '426i', 18000, Math.max(1,cantPIR))); }
  if (sens.includes('mag'))      { cantMag = Math.ceil(zonas*0.4); lista.push(prod('Contacto magnético Garnet', 'MAG-01', 5500, Math.max(1,cantMag))); }
  if (sens.includes('doble'))    lista.push(prod('Detector doble tec. Garnet DT', 'DT-200', 28000, Math.ceil(zonas*0.5)));
  if (sens.includes('exterior')) lista.push(prod('Detector exterior Garnet', 'EXT-100', 35000, 2));
  // Accesorios
  var acc = r.accesorios || [];
  if (acc.includes('sirena_ext')) lista.push(prod('Sirena exterior Garnet', 'SIR-EXT', 22000, 1));
  if (acc.includes('sirena_int')) lista.push(prod('Sirena interior Garnet', 'SIR-INT', 12000, 1));
  if (acc.includes('teclado'))    lista.push(prod('Teclado adicional KP-140', 'KP-140B', 45000, 1));
  if (acc.includes('bateria'))    lista.push(prod('Batería 12V 7Ah', 'BAT-7A', 18000, 1));
  // Fuente siempre
  lista.push(prod('Fuente switching 2A Garnet', 'FTE-2A', 12000, 1));
  return lista;
}

function calcularProductosCamaras(r) {
  var cant = r.cantidad_cam || 4;
  var lista = [];
  // Cámara según resolución y lugar
  var donde = r.tipo_cam;
  var res   = r.resolucion;
  var marca = r.marca_linea || 'hikvision';

  if (marca === 'ezviz_ptz') {
    // se muestra un ítem marcado "sin precio" (no se inventa un precio de referencia,
    // porque el catálogo real cargado en Productos es el que manda en este caso).
    var ezvizPtz = buscarProductoEnDB('ezviz ptz', cant) || buscarProductoEnDB('ezviz domo', cant);
    lista.push(ezvizPtz || { nombre: 'Cámara EZVIZ domo PTZ (no encontrada en Productos)', sku: '', precio: 0, qty: cant });
  } else if (marca === 'ezviz_fija') {
    var ezvizFija = buscarProductoEnDB('ezviz fija', cant) || buscarProductoEnDB('ezviz ip', cant);
    lista.push(ezvizFija || { nombre: 'Cámara EZVIZ fija (no encontrada en Productos)', sku: '', precio: 0, qty: cant });
  } else if (res==='2mp') {
    if (donde==='interior')  lista.push(prod('Cámara Hikvision DS-2CD2123G2-I 2MP domo', 'DS-2CD2123G2', 55000, cant));
    else if (donde==='exterior') lista.push(prod('Cámara Hikvision DS-2CD2143G2-I 2MP bullet', 'DS-2CD2143G2', 65000, cant));
    else { // mixto
      lista.push(prod('Cámara Hikvision 2MP domo interior', 'DS-2CD2123G2', 55000, Math.ceil(cant/2)));
      lista.push(prod('Cámara Hikvision 2MP bullet exterior', 'DS-2CD2143G2', 65000, Math.floor(cant/2)));
    }
  } else if (res==='4mp') {
    lista.push(prod('Cámara Hikvision DS-2CD2143G2 4MP', 'DS-2CD2143G2-4', 85000, cant));
  } else {
    lista.push(prod('Cámara Hikvision DS-2CD2083G2 8MP 4K', 'DS-2CD2083G2', 135000, cant));
  }
  // NVR según cantidad
  var chNVR = cant<=4?4:cant<=8?8:cant<=16?16:32;
  // Disco según días
  var gbPorCam = res==='8mp'?60:res==='4mp'?40:25;
  var gbTotal  = gbPorCam * cant * (r.grabacion==='30dias'?30:r.grabacion==='15dias'?15:7);
  var disco = gbTotal<=1000?'1TB':gbTotal<=2000?'2TB':'4TB';
  lista.push(prod('NVR Hikvision '+chNVR+'ch DS-7'+chNVR+'NI-K1', 'NVR-'+chNVR, chNVR<=4?95000:chNVR<=8?130000:185000, 1));
  lista.push(prod('Disco duro '+disco+' Seagate Skyhawk', 'HDD-'+disco, disco==='1TB'?45000:disco==='2TB'?75000:130000, 1));
  if (r.acceso_remoto==='si') lista.push(prod('Switch PoE para cámaras 8 puertos', 'SW-POE8', 55000, 1));
  return lista;
}

function calcularProductosVideoportero(r) {
  var lista = [];
  var monit = r.cant_monitor || 1;
  var panel = r.cant_panel  || 1;
  lista.push(prod('Panel exterior Hikvision DS-KD8003-IME1', 'DS-KD8003', 145000, panel));
  lista.push(prod('Monitor interior Hikvision DS-KH6320-WTE1', 'DS-KH6320', 95000, monit));
  if (r.apertura==='si') lista.push(prod('Chapa eléctrica 12V', 'CHAPA-12V', 28000, panel));
  if (monit > 1 || panel > 1) lista.push(prod('Switch Hikvision PoE 4 puertos', 'SW-POE4', 35000, 1));
  lista.push(prod('Fuente switching 2A', 'FTE-2A', 12000, 1));
  return lista;
}

function calcularProductosAcceso(r) {
  var lista = [];
  var lectores = r.cant_lectores || 1;
  var tipo = r.tipo_acceso;
  if (tipo==='tarjeta')   lista.push(prod('Lector RFID Hikvision DS-K1T804MF', 'DS-K1T804MF', 65000, lectores));
  else if (tipo==='huella') lista.push(prod('Lector huella Hikvision DS-K1T805MF', 'DS-K1T805MF', 95000, lectores));
  else if (tipo==='facial') lista.push(prod('Terminal facial Hikvision DS-K1T341BMF', 'DS-K1T341', 280000, lectores));
  else lista.push(prod('Terminal multi Hikvision DS-K1T805BMF', 'DS-K1T805BMF', 120000, lectores));
  // Controlador
  lista.push(prod('Controlador de acceso Hikvision DS-K2602G', 'DS-K2602G', 135000, Math.ceil(lectores/2)));
  lista.push(prod('Chapa eléctrica 12V', 'CHAPA-12V', 28000, lectores));
  lista.push(prod('Botón de salida', 'BOTON-SAL', 5500, lectores));
  lista.push(prod('Fuente switching 3A', 'FTE-3A', 18000, Math.ceil(lectores/2)));
  // Tarjetas o llaveros
  var usuarios = r.cant_usuarios==='hasta50'?30:r.cant_usuarios==='hasta200'?100:200;
  if (tipo==='tarjeta'||tipo==='combinado') lista.push(prod('Tarjetas RFID Mifare (pack x10)', 'RFID-10', 8500, Math.ceil(usuarios/10)));
  return lista;
}

function calcularProductosDomotica(r) {
  var lista = [];
  var ctrl  = r.tipo_control || ['luces'];
  var puntos = parseInt(r.cant_puntos)||6;
  var con   = r.conexion;

  // Módulos según tipo de control
  if (ctrl.includes('luces')) {
    // Sonoff MINI R2 (1 canal) o MINI DIM (regulable)
    var cantLuces = Math.ceil(puntos * 0.5);
    lista.push(prod('Sonoff MINI R2 relay inteligente', 'MINI-R2', 18500, cantLuces));
  }
  if (ctrl.includes('persianas')) {
    var cantPers = Math.max(1, Math.floor(puntos * 0.2));
    lista.push(prod('Sonoff DUAL R3 control persianas', 'DUAL-R3', 28000, cantPers));
  }
  if (ctrl.includes('enchufes')) {
    var cantEnch = Math.ceil(puntos * 0.3);
    lista.push(prod('Sonoff S26R2 enchufe inteligente', 'S26R2', 12500, cantEnch));
  }
  if (ctrl.includes('clima')) {
    lista.push(prod('Sonoff IRHVAC control AC por IR', 'IRHVAC', 22000, 1));
  }
  if (ctrl.includes('puertas')) {
    lista.push(prod('Sonoff SV 5-24V control puerta', 'SV', 14500, 1));
  }
  if (ctrl.includes('sensores')) {
    lista.push(prod('Sonoff SNZB-02 sensor temp/humedad Zigbee', 'SNZB-02', 15000, 2));
    lista.push(prod('Sonoff SNZB-03 sensor movimiento Zigbee', 'SNZB-03', 17500, 1));
  }

  // Hub / Gateway según conexión
  if (con === 'local') {
    lista.push(prod('Sonoff iHost Smart Home Hub local', 'IHOST', 95000, 1));
  } else if (ctrl.includes('sensores') || puntos > 8) {
    // Zigbee Bridge para sensores o muchos dispositivos
    lista.push(prod('Sonoff Zigbee Bridge Pro', 'ZBBRIDGE-P', 38000, 1));
  }

  // Alexa / Google si elige voz
  if (con === 'voz') {
    lista.push(prod('Amazon Echo Dot (4ta gen) Alexa', 'ECHO-DOT4', 45000, 1));
  }

  return lista;
}

function calcularProductosRedes(r) {
  var lista = [];
  var cantAP = r.superficie==='hasta150'?1:r.superficie==='hasta300'?2:r.superficie==='hasta600'?4:6;
  lista.push(prod('Access Point Omada EAP670 WiFi 6', 'EAP670', 95000, cantAP));
  if (r.gestion==='si') {
    lista.push(prod('Controller Omada OC200', 'OC200', 85000, 1));
    lista.push(prod('Router Omada ER605', 'ER605', 110000, 1));
  }
  if (cantAP > 1) lista.push(prod('Switch PoE Omada TL-SG2210P 8 puertos', 'TL-SG2210P', 78000, Math.ceil(cantAP/8)));
  return lista;
}
// MÓDULO VACACIONES

function diasVacPorAntiguedad(fechaIngreso) {
  if (!fechaIngreso) return 14;
  var anios = (new Date()-new Date(fechaIngreso))/(365.25*86400000);
  if (anios<5)  return 14;
  if (anios<10) return 21;
  if (anios<20) return 28;
  return 35;
}

function fbCargarVacaciones() {
  if (!window.fbDB) return;
  _suscribirModuloUnaVez('vacaciones', 'sisventas/vacaciones', function(snap){
    var data = snap.val()||{};
    var periodos = Object.entries(data).map(function(e){ return Object.assign({fbKey:e[0]},e[1]); });
    window._vacPeriodos = periodos; // caché en memoria
    renderAvisoProximasVacaciones();
    if (document.getElementById('page-vacaciones') && document.getElementById('page-vacaciones').classList.contains('active')) {
      renderTablaVacaciones(periodos);
      renderPeriodosVacaciones(periodos);
    }
  });
}

function renderModuloVacaciones() {
  var periodos = window._vacPeriodos || [];
  if (!periodos.length && window.fbDB) {
    window.fbGet(window.fbRef(window.fbDB,'sisventas/vacaciones')).then(function(snap){
      var data = snap.val()||{};
      periodos = Object.entries(data).map(function(e){ return Object.assign({fbKey:e[0]},e[1]); });
      window._vacPeriodos = periodos;
      renderTablaVacaciones(periodos);
      renderPeriodosVacaciones(periodos);
    }).catch(function(e){ console.error('[VAC] fbGet ERROR:', e); });
  } else {
    renderTablaVacaciones(periodos);
    renderPeriodosVacaciones(periodos);
  }
}

function renderTablaVacaciones(periodos) {
  var tbody = document.getElementById('vac-tbody'); if (!tbody) return;
  var empleados = Object.values(empData||{}).filter(function(e){ return e.activo!==false && e.tipoEmpleado !== 'Vendedor a comisión'; });
  if (window._empleadosCargaError) {
    tbody.innerHTML = '<tr><td colspan="8" style="text-align:center;color:var(--red);padding:24px">'+escapeHTML(window._empleadosCargaError)+'</td></tr>';
    return;
  }
  if (!window._empleadosDatosListos) {
    tbody.innerHTML = '<tr><td colspan="8" style="text-align:center;color:var(--text3);padding:24px">Cargando empleados...</td></tr>';
    return;
  }
  if (!empleados.length) {
    tbody.innerHTML = '<tr><td colspan="8" style="text-align:center;color:var(--text3);padding:24px">Sin empleados activos</td></tr>';
    var _vacSet = function(id,valor){ var el=document.getElementById(id); if(el) el.textContent=valor; };
    _vacSet('vac-total',0);
    _vacSet('vac-pendientes',0);
    _vacSet('vac-activas',0);
    return;
  }
  var hoy = svFechaLocalISO();
  var enLicencia=0, conPendientes=0, nombresPendientes=[];
  tbody.innerHTML = empleados.map(function(emp){
    var ingreso = emp.fechaIngreso || (emp.historial ? Object.values(emp.historial).sort(function(a,b){return (a.fecha||'').localeCompare(b.fecha||'');})[0] ? Object.values(emp.historial).sort(function(a,b){return a.fecha.localeCompare(b.fecha);})[0].fecha : null : null);
    var diasCorr = diasVacPorAntiguedad(ingreso);
    var anio = new Date().getFullYear();
    var periEmp = periodos.filter(function(p){ return p.empleadoId===emp.fbKey && String(p.desde||'').slice(0,4)===String(anio); });
    var tomados = periEmp.reduce(function(s,p){ return s+(parseInt(p.dias)||0); },0);
    var disp    = diasCorr-tomados;
    var activo  = periEmp.some(function(p){ return p.desde<=hoy&&p.hasta>=hoy; });
    if (activo) enLicencia++;
    if (disp>0) { conPendientes++; nombresPendientes.push(emp.nombre||'Empleado'); }
    var anios    = ingreso ? Math.floor((new Date()-new Date(ingreso))/(365.25*86400000)) : null;
    var antiguedad = anios===null?'—':anios<1?'< 1 año':anios+' año'+(anios!==1?'s':'');
    return '<tr>'+
      '<td style="font-family:monospace;color:var(--text3)">'+String(emp.legajo||'—').padStart(4,'0')+'</td>'+
      '<td style="font-weight:500">'+escapeHTML(emp.nombre||'—')+'</td>'+
      '<td style="font-size:12px;color:var(--text3)">'+antiguedad+'</td>'+
      '<td class="tr" style="font-weight:500">'+diasCorr+' d.</td>'+
      '<td class="tr" style="color:var(--text3)">'+tomados+' d.</td>'+
      '<td class="tr"><span style="font-weight:700;color:'+(disp>0?'var(--green)':disp===0?'var(--text3)':'var(--red)')+'">'+disp+' d.</span></td>'+
      '<td style="font-size:12px">'+(activo?'<span class="badge b-blue">En licencia</span>':periEmp.length?escapeHTML(_mostrarFecha(periEmp[periEmp.length-1].desde)):'—')+'</td>'+
      '<td><button class="btn btn-sm btn-icon" onclick="abrirModalVacaciones(\''+emp.fbKey+'\')" title="Registrar"><i class="ti ti-plus" style="font-size:14px"></i></button></td>'+
    '</tr>';
  }).join('');
  var _e=function(id,v){var el=document.getElementById(id);if(el)el.textContent=v;};
  _e('vac-total',empleados.length);_e('vac-pendientes',conPendientes);_e('vac-activas',enLicencia);
  var pendientesEl=document.getElementById('vac-pendientes');
  if (pendientesEl) {
    var metric=pendientesEl.closest('.metric');
    var sub=metric?metric.querySelector('.m-sub'):null;
    if (sub) sub.textContent=conPendientes ? 'empleado'+(conPendientes===1?'':'s')+' con días disponibles' : 'sin saldos pendientes';
    if (metric) metric.title=nombresPendientes.length ? 'Con días disponibles: '+nombresPendientes.join(', ') : 'Ningún empleado tiene días disponibles';
  }
}

function renderPeriodosVacaciones(periodos) {
  var tbody = document.getElementById('vac-periodos-tbody'); if (!tbody) return;
  var hoy = svFechaLocalISO();
  if (!periodos.length) { tbody.innerHTML='<tr><td colspan="6" style="text-align:center;color:var(--text3);padding:24px">Sin períodos registrados</td></tr>'; return; }
  tbody.innerHTML = periodos.sort(function(a,b){ return (b.desde||'').localeCompare(a.desde||''); }).map(function(p){
    var badge = p.hasta<hoy?'<span class="badge b-green">Finalizado</span>':p.desde<=hoy?'<span class="badge b-blue">En curso</span>':'<span class="badge b-amber">Programado</span>';
    var acciones = currentRole==='admin'
      ? '<button class="btn btn-sm btn-icon" onclick="abrirModalEditarVacaciones(\''+p.fbKey+'\')" title="Editar período"><i class="ti ti-edit" style="font-size:13px"></i></button>'+
        '<button class="btn btn-sm btn-icon" onclick="eliminarRegistro(\'vacaciones\',\''+p.fbKey+'\')" title="Eliminar período" style="color:var(--text3)" onmouseenter="this.style.color=\'var(--red)\'" onmouseleave="this.style.color=\'var(--text3)\'"><i class="ti ti-trash" style="font-size:13px"></i></button>'
      : '';
    return '<tr>'+
      '<td style="font-weight:500">'+escapeHTML(p.empleadoNombre||'—')+'</td>'+
      '<td>'+escapeHTML(_mostrarFecha(p.desde))+'</td>'+
      '<td>'+escapeHTML(_mostrarFecha(p.hasta))+'</td>'+
      '<td class="tr" style="font-weight:500">'+p.dias+' d.</td>'+
      '<td class="tr">'+badge+'</td>'+
      '<td style="white-space:nowrap">'+acciones+'</td>'+
    '</tr>';
  }).join('');
}

function abrirModalVacaciones(empFbKey) {
  window._modalVacPeriodoKey = null;
  window._modalVacEmpKey = empFbKey;
  var emp = empFbKey ? Object.values(empData||{}).find(function(e){ return e.fbKey===empFbKey; }) : null;
  var modal=document.getElementById('modal-nuevo'), modalTitle=document.getElementById('modal-nuevo-title'), modalBody=document.getElementById('modal-nuevo-body');
  if (!modal) return;
  modalTitle.textContent = emp?'Vacaciones — '+emp.nombre:'Registrar período';
  var selEmp = !empFbKey ? '<div class="fg full"><label>Empleado</label><select id="vac-emp-sel" style="width:100%"><option value="">— Seleccionar —</option>'+Object.values(empData||{}).filter(function(e){return e.activo!==false;}).map(function(e){return '<option value="'+e.fbKey+'">'+escapeHTML(e.nombre)+'</option>';}).join('')+'</select></div>' : '';
  modalBody.innerHTML = '<div class="form-grid">'+selEmp+
    '<div class="fg"><label>Desde</label><input type="date" id="vac-desde" style="width:100%" oninput="calcDiasVac()"></div>'+
    '<div class="fg"><label>Hasta</label><input type="date" id="vac-hasta" style="width:100%" oninput="calcDiasVac()"></div>'+
    '<div class="fg full"><label>Días</label><input type="number" id="vac-dias" style="width:100%"></div>'+
    '<div class="fg full"><label>Observaciones</label><input type="text" id="vac-obs" placeholder="Opcional" style="width:100%"></div>'+
  '</div>'+
  '<div style="display:flex;justify-content:flex-end;gap:8px;margin-top:16px">'+
    '<button class="btn" onclick="document.getElementById(\'modal-nuevo\').classList.remove(\'open\')">Cancelar</button>'+
    '<button class="btn btn-primary" onclick="guardarPeriodoVac()"><i class="ti ti-check"></i> Guardar período</button>'+
  '</div>';
  // texto/onclick, así no queda "pegado" para la próxima vez que se use el modal)
  var botonesFooter = modal.querySelectorAll('.modal > .flex-end button');
  botonesFooter.forEach(function(b){ b.style.display = 'none'; });
  modal.classList.add('open');
}

function abrirModalEditarVacaciones(periodoKey) {
  if (currentRole!=='admin') { notify('Solo el administrador puede editar vacaciones'); return; }
  var p=(window._vacPeriodos||[]).find(function(x){return x.fbKey===periodoKey;});
  if (!p) { notify('No se encontró el período'); return; }
  abrirModalVacaciones(p.empleadoId);
  window._modalVacPeriodoKey=periodoKey;
  var titulo=document.getElementById('modal-nuevo-title');
  if(titulo) titulo.textContent='Editar vacaciones — '+(p.empleadoNombre||'Empleado');
  var desde=document.getElementById('vac-desde'), hasta=document.getElementById('vac-hasta'), dias=document.getElementById('vac-dias'), obs=document.getElementById('vac-obs');
  if(desde) desde.value=p.desde||'';
  if(hasta) hasta.value=p.hasta||'';
  if(dias) dias.value=p.dias||'';
  if(obs) obs.value=p.obs||'';
  var guardar=document.querySelector('#modal-nuevo-body button.btn-primary');
  if(guardar) guardar.innerHTML='<i class="ti ti-check"></i> Guardar cambios';
}

function calcDiasVac() {
  var d1=document.getElementById('vac-desde'), d2=document.getElementById('vac-hasta');
  if (d1&&d2&&d1.value&&d2.value) { var el=document.getElementById('vac-dias'); if(el) el.value=Math.max(0,Math.round((new Date(d2.value)-new Date(d1.value))/86400000)+1); }
}

function guardarPeriodoVac() {
  var fkey = window._modalVacEmpKey || (document.getElementById('vac-emp-sel')?document.getElementById('vac-emp-sel').value:'');
  var desde=document.getElementById('vac-desde').value, hasta=document.getElementById('vac-hasta').value;
  var dias=parseInt(document.getElementById('vac-dias').value)||0;
  if (!fkey||!desde||!hasta) { notify('Completá los datos'); return; }
  var emp=Object.values(empData||{}).find(function(e){return e.fbKey===fkey;});
  if (hasta<desde || dias<=0) { notify('Revisá las fechas y la cantidad de días'); return; }
  var payload={
    empleadoId:fkey, empleadoNombre:emp?emp.nombre:'', desde:desde, hasta:hasta, dias:dias,
    obs:document.getElementById('vac-obs').value, ts:Date.now()
  };
  var periodoKey=window._modalVacPeriodoKey;
  var operacion=periodoKey
    ? window.fbUpdate(window.fbRef(window.fbDB,'sisventas/vacaciones/'+periodoKey),payload)
    : window.fbPush(window.fbRef(window.fbDB,'sisventas/vacaciones'),payload);
  operacion.then(function(){
    notify(periodoKey?'✓ Período actualizado':'✓ Período registrado');
    window._modalVacPeriodoKey=null;
    cerrarModalNuevoGenerico();
    renderModuloVacaciones();
  });
}

function _normalizarNombreVacaciones(valor) {
  return String(valor||'').toLowerCase().trim().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\s+/g,' ');
}

function _empleadoPorNombreVacaciones(nombre) {
  var clave=_normalizarNombreVacaciones(nombre);
  return Object.values(empData||{}).find(function(e){
    return [_normalizarNombreVacaciones(e.nombre),_normalizarNombreVacaciones(e.usuario),_normalizarNombreVacaciones(e.email)].indexOf(clave)>=0;
  })||null;
}

function periodoVacacionesPara(nombreTecnico, fecha) {
  var emp=_empleadoPorNombreVacaciones(nombreTecnico);
  var clave=_normalizarNombreVacaciones(nombreTecnico);
  return (window._vacPeriodos||[]).find(function(p){
    var mismo=emp ? p.empleadoId===emp.fbKey : _normalizarNombreVacaciones(p.empleadoNombre)===clave;
    var estado=_normalizarNombreVacaciones(p.estado);
    return mismo && estado!=='rechazado' && estado!=='cancelado' && p.desde<=fecha && p.hasta>=fecha;
  })||null;
}

async function cambiarTecnicoOT(select) {
  var anterior = select.dataset.previousValue || '';
  var nuevo = select.value || '';
  var fecha=(document.getElementById('ot-det-fecha')||{}).value || svFechaLocalISO();
  var periodo=nuevo ? periodoVacacionesPara(nuevo,fecha) : null;
  if (periodo) {
    notify('⚠ '+select.value+' está de vacaciones del '+periodo.desde+' al '+periodo.hasta+'. Elegí otro técnico.');
    select.value=anterior;
    return false;
  }
  if (nuevo === anterior) return true;
  var ot = (otData || []).find(function(o){ return o.id === otActualId || o.fbKey === otActualId; });
  if (!ot || !ot.fbKey || typeof fbGuardarOT !== 'function') {
    select.value = anterior;
    notify('No se pudo localizar la OT para transferirla');
    return false;
  }
  var mensaje = anterior
    ? 'Transferir esta OT de ' + anterior + ' a ' + (nuevo || 'Sin asignar') + '? El cambio quedara registrado en el historial.'
    : 'Asignar esta OT a ' + (nuevo || 'Sin asignar') + '? El cambio quedara registrado en el historial.';
  if (!await svConfirm(mensaje)) { select.value = anterior; return false; }
  if (window._otTransferenciaEnCurso) { select.value = anterior; notify('La transferencia de esta OT ya se esta guardando'); return false; }
  window._otTransferenciaEnCurso = true;
  select.disabled = true;
  try {
    var ahora = new Date().toLocaleDateString('es-AR') + ' ' + new Date().toLocaleTimeString('es-AR',{hour:'2-digit',minute:'2-digit'});
    ot.tecnico = nuevo;
    ot.audit = Array.isArray(ot.audit) ? ot.audit : [];
    ot.audit.push({ fecha:ahora, usuario:currentUser || 'Admin', accion:'Titularidad de OT transferida: ' + (anterior || 'Sin asignar') + ' -> ' + (nuevo || 'Sin asignar'), tecnicoAnterior:anterior, tecnicoNuevo:nuevo });
    await fbGuardarOT(ot);
    select.dataset.previousValue = nuevo;
    window._otDetalleHuella = JSON.stringify(ot);
    notify('OT transferida a ' + (nuevo || 'Sin asignar'));
  } catch (e) {
    ot.tecnico = anterior;
    select.value = anterior;
    notify('No se pudo transferir la OT: ' + e.message);
    return false;
  } finally {
    select.disabled = false;
    window._otTransferenciaEnCurso = false;
  }
  return true;
}

function renderAvisoProximasVacaciones() {
  var box=document.getElementById('dash-vacaciones-aviso');
  if(!box) return;
  if(currentRole==='admin'){box.style.display='none';return;}
  var emp=_empleadoPorNombreVacaciones(currentUser||'');
  if(!emp){box.style.display='none';return;}
  var hoy=svFechaLocalISO();
  var proximas=(window._vacPeriodos||[]).filter(function(p){
    var estado=_normalizarNombreVacaciones(p.estado);
    return p.empleadoId===emp.fbKey && p.hasta>=hoy && estado!=='rechazado' && estado!=='cancelado';
  }).sort(function(a,b){return (a.desde||'').localeCompare(b.desde||'');});
  if(!proximas.length){box.style.display='none';return;}
  var p=proximas[0], inicio=new Date(p.desde+'T00:00:00'), ahora=new Date(hoy+'T00:00:00');
  var faltan=Math.max(0,Math.ceil((inicio-ahora)/86400000));
  var titulo=document.getElementById('dash-vacaciones-titulo'), detalle=document.getElementById('dash-vacaciones-detalle');
  if(titulo) titulo.textContent=faltan===0?'¡Hoy empiezan tus vacaciones! 🎉':'¡Faltan '+faltan+' día'+(faltan===1?'':'s')+' para tus vacaciones!';
  if(detalle) detalle.textContent='Del '+p.desde+' al '+p.hasta+' · '+(p.dias||'—')+' días para descansar y recargar energías.';
  box.style.display='block';
}

function renderAvisoAumentoValorHora() {
  var box = document.getElementById('dash-aumento-hora-aviso');
  if (!box) return;
  if (currentRole === 'admin') { box.style.display = 'none'; return; }

  var usuActual = (window.usuariosData || []).find(function(u) {
    return (u.mail || '').toLowerCase() === (currentUserEmail || '').toLowerCase();
  });
  var emp = null;
  if (usuActual && usuActual.empleadoFbKey) emp = (empData || {})[usuActual.empleadoFbKey] || null;
  if (!emp) emp = _empleadoPorNombreVacaciones(currentUser || '');
  var cargo = emp && emp.cargoId ? CARGOS_DATA[emp.cargoId] : null;
  var ajuste = _cargoUltimoAjuste(cargo);
  var porcentaje = ajuste && ajuste.porcentaje != null ? parseFloat(ajuste.porcentaje) : 0;
  var ts = ajuste ? (parseInt(ajuste.ts, 10) || (ajuste.fecha ? new Date(ajuste.fecha + 'T12:00:00').getTime() : 0)) : 0;
  var diasDesdeCambio = ts ? Math.floor((Date.now() - ts) / 86400000) : 9999;
  if (!ajuste || ajuste.tipo !== 'aumento' || !(porcentaje > 0) || diasDesdeCambio < 0 || diasDesdeCambio > 30) {
    box.style.display = 'none';
    return;
  }

  var titulo = document.getElementById('dash-aumento-hora-titulo');
  var detalle = document.getElementById('dash-aumento-hora-detalle');
  if (titulo) titulo.textContent = '¡Tu valor hora aumentó ' + porcentaje.toLocaleString('es-AR',{maximumFractionDigits:2}) + '%! 🎉';
  if (detalle) detalle.textContent = 'Desde el ' + _cargoFechaAjusteLocal(ajuste) + ', tu valor hora es $' + Math.round(parseFloat(ajuste.nuevo)||0).toLocaleString('es-AR') + '. Se aplicará a tus próximos haberes.';
  box.style.display = 'block';
}

function toggleActivoCliente(cid) {
  var cli = (clientesData||[]).find(function(c){ return String(c.id) === String(cid) || String(c.fbKey||'') === String(cid); });
  if (!cli || !cli.fbKey || !window.fbDB) return;
  var nuevoEstado = cli.activo === false;
  window.fbUpdate(window.fbRef(window.fbDB, FB_PATHS.clientes + '/' + cli.fbKey), { activo: nuevoEstado })
    .then(function(){ notify(nuevoEstado ? 'Cliente activado' : 'Cliente dado de baja'); });
}

function abrirModalEstadoEmpleado(fbKey, estadoActual) {
  var emp = Object.values(empData||{}).find(function(e){ return e.fbKey===fbKey; });
  if (!emp) return;
  var estaActivo = estadoActual;
  var titulo = estaActivo ? 'Dar de baja: '+escapeHTML(emp.nombre) : 'Reactivar: '+escapeHTML(emp.nombre);
  var motivos = estaActivo
    ? ['Renuncia','Despido','Licencia','Suspensión','Jubilación','Fin de contrato','Otro']
    : ['Reingreso','Fin de licencia','Recontratación','Otro'];

  var html = '<div style="display:flex;flex-direction:column;gap:14px">' +
    '<div class="fg"><label>Motivo</label><select id="emp-estado-motivo" style="width:100%">' +
    motivos.map(function(m){ return '<option>'+m+'</option>'; }).join('') +
    '</select></div>' +
    '<div class="fg"><label>Fecha</label><input type="date" id="emp-estado-fecha" value="'+svFechaLocalISO()+'" style="width:100%"></div>' +
    '<div class="fg"><label>Observaciones (opcional)</label><textarea id="emp-estado-obs" rows="2" style="width:100%;resize:vertical;font-family:inherit;font-size:13px;padding:8px;border:0.5px solid var(--border2);border-radius:var(--radius);background:var(--bg3);color:var(--text);box-sizing:border-box"></textarea></div>' +
    '<div style="display:flex;justify-content:flex-end;gap:8px;margin-top:4px">' +
      '<button class="btn btn-primary" onclick="confirmarEstadoEmpleado(\''+fbKey+'\',' + (!estaActivo) + ',document.getElementById(\'emp-estado-motivo\').value,document.getElementById(\'emp-estado-fecha\').value,document.getElementById(\'emp-estado-obs\').value);document.getElementById(\'modal-nuevo\').classList.remove(\'open\')">' + (estaActivo ? 'Confirmar baja' : 'Confirmar alta') + '</button>' +
    '</div>' +
  '</div>';

  // Usar modal genérico de confirmación
  var modal = document.getElementById('modal-nuevo');
  var modalTitle = document.getElementById('modal-nuevo-title');
  var modalBody  = document.getElementById('modal-nuevo-body');
  if (!modal || !modalTitle || !modalBody) return;
  modalTitle.textContent = titulo;
  modalBody.innerHTML = html;
  // (nunca se muta su texto/onclick, así no queda "pegado" para la próxima vez que se use el modal)
  var botonesFooter = modal.querySelectorAll('.modal > .flex-end button');
  botonesFooter.forEach(function(b){ b.style.display = 'none'; });
  modal.classList.add('open');
}

function confirmarEstadoEmpleado(fbKey, nuevoEstado, motivo, fecha, obs) {
  if (!window.fbDB) return;
  var emp = Object.values(empData||{}).find(function(e){ return e.fbKey===fbKey; });
  if (!emp) return;
  var entrada = {
    tipo:   nuevoEstado ? 'alta' : 'baja',
    motivo: motivo,
    fecha:  fecha,
    obs:    obs || '',
    usuario: currentUser || ''
  };
  var historial = emp.historial ? Object.values(emp.historial) : [];
  historial.push(entrada);
  window.fbUpdate(window.fbRef(window.fbDB, 'sisventas/empleados/'+fbKey), {
    activo:    nuevoEstado,
    historial: historial
  }).then(function(){
    notify(nuevoEstado ? '✓ '+emp.nombre+' reactivado' : '✓ '+emp.nombre+' dado de baja ('+motivo+')');
  });
}

function abrirLegajoEmpleado(fbKey) {
  var emp = Object.values(empData||{}).find(function(e){ return e.fbKey===fbKey; });
  if (!emp) return;
  var historial = emp.historial ? Object.values(emp.historial).sort(function(a,b){ return (a.fecha||'').localeCompare(b.fecha||''); }) : [];
  var tipoIcon = { alta:'🟢', baja:'🔴', licencia:'🟡' };
  var htmlHist = historial.length
    ? historial.map(function(h){
        return '<div style="display:flex;align-items:flex-start;gap:12px;padding:10px 0;border-bottom:0.5px solid var(--border)">' +
          '<span style="font-size:16px">'+(tipoIcon[h.tipo]||'📋')+'</span>' +
          '<div><div style="font-size:13px;font-weight:500;text-transform:capitalize">'+escapeHTML(h.tipo)+'</div>' +
          '<div style="font-size:12px;color:var(--text3)">'+escapeHTML(h.fecha||'—')+' · '+escapeHTML(h.motivo||'—')+'</div>' +
          (h.obs?'<div style="font-size:12px;color:var(--text3);margin-top:2px">'+escapeHTML(h.obs)+'</div>':'') +
          '<div style="font-size:11px;color:var(--text3);margin-top:2px">Registrado por: '+escapeHTML(h.usuario||'Sistema')+'</div>' +
          '</div></div>';
      }).join('')
    : '<div style="padding:16px;text-align:center;color:var(--text3);font-size:13px">Sin movimientos registrados</div>';

  var estadoColor = emp.activo !== false ? 'var(--green)' : 'var(--red)';
  var estadoTxt   = emp.activo !== false ? 'Activo' : 'Inactivo';
  var cargoInfo = emp.cargoId ? CARGOS_DATA[emp.cargoId] : null;
  var mensualCargo = cargoInfo ? Math.round((parseFloat(cargoInfo.valorHora)||0)*8*(parseFloat(cargoInfo.diasMes)||0)) : 0;
  var horaExtraCargo = cargoInfo ? Math.round(parseFloat(cargoInfo.valorHoraExtra)||0) : 0;
  var modal = document.getElementById('modal-nuevo');
  var modalTitle = document.getElementById('modal-nuevo-title');
  var modalBody  = document.getElementById('modal-nuevo-body');
  if (!modal) return;
  modalTitle.textContent = 'Legajo N° ' + String(emp.legajo||'—').padStart(4,'0') + ' — ' + emp.nombre;
  modalBody.innerHTML =
    '<div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:16px">' +
      '<div style="background:var(--bg3);border-radius:var(--radius);padding:12px"><div style="font-size:10px;color:var(--text3);text-transform:uppercase;letter-spacing:.5px">DNI</div><div style="font-size:14px;font-weight:500;margin-top:2px">'+escapeHTML(emp.dni||'—')+'</div></div>' +
      '<div style="background:var(--bg3);border-radius:var(--radius);padding:12px"><div style="font-size:10px;color:var(--text3);text-transform:uppercase;letter-spacing:.5px">Cargo</div><div style="font-size:14px;font-weight:500;margin-top:2px">'+escapeHTML(emp.cargo||'Sin cargo asignado')+'</div></div>' +
      '<div style="background:var(--bg3);border-radius:var(--radius);padding:12px"><div style="font-size:10px;color:var(--text3);text-transform:uppercase;letter-spacing:.5px">Teléfono</div><div style="font-size:14px;font-weight:500;margin-top:2px">'+escapeHTML(emp.telefono||emp.tel||'—')+'</div></div>' +
      '<div style="background:var(--bg3);border-radius:var(--radius);padding:12px"><div style="font-size:10px;color:var(--text3);text-transform:uppercase;letter-spacing:.5px">Estado</div><div style="font-size:14px;font-weight:600;margin-top:2px;color:'+estadoColor+'">'+estadoTxt+'</div></div>' +
      '<div style="background:var(--bg3);border-radius:var(--radius);padding:12px"><div style="font-size:10px;color:var(--text3);text-transform:uppercase;letter-spacing:.5px">Fecha de inicio</div><div style="font-size:14px;font-weight:500;margin-top:2px">'+escapeHTML(emp.fechaIngreso||'—')+'</div></div>' +
      '<div style="background:var(--bg3);border-radius:var(--radius);padding:12px"><div style="font-size:10px;color:var(--text3);text-transform:uppercase;letter-spacing:.5px">Mensual (según cargo)</div><div style="font-size:14px;font-weight:500;margin-top:2px">'+(cargoInfo?'$'+mensualCargo.toLocaleString('es-AR'):'—')+'</div></div>' +
      '<div style="background:var(--bg3);border-radius:var(--radius);padding:12px"><div style="font-size:10px;color:var(--text3);text-transform:uppercase;letter-spacing:.5px">Valor hora extra</div><div style="font-size:14px;font-weight:500;margin-top:2px">'+(cargoInfo?'$'+horaExtraCargo.toLocaleString('es-AR'):'—')+'</div></div>' +
    '</div>' +
    '<div style="font-size:12px;color:var(--text3);text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px">Historial de altas y bajas</div>' +
    htmlHist +
    '<div style="margin-top:16px;display:flex;gap:8px">' +
      '<button class="btn btn-sm btn-primary" onclick="editarEmpleado(\''+fbKey+'\')"><i class="ti ti-edit"></i> Editar datos</button>' +
      (currentRole === 'admin' ? '<button class="btn btn-sm" onclick="abrirAdelantoEmpleadoDesdeEmpleados(\''+fbKey+'\')" style="color:var(--amber);border-color:var(--amber)"><i class="ti ti-cash"></i> Cargar adelanto</button>' : '') +
      (currentRole === 'admin' ? '<button class="btn btn-sm" onclick="abrirCuentaEmpleadoDesdeEmpleados(\''+fbKey+'\')" style="color:var(--green);border-color:var(--green)"><i class="ti ti-wallet"></i> Cuenta y movimientos</button>' : '') +
      '<button class="btn btn-sm" onclick="abrirModalEstadoEmpleado(\''+fbKey+'\','+(emp.activo!==false)+');"><i class="ti ti-refresh"></i> Cambiar estado</button>' +
    '</div>';
  // Ocultar botón guardar genérico
  var btnGuardar = modal.querySelector('.btn-primary[onclick*="guardarNuevo"]');
  if (btnGuardar) btnGuardar.style.display = 'none';
  modal.classList.add('open');
}

function editarEmpleado(fbKey) {
  if (!window.fbDB) return;
  window.fbOnValue(window.fbRef(window.fbDB, 'sisventas/empleados/' + fbKey), function(snap) {
    var e = snap.val();
    if (!e) { notify('Empleado no encontrado'); return; }
    var partes = (e.nombre||'').split(' ');
    var datos = {
      ap:     partes.slice(1).join(' ') || '',
      nm:     partes[0] || '',
      dni:    e.dni || '',
      cargoId: e.cargoId || '',
      'fecha-ingreso': e.fechaIngreso || '',
      tipo:   e.tipoEmpleado || 'Empleado',
      'pct-comision': e.pctComisionPropio || '',
      tel:    e.telefono || '',
      em:     e.mail || '',
      activo: e.activo !== false ? 'Activo' : 'Inactivo'
    };
    abrirModalNuevo('empleado', datos, fbKey);
  }, { onlyOnce: true });
}



function _normalizarRolUsuarioSistema(rol) {
  var r = String(rol || '').toLowerCase();
  if (r === 'admin' || r === 'administrador') return 'admin';
  if (r === 'tecnico_vendedor' || r === 'tecnico-vendedor' || r === 'técnico-vendedor') return 'tecnico_vendedor';
  if (r === 'tecnico' || r === 'técnico') return 'tecnico';
  if (r === 'vendedor') return 'vendedor';
  return 'administrativo';
}

function _emailUsuarioSistema(u) {
  return (u && (u.mail || (u.login && String(u.login).includes('@') ? u.login : (u.login || '') + '@sistemanixa.com'))) || '';
}

function _actualizarCabeceraSesion() {
  var rolLabels = { admin:'Administrador', administrativo:'Administrativo', vendedor:'Vendedor', tecnico_vendedor:'Técnico-vendedor', tecnico:'Técnico' };
  var sname = document.getElementById('s-uname-el');
  if (sname) sname.textContent = currentUser || '—';
  var srole = document.getElementById('s-urole-el');
  if (srole) srole.textContent = rolLabels[currentRole] || currentRole || '—';
  var av = document.getElementById('s-avatar-el');
  if (av) {
    var nombre = currentUser || '';
    var partes = nombre.split(' ').filter(Boolean);
    av.textContent = partes.length >= 2 ? (partes[0][0] + (partes[1][0] || '')).toUpperCase() : (nombre || 'US').slice(0,2).toUpperCase();
  }
}

function _mostrarBannerImpersonacion() {
  var viejo = document.getElementById('impersonacion-banner');
  if (viejo) viejo.remove();
  if (!window._impersonacionOriginal) return;
  var rolLabels = { admin:'Administrador', administrativo:'Administrativo', vendedor:'Vendedor', tecnico_vendedor:'Técnico-vendedor', tecnico:'Técnico' };
  var div = document.createElement('div');
  div.id = 'impersonacion-banner';
  div.style.cssText = 'position:fixed;left:0;right:0;top:0;z-index:12000;background:var(--amber-bg);color:var(--amber);border-bottom:0.5px solid var(--amber);padding:8px 14px;font-size:13px;display:flex;align-items:center;justify-content:space-between;gap:10px;box-shadow:0 2px 10px rgba(0,0,0,.12)';
  div.innerHTML = '<span><i class="ti ti-user-search" style="margin-right:6px"></i>Viendo como <strong>' + escapeHTML(currentUser || 'usuario') + '</strong> · ' + escapeHTML(rolLabels[currentRole] || currentRole || '') + '</span>' +
    '<button class="btn btn-sm" onclick="finalizarImpersonacionUsuario()" style="background:var(--text);color:var(--bg2);border-color:var(--text)"><i class="ti ti-arrow-back-up"></i> Volver a Admin</button>';
  document.body.appendChild(div);
}

function iniciarImpersonacionUsuario(fbKey) {
  if (currentRole !== 'admin' && !window._impersonacionOriginal) { notify('Solo administrador'); return; }
  var u = (window.usuariosData || []).find(function(x){ return x.fbKey === fbKey; });
  if (!u) { notify('Usuario no encontrado'); return; }
  var nuevoRol = _normalizarRolUsuarioSistema(u.rol);
  if (nuevoRol === 'admin') { notify('Ya estás en vista administrador'); return; }
  if (!window._impersonacionOriginal) {
    window._impersonacionOriginal = {
      user: currentUser,
      role: currentRole,
      email: currentUserEmail,
      uid: currentUserUid
    };
  }
  if (typeof registrarActividad === 'function') registrarActividad('Vista como usuario', (u.nombre || u.login || '') + ' · ' + nuevoRol);
  currentUser = u.nombre || u.login || _emailUsuarioSistema(u).split('@')[0] || 'Usuario';
  currentRole = nuevoRol;
  currentUserEmail = String(_emailUsuarioSistema(u) || '').toLowerCase();
  applyRole();
  _actualizarCabeceraSesion();
  _mostrarBannerImpersonacion();
  if (typeof actualizarPanelUsuario === 'function') actualizarPanelUsuario();
  showPage('dashboard', document.querySelector('[onclick*="dashboard"]'));
  notify('Vista cambiada a ' + currentUser);
}

function finalizarImpersonacionUsuario() {
  var orig = window._impersonacionOriginal;
  if (!orig) return;
  currentUser = orig.user || currentUser;
  currentRole = orig.role || 'admin';
  currentUserEmail = orig.email || currentUserEmail;
  currentUserUid = orig.uid || currentUserUid;
  window._impersonacionOriginal = null;
  var banner = document.getElementById('impersonacion-banner');
  if (banner) banner.remove();
  applyRole();
  _actualizarCabeceraSesion();
  if (typeof actualizarPanelUsuario === 'function') actualizarPanelUsuario();
  var mc=document.getElementById('dash-micuenta-card'); if (mc) mc.style.display='none';
  var adm=document.getElementById('dash-administrativo-card'); if (adm) adm.style.display='none';
  var tec=document.getElementById('dash-tecnico-card'); if (tec) tec.style.display='none';
  if (typeof registrarActividad === 'function') registrarActividad('Fin vista como usuario', '');
  showPage('usuarios', document.querySelector('.nav-item[onclick*="usuarios"]'));
  notify('Volviste a Admin');
}

function obtenerClaveUsuarioAdmin(u) {
  if (!u || currentRole !== 'admin') return '';
  return String(u.claveAdmin || u.passwordAdmin || u.password || u.pass || '').trim();
}

function toggleVerClaveUsuario(id) {
  if (currentRole !== 'admin') { notify('Solo administrador'); return; }
  var el = document.getElementById(id);
  if (!el) return;
  var visible = el.getAttribute('data-visible') === '1';
  var clave = el.getAttribute('data-clave') || '';
  el.textContent = visible ? '••••••••' : clave;
  el.setAttribute('data-visible', visible ? '0' : '1');
}

async function gestionarClaveUsuario(fbKey) {
  if (currentRole !== 'admin') { notify('Solo administrador'); return; }
  var u = (window.usuariosData || []).find(function(x){ return x.fbKey === fbKey; });
  if (!u) { notify('Usuario no encontrado'); return; }
  var actual = obtenerClaveUsuarioAdmin(u);
  var nueva = await svPrompt('Nueva clave registrada para ' + (u.login || u.mail || u.nombre || 'usuario') + ':', actual || '');
  if (nueva === null) return;
  nueva = String(nueva).trim();
  if (nueva.length < 6) { notify('La clave debe tener al menos 6 caracteres'); return; }
  window.fbUpdate(window.fbRef(window.fbDB, 'sisventas/usuarios/' + fbKey), {
    claveAdmin: nueva,
    claveActualizadaTs: Date.now(),
    claveActualizadaPor: currentUser || ''
  }).then(async function(){
    notify('✓ Clave registrada actualizada');
    if (await svConfirm('Clave registrada actualizada. ¿Enviar también email de reseteo de Firebase al usuario?')) {
      resetPasswordUsuario(u.mail || ((u.login||'') + '@sistemanixa.com'));
    }
  }).catch(function(e){ notify('Error: ' + e.message); });
}

function toggleActivoUsuario(fbKey, estadoActual) {
  if (!window.fbDB) return;
  var nuevoEstado = !estadoActual;
  window.fbUpdate(window.fbRef(window.fbDB, 'sisventas/usuarios/' + fbKey), { activo: nuevoEstado })
    .then(function(){ notify(nuevoEstado ? 'Usuario activado' : 'Usuario desactivado'); });
}

async function resetPasswordUsuario(email) {
  if (!email) { notify('Sin email registrado'); return; }
  if (!await svConfirm('¿Enviar email de reseteo de contraseña a ' + email + '?')) return;
  if (!window.fbResetPass || !window.fbAuth) { notify('Sin conexión a Firebase Auth'); return; }
  window.fbResetPass(window.fbAuth, email)
    .then(function() { notify('✓ Email de reseteo enviado a ' + email); })
    .catch(function(e) {
      var msg = e.code === 'auth/user-not-found'
        ? 'Este email no existe en Firebase Auth — el usuario nunca fue creado desde el sistema'
        : 'Error: ' + e.message;
      notify(msg);
    });
}

function editarUsuario(fbKey) {
  if (!window.fbDB) return;
  window.fbOnValue(window.fbRef(window.fbDB, 'sisventas/usuarios/' + fbKey), function(snap) {
    var u = snap.val();
    if (!u) { notify('Usuario no encontrado'); return; }
    var rolInverso = {admin:'Administrador',administrativo:'Administrativo',vendedor:'Vendedor',tecnico_vendedor:'Técnico-vendedor',tecnico:'Técnico'};
    var datos = {
      nm:             u.nombre || '',
      user:           u.login || u.mail || '',
      rol:            rolInverso[u.rol] || 'Administrativo',
      activo:         u.activo !== false ? 'Activo' : 'Inactivo',
      empleadoFbKey:  u.empleadoFbKey || '',
      pass:           u.claveAdmin || u.password || u.pass || ''
    };
    abrirModalNuevo('usuario', datos, fbKey);
  }, { onlyOnce: true });
}
function _eliminarBonificacionGastoVinculada(gasto, gastoFbKey) {
  if (!gasto || !window.fbDB || typeof window.fbUpdate !== 'function') {
    return Promise.reject(new Error('No hay conexión segura para eliminar la bonificación'));
  }
  var empleadoFbKey = String(gasto.empleadoFbKey || gasto.empleadoId || '');
  var movimientoCtaKey = String(gasto.movimientoCtaKey || '');
  if ((!empleadoFbKey || !movimientoCtaKey) && String(gasto.legacyKey || '').indexOf('ctaemp/') === 0) {
    var partesLegacy = String(gasto.legacyKey).split('/');
    empleadoFbKey = empleadoFbKey || String(partesLegacy[1] || '');
    movimientoCtaKey = movimientoCtaKey || String(partesLegacy[2] || '');
  }
  if (!empleadoFbKey || !movimientoCtaKey) {
    return Promise.reject(new Error('La bonificación no tiene un vínculo válido con la cuenta del empleado'));
  }
  var actualizaciones = {};
  actualizaciones['sisventas/gastos/' + gastoFbKey] = null;
  actualizaciones['sisventas/ctaemp/' + empleadoFbKey + '/' + movimientoCtaKey] = null;
  return window.fbUpdate(window.fbRef(window.fbDB), actualizaciones);
}

async function eliminarRegistro(coleccion, fbKey) {
  // No permitir eliminar gastos ya pagados
  var g = null;
  var esBonificacionVinculada = false;
  if (coleccion === 'gastos') {
    g = (gastosData||[]).find(function(x){ return x.fbKey === fbKey; });
    if (g && normalizarEstadoGasto(g) === 'pagado') {
      notify('No se puede eliminar un gasto que ya fue pagado');
      return;
    }
    esBonificacionVinculada = !!(g && (String(g.tipoPagable || '').toLowerCase() === 'bonificacion' || String(g.origen || '').toLowerCase() === 'bonificacion'));
  }
  var nombres = {
    gastos:'este gasto', proveedores:'este proveedor', ordenes:'esta orden',
    informes:'este informe', equipos:'este equipo', usuarios:'este usuario'
  };
  var nombre = nombres[coleccion] || 'este registro';
  var pregunta = esBonificacionVinculada
    ? '¿Eliminar esta bonificación? También se quitará de la cuenta del empleado. Esta acción no se puede deshacer.'
    : '¿Eliminar ' + nombre + '? Esta acción no se puede deshacer.';
  if (!await svConfirm(pregunta)) return;
  if (!window.fbDB) { notify('Sin conexión'); return; }
  var eliminacion = esBonificacionVinculada
    ? _eliminarBonificacionGastoVinculada(g, fbKey)
    : (coleccion === 'proveedores'
      ? proveedorPersistirEliminar(fbKey)
      : window.fbRemove(window.fbRef(window.fbDB, 'sisventas/' + coleccion + '/' + fbKey)));
  eliminacion
    .then(function(){ notify(esBonificacionVinculada ? 'Bonificación eliminada de Gastos y de la cuenta del empleado' : 'Eliminado correctamente'); })
    .catch(function(e){ notify('Error al eliminar: ' + e.message); });
}

async function eliminarCliente(el) {
  var cid = el.dataset.cid;
  var cli = (clientesData||[]).find(function(c){ return String(c.id) === String(cid) || String(c.fbKey||'') === String(cid); });
  if (!cli) return;
  var estructuraCliente = obtenerEstructuraClientePorLegacy(cli);
  if (estructuraCliente) {
    if (currentRole !== 'admin') { notify('Solo el administrador puede dar de baja un domicilio'); return; }
    var etiquetaDomicilio = (_clienteCategoriaSede(cli) || 'Domicilio') + (cli.dir || cli.direccion ? ' · ' + (cli.dir || cli.direccion) : '');
    if (!await svConfirm('¿Dar de baja '+etiquetaDomicilio+'?\n\nSe conservarán ventas, presupuestos, OT, cuenta corriente y credenciales. El domicilio dejará de aparecer en nuevas operaciones.', { titulo:'Dar de baja domicilio', textoAceptar:'Dar de baja' })) return;
    var indiceEstructura = clientesUnificadosIndice[String(cli.fbKey || '')] || {};
    var updatesBaja = {};
    updatesBaja[FB_PATHS.clientes + '/' + cli.fbKey + '/activo'] = false;
    if (indiceEstructura.clienteKey && indiceEstructura.sedeKey) {
      updatesBaja['sisventas/clientes_unificados/' + indiceEstructura.clienteKey + '/sedes/' + indiceEstructura.sedeKey + '/activo'] = false;
      updatesBaja['sisventas/clientes_unificados/' + indiceEstructura.clienteKey + '/actualizadoEn'] = Date.now();
    }
    try {
      await window.fbUpdate(window.fbRef(window.fbDB), updatesBaja);
      notify('Domicilio dado de baja; su historial permanece intacto');
    } catch (errorBaja) { notify('No se pudo dar de baja el domicilio: ' + errorBaja.message); }
    return;
  }
  var sedesVinculadas = (clientesData || []).filter(function(c){
    return String(c.clientePrincipalFbKey || '') === String(cli.fbKey || '');
  });
  if (sedesVinculadas.length) {
    notify('No se puede eliminar el cliente principal mientras tenga '+sedesVinculadas.length+' domicilio'+(sedesVinculadas.length===1?'':'s')+' vinculado'+(sedesVinculadas.length===1?'':'s')+'. Editá esos domicilios y desvinculalos primero.');
    return;
  }

  // para que el usuario sepa exactamente qué se va a borrar.
  var ventasCli = (ventasList||[]).filter(function(v){
    return _svRegistroPerteneceCliente(v, cli, true);
  });
  var pptosCli = (pptoData||[]).filter(function(p){
    return _svRegistroPerteneceCliente(p, cli, true);
  });
  var otSueltasCli = (otData||[]).filter(function(o){
    var deAlgunaVenta = ventasCli.some(function(v){ return _svRegistroPerteneceVenta(o, v); });
    if (deAlgunaVenta) return false; // esa OT ya se borra en cascada con su venta
    return _svRegistroPerteneceCliente(o, cli, true);
  });
  var pagosSueltosCli = (window._pagosListaActual||[]).filter(function(p){
    var deAlgunaVenta = ventasCli.some(function(v){ return _svRegistroPerteneceVenta(p, v); });
    if (deAlgunaVenta) return false; // ya se borra en cascada con la venta
    return _svRegistroPerteneceCliente(p, cli, true);
  });

  var resumen = [];
  if (ventasCli.length)      resumen.push(ventasCli.length + ' venta' + (ventasCli.length!==1?'s':'') + ' (con sus OT y pagos)');
  if (pptosCli.length)       resumen.push(pptosCli.length + ' presupuesto' + (pptosCli.length!==1?'s':''));
  if (otSueltasCli.length)   resumen.push(otSueltasCli.length + ' OT suelta' + (otSueltasCli.length!==1?'s':''));
  if (pagosSueltosCli.length) resumen.push(pagosSueltosCli.length + ' pago' + (pagosSueltosCli.length!==1?'s':'') + ' suelto' + (pagosSueltosCli.length!==1?'s':''));

  var msg = '¿Eliminar cliente "' + (cli.nombre||'') + '"?\n\nEsta acción no se puede deshacer.';
  if (resumen.length) {
    msg += '\n\nTambién se eliminará todo lo asociado:\n• ' + resumen.join('\n• ');
  }
  if (!await svConfirm(msg)) return;
  if (!window.fbDB) { notify('Sin conexión'); return; }
  var ventaFacturada = ventasCli.find(function(v){ return v.factura && v.factura.cae; });
  if (ventaFacturada) {
    notify('No se puede eliminar: el cliente tiene la venta ' + ventaFacturada.id + ' con factura electrónica (CAE) emitida. Anulá esa factura con una nota de crédito en ARCA antes de eliminar el cliente.');
    return;
  }

  var promesas = [];
  // (borra también la OT vinculada y los pagos de esa venta)
  ventasCli.forEach(function(v) {
    if (!v.fbKey) return;
    promesas.push(ventasPagosPersistirEliminarVenta(v.fbKey));
    var otVinculadas = (otData||[]).filter(function(o){ return _svRegistroPerteneceVenta(o, v); });
    otVinculadas.forEach(function(otVinculada) {
      if (otVinculada && otVinculada.fbKey) {
        promesas.push(otPersistirEliminar(otVinculada.fbKey));
      }
    });
    var pagosVenta = (window._pagosListaActual||[]).filter(function(p){ return _svRegistroPerteneceVenta(p, v) && p.fbKey; });
    pagosVenta.forEach(function(p) {
      promesas.push(ventasPagosPersistirEliminarPago(p.fbKey));
    });
  });

  // Presupuestos del cliente
  pptosCli.forEach(function(p) {
    if (p.fbKey) promesas.push(pptoPersistirEliminar(p.fbKey));
  });

  // OT sueltas del cliente (sin venta asociada, ej. service/garantía directo)
  otSueltasCli.forEach(function(o) {
    if (o.fbKey) promesas.push(otPersistirEliminar(o.fbKey));
  });

  // Pagos sueltos del cliente (sin venta asociada)
  pagosSueltosCli.forEach(function(p) {
    if (p.fbKey) promesas.push(ventasPagosPersistirEliminarPago(p.fbKey));
  });

  if (cli.fbKey) promesas.push(window.fbRemove(window.fbRef(window.fbDB, FB_PATHS.clientes + '/' + cli.fbKey)));

  Promise.all(promesas)
    .then(function() {
      notify('✓ Cliente y todo lo asociado eliminado' + (resumen.length ? ' (' + resumen.join(', ') + ')' : ''));
      if (typeof registrarActividad === 'function') {
        registrarActividad('Cliente eliminado en cascada', (cli.nombre||'') + ' — ' + resumen.join(', '));
      }
    })
    .catch(function(e){ notify('Error al eliminar: ' + e.message); });
}

function eliminarClienteDesdeHistorial() {
  if (!clienteActualId) { notify('Cliente no seleccionado'); return; }
  eliminarCliente({ dataset: { cid: clienteActualId } });
}

function eliminarProducto(el) {
  eliminarProductoPorId(el && el.dataset ? el.dataset.pid : '', false);
}

async function eliminarProductoPorId(pid, desdeDetalle) {
  if (typeof window.tienePermiso === 'function' && !window.tienePermiso('productos.eliminar')) {
    notify('Solo el administrador puede eliminar productos');
    return false;
  }
  var prod = prodData ? Object.values(prodData).find(function(p){ return String(p.fbKey) === String(pid); }) : null;
  if (!prod) { notify('Producto no encontrado'); return false; }
  if (!prod.fbKey || !window.fbDB) { notify('No se pudo identificar el producto en Firebase'); return false; }

  var ventasProducto = [];
  try {
    var snapVentas = await window.fbGet(window.fbRef(window.fbDB, FB_PATHS.ventas));
    var ventasGuardadas = snapVentas && snapVentas.val ? snapVentas.val() : null;
    ventasProducto = ventasGuardadas ? Object.values(ventasGuardadas).filter(function(v) {
      var items = v.items || v.detalle || v.productos || [];
      return items.some(function(item){ return productoCoincideItemVenta(prod, item); });
    }) : [];
  } catch (e) {
    notify('No se pudo comprobar el historial de ventas. Intentá nuevamente.');
    return false;
  }

  var nombre = prod.nombre || prod.descripcion || prod.codigo || 'este producto';
  var primeraAdvertencia = ventasProducto.length
    ? 'ADVERTENCIA 1 de 2\n\nEl producto "' + nombre + '" aparece en ' + ventasProducto.length + ' venta' + (ventasProducto.length === 1 ? '' : 's') + '.\n\nAl eliminarlo, las ventas históricas conservarán el nombre, precio y cantidades registrados. El producto desaparecerá del catálogo y ya no podrá seleccionarse en operaciones nuevas.\n\n¿Querés continuar?'
    : 'ADVERTENCIA 1 de 2\n\nEl producto "' + nombre + '" no aparece en ninguna venta registrada.\n\nAl eliminarlo desaparecerá del catálogo y ya no podrá seleccionarse en operaciones nuevas.\n\n¿Querés continuar?';
  if (!await svConfirm(primeraAdvertencia)) return false;
  if (!await svConfirm('ADVERTENCIA 2 de 2\n\n¿Estás seguro de eliminar definitivamente "' + nombre + '"?\n\nEsta acción no se puede deshacer.')) return false;

  try {
    await window.fbRemove(window.fbRef(window.fbDB, FB_PATHS.productos + '/' + prod.fbKey));
    // Firebase confirma primero el borrado, pero el listener remoto puede tardar
    // unos instantes. Depuramos la copia local para que ninguna grilla conserve
    // visualmente un producto que ya no existe.
    if (Array.isArray(prodData)) {
      for (var indiceProd = prodData.length - 1; indiceProd >= 0; indiceProd--) {
        if (String((prodData[indiceProd] || {}).fbKey || '') === String(prod.fbKey)) prodData.splice(indiceProd, 1);
      }
    } else if (prodData && typeof prodData === 'object') {
      Object.keys(prodData).forEach(function(claveProd) {
        var itemProd = prodData[claveProd];
        if (claveProd === String(prod.fbKey) || String((itemProd || {}).fbKey || '') === String(prod.fbKey)) delete prodData[claveProd];
      });
    }
    var busquedaProductos = (document.getElementById('prod-search') || {}).value || '';
    if (typeof renderTablaProductos === 'function') renderTablaProductos(busquedaProductos);
    if (typeof actualizarStatProductos === 'function') actualizarStatProductos();
    notify('Producto eliminado del catálogo');
    if (typeof registrarActividad === 'function') {
      registrarActividad('Producto eliminado', nombre + ' — ' + ventasProducto.length + ' venta' + (ventasProducto.length === 1 ? '' : 's') + ' histórica' + (ventasProducto.length === 1 ? '' : 's') + ' preservada' + (ventasProducto.length === 1 ? '' : 's'));
    }
    if (desdeDetalle) cerrarDetalleProducto();
    return true;
  } catch (e) {
    notify('Error: ' + e.message);
    return false;
  }
}

async function eliminarEmpleado(fbKey) {
  if (String(currentRole || '').toLowerCase() !== 'admin') { notify('Solo el administrador puede eliminar empleados'); return; }
  var emp = Object.values(empData||{}).find(function(e){ return (e.fbKey||String(e.id)) === String(fbKey); });
  if (!emp) { notify('Empleado no encontrado'); return; }
  var nombre = String(emp.nombre || '').trim().toLowerCase();
  var tieneVentas = (ventasList||[]).some(function(v){ return String(v.empleadoFbKey||'') === String(fbKey) || String(v.empleado||v.vendedor||'').trim().toLowerCase() === nombre; });
  var tieneOT = (otData||[]).some(function(ot){ return String(ot.tecnicoFbKey||ot.empleadoFbKey||'') === String(fbKey) || String(ot.tecnico||'').trim().toLowerCase() === nombre; });
  if (tieneVentas || tieneOT) {
    notify('No se puede eliminar porque tiene ventas u órdenes históricas. Desactivá el empleado para conservar la trazabilidad.');
    return;
  }
  if (!await svConfirm('¿Eliminar empleado "' + ((emp||{}).nombre||'') + '"?')) return;
  window.fbRemove(window.fbRef(window.fbDB, 'sisventas/empleados/' + fbKey))
    .then(function(){ notify('Empleado eliminado'); })
    .catch(function(e){ notify('Error: ' + e.message); });
}
// INFORMES TÉCNICOS

var informesData = [];
var informeActualId = null;

function fbCargarInformes() {
  if (!window.fbDB) return;
  window.fbOnValue(window.fbRef(window.fbDB, 'sisventas/informes'), function(snap) {
    var data = snap.val();
    informesData = data ? Object.entries(data).map(function(e){ return Object.assign({ fbKey: e[0] }, e[1]); })
                         .sort(function(a,b){ return (b.ts||0)-(a.ts||0); }) : [];
    renderTablaInformes();
  });
}

function renderTablaInformes() {
  var tbody = document.getElementById('informes-tbody');
  if (!tbody) return;
  var busq   = (document.getElementById('inf-search')||{}).value || '';
  var estado = (document.getElementById('inf-filtro-estado')||{}).value || '';
  var lista  = informesData.filter(function(inf) {
    var texto = ((inf.numero||'') + (inf.cliente||'') + (inf.equipo||'') + (inf.tecnico||'')).toLowerCase();
    return (!busq || texto.includes(busq.toLowerCase())) && (!estado || inf.estado === estado);
  });
  if (!lista.length) {
    tbody.innerHTML = '<tr><td colspan="7" style="text-align:center;color:var(--text3);padding:32px">Sin informes registrados</td></tr>';
    return;
  }
  tbody.innerHTML = lista.map(function(inf) {
    var estBadge = {borrador:'<span class="badge b-amber">Borrador</span>',completado:'<span class="badge b-blue">Completado</span>',enviado:'<span class="badge b-green">Enviado</span>'}[inf.estado]||inf.estado;
    var tipoBadge = {seguro:'<span class="badge b-red">Seguro</span>',garantia:'<span class="badge b-purple">Garantía</span>',mantenimiento:'<span class="badge b-blue">Mantenimiento</span>',instalacion:'<span class="badge b-green">Instalación</span>',tecnico:'<span class="badge b-blue">Técnico</span>'}[inf.tipo]||'<span class="badge b-blue">Técnico</span>';
    var fecha = inf.fecha ? inf.fecha.split('-').reverse().join('/') : '—';
    return '<tr style="cursor:pointer;touch-action:pan-x pan-y" onclick="editarInforme(\''+inf.fbKey+'\')">' +
      '<td style="font-family:monospace;font-size:12px;font-weight:500">'+ escapeHTML(inf.numero||'—') +'</td>' +
      '<td style="color:var(--text3);font-size:12px">'+ fecha +'</td>' +
      '<td><div style="font-weight:500;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+ escapeHTML(inf.cliente||'—') +'</div><div style="font-size:11px;color:var(--text3);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+ escapeHTML(inf.equipo||'') +'</div></td>' +
      '<td style="color:var(--text3);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+ escapeHTML(inf.tecnico||'—') +'</td>' +
      '<td class="tr">'+ tipoBadge +'</td>' +
      '<td class="tr">'+ estBadge +'</td>' +
      '<td onclick="event.stopPropagation()" style="white-space:nowrap"><button class="btn btn-sm btn-icon" onclick="editarInforme(\''+inf.fbKey+'\')" title="Editar"><i class="ti ti-edit" style="font-size:14px"></i></button>' +
           '<button class="btn btn-sm btn-icon" onclick="eliminarRegistro(\'informes\',\''+inf.fbKey+'\')" title="Eliminar" style="color:var(--text3)" onmouseenter="this.style.color=\'var(--red)\'" onmouseleave="this.style.color=\'var(--text3)\'"><i class="ti ti-trash" style="font-size:14px"></i></button></td>' +
    '</tr>';
  }).join('');
}

function filtrarInformes() { renderTablaInformes(); }

function abrirNuevoInforme() {
  informeActualId = null;
  document.getElementById('inf-form-titulo').textContent = 'Nuevo informe técnico';
  ['inf-numero','inf-fecha','inf-cliente','inf-dir','inf-equipo','inf-serie','inf-venta',
   'inf-motivo','inf-diagnostico','inf-acciones','inf-materiales','inf-preventivas','inf-obs',
   'inf-receptor','inf-receptor-dni'].forEach(function(id){
    var el = document.getElementById(id);
    if (el) el.value = '';
  });
  document.getElementById('inf-fecha').value = new Date().toISOString().split('T')[0];
  // Número automático
  var num = 'IT-' + String(informesData.length + 1).padStart(4,'0');
  document.getElementById('inf-numero').value = num;
  // Llenar select técnico
  var selTec = document.getElementById('inf-tecnico');
  if (selTec) {
    var opts = '<option value="">— Seleccionar —</option>';
    Object.values(empData||{}).filter(function(e){ return e.activo !== false; }).forEach(function(e){
      opts += '<option value="'+escapeHTML(e.nombre)+'">'+escapeHTML(e.nombre)+'</option>';
    });
    selTec.innerHTML = opts;
  }
  document.getElementById('informes-lista-view').style.display = 'none';
  document.getElementById('informes-form-view').style.display = '';
}

function editarInforme(fbKey) {
  var inf = informesData.find(function(i){ return i.fbKey === fbKey; });
  if (!inf) return;
  abrirNuevoInforme();
  // abrirNuevoInforme limpia deliberadamente la identidad para que un alta no
  // pueda reutilizar una edición anterior. Restaurarla sólo después de preparar
  // el formulario mantiene inequívoca la ruta de UPDATE.
  informeActualId = fbKey;
  document.getElementById('inf-form-titulo').textContent = 'Editar informe ' + (inf.numero||'');
  var campos = {
    'inf-numero':inf.numero,'inf-fecha':inf.fecha,'inf-cliente':inf.cliente,'inf-dir':inf.dir,
    'inf-equipo':inf.equipo,'inf-serie':inf.serie,'inf-venta':inf.venta,
    'inf-motivo':inf.motivo,'inf-diagnostico':inf.diagnostico,'inf-acciones':inf.acciones,
    'inf-materiales':inf.materiales,'inf-preventivas':inf.preventivas,'inf-obs':inf.obs,
    'inf-receptor':inf.receptor,'inf-receptor-dni':inf.receptorDni
  };
  Object.entries(campos).forEach(function(p){
    var el = document.getElementById(p[0]);
    if (el) el.value = p[1]||'';
  });
  var selTipo = document.getElementById('inf-tipo');
  if (selTipo && inf.tipo) selTipo.value = inf.tipo;
  var selRes = document.getElementById('inf-resultado');
  if (selRes && inf.resultado) selRes.value = inf.resultado;
  var selTec = document.getElementById('inf-tecnico');
  if (selTec && inf.tecnico) selTec.value = inf.tecnico;
}

function volverListaInformes() {
  // Cancelar/cerrar no deja una identidad de edición latente para la próxima alta.
  informeActualId = null;
  document.getElementById('informes-lista-view').style.display = '';
  document.getElementById('informes-form-view').style.display = 'none';
}

function guardarInforme(estado) {
  if (!window.fbDB) { notify('Sin conexión'); return; }
  var g = function(id){ var el=document.getElementById(id); return el?el.value.trim():''; };
  var inf = {
    numero:      g('inf-numero'),
    fecha:       g('inf-fecha'),
    tipo:        g('inf-tipo'),
    tecnico:     g('inf-tecnico'),
    cliente:     g('inf-cliente'),
    dir:         g('inf-dir'),
    equipo:      g('inf-equipo'),
    serie:       g('inf-serie'),
    venta:       g('inf-venta'),
    motivo:      g('inf-motivo'),
    diagnostico: g('inf-diagnostico'),
    acciones:    g('inf-acciones'),
    materiales:  g('inf-materiales'),
    preventivas: g('inf-preventivas'),
    obs:         g('inf-obs'),
    receptor:    g('inf-receptor'),
    receptorDni: g('inf-receptor-dni'),
    resultado:   g('inf-resultado'),
    estado:      estado,
    ts:          Date.now()
  };
  if (!inf.cliente) { notify('Ingresá el cliente'); return; }
  var promesa = informeActualId
    ? window.fbUpdate(window.fbRef(window.fbDB, 'sisventas/informes/'+informeActualId), inf)
    : window.fbPush(window.fbRef(window.fbDB, 'sisventas/informes'), inf);
  promesa.then(function(){
    notify('Informe ' + (estado==='borrador'?'guardado como borrador':estado==='enviado'?'marcado como enviado':'completado'));
    volverListaInformes();
  }).catch(function(e){ notify('Error: '+e.message); });
}

